        public static string Localize(string text)
        {
            return MultilingualTranslationRuntime.TranslateToLanguage(text, Language.Japanese);
        }

        public static void RegisterGeneratedCardName(string name)
        {
            if (string.IsNullOrEmpty(name)) return;
            int separator = name.IndexOf('-');
            if (separator <= 0 || separator >= name.Length - 1) return;
            string left = name.Substring(0, separator);
            string right = name.Substring(separator + 1);
            if (!P03InKayceesModMod.CardParts.TryGetValue(left, out string translatedLeft) ||
                !P03InKayceesModMod.CardParts.TryGetValue(right, out string translatedRight)) return;
            string localized = translatedLeft + translatedRight;
            Translate(GUID, null, name, localized, Language.Japanese);
            if (name.ToLowerInvariant().Contains("skel-e"))
                Translate(GUID, null, "Skel-E-" + name.Replace(" ", "-"), localized + "ガイコツ", Language.Japanese);
            else
                Translate(GUID, null, "Skele " + name, localized + "外骨格", Language.Japanese);
            Translate(GUID, null, "Beta " + name, localized + "ベータ版", Language.Japanese);
            Translate(GUID, null, "Lesser " + name, "幼い" + localized, Language.Japanese);
            Translate(GUID, null, "Elder " + name, "長老" + localized, Language.Japanese);
            for (int score = 0; score <= 100; score++)
            {
                string suffix = score.ToString() + ".0";
                Translate(GUID, null, name + " " + suffix, localized + " " + suffix, Language.Japanese);
            }
        }

