                string text5Loc = string.Concat(new string[] { text2Loc, " ", text5LocCardName, "のカードが作られる。", text3Loc });
                Translate(GUID, null, text5, text5Loc, Language.Japanese);
                Translate(GUID, null, "While " + value.DisplayedNameLocalized + " is on the board, remove ally Terrain and Pelt cards and transform the rest into random Apostles.", value.DisplayedNameLocalized + "が盤上にいる間、味方の地形と毛皮のカードを取り除き、残りをランダムな使徒に変える。", Language.Japanese);
                Translate(GUID, null, "[c:bR]The Clock[c:] and your [c:bR]" + value.DisplayedNameLocalized + "[c:] will remain in that abandoned time.", "[c:bR]時計[c:]と君の[c:bR]" + value.DisplayedNameLocalized + "[c:]は、捨てられた時間に残る。", Language.Japanese);
                Translate(GUID, null, "False " + value.DisplayedNameLocalized, "偽の" + value.DisplayedNameLocalized, Language.Japanese);
                Translate(GUID, null, "[c:bB]That " + value.DisplayedNameLocalized + " costs more energy than you have.[c:]", "[c:bB]" + value.DisplayedNameLocalized + "を出すにはエネルギーが足りない。[c:]", Language.Japanese);
            }
            if (source == null)
            for (int max = 1; max <= 10; max++)
            {
                Translate(GUID, null, "[c:bB]Do you still not get it? It costs " + max.ToString() + " energy and you don't have enough.[c:]", "[c:bB]まだわからないのか？ コストはエネルギー" + max.ToString() + "だが、足りていない。[c:]", Language.Japanese);
                for (int count = 0; count < max; count++)
                {
                    Translate(GUID, null, "[c:bB]That costs " + max.ToString() + " energy and you have " + count.ToString() + ".[c:]", "[c:bB]コストはエネルギー" + max.ToString() + "だが、君は" + count.ToString() + "しか持っていない。[c:]", Language.Japanese);
                }
            }


            // LifeCostAPI
            if (source == null) Debug.Log("Post Register Translations for LifeCostAPI");
            foreach (var value in cards)
            {
                if (!value.HasDisplayedNameEnglish) continue;
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bG]Scales[c:] are too tipped to play [c:bG]" + value.DisplayedNameLocalized + "[c:].", "君の[c:bG]天秤[c:]は傾きすぎていて、[c:bG]" + value.DisplayedNameLocalized + "[c:]を出せない。", Language.Japanese);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]" + value.DisplayedNameLocalized + "[c:] requires you to pay in life, in which you can not fullfill without killing yourself.", "[c:bG]" + value.DisplayedNameLocalized + "[c:]は命を支払う必要があるが、自分を殺さずには支払えない。", Language.Japanese);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You would kill yourself if you played [c:bG]" + value.DisplayedNameLocalized + "[c:]. Your [c:bG]Scales[c:] are too tipped", "[c:bG]" + value.DisplayedNameLocalized + "[c:]を出すと君は死ぬ。[c:bG]天秤[c:]が傾きすぎている。", Language.Japanese);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bG]Scales[c:] are too tipped and you lack the [c:gray]Foils[c:] to play " + value.DisplayedNameLocalized + ".", "[c:bG]天秤[c:]が傾きすぎており、[c:gray]プレミアム[c:]も足りないため、" + value.DisplayedNameLocalized + "を出せない。", Language.Japanese);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You lack the foils to play that [c:gray]" + value.DisplayedNameLocalized + "[c:].", "[c:gray]" + value.DisplayedNameLocalized + "[c:]を出すためのプレミアムが足りない。", Language.Japanese);
                for (int count = 0; count <= 20; count++)
                {
                    Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:gray]" + value.DisplayedNameLocalized + "[c:] requires you pay it's cost in [c:gray]foils[c:], that which you have [c:gray]" + count.ToString() + "[c:].", "[c:gray]" + value.DisplayedNameLocalized + "[c:]のコストは[c:gray]プレミアム[c:]で支払う。君の所持数は[c:gray]" + count.ToString() + "[c:]だ。", Language.Japanese);
                    Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That [c:gray]" + value.DisplayedNameLocalized + "[c:] has the cost of [c:gray]" + count.ToString() + "[c:] foils, which you do not have.", "[c:gray]" + value.DisplayedNameLocalized + "[c:]のコストはプレミアム[c:gray]" + count.ToString() + "[c:]だが、足りない。", Language.Japanese);
                }
            }

            // Sire_MoDeers
            if (source == null) Debug.Log("Post Register Translations for Sire_MoDeers");
            foreach (var value in cards)
            {
                if (!value.HasDisplayedNameEnglish) continue;
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, value.DisplayedName + "'s Protector", value.DisplayedNameLocalized + "の守護者", Language.Japanese);
            }

            if (source == null) Debug.Log("Post Register Translations Ended");
            stopwatch.Stop();
            if (source == null) Debug.Log($"PostRegisterTranslations 执行时间: {stopwatch.ElapsedMilliseconds} ms");
        }

        private static List<PostRegisterCardData> CachePostRegisterCardData(IEnumerable<CardInfo> source)
        {
            var cards = new List<PostRegisterCardData>();
            foreach (var card in source)
            {
                if (card.SafeIsUnityNull()) continue;
                cards.Add(new PostRegisterCardData(card, card.IsBaseGameCard()));
            }
            return cards;
        }

        private sealed class PostRegisterCardData
        {
            public PostRegisterCardData(CardInfo card, bool isBaseGameCard)
            {
                IsBaseGameCard = isBaseGameCard;
                DisplayedNameEnglish = card.DisplayedNameEnglish;
                DisplayedNameLocalized = card.DisplayedNameLocalized;
                DisplayedName = card.displayedName;
                Description = card.description;
                Name = card.name;
                Attack = card.Attack;
                Health = card.Health;
                Abilities = card.Abilities?.ToArray() ?? Array.Empty<Ability>();
            }

            public bool IsBaseGameCard { get; }
            public string DisplayedNameEnglish { get; }
            public string DisplayedNameLocalized { get; }
            public string DisplayedName { get; }
            public string Description { get; }
            public string Name { get; }
            public int Attack { get; }
            public int Health { get; }
            public Ability[] Abilities { get; }
            public bool HasDisplayedNameEnglish => DisplayedNameEnglish != null;
            public bool HasDisplayedName => DisplayedName != null;
        }
        private static bool NameStartsWithVowel(string name)
        {
            if (string.IsNullOrEmpty(name))
            {
                return false;
            }
            char c = name.ToLowerInvariant()[0];
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        }

    }

