            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dont change this value, it is used by the game to store certain events.", "この値は変更しないこと。特定のイベントの保存に使われる。", Language.Japanese);

