    public class MagnificusMod
    {
        public static Dictionary<string, string> Cards = new();
        public static Dictionary<string, List<KeyValuePair<string, string>>> CardsDescription = new();

        public static Dictionary<string, string> Abilities = new();

        public static void RegisterCard(string en, string zh, string desen, string deszh)
        {
            if (!Cards.ContainsKey(en))
            {
                Cards.Add(en, zh);
            }
            if (!CardsDescription.ContainsKey(en))
            {
                CardsDescription[en] = new List<KeyValuePair<string, string>>();
            }
            CardsDescription[en].Add(new KeyValuePair<string, string>(desen, deszh));
        }

        public static void RegisterAbility(string en, string zh)
        {
            Abilities.Add(en, zh);
        }

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Magnificus Mod");
            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "New Magnificus Run", "マグニフィカスの新しいランを開始", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW MAGNIFICUS RUN", "マグニフィカスの新しいランを開始", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "View Deck", "デッキを見る", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TOWER OF MAGICKS", "魔法の塔", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GOO DUNGEON", "粘液ダンジョン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LAVA DUNGEON", "溶岩のダンジョン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VOID DUNGEON", "虚無のダンジョン", Language.Japanese);

            // Config
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Automatically unlocks every challenge and starter deck in Magnificus' Kaycees Mod. This does NOT change your magnificus challenge point value. If you have a change of heart and decide to unlock the challenges fairly, your challenge points will remain the same.", "マグニフィカスのKaycee's Modで、すべてのチャレンジと初期デッキを自動で解放する。マグニフィカスのチャレンジポイントは変更しない。後から気が変わって正規の方法で解放しようとしても、ポイントは元のままになる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Base wizard cards from act 2 will keep their original statlines.", "第2章の基本ウィザードカードは、元の能力値を維持する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use the old 2D flat card designs instead of the new 3D models.", "新しい3Dモデルの代わりに、古い2Dの平面カードデザインを使う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add paint splashes to the background of every card (like in the original magnificus finale).", "各カードの背景に絵の具の飛沫を加える。本編のマグニフィカスの最終戦と同様。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third person perspective for magnificus' game. Disable if you want the classic first person experience.", "マグニフィカスのゲームを三人称視点にする。従来の一人称視点にしたい場合は無効にする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Show a grid around the player in tabletop mode.", "卓上モードで、プレイヤーの周囲にグリッドを表示する。", Language.Japanese);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blank Mox", "空白のモックス", Language.Japanese);
            RegisterAbility("Blank Mox", "空白のモックス");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, it will materialize into a random Mox Crystal. \n When on another card, the card will generate a random Mox Crystal.", "この印を持つカードを引くと、ランダムなモックスの結晶に実体化する。\nほかのカードについた場合、そのカードはランダムなモックスの結晶を生成する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undecided Mox", "形なきモックス", Language.Japanese);
            RegisterAbility("Undecided Mox", "形なきモックス");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, select a mox type for this card to provide.", "この印を持つカードを場に出すと、このカードが供給するモックスの種類を選ぶ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Heart", "ルビーハート", Language.Japanese);
            RegisterAbility("Ruby Heart", "ルビーハート");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Ruby Mox in its place.", "この印を持つカードが死ぬと、元いた場所にルビー・モックスを生成する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Heart", "サファイアの心臓", Language.Japanese);
            RegisterAbility("Sapphire Heart", "サファイアの心臓");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Sapphire Mox in its place.", "この印を持つカードが死ぬと、元いた場所にサファイア・モックスを生成する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Marrow", "骨髄", Language.Japanese);
            RegisterAbility("Bone Marrow", "骨髄");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When one of your non-gem cards perishes, a card bearing this sigil gains 1 power, maxing out at 5.", "自分のジェムでないカードが死ぬと、この印を持つカードの攻撃力が1増える。上限は5。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation", "興奮", Language.Japanese);
            RegisterAbility("Stimulation", "興奮");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 1 power, maxing out at 4.", "各ターン終了時、この印を持つカードの攻撃力が1増える。上限は4。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation (Health)", "興奮（体力）", Language.Japanese);
            RegisterAbility("Stimulation (Health)", "興奮（体力）");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 2 health, maxes out at 10.", "各ターン終了時、この印を持つカードの体力が2増える。上限は10。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Draw", "死の略奪", Language.Japanese);
            RegisterAbility("Dead Draw", "死の略奪");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card dies, draw a card from your deck.", "ジェムでないカードが死ぬと、自分のデッキからカードを引く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Heart", "エメラルドの心臓", Language.Japanese);
            RegisterAbility("Emerald Heart", "エメラルドの心臓");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates an Emerald Mox in its place.", "この印を持つカードが死ぬと、元いた場所にエメラルド・モックスを生成する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gooey", "粘液", Language.Japanese);
            RegisterAbility("Gooey", "粘液");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, the striker loses 1 attack.", "この印を持つカードが攻撃を受けると、攻撃したカードの攻撃力が1減る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mental Gemnastics", "ジェム製錬", Language.Japanese);
            RegisterAbility("Mental Gemnastics", "ジェム製錬");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw cards from your deck based on how many Gems are on the board.", "この印を持つカードを場に出すと、盤上のジェムの数だけ自分のデッキからカードを引く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loot", "略奪", Language.Japanese);
            RegisterAbility("Loot", "略奪");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, draw cards from your deck based on how much damage was dealt.", "この印を持つカードが直接ダメージを与えると、そのダメージ量だけ自分のデッキからカードを引く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life Steal", "生命吸収", Language.Japanese);
            RegisterAbility("Life Steal", "生命吸収");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, the amount dealt will be healed to the owner of this card.", "この印を持つカードが直接ダメージを与えると、その所有者が同じ量だけ回復する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knockback Hit", "時を押し戻す一撃", Language.Japanese);
            RegisterAbility("Knockback Hit", "時を押し戻す一撃");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil hits an opposing card, the opposing card will be kicked in the direction inscrybed in the sigil.", "この印を持つカードが相手のカードに攻撃を当てると、そのカードを印に示された方向へ蹴り飛ばす。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Impaled", "槍の召喚", Language.Japanese);
            RegisterAbility("Impaled", "槍の召喚");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Spear in its placed. A spear is defined as Sharp, 0 power, 3 health.", "この印を持つカードが死ぬと、元いた場所に槍を生成する。槍は針毛を持ち、攻撃力0、体力3。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnus Mox", "マグナス・モックス", Language.Japanese);
            RegisterAbility("Magnus Mox", "マグナス・モックス");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, it provides an orange gem, a blue gem and a green gem to its owner.", "この印を持つカードが盤上にある間、その所有者にオレンジ、ブルー、緑のジェムを一つずつ供給する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resurrection", "復活再生", Language.Japanese);
            RegisterAbility("Resurrection", "復活再生");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card perishes, the dead card will be brought back to life, but this card loses 3 health.", "ジェムでないカードが死ぬと、そのカードが蘇る。ただし、この印を持つカードは体力を3失う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rerolls", "サイコロの力", Language.Japanese);
            RegisterAbility("Rerolls", "サイコロの力");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigils' base power will be increased by a random value between 0 and 3.", "各ターン終了時、この印を持つカードの攻撃力を振り直し、0から3の間のランダムな値にする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Steel Trap", "トラバサミ", Language.Japanese);
            RegisterAbility("Steel Trap", "トラバサミ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the opposing card also perishes.", "この印を持つカードが死ぬと、向かいのカードも死ぬ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Shield", "ジェムシールド", Language.Japanese);
            RegisterAbility("Gem Shield", "ジェムシールド");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on the board gain a shield.", "この印を持つカードを場に出すと、盤上のすべてのジェムがシールドを得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plating Work", "メッキ加工", Language.Japanese);
            RegisterAbility("Plating Work", "メッキ加工");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all gems on your side of the board gain the Sharp Quills sigil, and 2 health.", "この印を持つカードが盤上にある間、自分のサイドのすべてのジェムが針毛の印と体力2を得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animator", "操り人形師", Language.Japanese);
            RegisterAbility("Animator", "操り人形師");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all non-mox cards with 0 power gain 2 power", "この印を持つカードが盤上にある間、モックスでない攻撃力0のすべてのカードが攻撃力2を得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "ジェム吸収者", Language.Japanese);
            RegisterAbility("Gem Absorber", "ジェム吸収者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on your side of the board will perish. For each gem absorbed, gain 1 power and 2 health.", "この印を持つカードを場に出すと、自分のサイドのすべてのジェムが死ぬ。吸収したジェム一つにつき、このカードの攻撃力が1、体力が2増える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerge", "潜水", Language.Japanese);
            RegisterAbility("Submerge", "潜水");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil will submerge. Upon resubmerging, this card will become a random Tentacle Card.", "ターン終了時、この印を持つカードは水中に潜る。再び浮上すると、ランダムな触手カードに変わる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Familiar", "使い魔", Language.Japanese);
            RegisterAbility("Familiar", "使い魔");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish if there are no non-gem cards on the board.", "盤上にジェムでないカードがなければ、この印を持つカードは死ぬ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fading", "消失", Language.Japanese);
            RegisterAbility("Fading", "消失");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish at the end of the turn.", "この印を持つカードはターン終了時に死ぬ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morph", "不定の変異体", Language.Japanese);
            RegisterAbility("Morph", "不定の変異体");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will mimic the card opposing it. If there is no card opposing it, this card will perish.", "この印を持つカードを場に出すと、向かいのカードを模倣する。向かいにカードがなければ死亡する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication", "行列の乗算", Language.Japanese);
            RegisterAbility("Multiplication", "行列の乗算");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw another of this card, but with a different gem cost.", "この印を持つカードを場に出すと、ジェムコストの異なる同じカードをもう一枚引く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Cycle", "モックス循環", Language.Japanese);
            RegisterAbility("Mox Cycle", "モックス循環");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, all the mox on the board will cycle into different gems.", "各ターン終了時、盤上のすべてのモックスが別のジェムへ順に切り替わる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Strafe", "モックス落とし", Language.Japanese);
            RegisterAbility("Mox Strafe", "モックス落とし");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, this card will move to the direction inscrybed on the sigil, and leave behind a mox.", "ターン終了時、このカードは印に示された方向へ移動し、元いた場所にモックスを残す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purist", "純粋主義", Language.Japanese);
            RegisterAbility("Purist", "純粋主義");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any card directly opposing this one will have all it's sigils removed.", "このカードの真向かいにあるカードは、すべての印を失う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brewery", "醸造所", Language.Japanese);
            RegisterAbility("Brewery", "醸造所");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, you automatically draw a mox card from your side deck.", "各ターン終了時、自動的に自分のサイドデッキからモックスのカードを引く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "火付け", Language.Japanese);
            RegisterAbility("Ignite", "火付け");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, every empty opposing slot will be filled with flames. A flame is defined as a 0/1, Annoying.", "この印を持つカードを場に出すと、相手側のすべての空きスロットを炎で埋める。炎は攻撃力0、体力1で、嫌がらせを持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Projection", "星空の投影", Language.Japanese);
            RegisterAbility("Projection", "星空の投影");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is stuck, it will move and leave behind an astral projection of itself.", "この印を持つカードが攻撃を受けると、移動して自身のアストラル投射を残す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Book", "呪文大全", Language.Japanese);
            RegisterAbility("Spell Book", "呪文大全");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random spell card.", "この印を持つカードを場に出すと、ランダムな呪文カードを引く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scholar", "魔術の学者", Language.Japanese);
            RegisterAbility("Scholar", "魔術の学者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random one of Bleene's Books.", "この印を持つカードを場に出すと、ブルーンの本をランダムに一冊引く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Midas' Touch", "黄金の手", Language.Japanese);
            RegisterAbility("Midas' Touch", "黄金の手");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil attacks another card, the attacked card will lose all of it's attack and turn to gold.", "この印を持つカードがほかのカードを攻撃すると、攻撃されたカードは攻撃力をすべて失い、金に変わる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Made of Gold", "黄金の体", Language.Japanese);
            RegisterAbility("Made of Gold", "黄金の体");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the killer will gain 2 crystals.", "この印を持つカードが死ぬと、倒した側が結晶を2個得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Runes", "起爆召喚", Language.Japanese);
            RegisterAbility("Summon Runes", "起爆召喚");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will summon two runes beside it. A rune is defined as 0 power, 1 health, Detonator.", "この印を持つカードを場に出すと、両隣にルーンを二つ召喚する。ルーンは攻撃力0、体力1で、起爆剤を持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Health", "体力の呪文", Language.Japanese);
            RegisterAbility("Spell of Health", "体力の呪文");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +2 health.", "この印を持つ呪文を使うと、自分のサイドのすべてのカードが体力+2を得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Attack", "攻撃の呪文", Language.Japanese);
            RegisterAbility("Spell of Attack", "攻撃の呪文");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +1 attack.", "この印を持つ呪文を使うと、自分のサイドのすべてのカードが攻撃力+1を得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Spell", "霜の呪文", Language.Japanese);
            RegisterAbility("Frost Spell", "霜の呪文");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards belonging to the opponent will have their attack set to 0, but given +2 health.", "この印を持つ呪文を使うと、相手のすべてのカードの攻撃力を0にし、体力+2を与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Wind", "強風の呪文", Language.Japanese);
            RegisterAbility("Spell of Wind", "強風の呪文");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board will become airborne.", "この印を持つ呪文を使うと、自分のサイドのすべてのカードが飛行を得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruckus", "時計回りのささやき", Language.Japanese);
            RegisterAbility("Ruckus", "時計回りのささやき");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all cards on the board will move clockwise.", "この印を持つカードを場に出すと、盤上のすべてのカードが時計回りに移動する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Water", "浄水の呪文", Language.Japanese);
            RegisterAbility("Spell of Water", "浄水の呪文");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, every card on the board will have their sigils erased.", "この印を持つ呪文を使うと、盤上のすべてのカードの印を消す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Flame", "炎の呪文", Language.Japanese);
            RegisterAbility("Spell of Flame", "炎の呪文");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a side of the board, every card on that side will lose 2 health (without perishing) and have their attack increased by 1.", "盤の片側を選ぶ。その側のすべてのカードは体力を2失い、攻撃力が1増える。ただし、この体力減少では死なない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Set Ablaze", "点火", Language.Japanese);
            RegisterAbility("Set Ablaze", "点火");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every card on the opposite side will lose 2 health (without perishing) and have their attack increased by 1.", "反対側のすべてのカードは体力を2失い、攻撃力が1増える。ただし、この体力減少では死なない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Time Spell", "使い捨ての呪文", Language.Japanese);
            RegisterAbility("One Time Spell", "使い捨ての呪文");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the turn ends, a spell bearing this sigil will perish and be removed from your deck.", "ターン終了時、この印を持つ呪文は死に、自分のデッキから取り除かれる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vase of Greed", "強欲の壺", Language.Japanese);
            RegisterAbility("Vase of Greed", "強欲の壺");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, discard your current hand and draw 4 new cards.", "この印を持つ呪文を使うと、今の手札をすべて捨て、新たにカードを4枚引く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gnomification", "ノーム化", Language.Japanese);
            RegisterAbility("Gnomification", "ノーム化");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a slot to summon a Gnome card in.", "ノームのカードを召喚するスロットを選ぶ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed", "呪い", Language.Japanese);
            RegisterAbility("Cursed", "呪い");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, it will immediately perish.", "この印を持つ呪文を使うと、即座に死ぬ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspiration", "ひらめき", Language.Japanese);
            RegisterAbility("Inspiration", "ひらめき");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to give Airborne + Looter for 1 turn.", "カードを選び、1ターンの間、飛行と略奪を与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calculus", "微積分", Language.Japanese);
            RegisterAbility("Calculus", "微積分");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to swap stats.", "カードを選び、攻撃力と体力を入れ替える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rage", "激怒", Language.Japanese);
            RegisterAbility("Rage", "激怒");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to kill. The opponent of the card will recieve damage equal to the amount of health the card had.", "倒すカードを選ぶ。そのカードの所有者の対戦相手は、カードが持っていた体力と同じダメージを受ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fireball", "火球の術", Language.Japanese);
            RegisterAbility("Fireball", "火球の術");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to take 2 damage.", "カードを選び、2ダメージを与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cold to the Touch", "凍てつく接触", Language.Japanese);
            RegisterAbility("Cold to the Touch", "凍てつく接触");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigils attack another card, that card will lose 1 attack.", "この印を持つカードがほかのカードを攻撃すると、攻撃されたカードの攻撃力が1減る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen", "凍結", Language.Japanese);
            RegisterAbility("Frozen", "凍結");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, this card will lose its frozen health. When all frozen health is depleted, or this card is struck, it will defrost.", "各ターン終了時、このカードは凍結中の体力を失う。凍結中の体力が尽きるか、攻撃を受けると解凍される。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong Pull", "強力な牽引", Language.Japanese);
            RegisterAbility("Strong Pull", "強力な牽引");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every opposing card will be inclined to hit this card instead of any other.", "相手のすべてのカードは、ほかよりもこのカードを優先して攻撃しようとする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Displacement", "置換反応", Language.Japanese);
            RegisterAbility("Displacement", "置換反応");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, another of this card will be added randomly into your deck", "この印を持つカードを引くと、同じカードをもう一枚、自分のデッキのランダムな位置に加える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Reckoning", "ジェムの清算", Language.Japanese);
            RegisterAbility("Gem Reckoning", "ジェムの清算");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, if the owner of this card does not control any gems, the leftmost card in your hand is discarded.", "各ターン終了時、このカードの所有者がジェムを一つもコントロールしていなければ、自分の手札の一番左のカードを捨てる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Power", "モックスの攻撃力", Language.Japanese);
            RegisterAbility("Mox Power", "モックスの攻撃力");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "この印が示す値は、所有者サイドのテーブルにあるモックスのカードの数に等しい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Health", "モックスの体力", Language.Japanese);
            RegisterAbility("Mox Health", "モックスの体力");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "この印が示す値は、所有者サイドのテーブルにあるモックスのカードの数に等しい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candle Proximity", "ロウソクへの接近", Language.Japanese);
            RegisterAbility("Candle Proximity", "ロウソクへの接近");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to how close this card is to the Candle on the table.", "この印が示す値は、このカードがテーブルのロウソクにどれだけ近いかで決まる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Murder Power", "殺戮の力", Language.Japanese);
            RegisterAbility("Murder Power", "殺戮の力");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal the total amount of power on the opponents board.", "この印が示す値は、相手の盤上の攻撃力の合計に等しい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to half the total amount of power on your board.", "この印が示す値は、自分の盤上の攻撃力の合計の半分に等しい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Power", "呪文の力", Language.Japanese);
            RegisterAbility("Spell Power", "呪文の力");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during this current dungeon.", "この印が示す値は、現在のダンジョンで使われた呪文の総数に等しい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during the battle.", "この印が示す値は、この戦闘で使われた呪文の総数に等しい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Counterbattery Power", "反撃力", Language.Japanese);
            RegisterAbility("Counterbattery Power", "反撃力");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the amount of damage taken by you this battle, divided by two.", "この印が示す値は、この戦闘で自分が受けたダメージの合計を二で割った値に等しい。", Language.Japanese);
            foreach (Ability ability in Enum.GetValues(typeof(Ability)))
            {
                var info = AbilitiesUtil.GetInfo(ability);
                if (info == null || info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的info，已跳过。");
                    continue;
                }
                if (info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的rulebookName，或本身已注册，已跳过。");
                    continue;
                }
                RegisterAbility(info.rulebookName, JapaneseLanguagePack.Localize(info.rulebookName));
            }

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox", "モックス", Language.Japanese);
            RegisterCard("Mox", "モックス", "its a me moxio", "イッツ・ミー、モックシオ！");
            RegisterCard("Ruby Mox", "ルビー・モックス", "its a me moxio", "イッツ・ミー、モックシオ！");
            RegisterCard("Emerald Mox", "エメラルド・モックス", "its a me moxio", "イッツ・ミー、モックシオ！");
            RegisterCard("Sapphire Mox", "サファイア・モックス", "its a me moxio", "イッツ・ミー、モックシオ！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "its a me moxio", "イッツ・ミー、モックシオ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spear", "槍", Language.Japanese);
            RegisterCard("Spear", "槍", "ayo", "おっと");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ayo", "おっと", Language.Japanese);
            RegisterCard("Mage Pupil", "見習いメイジ", "Though weak, it can always be useful in the right situation.", "弱くとも、状況次第では必ず役に立つ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though weak, it can always be useful in the right situation.", "弱くとも、状況次第では必ず役に立つ。", Language.Japanese);
            RegisterCard("Junior Sage", "若い賢者", "Although simple, it can prove itself to be useful.", "単純ではあるが、その有用性を証明してくれる。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Although simple, it can prove itself to be useful.", "単純ではあるが、その有用性を証明してくれる。", Language.Japanese);
            RegisterCard("Muscle Mage", "マッスル・メイジ", "An abomination of muscles, developed from drinking too many potions of the alchemist..", "錬金術師の薬を飲みすぎて生まれた、筋肉の怪物…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An abomination of muscles, developed from drinking too many potions of the alchemist..", "錬金術師の薬を飲みすぎて生まれた、筋肉の怪物…", Language.Japanese);
            RegisterCard("Green Mage", "グリーン・メイジ", "It draws its power from the mana of the mox on the board.", "盤上のモックスのマナから力を引き出す。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It draws its power from the mana of the mox on the board.", "盤上のモックスのマナから力を引き出す。", Language.Japanese);
            RegisterCard("Blue Mage", "ブルー・メイジ", "Never doubt its utility.", "その有用性を疑ってはいけない。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Never doubt its utility.", "その有用性を疑ってはいけない。", Language.Japanese);
            RegisterCard("Blue Sporemage", "ブルー・スポアメイジ", "", "");
            RegisterCard("Force Mage", "フォース・メイジ", "A mage, proficient in a martial stance which allows it block nearly anything..", "ほとんど何でも防げる武術の構えに熟達した魔術師…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage, proficient in a martial stance which allows it block nearly anything..", "ほとんど何でも防げる武術の構えに熟達した魔術師…", Language.Japanese);
            RegisterCard("Gem Fiend", "ジェム・フィーンド", "A wretched, unstable creature of gems. It can tear through anything.", "忌まわしく、不安定なジェムの生物。何でも引き裂く。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wretched, unstable creature of gems. It can tear through anything.", "忌まわしく、不安定なジェムの生物。何でも引き裂く。", Language.Japanese);
            RegisterCard("Hover Mage", "ホバー・メイジ", "Using its spells it soars high to hit directly", "呪文で高く飛び、直接攻撃を仕掛ける。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Using its spells it soars high to hit directly", "呪文で高く飛び、直接攻撃を仕掛ける。", Language.Japanese);
            RegisterCard("Mage Knight", "メイジ・ナイト", "An intimidating and towering defense, however requiring gems to stay stable.", "威圧的で高くそびえる守り。ただし、安定を保つにはジェムが必要だ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An intimidating and towering defense, however requiring gems to stay stable.", "威圧的で高くそびえる守り。ただし、安定を保つにはジェムが必要だ。", Language.Japanese);
            RegisterCard("Orange Mage", "オレンジ・メイジ", "Using its spells, it boosts the damage of all gems.", "呪文を使い、すべてのジェムのダメージを高める。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Using its spells, it boosts the damage of all gems.", "呪文を使い、すべてのジェムのダメージを高める。", Language.Japanese);
            RegisterCard("Practice Wizard", "練習用ウィザード", "A lifeless practice target.. standing tall enough to block any attacks.", "命のない練習用の的…どんな攻撃も遮るほど高く立っている。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A lifeless practice target.. standing tall enough to block any attacks.", "命のない練習用の的…どんな攻撃も遮るほど高く立っている。", Language.Japanese);
            RegisterCard("Ruby Golem", "ルビー・ゴーレム", "A construct powered by Mox.As it perishes it leaves behind parts of itself.", "モックスで動く構造体。死ぬと自身の部品を残す。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A construct powered by Mox.As it perishes it leaves behind parts of itself.", "モックスで動く構造体。死ぬと自身の部品を残す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnus Mox", "マグナス・モックス", Language.Japanese);
            RegisterCard("Magnus Mox", "マグナス・モックス", "is the return of bin laden", "ビン・ラディンの帰還だ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "is the return of bin laden", "ビン・ラディンの帰還だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wolf Familiar", "オオカミの使い魔", Language.Japanese);
            RegisterCard("Wolf Familiar", "オオカミの使い魔", "It rips into its enemies with little to no remorse.", "ほとんど、あるいはまったく悔いることなく敵を引き裂く。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It rips into its enemies with little to no remorse.", "ほとんど、あるいはまったく悔いることなく敵を引き裂く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trading Obelisk", "交易のオベリスク", Language.Japanese);
            RegisterCard("Trading Obelisk", "交易のオベリスク", "draft token aka pelt no way jose", "ドラフトトークン、別名毛皮。いやいや、まさか。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "draft token aka pelt no way jose", "ドラフトトークン、別名毛皮。いやいや、まさか。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Worm", "水晶ワーム", Language.Japanese);
            RegisterCard("Crystal Worm", "水晶ワーム", "Its body is made out of pure mana.. Gleaming and transforming into other gems.", "体は純粋なマナでできている…輝きながら、別のジェムへ変わっていく。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its body is made out of pure mana.. Gleaming and transforming into other gems.", "体は純粋なマナでできている…輝きながら、別のジェムへ変わっていく。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Larva", "宝石の幼虫", Language.Japanese);
