            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Techno Mage", "技術の魔術師", Language.Japanese);
            RegisterCard("Techno Mage", "技術の魔術師", "sponsored by me", "私の提供でお送りする");
