            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ouroberyl", "ウロベリル", Language.Japanese);
            RegisterCard("Ouroberyl", "ウロベリル", "It gleams and takes different forms.. How majestic..", "輝きながら、さまざまな姿に変わる…なんと荘厳なことか…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It gleams and takes different forms.. How majestic..", "輝きながら、さまざまな姿に変わる…なんと荘厳なことか…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spellcaster", "魔術の使者", Language.Japanese);
