            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It reads out spells from its book and casts them directly to your hand.", "本から呪文を読み上げ、自分の手札へ直接唱える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Magician", "混沌の魔術師", Language.Japanese);
            RegisterCard("Chaos Magician", "混沌の魔術師", "A scholar proficient in Chaos Theory, channeling a scramble unto the entire board.", "カオス理論に熟達した学者。盤全体をかき乱す力を送り込む。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A scholar proficient in Chaos Theory, channeling a scramble unto the entire board.", "カオス理論に熟達した学者。盤全体をかき乱す力を送り込む。", Language.Japanese);
