            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homunculus", "ホムンクルス", Language.Japanese);
            RegisterCard("Homunculus", "ホムンクルス", "A strange, to say the least creature.", "控えめに言っても、奇妙な生物だ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange, to say the least creature.", "控えめに言っても、奇妙な生物だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mimagius", "ミマギウス", Language.Japanese);
            RegisterCard("Mimagius", "ミマギウス", "It distorts itself into the form of the opposing card.", "自らを歪め、向かいのカードの姿を取る。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It distorts itself into the form of the opposing card.", "自らを歪め、向かいのカードの姿を取る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deflector", "偏向装置", Language.Japanese);
            RegisterCard("Deflector", "偏向装置", "You would not want to end up on the wrong side of it..", "敵には回したくないだろう…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You would not want to end up on the wrong side of it..", "敵には回したくないだろう…", Language.Japanese);
