            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It harnesses the power of the stars for you..", "君のために星の力を操る…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astral Sorcerer", "星界の魔術師", Language.Japanese);
            RegisterCard("Astral Sorcerer", "星界の魔術師", "A sorcerer proficient in summoning astral projections to protect itself when in danger.", "危険な時にアストラル投射を召喚して身を守る、熟練の魔術師。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sorcerer proficient in summoning astral projections to protect itself when in danger.", "危険な時にアストラル投射を召喚して身を守る、熟練の魔術師。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astral Projection", "アストラル投射", Language.Japanese);
            RegisterCard("Astral Projection", "アストラル投射", "real", "本物の");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "real", "本物の", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trinket Bearer", "荷物運搬", Language.Japanese);
            RegisterCard("Trinket Bearer", "荷物運搬", "A mischevious little goblin creature. It carries around valueables in its backpack.", "いたずら好きな小さなゴブリン。リュックに貴重品を入れて持ち歩く。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mischevious little goblin creature. It carries around valueables in its backpack.", "いたずら好きな小さなゴブリン。リュックに貴重品を入れて持ち歩く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backpack", "リュック", Language.Japanese);
            RegisterCard("Backpack", "リュック", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimbot", "ハッスルボット", Language.Japanese);
            RegisterCard("Stimbot", "ハッスルボット", "Powered by stimulation, and steam..", "興奮と蒸気で動く…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powered by stimulation, and steam..", "興奮と蒸気で動く…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magimorph", "変身の魔術師", Language.Japanese);
            RegisterCard("Magimorph", "変身の魔術師", "Its disgusting gooey body warps and distorts into distant forms. It's wonderous if you look at it right.", "気味の悪い粘液の体が、かけ離れた姿へ歪み、変わる。見方次第では実に不思議だ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its disgusting gooey body warps and distorts into distant forms. It's wonderous if you look at it right.", "気味の悪い粘液の体が、かけ離れた姿へ歪み、変わる。見方次第では実に不思議だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Performer", "演者", Language.Japanese);
            RegisterCard("Performer", "演者", "Watch it create a rabbit out of its wand..", "杖からウサギを生み出すところをご覧あれ…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch it create a rabbit out of its wand..", "杖からウサギを生み出すところをご覧あれ…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Senior Sage", "上級の賢者", Language.Japanese);
            RegisterCard("Senior Sage", "上級の賢者", "A Junior Sage that has mastered the art of Magicks.", "魔法の技を極めた若い賢者。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Junior Sage that has mastered the art of Magicks.", "魔法の技を極めた若い賢者。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Mech", "サファイアの機甲", Language.Japanese);
            RegisterCard("Sapphire Mech", "サファイアの機甲", "A mage-like automaton piloted by a sapphire mox.. Admirable.", "サファイア・モックスが操縦する、魔術師型のオートマトン…見事だ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage-like automaton piloted by a sapphire mox.. Admirable.", "サファイア・モックスが操縦する、魔術師型のオートマトン…見事だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Titan", "ルビーのタイタン", Language.Japanese);
            RegisterCard("Ruby Titan", "ルビーのタイタン", "A perfected construct of a ruby golem, a monstrous machine of destruction.", "ルビー・ゴーレムを完成させた構造体。恐るべき破壊の機械だ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A perfected construct of a ruby golem, a monstrous machine of destruction.", "ルビー・ゴーレムを完成させた構造体。恐るべき破壊の機械だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleene's Scholar", "ブルーンの学徒", Language.Japanese);
            RegisterCard("Bleene's Scholar", "ブルーンの学徒", "A scholar in training, currently studying the works of Master Bleene.", "修業中の学者。今はマスター・ブルーンの著作を研究している。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A scholar in training, currently studying the works of Master Bleene.", "修業中の学者。今はマスター・ブルーンの著作を研究している。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goranj's Warrior", "グリンジの戦士", Language.Japanese);
            RegisterCard("Goranj's Warrior", "グリンジの戦士", "A foe mentored by Master Goranj, proficient at dual striking.", "マスター・グリンジの教えを受けた敵。二連撃に長けている。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A foe mentored by Master Goranj, proficient at dual striking.", "マスター・グリンジの教えを受けた敵。二連撃に長けている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cider Mage", "シードルの魔術師", Language.Japanese);
            RegisterCard("Cider Mage", "シードルの魔術師", "This mage has a secret formula of cider that nullifies the opponents spells..", "相手の呪文を無効にする、シードルの秘伝の配合を持つ魔術師…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage has a secret formula of cider that nullifies the opponents spells..", "相手の呪文を無効にする、シードルの秘伝の配合を持つ魔術師…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brewer Sage", "醸造の賢者", Language.Japanese);
            RegisterCard("Brewer Sage", "醸造の賢者", "A sage, sitting still and perfecting his art of brewing..", "じっと座り、醸造の技を磨く賢者…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sage, sitting still and perfecting his art of brewing..", "じっと座り、醸造の技を磨く賢者…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soda Mage", "炭酸の魔術師", Language.Japanese);
            RegisterCard("Soda Mage", "炭酸の魔術師", "This pathetic mage melted away from drinking too much carbonated liquid..", "炭酸の飲み物を飲みすぎて溶けてしまった、哀れな魔術師…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This pathetic mage melted away from drinking too much carbonated liquid..", "炭酸の飲み物を飲みすぎて溶けてしまった、哀れな魔術師…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whitesmith", "宝石の鍛冶師", Language.Japanese);
            RegisterCard("Whitesmith", "宝石の鍛冶師", "Their life's work was dedicated to reinforcing gems.", "生涯をジェムの強化に捧げた。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Their life's work was dedicated to reinforcing gems.", "生涯をジェムの強化に捧げた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppeteer", "人形遣い", Language.Japanese);
            RegisterCard("Puppeteer", "人形遣い", "Its mastery of control magicks lets even Practice Wizards contribute.", "支配の魔法を極めたことで、練習用ウィザードにさえ活躍させられる。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its mastery of control magicks lets even Practice Wizards contribute.", "支配の魔法を極めたことで、練習用ウィザードにさえ活躍させられる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juggler", "曲芸師", Language.Japanese);
            RegisterCard("Juggler", "曲芸師", "It juggles around your mox cards, as if they were juggling balls..", "まるで曲芸の玉のように、君のモックスのカードを放り上げる…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It juggles around your mox cards, as if they were juggling balls..", "まるで曲芸の玉のように、君のモックスのカードを放り上げる…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Joker", "ジョーカー", Language.Japanese);
            RegisterCard("Joker", "ジョーカー", "Dedicated to the art of fun.. though most only find it annoying.", "楽しませる技に打ち込んでいる…ただ、大抵はうるさがられるだけだ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dedicated to the art of fun.. though most only find it annoying.", "楽しませる技に打ち込んでいる…ただ、大抵はうるさがられるだけだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valkyrie", "ヴァルキリー", Language.Japanese);
            RegisterCard("Valkyrie", "ヴァルキリー", "A student that has trained under Master Orlu. It has become an expert in airborne magicks.", "マスター・オレーに学んだ生徒。飛行の魔法の達人となった。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A student that has trained under Master Orlu. It has become an expert in airborne magicks.", "マスター・オレーに学んだ生徒。飛行の魔法の達人となった。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valkyrie Thief", "ヴァルキリーの盗賊", Language.Japanese);
            RegisterCard("Valkyrie Thief", "ヴァルキリーの盗賊", "liar liar chicken friar.", "うそつき、うそつき、ニワトリ坊主。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "liar liar chicken friar.", "うそつき、うそつき、ニワトリ坊主。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Maniac", "エメラルドの狂人", Language.Japanese);
            RegisterCard("Emerald Maniac", "エメラルドの狂人", "A crazed maniac.. Drawing out health from the mox..", "狂った男…モックスから体力を引き出している…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A crazed maniac.. Drawing out health from the mox..", "狂った男…モックスから体力を引き出している…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Daemon", "ルビーの悪魔", Language.Japanese);
            RegisterCard("Ruby Daemon", "ルビーの悪魔", "If not properly sustained, it will destroy your hand to fuel itself..", "十分に養われなければ、君の手札を壊して自らの燃料にする…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If not properly sustained, it will destroy your hand to fuel itself..", "十分に養われなければ、君の手札を壊して自らの燃料にする…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Friend", "ジェムの友", Language.Japanese);
            RegisterCard("Gem Friend", "ジェムの友", "fren", "おともだち");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "fren", "おともだち", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Druid", "ドルイド", Language.Japanese);
            RegisterCard("Druid", "ドルイド", "Just look at what you've done..", "自分が何をしたか、見てごらん…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just look at what you've done..", "自分が何をしたか、見てごらん…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chained Legs", "鎖につながれた脚", Language.Japanese);
            RegisterCard("Chained Legs", "鎖につながれた脚", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sealed Body", "封印された体", Language.Japanese);
            RegisterCard("Sealed Body", "封印された体", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bound Arms", "束縛の腕", Language.Japanese);
            RegisterCard("Bound Arms", "束縛の腕", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Imprisoned Tyrant", "囚われの暴君", Language.Japanese);
            RegisterCard("Imprisoned Tyrant", "囚われの暴君", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication mage", "行列の魔術師", Language.Japanese);
            RegisterCard("Multiplication mage", "行列の魔術師", "This cycle can go on forever..", "この循環は永遠に続けられる…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cycle can go on forever..", "この循環は永遠に続けられる…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Invisible mage", "透明な魔術師", Language.Japanese);
            RegisterCard("Invisible mage", "透明な魔術師", "It drank the wrong potion and ended up invisible. How clumsy.", "違う薬を飲んで、透明になってしまった。なんて不器用なんだ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It drank the wrong potion and ended up invisible. How clumsy.", "違う薬を飲んで、透明になってしまった。なんて不器用なんだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Sage", "水晶の賢者", Language.Japanese);
            RegisterCard("Crystal Sage", "水晶の賢者", "A young scholar, profoundly studying mana crystals.", "マナの結晶を深く研究する、若い学者。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A young scholar, profoundly studying mana crystals.", "マナの結晶を深く研究する、若い学者。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Guardian", "ジェム・ガーディアン", Language.Japanese);
            RegisterCard("Gem Guardian", "ジェム・ガーディアン", "The inverse of the Gem Detonator, this one seeks to protect all mox.", "ジェム・デトネとは逆に、すべてのモックスを守ろうとする。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The inverse of the Gem Detonator, this one seeks to protect all mox.", "ジェム・デトネとは逆に、すべてのモックスを守ろうとする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gembound Ripper", "ジェムバウンド・リッパー", Language.Japanese);
            RegisterCard("Gembound Ripper", "ジェムバウンド・リッパー", "It is unstable, but such is the price for unending power.", "不安定だが、それが尽きぬ力の代償だ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is unstable, but such is the price for unending power.", "不安定だが、それが尽きぬ力の代償だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "ジェム喰らい", Language.Japanese);
            RegisterCard("Gem Absorber", "ジェム喰らい", "It seeks out to consume all mana within Mox to grow stronger.", "モックスに宿るすべてのマナを喰らい、強くなろうとする。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seeks out to consume all mana within Mox to grow stronger.", "モックスに宿るすべてのマナを喰らい、強くなろうとする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemagus", "スカルマグス", Language.Japanese);
            RegisterCard("Skelemagus", "スカルマグス", "Great power for a few, fleeting moments..", "強大な力は、ほんの束の間だけ…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great power for a few, fleeting moments..", "強大な力は、ほんの束の間だけ…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelesage", "骨の賢者", Language.Japanese);
            RegisterCard("Skelesage", "骨の賢者", "One of my own Junior Sages, lost and revived.", "かつて失い、蘇った私の若い賢者の一人。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of my own Junior Sages, lost and revived.", "かつて失い、蘇った私の若い賢者の一人。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic Scholar", "苛立つ学徒", Language.Japanese);
            RegisterCard("Erratic Scholar", "苛立つ学徒", "A panicked scholar.. Always running from its problems..", "取り乱した学者…いつも問題から逃げている…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A panicked scholar.. Always running from its problems..", "取り乱した学者…いつも問題から逃げている…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Mage", "モックスの魔術師", Language.Japanese);
            RegisterCard("Mox Mage", "モックスの魔術師", "A Mox disguised as a mage.. It's not going to fool anyone.", "魔術師に化けたモックス…誰も騙されないだろう。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Mox disguised as a mage.. It's not going to fool anyone.", "魔術師に化けたモックス…誰も騙されないだろう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aurumtact", "黄金の錬金術師", Language.Japanese);
            RegisterCard("Aurumtact", "黄金の錬金術師", "An elder scholar, cursed for his greed, entombing anything he touches in pure gold.", "強欲ゆえに呪われた老学者。触れるものすべてを純金に閉じ込める。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elder scholar, cursed for his greed, entombing anything he touches in pure gold.", "強欲ゆえに呪われた老学者。触れるものすべてを純金に閉じ込める。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chained Mox", "連鎖モックス", Language.Japanese);
            RegisterCard("Chained Mox", "連鎖モックス", "A collection of 3 moxen, tangled together, combining their mana energy.", "3個のモックスが絡まり合った集合体。マナの力を一つにしている。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of 3 moxen, tangled together, combining their mana energy.", "3個のモックスが絡まり合った集合体。マナの力を一つにしている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maux", "モークス", Language.Japanese);
            RegisterCard("Maux", "モークス", "In all my years, I have NEVER seen an imitation cruder than this.", "これまで生きてきて、これほど粗末な模倣は見たことがない。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In all my years, I have NEVER seen an imitation cruder than this.", "これまで生きてきて、これほど粗末な模倣は見たことがない。", Language.Japanese);
            RegisterCard("Stim Mage", "ハッスル・メイジ", "It strives to grow stronger, disregarding its own wellbeing..", "自分の身を顧みず、強さを追い求める…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It strives to grow stronger, disregarding its own wellbeing..", "自分の身を顧みず、強さを追い求める…", Language.Japanese);
            RegisterCard("Gourmage", "グルメイジ", "A gluttonous mage who devours the corpses of your fallen to grow stroner.. Disgusting.", "君の倒れた仲間の死体を貪り、強くなる大食らいの魔術師…気色が悪い。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A gluttonous mage who devours the corpses of your fallen to grow stroner.. Disgusting.", "君の倒れた仲間の死体を貪り、強くなる大食らいの魔術師…気色が悪い。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dunce", "おバカな魔術師", Language.Japanese);
            RegisterCard("Dunce", "おバカな魔術師", "This one can never seem to hit its target..", "どうにも狙いに当てられないようだ…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one can never seem to hit its target..", "どうにも狙いに当てられないようだ…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grootslang", "グルートスラング", Language.Japanese);
            RegisterCard("Grootslang", "グルートスラング", "The mere graze of its fangs is enough to kill any creature. No matter the size.", "牙がかするだけで、どんな生物も殺せる。大きさは関係ない。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mere graze of its fangs is enough to kill any creature. No matter the size.", "牙がかするだけで、どんな生物も殺せる。大きさは関係ない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bookworm", "本の虫", Language.Japanese);
            RegisterCard("Bookworm", "本の虫", "A rare kind of insect that absorbs knowledge out of books.", "本から知識を吸収する、珍しい昆虫。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rare kind of insect that absorbs knowledge out of books.", "本から知識を吸収する、珍しい昆虫。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alchemist", "錬金術師", Language.Japanese);
            RegisterCard("Alchemist", "錬金術師", "A supporting one. It brews potions to empower your cards.", "支援役だ。薬を醸して君のカードを強化する。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A supporting one. It brews potions to empower your cards.", "支援役だ。薬を醸して君のカードを強化する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime Mage", "鐘鳴らしの魔術師", Language.Japanese);
            RegisterCard("Chime Mage", "鐘鳴らしの魔術師", "Its chime can prove to be quite annoying..", "その鐘の音は、かなりうるさいものだ…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its chime can prove to be quite annoying..", "その鐘の音は、かなりうるさいものだ…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revivor", "蘇生者", Language.Japanese);
            RegisterCard("Revivor", "蘇生者", "It brings a mage back from the dead, at the cost of its own health.", "自分の体力を代償に、魔術師を死から呼び戻す。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It brings a mage back from the dead, at the cost of its own health.", "自分の体力を代償に、魔術師を死から呼び戻す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rune Mage", "ルーンの魔術師", Language.Japanese);
            RegisterCard("Rune Mage", "ルーンの魔術師", "It conjures explosive runes alongside it when summoned. Not a good idea, I must say.", "召喚されると、両隣に爆発するルーンを生み出す。あまりいい考えとは言えないな。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It conjures explosive runes alongside it when summoned. Not a good idea, I must say.", "召喚されると、両隣に爆発するルーンを生み出す。あまりいい考えとは言えないな。", Language.Japanese);
            RegisterCard("--~~--~~--", "--~~--~~--", "So it arrives.", "そうして、やって来た。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So it arrives.", "そうして、やって来た。", Language.Japanese);
            RegisterCard("~-~-~-~-~-~", "~-~-~-~-~-~", "I foresaw its arrival.", "その到来は予見していた。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I foresaw its arrival.", "その到来は予見していた。", Language.Japanese);
            RegisterCard("~~--~~--~~", "~~--~~--~~", "At last, it is here.", "ついに、ここへ来た。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At last, it is here.", "ついに、ここへ来た。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sniper Sage", "狙撃の賢者", Language.Japanese);
            RegisterCard("Sniper Sage", "狙撃の賢者", "A mage whose training allows it to cast spells from afar.", "修業によって、遠くから呪文を唱えられる魔術師。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage whose training allows it to cast spells from afar.", "修業によって、遠くから呪文を唱えられる魔術師。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rune", "ルーン", Language.Japanese);
            RegisterCard("Rune", "ルーン", "This is the last call, for alcohol.", "お酒のラストオーダーだ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "お酒のラストオーダーだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame", "魔炎", Language.Japanese);
            RegisterCard("Flame", "魔炎", "This is the last call, for alcohol.", "お酒のラストオーダーだ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "お酒のラストオーダーだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabbit", "ウサギ", Language.Japanese);
            RegisterCard("Rabbit", "ウサギ", "This is the last call, for alcohol.", "お酒のラストオーダーだ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "お酒のラストオーダーだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for booze.", "酒のラストオーダーだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for ale.", "エールのラストオーダーだ。", Language.Japanese);
            RegisterCard("Master Goranj", "マスター・グリンジ", "The towering Master Goranj. Not only a caster of fearsome Magicks, but possessed of a sturdy poise as well.", "高くそびえるマスター・グリンジ。恐るべき魔法を操るだけでなく、揺るがぬ構えも備えている。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The towering Master Goranj. Not only a caster of fearsome Magicks, but possessed of a sturdy poise as well.", "高くそびえるマスター・グリンジ。恐るべき魔法を操るだけでなく、揺るがぬ構えも備えている。", Language.Japanese);
            RegisterCard("Master Bleene", "マスター・ブルーン", "The selfless Master Bleene. It shall help you in times of dire need… At the cost of its own ability to defend itself. Admirable.", "無私のマスター・ブルーン。窮地にあれば助けてくれる…自分を守る力を犠牲にして。実に立派だ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The selfless Master Bleene. It shall help you in times of dire need… At the cost of its own ability to defend itself. Admirable.", "無私のマスター・ブルーン。窮地にあれば助けてくれる…自分を守る力を犠牲にして。実に立派だ。", Language.Japanese);
            RegisterCard("Master Orlu", "マスター・オレー", "The great Master Orlu, soaring on pale wings, it attacks from above and draws in cards from below..", "偉大なるマスター・オレー。淡い翼で舞い上がり、上から攻撃し、下からカードを引き寄せる…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The great Master Orlu, soaring on pale wings, it attacks from above and draws in cards from below..", "偉大なるマスター・オレー。淡い翼で舞い上がり、上から攻撃し、下からカードを引き寄せる…", Language.Japanese);
            RegisterCard("Master Magnus", "マスター・マグナス", "my name is.. Shake-Zula! The Mic rula! The Old Schoola! You want a trip? I'll bring it to ya...", "俺の名は…シェイク・ズーラ！マイクの支配者！昔気質の男！刺激が欲しいか？届けてやるぜ…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "my name is.. Shake-Zula! The Mic rula! The Old Schoola! You want a trip? I'll bring it to ya...", "俺の名は…シェイク・ズーラ！マイクの支配者！昔気質の男！刺激が欲しいか？届けてやるぜ…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Magnus", "マスター・マグナス", Language.Japanese);
            RegisterCard("Master Magnus", "マスター・マグナス", "Frylock yeah Im on top rock you like a cop, meatwad you're up next with your knock knock!", "フライロック、そうさ俺がトップ！警官のように揺さぶるぜ。ミートワッド、次はお前のノックノックだ！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frylock yeah Im on top rock you like a cop, meatwad you're up next with your knock knock!", "フライロック、そうさ俺がトップ！警官のように揺さぶるぜ。ミートワッド、次はお前のノックノックだ！", Language.Japanese);
            RegisterCard("Master Magnus", "マスター・マグナス", "Meatwad get the money, see. Meatwad get the honeys, G. ", "ミートワッドは金を稼ぐ、分かるか。ミートワッドはモテるぜ、兄弟。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meatwad get the money, see. Meatwad get the honeys, G. ", "ミートワッドは金を稼ぐ、分かるか。ミートワッドはモテるぜ、兄弟。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phoenix", "フェニックス", Language.Japanese);
            RegisterCard("Phoenix", "フェニックス", "Majestic avian, rumoured to have been an accomplice to Master Orlu...", "威厳ある鳥。マスター・オレーの共犯者だったという…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Majestic avian, rumoured to have been an accomplice to Master Orlu...", "威厳ある鳥。マスター・オレーの共犯者だったという…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleenehound", "宝探しの猟犬", Language.Japanese);
            RegisterCard("Bleenehound", "宝探しの猟犬", "Loyalist canine, rumoured to have been Master Bleene's loyal companion.", "忠実な犬。マスター・ブルーンの忠実な相棒だったという。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loyalist canine, rumoured to have been Master Bleene's loyal companion.", "忠実な犬。マスター・ブルーンの忠実な相棒だったという。", Language.Japanese);
