            RegisterCard("Art of Possesion", "憑依の術", "[c:g2]The Art of Possesion[c:]\n[c:g3]Animating[c:] [c:g1]other[c:] [c:g3]mages[c:] [c:g1]was[c:] [c:g3]considered[c:] [c:g1]taboo[c:] [c:g3]back[c:] [c:g1]when[c:] [c:g3]I[c:] [c:g1]was[c:] [c:g3]around.[c:]", "[c:g2]憑依の術[c:]\n[c:g3]私が[c:][c:g1]いた[c:][c:g3]頃は、[c:][c:g1]ほかの[c:][c:g3]魔術師を[c:][c:g1]魔法で[c:][c:g3]動かす[c:][c:g1]ことは[c:][c:g3]禁忌と[c:][c:g1]見なされて[c:][c:g3]いた。[c:]");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]The Art of Possesion[c:]\n[c:g3]Animating[c:] [c:g1]other[c:] [c:g3]mages[c:] [c:g1]was[c:] [c:g3]considered[c:] [c:g1]taboo[c:] [c:g3]back[c:] [c:g1]when[c:] [c:g3]I[c:] [c:g1]was[c:] [c:g3]around.[c:]", "[c:g2]憑依の術[c:]\n[c:g3]私が[c:][c:g1]いた[c:][c:g3]頃は、[c:][c:g1]ほかの[c:][c:g3]魔術師を[c:][c:g1]魔法で[c:][c:g3]動かす[c:][c:g1]ことは[c:][c:g3]禁忌と[c:][c:g1]見なされて[c:][c:g3]いた。[c:]", Language.Japanese);
