            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A terrible creature of the sea.. Posessing 3 strange and powerful appendages.", "恐ろしい海の生物…奇妙で強力な付属肢を3本持つ。", Language.Japanese);
