            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goobert", "グーバート", Language.Japanese);
            RegisterCard("Goobert", "グーバート", "A replica of my goo mage.. Its loyalty is only matched by its suffering.", "私の粘液の魔術師の複製体…その忠誠に匹敵するのは苦しみだけだ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A replica of my goo mage.. Its loyalty is only matched by its suffering.", "私の粘液の魔術師の複製体…その忠誠に匹敵するのは苦しみだけだ。", Language.Japanese);
