            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Portrait Mage", "肖像の魔術師", Language.Japanese);
            RegisterCard("Portrait Mage", "肖像の魔術師", "Your own creation.. How did it get here?", "君自身の創造物…どうやってここへ来た？");
