            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revitilization", "蘇生術", Language.Japanese);
            RegisterCard("Revitilization", "蘇生術", "This spell casts several healing auras to all of your cards.", "この呪文は、自分のすべてのカードに複数の回復のオーラをかける。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This spell casts several healing auras to all of your cards.", "この呪文は、自分のすべてのカードに複数の回復のオーラをかける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carnage", "殺戮", Language.Japanese);
            RegisterCard("Carnage", "殺戮", "This spell channels raw hellcow energy unto your cards.. Boosting their attack.", "この呪文は、生の地獄牛のエネルギーを君のカードに注ぎ、攻撃力を高める。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This spell channels raw hellcow energy unto your cards.. Boosting their attack.", "この呪文は、生の地獄牛のエネルギーを君のカードに注ぎ、攻撃力を高める。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blizzard", "吹雪", Language.Japanese);
            RegisterCard("Blizzard", "吹雪", "Freeze over your opponents side with a mighty blizzard..", "強大な吹雪で、相手側の場を凍らせる…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freeze over your opponents side with a mighty blizzard..", "強大な吹雪で、相手側の場を凍らせる…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cyclone", "強風の呪文", Language.Japanese);
            RegisterCard("Cyclone", "強風の呪文", "This spell shall summon a whirlwind that boosts your cards into the air.", "この呪文は旋風を召喚し、君のカードを空へ押し上げる。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This spell shall summon a whirlwind that boosts your cards into the air.", "この呪文は旋風を召喚し、君のカードを空へ押し上げる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flood", "洪水", Language.Japanese);
            RegisterCard("Flood", "洪水", "When used, it will summon a tsunami that wipes away the sigils of every card on the board.", "使うと津波を召喚し、盤上のすべてのカードの印を洗い流す。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When used, it will summon a tsunami that wipes away the sigils of every card on the board.", "使うと津波を召喚し、盤上のすべてのカードの印を洗い流す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Engulf", "呑み込む", Language.Japanese);
            RegisterCard("Engulf", "呑み込む", "Select a side of the board to be set ablaze.", "盤の片側を選び、炎上させる。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a side of the board to be set ablaze.", "盤の片側を選び、炎上させる。", Language.Japanese);
            RegisterCard("Engulf", "呑み込む", "Erm.,, erxcsqueeze me sauce?.", "えっと…ソースみません？");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erm.,, erxcsqueeze me sauce?.", "えっと…ソースみません？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ethereal Gems", "虚空のジェム", Language.Japanese);
            RegisterCard("Ethereal Gems", "虚空のジェム", "A frail spirit of a late magnus mox.. Only sustains for a turn.", "死んだマグナス・モックスの脆い霊…一ターンしか持たない。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A frail spirit of a late magnus mox.. Only sustains for a turn.", "死んだマグナス・モックスの脆い霊…一ターンしか持たない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vase of Greed", "強欲の壺", Language.Japanese);
            RegisterCard("Vase of Greed", "強欲の壺", "The vase of greed.. Look at its smug face..", "強欲の壺…あの得意げな顔を見てごらん…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vase of greed.. Look at its smug face..", "強欲の壺…あの得意げな顔を見てごらん…", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gnomification", "ノーム化", Language.Japanese);
