            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conjure a plain old garden gnome on the board..", "盤上に、ごく普通の庭のノームを生み出す…", Language.Japanese);
