            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm, a cursed skull. Handle it with care.", "ふむ、呪われた頭蓋骨だ。扱いには気をつけることだ。", Language.Japanese);
