    public class MagicExpansionMod
    {

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for MagicExpansion Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angry Witch", "憤怒の魔女", Language.Japanese);
            MagnificusMod.RegisterCard("Angry Witch", "憤怒の魔女", "The witch in charge of anger will ignite flames in the opposite battlefield.", "憤怒を司る魔女は、敵側の戦場に炎をともす。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of anger will ignite flames in the opposite battlefield.", "憤怒を司る魔女は、敵側の戦場に炎をともす。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arrogant Witch", "傲慢の魔女", Language.Japanese);
            MagnificusMod.RegisterCard("Arrogant Witch", "傲慢の魔女", "The witch who mastered the power of arrogance appeared with the demon.", "傲慢の力を操る魔女は、悪魔とともに姿を現す。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch who mastered the power of arrogance appeared with the demon.", "傲慢の力を操る魔女は、悪魔とともに姿を現す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee Mage", "コーヒーの魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Coffee Mage", "コーヒーの魔術師", "Mages who love coffee use gems to regulate their breath.", "コーヒー好きの魔術師は、ジェムで息を整える。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mages who love coffee use gems to regulate their breath.", "コーヒー好きの魔術師は、ジェムで息を整える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funny MagiChiking", "愉快な魔法ニワトリ", Language.Japanese);
            MagnificusMod.RegisterCard("Funny MagiChiking", "愉快な魔法ニワトリ", "A smelly Rooster who has learned magic.", "魔法を覚えた、臭い雄鶏。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A smelly Rooster who has learned magic.", "魔法を覚えた、臭い雄鶏。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gluttonous Witch", "暴食の魔女", Language.Japanese);
            MagnificusMod.RegisterCard("Gluttonous Witch", "暴食の魔女", "The witch in charge of gluttony committed a terrible sin.", "暴食を司る魔女は、恐ろしい罪を犯した。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of gluttony committed a terrible sin.", "暴食を司る魔女は、恐ろしい罪を犯した。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greedy Witch", "強欲な魔女", Language.Japanese);
            MagnificusMod.RegisterCard("Greedy Witch", "強欲な魔女", "The witch who controls the power of greed, unfortunately, can only bring value to us after death.", "強欲の力を操る魔女。残念ながら、私たちに価値をもたらすのは死んだあとだけだ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch who controls the power of greed, unfortunately, can only bring value to us after death.", "強欲の力を操る魔女。残念ながら、私たちに価値をもたらすのは死んだあとだけだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inquisitive Witch", "貪欲な魔女", Language.Japanese);
            MagnificusMod.RegisterCard("Inquisitive Witch", "貪欲な魔女", "Nothing is more powerful than her curiosity.", "彼女の好奇心ほど強いものはない。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing is more powerful than her curiosity.", "彼女の好奇心ほど強いものはない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jealous Witch", "嫉妬の魔女", Language.Japanese);
            MagnificusMod.RegisterCard("Jealous Witch", "嫉妬の魔女", "The witch in charge of jealousy has powerful magic and power.", "嫉妬を司る魔女は、強大な魔法と力を持つ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of jealousy has powerful magic and power.", "嫉妬を司る魔女は、強大な魔法と力を持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy Witch", "怠惰の魔女", Language.Japanese);
            MagnificusMod.RegisterCard("Lazy Witch", "怠惰の魔女", "The witch in charge of the power of laziness is really a lazy guy.", "怠惰の力を操る魔女は、本当に怠け者だ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of the power of laziness is really a lazy guy.", "怠惰の力を操る魔女は、本当に怠け者だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lust Witch", "色欲の魔女", Language.Japanese);
            MagnificusMod.RegisterCard("Lust Witch", "色欲の魔女", "The witch in charge of lust, don't look into her eyes.", "色欲を司る魔女。その目を見てはいけない。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of lust, don't look into her eyes.", "色欲を司る魔女。その目を見てはいけない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nine Color Deer", "九色のシカ", Language.Japanese);
            MagnificusMod.RegisterCard("Nine Color Deer", "九色のシカ", "The colorful nine color deer has precious value.", "色鮮やかな九色のシカは、貴重な価値を持つ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The colorful nine color deer has precious value.", "色鮮やかな九色のシカは、貴重な価値を持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stinky MagiChiking", "魔法の臭いチキン", Language.Japanese);
            MagnificusMod.RegisterCard("Stinky MagiChiking", "魔法の臭いチキン", "Hatched by magic eggs.", "魔法の卵から孵った。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hatched by magic eggs.", "魔法の卵から孵った。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Maniac", "爆弾狂", Language.Japanese);
            MagnificusMod.RegisterCard("Bomb Maniac", "爆弾狂", "Even if it detonates itself, it never surrenders to others.", "自爆しても、決して他者には屈しない。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even if it detonates itself, it never surrenders to others.", "自爆しても、決して他者には屈しない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Earl Bunny", "ウサギ伯爵", Language.Japanese);
            MagnificusMod.RegisterCard("Earl Bunny", "ウサギ伯爵", "The versatile Earl Bunny, not everyone can comprehend this art.", "多才なウサギ伯爵。この芸術を理解できるとは限らない。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The versatile Earl Bunny, not everyone can comprehend this art.", "多才なウサギ伯爵。この芸術を理解できるとは限らない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chinese Loong", "中国の龍", Language.Japanese);
            MagnificusMod.RegisterCard("Chinese Loong", "中国の龍", "Diving into the abyss will bring peace to the four seas, flying will protect all things and bring peace, and the dragon's journey of thousands of miles is a sign of good fortune.", "淵に潜れば四海を鎮め、天を飛べば万物を守る。龍がはるかな道を行くことは、どこでも吉兆となる。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diving into the abyss will bring peace to the four seas, flying will protect all things and bring peace, and the dragon's journey of thousands of miles is a sign of good fortune.", "淵に潜れば四海を鎮め、天を飛べば万物を守る。龍がはるかな道を行くことは、どこでも吉兆となる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Wizard", "チーズの魔法使い", Language.Japanese);
            MagnificusMod.RegisterCard("Cheese Wizard", "チーズの魔法使い", "A humorous wizard who is proficient in cooking, his cheese has magical power.", "料理に通じた愉快なウィザード。そのチーズには不思議な魔力がある。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A humorous wizard who is proficient in cooking, his cheese has magical power.", "料理に通じた愉快なウィザード。そのチーズには不思議な魔力がある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Golem", "霜のゴーレム", Language.Japanese);
            MagnificusMod.RegisterCard("Frost Golem", "霜のゴーレム", "Once on the field, there is a strong sense of oppression.", "盤上に現れるだけで、強烈な威圧感が漂う。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once on the field, there is a strong sense of oppression.", "盤上に現れるだけで、強烈な威圧感が漂う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "野球の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Baseball Mage", "野球の魔術師", "His soul is bound under sportswear and can never be liberated.", "その魂はスポーツウェアの下に縛られ、永遠に解放されない。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His soul is bound under sportswear and can never be liberated.", "その魂はスポーツウェアの下に縛られ、永遠に解放されない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raid Mage", "襲撃の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Raid Mage", "襲撃の魔術師", "You will understand how terrifying it is for a robber to master magic.", "強盗が魔法を覚える恐ろしさが、わかるだろう。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will understand how terrifying it is for a robber to master magic.", "強盗が魔法を覚える恐ろしさが、わかるだろう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jade Turtle", "翡翠の魔亀", Language.Japanese);
            MagnificusMod.RegisterCard("Jade Turtle", "翡翠の魔亀", "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "頭から足までエメラルドをまとったカメ。こんな絵が存在するとは、驚くほかない。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "頭から足までエメラルドをまとったカメ。こんな絵が存在するとは、驚くほかない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Cheese", "魔法のチーズ", Language.Japanese);
            MagnificusMod.RegisterCard("Magic Cheese", "魔法のチーズ", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scarlet Cuckoo", "真紅のカッコウ", Language.Japanese);
            MagnificusMod.RegisterCard("Scarlet Cuckoo", "真紅のカッコウ", "The success or failure of the angry magic bird often depends on its face.", "怒れる魔法の鳥。その機嫌が、しばしば成否を左右する。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The success or failure of the angry magic bird often depends on its face.", "怒れる魔法の鳥。その機嫌が、しばしば成否を左右する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spear Apprentice", "槍の弟子", Language.Japanese);
            MagnificusMod.RegisterCard("Spear Apprentice", "槍の弟子", "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "槍の魔術師の弟子。賢い者は、常に次の手を用意しておく。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "槍の魔術師の弟子。賢い者は、常に次の手を用意しておく。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Eye of Darkness", "闇の眼", Language.Japanese);
            MagnificusMod.RegisterCard("The Eye of Darkness", "闇の眼", "This precious pearl was once the devil's eye.", "この貴重な真珠は、かつて悪魔の目だった。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This precious pearl was once the devil's eye.", "この貴重な真珠は、かつて悪魔の目だった。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forest Spell", "森の呪文", Language.Japanese);
            MagnificusMod.RegisterCard("Forest Spell", "森の呪文", "The forest spell obtained from Leshy can provide the most primitive defense.", "レシーから得た森の呪文は、最も原始的な守りをもたらす。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The forest spell obtained from Leshy can provide the most primitive defense.", "レシーから得た森の呪文は、最も原始的な守りをもたらす。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MoxShield", "モックスの魔法盾", Language.Japanese);
            MagnificusMod.RegisterCard("MoxShield", "モックスの魔法盾", "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "ジェムをはめ込んだ魔法の盾。その存在は、いつも安心感を与える。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "ジェムをはめ込んだ魔法の盾。その存在は、いつも安心感を与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nebula Storm", "星雲の嵐", Language.Japanese);
            MagnificusMod.RegisterCard("Nebula Storm", "星雲の嵐", "This cruel storm can directly take away an enemy.", "この残酷な嵐は、敵をそのまま一体さらっていく。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cruel storm can directly take away an enemy.", "この残酷な嵐は、敵をそのまま一体さらっていく。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Contract", "魂の契約", Language.Japanese);
            MagnificusMod.RegisterCard("Soul Contract", "魂の契約", "Perhaps you need more card assistance, and a soul contract is a great choice.", "もっとカードの助けが必要かもしれない。魂の契約は、よい選択だ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you need more card assistance, and a soul contract is a great choice.", "もっとカードの助けが必要かもしれない。魂の契約は、よい選択だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wailing Wall", "慟哭の壁", Language.Japanese);
            MagnificusMod.RegisterCard("Wailing Wall", "慟哭の壁", "Such perseverance even moves the thorny walls to weep.", "その粘り強さには、茨の壁すら涙する。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such perseverance even moves the thorny walls to weep.", "その粘り強さには、茨の壁すら涙する。", Language.Japanese);
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee Time", "コーヒータイム", Language.Japanese);
            MagnificusMod.RegisterAbility("Coffee Time", "コーヒータイム");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] receives the first damage, it gains 2 strength.", "[creature]が初めてダメージを受けると、攻撃力が2増える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Arrogance", "傲慢の死", Language.Japanese);
            MagnificusMod.RegisterAbility("Death of Arrogance", "傲慢の死");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 2 power.", "[creature]が死ぬと、隣接するカードの攻撃力が2増える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Greed", "強欲の死", Language.Japanese);
            MagnificusMod.RegisterAbility("Death of Greed", "強欲の死");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 3 health.", "[creature]が死ぬと、隣接するカードの体力が3増える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Made", "神の被造物", Language.Japanese);
            MagnificusMod.RegisterAbility("God Made", "神の被造物");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Homunculus is created on each empty adjacent space. The Homunculus has : 1 power, 1 health, Familiar.", "[creature]を場に出すと、隣接する各空きマスにホムンクルスが生成される。ホムンクルスは攻撃力1、体力1、使い魔の印を持つ。", Language.Japanese);
            MagnificusMod.RegisterAbility("Fir Caller", "森を呼ぶ者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the empty slot on the cardholder's side is filled with Great Firs. Great Fir has: 0 Power, 3 Health, Mighty Leap.", "[creature]が死ぬと、所有者側の空きスロットがモミの大木で埋まる。モミの大木は攻撃力0、体力3、マイティ・リープの印を持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering Taste", "忘れられない味", Language.Japanese);
            MagnificusMod.RegisterAbility("Lingering Taste", "忘れられない味");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 1 health.", "[creature]が死ぬと、隣接するカードの体力が1増える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love of Cheese", "チーズ愛", Language.Japanese);
            MagnificusMod.RegisterAbility("Love of Cheese", "チーズ愛");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw a cheese card, cheese has: 0 power, 2 health,Lingering Taste.", "[creature]を場に出すと、チーズのカードを一枚引く。チーズは攻撃力0、体力2、忘れられない味の印を持つ。", Language.Japanese);
            // Other
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Expansion", "魔法の拡張パック", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here comes the card of the fantasy world! More content will be added in the future!", "幻想の世界のカードが登場！ 今後もコンテンツを追加予定！", Language.Japanese);
        }
    }
    public class NevernamedsSigilariumMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for NevernamedsSigilarium Mod");
            // Consumable
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NevernamedsSigils", "Nevernamedの印", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pliers", "ペンチ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scissors", "ハサミ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleach", "漂白剤", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skinning Knife", "皮はぎ用ナイフ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fish Hook", "釣り針", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Hand", "デッドハンド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harpie's Birdleg Fan", "ハーピーの脚の扇", Language.Japanese);
