            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Expansion Pack #1", "ケイシーのP03拡張パック #1", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The first expansion pack from the developers of 'P03 in Kaycees Mod' adds [count] new cards across all four regions of Botopia.", "「ケイシーのModのP03」の開発陣による最初の拡張パック。ボットピアの四つの地域すべてに、計[count]枚の新カードを追加する。", Language.Japanese);
