    public class P03ExpansionPack3Mod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for P03ExpansionPack3 Mod");
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gunbot Summoner", "ガンボット召喚士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, play a Gunbot in all empty spaces on the board.", "[creature]を場に出すと、盤上の全ての空きマスにガンボットを出す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sticker Lord", "ステッカーの領主", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all friendly cards get a random sticker.", "[creature]が盤上にいる間、全ての味方カードはランダムなステッカーを得る。", Language.Japanese);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Expansion Pack #3", "ケイシーのP03拡張パック #3", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They said it would never happen, but it's here! The third official expansion pack breaks all of the rules, with [count] new cards that bring bones, blood, and gems to Botopia!", "あり得ないと言われたものが、ついに登場！ 公式第三弾の拡張パックはすべてのルールを破り、[count]枚の新カードで骨、血、ジェムをボットピアに持ち込む！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Encounter Expansion #3", "ケイシーのP03遭遇戦拡張 #3", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[count] additional encounters that feature cards from the third official P03 expansion pack.", "P03の公式第三弾拡張パックのカードを使う、追加エンカウント[count]件。", Language.Japanese);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unpacker", "展開器", Language.Japanese);
            P03InKayceesModMod.RegisterCard("Unpacker", "展開器");
