            P03InKayceesModMod.RegisterCardPart("Necromancer", "ネクロマンサー");
            P03InKayceesModMod.RegisterCardPart("Revenant", "レヴナント");
            P03InKayceesModMod.RegisterCardPart("Sarcophagus", "石棺");
