            P03InKayceesModMod.RegisterCardPart("Gourmage", "グルメイジ");
            P03InKayceesModMod.RegisterCardPart("Master", "マスター");
            P03InKayceesModMod.RegisterCardPart("Magnus", "マグナス");
            P03InKayceesModMod.RegisterCardPart("Practice", "練習相手");
            P03InKayceesModMod.RegisterCardPart("Stim", "ハッスル");

            foreach (var value in P03InKayceesModMod.Cards)
            {
                string name;
                string nameLoc;
                if (value.Key != null && value.Key.ToLowerInvariant().Contains("skel-e"))
                {
                    name = "Skel-E-" + value.Key.Replace(" ", "-");
                    nameLoc = value.Value + "ガイコツ";
                }
                else
                {
                    name = "Skele " + value.Key;
                    nameLoc = value.Value + "外骨格";
                }
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name, nameLoc, Language.Japanese);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beta " + value.Key, value.Value + "ベータ版", Language.Japanese);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser " + value.Key, "幼い" + value.Value, Language.Japanese);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder " + value.Key, "長老" + value.Value, Language.Japanese);
                for (int score = 0; score <= 100; score++)
                {
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, value.Key + " " + score.ToString() + ".0", value.Value + " " + score.ToString() + ".0", Language.Japanese);
                }
                //string[] array = value.Key.Split(new char[] { ' ', '-' });
                //Debug.Log(((array.Length > 1) ? (array[0].ToLowerInvariant().Contains("gem") ? array[1] : array[0]) : (value.Key.Contains("bot") ? value.Key.Replace("bot", "") : value.Key)) + ", " + value.Key + ", " + value.Value);
            }

            // DialogueEvent
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glug glug glug", "ゴボゴボゴボ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We seem to have a [c:bR]tentacle[c:] problem", "[c:bR]触手[c:]の問題が起きているようだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you want to help out, talk to me again.", "手伝いたければ、また話しかけてくれ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you for your help", "手伝ってくれてありがとう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are [c:bR]3[c:] tentacles that need to be destroyed.", "破壊すべき触手が[c:bR]3[c:]本ある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once you've done that, come talk to me again.", "終わったらまた話しかけてくれ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glug glug glug", "ゴボゴボゴボ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have killed [c:bR][v:0][c:] tentacles.", "君は触手を[c:bR][v:0][c:]本倒した。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "See me once you've killed them all.", "全て倒したら会いに来てくれ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glug glug glug", "ゴボゴボゴボ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The scourge of the tentacles has been erased", "触手の災厄は取り除かれた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please take this as a token of my gratitude.", "感謝の印として、これを受け取ってくれ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WARNING! WARNING![c:]", "[c:bR]警告！　警告！[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Unidentified flying objects[c:] have been spotted in the area", "この区域で[c:bR]未確認飛行物体[c:]が目撃された", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should leave [c:bR]immediately[c:] before they return.", "戻ってくる前に[c:bR]すぐ[c:]立ち去るべきだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WARNING! WARNING![c:]", "[c:bR]警告！　警告！[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]UFOs[c:] are arriving!", "[c:bR]UFO[c:]がやって来る！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]CONGRATULATIONS![c:]", "[c:bR]おめでとう！[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]UFOs[c:] have been defeated!", "[c:bR]UFO[c:]は倒された！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And they event left one behind!", "しかも一つ置いていった！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]DISASTER! DISASTER![c:]", "[c:bR]大惨事！　大惨事！[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]UFOs[c:] were victorious!", "[c:bR]UFO[c:]が勝利した！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We may never recover from this failure!", "この失敗から二度と立ち直れないかもしれない！", Language.Japanese);

            // DialogueState
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GLUG GLUG GLUG", "ゴボゴボゴボ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FIGHT THE TENTACLES", "触手と戦え", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FIGHT THE TENTACLES", "触手と戦え", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEATH TO THE TENTACLES", "触手に死を", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WARNING!!!", "警告！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HERE THEY COME!!!", "奴らが来る！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONGRATULATIONS!!!", "おめでとう！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DISASTER!!!", "大惨事！！！", Language.Japanese);
        }
    }
