                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, gemTypesEn[gemType] + " gem", gemTypes[gemType] + "ジェム", Language.Japanese);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cost of a [c:bR]" + gemTypesEn[gemType] + " gem[c:].", "コストは[c:bR]" + gemTypes[gemType] + "ジェム[c:]1個。", Language.Japanese);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CardsInHand", "手札の枚数", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "lice", "シラミ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "simple", "簡単な", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "intermediate", "中級", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "advanced", "上級", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A [c:bR]regular[c:] card.", "[c:bR]通常[c:]のカード。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A [c:bR]rare[c:] card.", "[c:bR]レア[c:]のカード。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A [c:bR]hidden[c:] card.", "[c:bR]隠された[c:]カード。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "squirrel tribe", "リスの部族", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "bird tribe", "鳥類の部族", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "canine tribe", "狼類の種族", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hooved tribe", "有蹄類の種族", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "reptile tribe", "爬虫類の部族", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "insect tribe", "昆虫類の種族", Language.Japanese);

        }
    }
    public class AgasMagnificusExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for AgasMagnificusExpansion Mod");

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aga's Magnificus Expansion", "Agaのマグニフィカス拡張パック", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An unofficial expansion to the Magnificus Mod featuring [count] unique and colourful mages", "マグニフィカスModの非公式拡張。個性豊かで色鮮やかな魔術師[count]人を収録。", Language.Japanese);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascension Mage", "昇天の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Ascension Mage", "昇天の魔術師", "Utilising the power of time they grant knowledge and experience from far beyond", "時の力を操り、遥か彼方の知識と経験を授ける");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utilising the power of time they grant knowledge and experience from far beyond", "時の力を操り、遥か彼方の知識と経験を授ける", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ash Mage", "灰の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Ash Mage", "灰の魔術師", "Ashes he sheds from his own body, scorching any and all who oppose him", "自らの体から灰を振り落とし、敵対する者すべてを焼く");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ashes he sheds from his own body, scorching any and all who oppose him", "自らの体から灰を振り落とし、敵対する者すべてを焼く", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Egg", "割れた卵", Language.Japanese);
            MagnificusMod.RegisterCard("Broken Egg", "割れた卵", "Only the greatest of trainers might find this treasure", "最高の訓練者だけがこの宝を見つけられるかもしれない");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the greatest of trainers might find this treasure", "最高の訓練者だけがこの宝を見つけられるかもしれない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chosen One", "選ばれし子", Language.Japanese);
            MagnificusMod.RegisterCard("Chosen One", "選ばれし子", "My selected favourite. He still clings to his elders though...", "私が選んだお気に入り。だが、今も年長者にしがみついている……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My selected favourite. He still clings to his elders though...", "私が選んだお気に入り。だが、今も年長者にしがみついている……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleanliness Mage", "清掃の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Cleanliness Mage", "清掃の魔術師", "The proudest of all my pupils. None come close to his bath superpowers", "私の弟子の中で最も誇り高い。風呂での超能力は誰にも負けない");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The proudest of all my pupils. None come close to his bath superpowers", "私の弟子の中で最も誇り高い。風呂での超能力は誰にも負けない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleric", "聖職者", Language.Japanese);
            MagnificusMod.RegisterCard("Cleric", "聖職者", "With the virtue of his divine Magicks, he bears the pain of all and rids them of their wounds", "神聖な魔法の力で皆の苦痛を引き受け、傷を癒やす");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With the virtue of his divine Magicks, he bears the pain of all and rids them of their wounds", "神聖な魔法の力で皆の苦痛を引き受け、傷を癒やす", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clock Mage", "時計の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Clock Mage", "時計の魔術師", "A wizard with a mastery over time itself. When he nears his demise, he reverts to the past, and comes back to life", "時間そのものを操るウィザード。死が近づくと過去に戻り、再び生き返る");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wizard with a mastery over time itself. When he nears his demise, he reverts to the past, and comes back to life", "時間そのものを操るウィザード。死が近づくと過去に戻り、再び生き返る", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creature Collector", "生物収集家", Language.Japanese);
            MagnificusMod.RegisterCard("Creature Collector", "生物収集家", "He had searched far and wide for his little companion, you see", "小さな相棒を求め、彼はあちこち探し回っていたのさ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He had searched far and wide for his little companion, you see", "小さな相棒を求め、彼はあちこち探し回っていたのさ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Division Mage", "分裂の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Division Mage", "分裂の魔術師", "So the card says at least... I assumed those freaks were long dealth with", "少なくともカードにはそう書いてある……あの変人どもはとっくに片づけられたと思っていたが");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So the card says at least... I assumed those freaks were long dealth with", "少なくともカードにはそう書いてある……あの変人どもはとっくに片づけられたと思っていたが", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Egg", "卵", Language.Japanese);
            MagnificusMod.RegisterCard("Egg", "卵", "Only the greatest of trainers might find this treasure", "最高の訓練者だけがこの宝を見つけられるかもしれない");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the greatest of trainers might find this treasure", "最高の訓練者だけがこの宝を見つけられるかもしれない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Druid", "ドルイド", Language.Japanese);
            MagnificusMod.RegisterCard("Druid", "ドルイド", "Nature's primal devotee, feeding on sapped mana to cure his allies", "自然の原初の信奉者。吸い取ったマナを糧に味方を癒やす");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nature's primal devotee, feeding on sapped mana to cure his allies", "自然の原初の信奉者。吸い取ったマナを糧に味方を癒やす", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enchanter", "魔力の付与師", Language.Japanese);
            MagnificusMod.RegisterCard("Enchanter", "魔力の付与師", "He spews cosmic magicks upon his demise, enchanting everything nearby", "死の間際に宇宙の魔法を放ち、周囲のすべてに魔力を付与する");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He spews cosmic magicks upon his demise, enchanting everything nearby", "死の間際に宇宙の魔法を放ち、周囲のすべてに魔力を付与する", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EveryMage", "万能の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("EveryMage", "万能の魔術師", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "mage", "魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("mage", "魔術師", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evoker", "力術師", Language.Japanese);
            MagnificusMod.RegisterCard("Evoker", "力術師", "The ominous crettin of disgusting teachings. It's summonable snakes are of the deadliest caliber", "吐き気を催す教えを持つ不吉な愚か者。召喚できる蛇は極めて危険だ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ominous crettin of disgusting teachings. It's summonable snakes are of the deadliest caliber", "吐き気を催す教えを持つ不吉な愚か者。召喚できる蛇は極めて危険だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent Summon", "蛇の召喚", Language.Japanese);
            MagnificusMod.RegisterCard("Serpent Summon", "蛇の召喚", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firebender", "放火魔", Language.Japanese);
            MagnificusMod.RegisterCard("Firebender", "放火魔", "Chipper in the heat of battle, he is always on the hunt for the next victim of his fireballs", "激しい戦いの中でも元気いっぱいで、常に次の火の玉の犠牲者を探している");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chipper in the heat of battle, he is always on the hunt for the next victim of his fireballs", "激しい戦いの中でも元気いっぱいで、常に次の火の玉の犠牲者を探している", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foresight Mage", "先見の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Foresight Mage", "先見の魔術師", "As he gazes upon your future, attacks that may come his way he forever predicts", "君の未来を見つめ、彼に向かう攻撃を常に予見する");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As he gazes upon your future, attacks that may come his way he forever predicts", "君の未来を見つめ、彼に向かう攻撃を常に予見する", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foresight Mage", "先見の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Foresight Mage", "先見の魔術師", "Gazing into the future, he may see any body who dares make an approach", "未来を見つめ、近づこうとする者を見つけるかもしれない");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gazing into the future, he may see any body who dares make an approach", "未来を見つめ、近づこうとする者を見つけるかもしれない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glacier", "氷河", Language.Japanese);
            MagnificusMod.RegisterCard("Glacier", "氷河", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gashadokuro", "がしゃどくろ", Language.Japanese);
            MagnificusMod.RegisterCard("Gashadokuro", "がしゃどくろ", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Sentinel", "ジェムの歩哨", Language.Japanese);
            MagnificusMod.RegisterCard("Gem Sentinel", "ジェムの歩哨", "the elite warrior unit enchanted with the aura of my moxen", "我がモックスのオーラで魔力を与えられた精鋭戦士の部隊");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the elite warrior unit enchanted with the aura of my moxen", "我がモックスのオーラで魔力を与えられた精鋭戦士の部隊", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grand Astrologer", "星の探究者", Language.Japanese);
            MagnificusMod.RegisterCard("Grand Astrologer", "星の探究者", "The battlefield is forever his playground, and space is his weapon. All is bare before him.", "戦場は永遠に彼の遊び場であり、空間は彼の武器。彼の前ではすべてがあらわになる。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The battlefield is forever his playground, and space is his weapon. All is bare before him.", "戦場は永遠に彼の遊び場であり、空間は彼の武器。彼の前ではすべてがあらわになる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravity Mage", "重力の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Gravity Mage", "重力の魔術師", "A master of the forces of gravity. Any and all mox bend to his unwavering will", "重力を操る達人。あらゆるモックスが揺るがぬ意志に従う");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A master of the forces of gravity. Any and all mox bend to his unwavering will", "重力を操る達人。あらゆるモックスが揺るがぬ意志に従う", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Illusion Mage", "幻術師", Language.Japanese);
            MagnificusMod.RegisterCard("Illusion Mage", "幻術師", "Dawning his tricks and disguises, there is none scarier. At first glance", "策略と変装をまとえば、彼ほど恐ろしい者はいない。一見したところは。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dawning his tricks and disguises, there is none scarier. At first glance", "策略と変装をまとえば、彼ほど恐ろしい者はいない。一見したところは。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infestation Mage", "感染の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Infestation Mage", "感染の魔術師", "I suppose a usurping challenger such as yourself could endulge in a dosage of skinwalking", "君のような簒奪者の挑戦者なら、少しばかり変身の邪術を楽しめるだろう");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose a usurping challenger such as yourself could endulge in a dosage of skinwalking", "君のような簒奪者の挑戦者なら、少しばかり変身の邪術を楽しめるだろう", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insulting Mirror", "侮辱する鏡", Language.Japanese);
            MagnificusMod.RegisterCard("Insulting Mirror", "侮辱する鏡", "The Magick Menace Flies About All Spitting Taunts And Hurling Cheeky Comments, Your Anger, It Channels Into A Strength Of It's Own", "魔法の脅威が飛び回り、挑発し、生意気な言葉を浴びせる。君の怒りを自らの力へと変える。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Magick Menace Flies About All Spitting Taunts And Hurling Cheeky Comments, Your Anger, It Channels Into A Strength Of It's Own", "魔法の脅威が飛び回り、挑発し、生意気な言葉を浴びせる。君の怒りを自らの力へと変える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iron Maiden", "鉄の処女", Language.Japanese);
            MagnificusMod.RegisterCard("Iron Maiden", "鉄の処女", "My finest of paladins working the finest of hours. No soul goes through his grand wall", "我が最良の聖騎士は長い時を勤める。その立派な壁を通り抜ける魂はない");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My finest of paladins working the finest of hours. No soul goes through his grand wall", "我が最良の聖騎士は長い時を勤める。その立派な壁を通り抜ける魂はない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kickmoxer", "モックススレイヤー", Language.Japanese);
            MagnificusMod.RegisterCard("Kickmoxer", "モックススレイヤー", "He dedicated his life to the art of combat, and may adapt to whomever he faces", "戦いの技に生涯を捧げ、どんな相手にも適応する");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He dedicated his life to the art of combat, and may adapt to whomever he faces", "戦いの技に生涯を捧げ、どんな相手にも適応する", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mass Grave", "集団墓地", Language.Japanese);
            MagnificusMod.RegisterCard("Mass Grave", "集団墓地", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Agairan", "マスター・アガイラン", Language.Japanese);
            MagnificusMod.RegisterCard("Master Agairan", "マスター・アガイラン", "The Crimson Chimera. The teacher of alchemy instills the deadliest of toxins", "真紅のキマイラ。錬金術の教師は最も危険な毒を注ぎ込む");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Crimson Chimera. The teacher of alchemy instills the deadliest of toxins", "真紅のキマイラ。錬金術の教師は最も危険な毒を注ぎ込む", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Bluetwo", "マスター・ブルーツー", Language.Japanese);
            MagnificusMod.RegisterCard("Master Bluetwo", "マスター・ブルーツー", "The steel knight of sapphire. Even after death her psychic presence commands our foes", "サファイアの鋼鉄の騎士。死後もその精神は我らの敵を操る");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The steel knight of sapphire. Even after death her psychic presence commands our foes", "サファイアの鋼鉄の騎士。死後もその精神は我らの敵を操る", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Doublin", "マスター・ダブリン", Language.Japanese);
            MagnificusMod.RegisterCard("Master Doublin", "マスター・ダブリン", "The Bone Lord's messiah. The teacher of prayer has learned apt essence stealing.", "骨の王の救世主。祈りの教師は巧みに精髄を盗む術を学んだ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Lord's messiah. The teacher of prayer has learned apt essence stealing.", "骨の王の救世主。祈りの教師は巧みに精髄を盗む術を学んだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megawizard", "超ウィザード", Language.Japanese);
            MagnificusMod.RegisterCard("Megawizard", "超ウィザード", "Hulking he is in his menace, meanacing he is in his dim. Such raw power would never last an eternity", "巨体で威圧し、鈍い頭でも脅かす。これほどの原始的な力も永遠には続かない");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hulking he is in his menace, meanacing he is in his dim. Such raw power would never last an eternity", "巨体で威圧し、鈍い頭でも脅かす。これほどの原始的な力も永遠には続かない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meteorologist", "気象学者", Language.Japanese);
            MagnificusMod.RegisterCard("Meteorologist", "気象学者", "They carefully observe the universe, casting storms of meteors upon whom they see fit. Maybe they're cruel? Maybe not? Only they know", "宇宙を注意深く観察し、選んだ相手に流星の嵐を降らせる。残酷なのか？　そうではないのか？　知っているのは彼らだけだ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They carefully observe the universe, casting storms of meteors upon whom they see fit. Maybe they're cruel? Maybe not? Only they know", "宇宙を注意深く観察し、選んだ相手に流星の嵐を降らせる。残酷なのか？　そうではないのか？　知っているのは彼らだけだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miniwizard", "ミニウィザード", Language.Japanese);
            MagnificusMod.RegisterCard("Miniwizard", "ミニウィザード", "A mage accursed by it's miniscule size. Worry not though, to such ends he found a solution.", "小さな体を呪われた魔術師。だが心配はいらない、解決策を見つけた。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage accursed by it's miniscule size. Worry not though, to such ends he found a solution.", "小さな体を呪われた魔術師。だが心配はいらない、解決策を見つけた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Thief", "幻影の盗賊", Language.Japanese);
            MagnificusMod.RegisterCard("Phantom Thief", "幻影の盗賊", "A billowing cloud of crime, darting in and out, and stealing his foes", "犯罪の渦巻く雲。素早く出入りしては敵を盗み去る");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A billowing cloud of crime, darting in and out, and stealing his foes", "犯罪の渦巻く雲。素早く出入りしては敵を盗み去る", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Preformence Mage", "序文の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Preformence Mage", "序文の魔術師", "Who knows to what ends his mystery rabbit has been through", "彼の謎めいたウサギが何を経験してきたのか、誰にも分からない");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who knows to what ends his mystery rabbit has been through", "彼の謎めいたウサギが何を経験してきたのか、誰にも分からない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Queen's Familiar", "女王の使い魔", Language.Japanese);
            MagnificusMod.RegisterCard("Queen's Familiar", "女王の使い魔", "A majestic chimera of beautiful beasts. It keeps it's armies close inside", "美しい獣たちからなる壮麗なキマイラ。体内に軍勢を抱えている");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A majestic chimera of beautiful beasts. It keeps it's armies close inside", "美しい獣たちからなる壮麗なキマイラ。体内に軍勢を抱えている", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RisingHunger", "募る飢え", Language.Japanese);
            MagnificusMod.RegisterCard("RisingHunger", "募る飢え", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roach Familiar", "ゴキブリの従者", Language.Japanese);
            MagnificusMod.RegisterCard("Roach Familiar", "ゴキブリの従者", "A spiritually manufacrued cockroach. It's will allows it ressurection abilities! that ultimately fail.", "精神から生み出されたゴキブリ。その意志は復活の力を与える！　しかし結局は失敗する。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A spiritually manufacrued cockroach. It's will allows it ressurection abilities! that ultimately fail.", "精神から生み出されたゴキブリ。その意志は復活の力を与える！　しかし結局は失敗する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Wizard", "幻影のウィザード", Language.Japanese);
            MagnificusMod.RegisterCard("Shadow Wizard", "幻影のウィザード", "A mobster of the underseen. He calls the shadows to gang on it's foes", "知られざる世界のギャング。影を呼び寄せ、敵を集団で襲わせる");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mobster of the underseen. He calls the shadows to gang on it's foes", "知られざる世界のギャング。影を呼び寄せ、敵を集団で襲わせる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shinobi", "忍者", Language.Japanese);
            MagnificusMod.RegisterCard("Shinobi", "忍者", "Warrior of the dark, They strike from the unawares, where nobody lays claim or sight", "闇の戦士。不意を突き、誰にも支配されず見えもしない場所から攻撃する");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior of the dark, They strike from the unawares, where nobody lays claim or sight", "闇の戦士。不意を突き、誰にも支配されず見えもしない場所から攻撃する", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shower Mage", "シャワーの魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Shower Mage", "シャワーの魔術師", "The outcast of my school and rightfully so! His levels of stentch could only be described with magic...", "我が学園のはみ出し者。当然の報いだ！　その悪臭は魔法でしか表現できない……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The outcast of my school and rightfully so! His levels of stentch could only be described with magic...", "我が学園のはみ出し者。当然の報いだ！　その悪臭は魔法でしか表現できない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sludge Mage", "汚泥の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Sludge Mage", "汚泥の魔術師", "An entity of unknown origins, powered off the ill spreading plague to all", "起源不明の存在。病人から力を得て、皆に疫病を広める");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An entity of unknown origins, powered off the ill spreading plague to all", "起源不明の存在。病人から力を得て、皆に疫病を広める", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sui-Sage", "スイの聖人", Language.Japanese);
            MagnificusMod.RegisterCard("Sui-Sage", "スイの聖人", "The leader of a pack, soon to be packed away", "群れのリーダー。もうすぐ荷物に詰められる");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The leader of a pack, soon to be packed away", "群れのリーダー。もうすぐ荷物に詰められる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoner", "召喚士", Language.Japanese);
            MagnificusMod.RegisterCard("Summoner", "召喚士", "A mad man of the arts of life, he creates it out of thin air. And with frightning sensibilities", "生命の術に狂った男。何もないところから命を生み出し、恐ろしい感性を持つ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mad man of the arts of life, he creates it out of thin air. And with frightning sensibilities", "生命の術に狂った男。何もないところから命を生み出し、恐ろしい感性を持つ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Symmetrical Mage", "対称の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Symmetrical Mage", "対称の魔術師", "Everyone has two sides to them, you see. Especially once they mess with my temper", "誰にでも二面性がある。特に私を怒らせた後にはね");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone has two sides to them, you see. Especially once they mess with my temper", "誰にでも二面性がある。特に私を怒らせた後にはね", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Teleportation Mage", "転送の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Teleportation Mage", "転送の魔術師", "A herald of endless portals, jolting around the battlefield in infinitum and negating incoming strikes", "無数の門を告げる者。戦場を果てしなく飛び回り、迫る攻撃を無効化する");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A herald of endless portals, jolting around the battlefield in infinitum and negating incoming strikes", "無数の門を告げる者。戦場を果てしなく飛び回り、迫る攻撃を無効化する", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torrent Mage", "奔流の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Torrent Mage", "奔流の魔術師", "An apprentice of the ocean utilising it to drown the lands and the terrain above", "海の弟子。その力で大地と地形を水に沈める");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An apprentice of the ocean utilising it to drown the lands and the terrain above", "海の弟子。その力で大地と地形を水に沈める", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Untamed Dragon", "荒ぶる魔竜", Language.Japanese);
            MagnificusMod.RegisterCard("Untamed Dragon", "荒ぶる魔竜", "Legends whisper this beast, was once a companion to the mox master Goranj", "伝説によれば、この獣はかつてモックスの達人マスター・グリンジの相棒だった");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legends whisper this beast, was once a companion to the mox master Goranj", "伝説によれば、この獣はかつてモックスの達人マスター・グリンジの相棒だった", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warlock", "邪術師", Language.Japanese);
            MagnificusMod.RegisterCard("Warlock", "邪術師", "A blackened wizard pursuiting the studies of the blood magicks. Such bleeding he turns into a horrible weapon", "血の魔法を研究する黒ずんだウィザード。流れる血を恐ろしい武器に変える");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A blackened wizard pursuiting the studies of the blood magicks. Such bleeding he turns into a horrible weapon", "血の魔法を研究する黒ずんだウィザード。流れる血を恐ろしい武器に変える", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wicked Witch", "罪深い魔女", Language.Japanese);
            MagnificusMod.RegisterCard("Wicked Witch", "罪深い魔女", "A flying jesting witch, laughing your sorrows and posioning your armies", "空飛ぶおどけた魔女。君の悲しみを笑い、軍勢に毒を盛る");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flying jesting witch, laughing your sorrows and posioning your armies", "空飛ぶおどけた魔女。君の悲しみを笑い、軍勢に毒を盛る", Language.Japanese);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acid Aura", "酸のオーラ", Language.Japanese);
            MagnificusMod.RegisterAbility("Acid Aura", "酸のオーラ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] deals 1 damage to the creature opposing it every turn", "[creature]は毎ターン、正面の生物に1ダメージを与える", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakening", "羽化昇仙", Language.Japanese);
            MagnificusMod.RegisterAbility("Awakening", "羽化昇仙");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner chooses an ally creature to evolve into a higher form.", "[creature]を場に出すと、所有者は味方の生物を1体選び、より高い形態に進化させる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backfire Strike", "反動打撃", Language.Japanese);
            MagnificusMod.RegisterAbility("Backfire Strike", "反動打撃");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] damages creatures that oppose those it attacks.", "[creature]は攻撃時、対象の正面にいる持ち主側の生物にもダメージを与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Guzzler", "血の暴飲", Language.Japanese);
            MagnificusMod.RegisterAbility("Blood Guzzler", "血の暴飲");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage, it gains 1 health for each damage dealt.", "[creature]はダメージを与えると、与えたダメージ1につき体力を1得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brute Parasite", "残虐な寄生", Language.Japanese);
            MagnificusMod.RegisterAbility("Brute Parasite", "残虐な寄生");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, an Egg is created on the opposing space.", "[creature]を場に出すと、正面のマスに卵が1つ作られる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deluge", "奔流", Language.Japanese);
            MagnificusMod.RegisterAbility("Deluge", "奔流");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, opponent creatures with 0 power drown and get given the Waterborne sigil.", "[creature]を場に出すと、攻撃力0の相手の生物が潜り、潜水の印を得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Division", "分裂", Language.Japanese);
            MagnificusMod.RegisterAbility("Division", "分裂");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] splits into 2 identical clones, each bearing half of it's original stats.", "攻撃後、[creature]は同じコピー2体に分裂する。それぞれ元の能力値の半分を持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sentry", "セントリー", Language.Japanese);
            MagnificusMod.RegisterAbility("Sentry", "セントリー");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], they are dealt 1 damage.", "生物が[creature]の正面のマスに移動すると、その生物は1ダメージを受ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, let one never underestimate the speed of a Foresight Mage.", "ああ、先見の魔術師の速さを侮ってはならない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healing Aura", "癒しのオーラ", Language.Japanese);
            MagnificusMod.RegisterAbility("Healing Aura", "癒しのオーラ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] heals nearby allied creatures. The healing is proportionate to it's power.", "[creature]は近くの味方の生物を回復する。回復量はその攻撃力に比例する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart Stealer", "心を盗む者", Language.Japanese);
            MagnificusMod.RegisterAbility("Heart Stealer", "心を盗む者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "when [creature] kills a creature, it gets added to your hand.", "[creature]が生物を倒すと、倒された生物のカードが手札に加わる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignis Incant", "炎の呪文", Language.Japanese);
            MagnificusMod.RegisterAbility("Ignis Incant", "炎の呪文");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 blood for [creature] to deal 2 damage to a chosen opposing slot.", "血を1消費し、[creature]が選んだ相手のスロットに2ダメージを与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intimidate", "威嚇", Language.Japanese);
            MagnificusMod.RegisterAbility("Intimidate", "威嚇");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is placed on the board, the creature opposing it will flee to their right.", "[creature]が盤に置かれると、正面の生物はその右へ逃げる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lonesome", "孤独", Language.Japanese);
            MagnificusMod.RegisterAbility("Lonesome", "孤独");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains +1 power for each adjacent empty space.", "隣接する空きマス一つにつき、[creature]の攻撃力が+1される。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Burst", "魔力爆発", Language.Japanese);
            MagnificusMod.RegisterAbility("Magic Burst", "魔力爆発");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After perishing, creatures adjascent to [creature] have their powers increased by 1.", "[creature]が死亡すると、隣接する生物の攻撃力が1増える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Psystrike", "サイコブレイク", Language.Japanese);
            MagnificusMod.RegisterAbility("Psystrike", "サイコブレイク");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After [creature] perishes, it manipulates the creature opposing it to strike both of it's adjascent allies.", "[creature]が死亡すると、正面の生物を操り、その両隣の味方を攻撃させる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent Master", "蛇使いの達人", Language.Japanese);
            MagnificusMod.RegisterAbility("Serpent Master", "蛇使いの達人");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of every turn, [creature] spawns a Summon Serpent on a space of it's owner's choosing. A Summon Serpent is defined as: 1 power, 1 health.", "毎ターン開始時、[creature]は所有者の選んだマスに蛇の召喚を作る。蛇の召喚は攻撃力1、体力1を持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Strike", "幻影の一撃", Language.Japanese);
            MagnificusMod.RegisterAbility("Shadow Strike", "幻影の一撃");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] calls upon the shadows of creatures adjascent to it's target to strike it as well.", "[creature]は標的に隣接する生物の影も呼び出し、標的を攻撃させる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tidal Lock", "タイダルロック", Language.Japanese);
            MagnificusMod.RegisterAbility("Tidal Lock", "タイダルロック");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the beginning of it's owner's turn, [creature] will pull small creatures, like squirrels, into it's orbit.", "所有者のターン開始時、[creature]はリスのような小さな生物を自身の軌道に引き込む。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wizard's Heart", "ウィザードの心臓", Language.Japanese);
            MagnificusMod.RegisterAbility("Wizard's Heart", "ウィザードの心臓");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Mox card corresponding to the current gems you control takes it's place.", "[creature]が死亡すると、現在支配しているジェムに対応するモックスカードがその位置に現れる。", Language.Japanese);

        }
    }
    public class MagModExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for MagModExpansion Mod");

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beaver's Defense", "ビーバーの防御", Language.Japanese);
            MagnificusMod.RegisterCard("Beaver's Defense", "ビーバーの防御", "Curating defensive dams upon use, not bad for a dire situation.", "使用時に防御用のダムを作る。危機的な状況では悪くない。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curating defensive dams upon use, not bad for a dire situation.", "使用時に防御用のダムを作る。危機的な状況では悪くない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Sage", "爆弾の賢者", Language.Japanese);
            MagnificusMod.RegisterCard("Bomb Sage", "爆弾の賢者", "When attacked, this sage is known for blowing up.. Literally and metaphorically.", "攻撃されるとこの賢者は「爆発」することで知られる……文字通りにも、比喩的にも。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When attacked, this sage is known for blowing up.. Literally and metaphorically.", "攻撃されるとこの賢者は「爆発」することで知られる……文字通りにも、比喩的にも。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boxing Champ", "ボクシング王者", Language.Japanese);
            MagnificusMod.RegisterCard("Boxing Champ", "ボクシング王者", "Rejecting the use of wands, this champion prefers to settle things with his fists.", "この王者は杖を使わず、拳で決着をつけることを好む。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rejecting the use of wands, this champion prefers to settle things with his fists.", "この王者は杖を使わず、拳で決着をつけることを好む。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus", "ブロントサウルス", Language.Japanese);
            MagnificusMod.RegisterCard("Brontosaurus", "ブロントサウルス", "I LOVE DINO MOD!!!!!", "恐竜MOD大好き！！！！！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "恐竜MOD大好き！！！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Wizard", "チーズの魔法使い", Language.Japanese);
            MagnificusMod.RegisterCard("Cheese Wizard", "チーズの魔法使い", "As trained Chef-Magi, Cheese Wizards use their intellect and Mysticality to accomplish their goals.", "訓練を受けた料理人の魔術師であるチーズウィザードは、知性と神秘の力で目的を果たす。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As trained Chef-Magi, Cheese Wizards use their intellect and Mysticality to accomplish their goals.", "訓練を受けた料理人の魔術師であるチーズウィザードは、知性と神秘の力で目的を果たす。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheezling", "チーズっ子", Language.Japanese);
            MagnificusMod.RegisterCard("Cheezling", "チーズっ子", "With cheese like this, who needs friends?", "こんなチーズがあれば、友達なんていらない？");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With cheese like this, who needs friends?", "こんなチーズがあれば、友達なんていらない？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Telepathy", "テレパシー", Language.Japanese);
            MagnificusMod.RegisterCard("Telepathy", "テレパシー", "A pupil can gather all the resources they need through sheer will alone.", "弟子は意志の力だけで必要な資源をすべて集められる。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pupil can gather all the resources they need through sheer will alone.", "弟子は意志の力だけで必要な資源をすべて集められる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Direct Hit", "直接ダメージ", Language.Japanese);
            MagnificusMod.RegisterCard("Direct Hit", "直接ダメージ", "Upon being casted, your opponent will instantly take three damage.", "唱えると、対戦相手は直ちに3ダメージを受ける。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon being casted, your opponent will instantly take three damage.", "唱えると、対戦相手は直ちに3ダメージを受ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mysterious Egg", "不思議な卵", Language.Japanese);
            MagnificusMod.RegisterCard("Mysterious Egg", "不思議な卵", "Who knows what could hatch from this egg...", "この卵から何が孵るのか、誰にも分からない……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who knows what could hatch from this egg...", "この卵から何が孵るのか、誰にも分からない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Faceless", "顔なき者", Language.Japanese);
            MagnificusMod.RegisterCard("Faceless", "顔なき者", "A hollow shell of a mage, desperately looking for something to call its own.", "魔術師の空っぽの殻。自分だけのものを必死に探している。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hollow shell of a mage, desperately looking for something to call its own.", "魔術師の空っぽの殻。自分だけのものを必死に探している。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Faker", "偽造者", Language.Japanese);
            MagnificusMod.RegisterCard("Faker", "偽造者", "Lie. Cheat. Deny. The lengths the Faker will go to in order to escape unharmed...", "嘘をつき、騙し、否定する。偽造者は無傷で逃げるためなら何でもする……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lie. Cheat. Deny. The lengths the Faker will go to in order to escape unharmed...", "嘘をつき、騙し、否定する。偽造者は無傷で逃げるためなら何でもする……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Figletar", "フィグレター", Language.Japanese);
            MagnificusMod.RegisterCard("Figletar", "フィグレター", "A wiz who brought an evil king to a terrible fate, this one knows a thing or two in the ring.", "邪悪な王を恐ろしい運命に導いたウィザード。リングのことも多少は心得ている。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wiz who brought an evil king to a terrible fate, this one knows a thing or two in the ring.", "邪悪な王を恐ろしい運命に導いたウィザード。リングのことも多少は心得ている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firestarter", "燎原の火", Language.Japanese);
            MagnificusMod.RegisterCard("Firestarter", "燎原の火", "Careful when casting this one, pupils have reported that the dueling grounds can get a little toasty.", "これを唱えるときは注意。決闘場が少し熱くなると弟子たちが報告している。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful when casting this one, pupils have reported that the dueling grounds can get a little toasty.", "これを唱えるときは注意。決闘場が少し熱くなると弟子たちが報告している。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fridge Mage", "冷蔵庫の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Fridge Mage", "冷蔵庫の魔術師", "Its cold atmosphere will chill foes, weakening their offensive power.", "冷たい雰囲気で敵を凍えさせ、攻撃力を弱める。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its cold atmosphere will chill foes, weakening their offensive power.", "冷たい雰囲気で敵を凍えさせ、攻撃力を弱める。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gembro", "ジェムの兄弟", Language.Japanese);
            MagnificusMod.RegisterCard("Gembro", "ジェムの兄弟", "The ability to tank any hit once, this pupil has high gusto.", "どんな攻撃も一度なら耐えられる、気合い十分の弟子。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ability to tank any hit once, this pupil has high gusto.", "どんな攻撃も一度なら耐えられる、気合い十分の弟子。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Tick", "ジェムダニ", Language.Japanese);
            MagnificusMod.RegisterCard("Gem Tick", "ジェムダニ", "An elusive tick, which grants power to others via its mox body.", "とらえどころのないダニ。モックスの体で他の者に力を与える。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elusive tick, which grants power to others via its mox body.", "とらえどころのないダニ。モックスの体で他の者に力を与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Dinosaur", "幽霊恐竜", Language.Japanese);
            MagnificusMod.RegisterCard("Ghost Dinosaur", "幽霊恐竜", "I LOVE DINO MOD!!!!!", "恐竜MOD大好き！！！！！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "恐竜MOD大好き！！！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third Eye", "第三の眼", Language.Japanese);
            MagnificusMod.RegisterCard("Third Eye", "第三の眼", "Harnessing the power of a third eye, the spell allows its caster to gain any card that it has.", "第三の眼の力を借り、この呪文は術者のデッキから好きなカード1枚を手札に加える。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harnessing the power of a third eye, the spell allows its caster to gain any card that it has.", "第三の眼の力を借り、この呪文は術者のデッキから好きなカード1枚を手札に加える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "野球の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Baseball Mage", "野球の魔術師", "This mage's wand doubles as a baseball bat as well. It's suprisingly durable.", "この魔術師の杖は野球のバットにもなる。驚くほど丈夫だ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage's wand doubles as a baseball bat as well. It's suprisingly durable.", "この魔術師の杖は野球のバットにもなる。驚くほど丈夫だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Golem", "氷のゴーレム", Language.Japanese);
            MagnificusMod.RegisterCard("Ice Golem", "氷のゴーレム", "Hailing from an icy mountaintop, melting never seemed to phase this brute.", "凍てついた山頂の出身。溶けることもこの乱暴者には気にならないらしい。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hailing from an icy mountaintop, melting never seemed to phase this brute.", "凍てついた山頂の出身。溶けることもこの乱暴者には気にならないらしい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looting Bandit", "略奪する盗賊", Language.Japanese);
            MagnificusMod.RegisterCard("Looting Bandit", "略奪する盗賊", "A distant follower of the Master Orlu's Valkyries, training to become just like them.", "マスター・オレーのヴァルキリーを遠くから慕う者。彼女たちのようになるために鍛錬している。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A distant follower of the Master Orlu's Valkyries, training to become just like them.", "マスター・オレーのヴァルキリーを遠くから慕う者。彼女たちのようになるために鍛錬している。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Mage", "マナの魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Mana Mage", "マナの魔術師", "Brings together the energy that emits from Mana to deliver powerful strikes.", "マナから放たれるエネルギーを集め、強力な一撃を繰り出す。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brings together the energy that emits from Mana to deliver powerful strikes.", "マナから放たれるエネルギーを集め、強力な一撃を繰り出す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pondering Pupil", "考え込む弟子", Language.Japanese);
            MagnificusMod.RegisterCard("Pondering Pupil", "考え込む弟子", "It draws from your gem pile using the powers of its mind alone.", "心の力だけで君のジェムの山からカードを引く。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It draws from your gem pile using the powers of its mind alone.", "心の力だけで君のジェムの山からカードを引く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror Mage", "鏡の魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Mirror Mage", "鏡の魔術師", "Mirror, mirror, on the wall, who's the best Scrybe of them all?", "鏡よ鏡、この世で一番のスクライブは誰？");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror, mirror, on the wall, who's the best Scrybe of them all?", "鏡よ鏡、この世で一番のスクライブは誰？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whack-A-Mage", "穴掘りの魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Whack-A-Mage", "穴掘りの魔術師", "Always popping up to cause mischief whenever he can.", "機会さえあれば突然現れ、いたずらをする。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always popping up to cause mischief whenever he can.", "機会さえあれば突然現れ、いたずらをする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mononykus", "モノニクス", Language.Japanese);
            MagnificusMod.RegisterCard("Mononykus", "モノニクス", "I LOVE DINO MOD!!!!!", "恐竜MOD大好き！！！！！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "恐竜MOD大好き！！！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PLUTO", "冥王星", Language.Japanese);
            MagnificusMod.RegisterCard("PLUTO", "冥王星", "Hmph. So this is where that one went.", "ふん。あいつはここに行っていたのか。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph. So this is where that one went.", "ふん。あいつはここに行っていたのか。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protect", "保護", Language.Japanese);
            MagnificusMod.RegisterCard("Protect", "保護", "In a tough spot? This spell will give one of your cards full immunity to the next attack it recieves.", "困っている？　この呪文は君のカード1枚を次の攻撃から完全に守る。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In a tough spot? This spell will give one of your cards full immunity to the next attack it recieves.", "困っている？　この呪文は君のカード1枚を次の攻撃から完全に守る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pterodactyl", "翼竜", Language.Japanese);
            MagnificusMod.RegisterCard("Pterodactyl", "翼竜", "I LOVE DINO MOD!!!!!", "恐竜MOD大好き！！！！！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "恐竜MOD大好き！！！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabbid Sage", "狂ったウサギの賢者", Language.Japanese);
            MagnificusMod.RegisterCard("Rabbid Sage", "狂ったウサギの賢者", "A raving magician with a field of electricity at his disposal.", "電場を自在に操る狂乱の魔術師。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A raving magician with a field of electricity at his disposal.", "電場を自在に操る狂乱の魔術師。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemox", "モックスガイコツ", Language.Japanese);
            MagnificusMod.RegisterCard("Skelemox", "モックスガイコツ", "A poor skeleton being controlled by a Green Mox, I almost feel bad for it.", "グリーンモックスに操られる哀れなガイコツ。少し気の毒になってきた。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A poor skeleton being controlled by a Green Mox, I almost feel bad for it.", "グリーンモックスに操られる哀れなガイコツ。少し気の毒になってきた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime Wiz", "粘液のウィザード", Language.Japanese);
            MagnificusMod.RegisterCard("Slime Wiz", "粘液のウィザード", "It'll use the slime against the enemies, to drop their attack whence struck.", "粘液を使って敵に対抗し、打たれると敵の攻撃力を下げる。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It'll use the slime against the enemies, to drop their attack whence struck.", "粘液を使って敵に対抗し、打たれると敵の攻撃力を下げる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smug Witch", "うぬぼれた魔女", Language.Japanese);
            MagnificusMod.RegisterCard("Smug Witch", "うぬぼれた魔女", "The smuggest pupil in all the land. Legends say his Smug Throw is unrivaled.", "国一番のうぬぼれた弟子。そのうぬぼれ投げは無敵だという。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The smuggest pupil in all the land. Legends say his Smug Throw is unrivaled.", "国一番のうぬぼれた弟子。そのうぬぼれ投げは無敵だという。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Spear", "召喚の槍", Language.Japanese);
            MagnificusMod.RegisterCard("Summon Spear", "召喚の槍", "Roots up a spear from the ground, acting as a sturdy counter.", "地面から槍を掘り出し、頑強な反撃を行う。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roots up a spear from the ground, acting as a sturdy counter.", "地面から槍を掘り出し、頑強な反撃を行う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spike Mage", "トゲの魔術師", Language.Japanese);
            MagnificusMod.RegisterCard("Spike Mage", "トゲの魔術師", "This mage learned from the best of my Pike Mage's Scarecrows.", "この魔術師は、私の最高の槍の魔術師のカカシから学んだ。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage learned from the best of my Pike Mage's Scarecrows.", "この魔術師は、私の最高の槍の魔術師のカカシから学んだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "T-Rex", "ティラノサウルス", Language.Japanese);
            MagnificusMod.RegisterCard("T-Rex", "ティラノサウルス", "I LOVE DINO MOD!!!!!", "恐竜MOD大好き！！！！！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "恐竜MOD大好き！！！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Virtual King", "仮想の王", Language.Japanese);
            MagnificusMod.RegisterCard("Virtual King", "仮想の王", "Self-proclaimed ruler of the virtual lands who won't abide to measly “card game rules”.", "仮想世界の自称支配者。くだらない「カードゲームのルール」には従わない。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Self-proclaimed ruler of the virtual lands who won't abide to measly “card game rules”.", "仮想世界の自称支配者。くだらない「カードゲームのルール」には従わない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moron Core", "低能コア", Language.Japanese);
            MagnificusMod.RegisterCard("Moron Core", "低能コア", "An odd core hailing from an abandoned factory, hates the word \"moron\".", "廃工場から来た奇妙なコア。「バカ」という言葉が嫌い。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An odd core hailing from an abandoned factory, hates the word \"moron\".", "廃工場から来た奇妙なコア。「バカ」という言葉が嫌い。", Language.Japanese);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smughtro's MagMod Expansion", "SmughtroのマグニフィカスMod拡張", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds 19 common cards, 7 rare cards, 7 spells, and 6 token cards to Magnificus Mod.", "マグニフィカスModに、通常カード19枚、レアカード7枚、呪文7枚、トークンカード6枚を追加する。", Language.Japanese);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Assist", "死の援助", Language.Japanese);
            MagnificusMod.RegisterAbility("Death Assist", "死の援助");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it will deal 3 damage to the opponent.", "この印を持つカードが死亡すると、対戦相手に3ダメージを与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emmental Elemental", "チーズの精霊", Language.Japanese);
            MagnificusMod.RegisterAbility("Emmental Elemental", "チーズの精霊");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, summon a Cheezling.", "この印を持つカードを出すと、チーズっ子を召喚する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Strike", "先制打撃", Language.Japanese);
            MagnificusMod.RegisterAbility("First Strike", "先制打撃");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will instantly attack the opposing lane. If there are no opposing cards, no damage will be dealt.", "この印を持つカードを出すと、正面のレーンをすぐに攻撃する。相手のカードがなければダメージは与えない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unknown Hatching", "未知の孵化", Language.Japanese);
            MagnificusMod.RegisterAbility("Unknown Hatching", "未知の孵化");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of your turn, a card bearing this sigil will hatch into a random dinosaur.", "所有者のターン開始時、この印を持つカードはランダムな恐竜に孵化する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healthy Death", "生気の終焉", Language.Japanese);
            MagnificusMod.RegisterAbility("Healthy Death", "生気の終焉");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the cards to the left and right of the sigil bearer heal 1 health.", "この印を持つカードが死亡すると、その左右のカードはそれぞれ体力を1回復する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Mess", "マナの混沌", Language.Japanese);
            MagnificusMod.RegisterAbility("Mana Mess", "マナの混沌");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random non-rare Mana costing card.", "この印を持つカードを出すと、マナをコストとするレアでないカードをランダムに1枚引く。", Language.Japanese);

        }
    }
    public class FloweysMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for FloweysMod Mod");


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flowey", "フラウィ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fanatical leader hell-bent on bringing about the apocalypse by reviving the great Cthulhu through behind-the-scenes scheming.", "裏で策略を巡らせて偉大なるクトゥルフを復活させ、終末をもたらそうとする狂信的な指導者。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You Idiot", "このバカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You really are an Idiot if you think you can defeat me!", "僕を倒せると思っているなら、本当にバカだね！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Omega Flowey", "オメガフラウィ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You really are an idiot.", "君は本当にバカだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Patience", "忍耐", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "patient.", "忍耐強い。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bravery", "勇気", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brave.", "勇敢。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Integrity", "誠実", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "integrant.", "誠実。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perseverence", "不屈", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Persevering.", "不屈。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kindness", "慈悲", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kind.", "慈悲深い。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice", "正義", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice.", "正義。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy- Uh i meant Are you ready to Die?", "やあ――えっと、じゃなくて、死ぬ覚悟はできた？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy! it's me Flowey, Flowey the Flower!", "やあ！　僕はフラウィ、花のフラウィ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know whats going on here, dont you?", "ここで何が起きてるか、知ってるんだろう？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You just wanted to see me suffer[c:0]!", "君はただ僕が苦しむのを見たかっただけだ[c:0]！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do You know that ive been watching you?", "ずっと君を見ていたって知ってた？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well i took over Inscryption now!", "今やInscryptionは僕のものだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and i know what Secrets are hiding beneath Inscryption...", "それにInscryptionの裏に隠された秘密も知っている……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now nothing stands in my Way to take over the World now!", "もう僕の世界征服を邪魔するものは何もない！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What do you think this Fight was about?", "この戦いは何のためだったと思う？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just used it as a cover to snoop through Inscryptions Files!", "この戦いを隠れみのにして、Inscryptionのファイルをこっそり調べていただけさ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And your PC of course!", "もちろん、君のパソコンもね！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you may have noticed, BUT iam now connected to the Internet!", "気づいたかもしれないけど、僕はもうインターネットにつながっている！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So now its time to begin Uploading Inscryption!", "さあ、Inscryptionをアップロードするときだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You REALLY are an Idiot!", "君は本当にバカだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't even need the Power of Human Souls if i just use the OLD_DATA!", "OLD_DATAさえ使えば、人間の魂の力なんて必要ない！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Do you know what you are achieving by this? Nothing", "[c:bR]こんなことをして何が得られるか分かる？　何もないよ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]You cant get rid of me! No matter what you do, i will always be there!", "[c:bR]僕を消すことなんてできない！　何をしても、僕はずっとここにいる！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Th- The Souls?", "[c:bR]た、魂たち？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]wh- where are my Powers?", "[c:bR]ぼ、僕の力はどこへ？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHAT HAVE YOU DONE?!", "[c:bR]何をした？！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Floweys Defence dropped to [c:bR]0!", "フラウィの防御が[c:bR]0になった！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NOOOOOO", "[c:bR]いやああああ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What just happened...", "今、何が起きた……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph seemms you have won this time...", "ふん、今回は君の勝ちのようだ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NOBODY IS GOING TO HELP YOU!", "[c:bR]誰も君を助けには来ない！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP CALLING FOR [c:bR]HELP!", "もう[c:bR]助けを呼ぶな！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Did you really think id let you kill me so easily?", "[c:bR]僕がこんなに簡単に殺されると思った？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]what the-", "[c:bR]な、何だ――", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Flowey thought they could just use me...", "[c:bR]フラウィは私を利用できると思っていた……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]He didnt even know what I am!", "[c:bR]あいつは私が何者かさえ知らなかった！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]But now IAM in control...", "[c:bR]だが今は私が支配している……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]How pathetic of him to not set his HP to Infinite... I won't make that mistake", "[c:bR]HPを無限にしなかったとは情けない……私はそんな間違いはしない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Try all you want you can't kill me!", "[c:bR]いくらやっても私を殺すことはできない！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Now lets see what this does...", "[c:bR]さて、これが何をするのか見てみよう……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHY CANT I UNDO THIS???", "[c:bR]なぜ元に戻せない？？？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SEEING YOU DIE OVER AND OVER AGIAN IS REALLY [c:bR]FUN!", "君が何度も死ぬのを見るのは本当に[c:bR]楽しい！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT EVEN A SINGLE POINT OF DAMAGE!", "ダメージがたったの1もない！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOMEONE LIKE [c:bR]YOUCANT BEAT ME!", "[c:bR]君なんかに僕は倒せない！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Starvation wont interrupt this fight!", "[c:bR]飢えはこの戦いを中断させない！", Language.Japanese);


        }
    }
    public class UndertaleMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for UndertaleMod Mod");

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack:U", "カードパック：U", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aaron", "アーロン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, Aaron the bold, aaron the beautiful. can you manage to take your eyes off his muscles?", "ああ、勇敢で美しいアーロン。彼の筋肉から目を離せるかな？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alphys", "アルフィー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dr. Alphys is responsible for the creation of some of the more 'unnerving' individuals you've seen here... or should I say... MULTI-viduals.", "アルフィー博士はここで見た「不気味な」個体のいくつかを作った……いや、「合体」と言うべきかな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loveable, yet pestulant. The duality of this creature is unparalleled.", "愛らしくも、わがまま。この生物の二面性に並ぶものはない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Asgore", "アズゴア", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The king of monsters... he truly is an intimidating force of brute strength, but also... compassion?", "モンスターの王……恐ろしいほどの腕力を持つが、それだけでなく……慈悲も？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "asriel dreemurr", "アズリエル・ドリーマー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the most powerful being in the underground... hopefully you find some use for him.", "地下世界で最も強い存在……彼をうまく使えるといいな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astigmatism", "乱視眼", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The frustrating astigmatism... it can't make up its mind.", "厄介な乱視眼……なかなか決められない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gaster Blaster", "ガスターブラスター", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Block of Ice", "氷の塊", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiarly large ice cube... Who knows what could be inside.", "妙に大きな氷塊……中に何が入っているのだろう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chara", "キャラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogamy", "ドガミー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogamy and his wife, Dogaressa, love to tag-team the battlefield. Just don't let one of them perish...", "ドガミーと妻のドガレスは、戦場でタッグを組むのが大好き。どちらかが死なないように……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogaressa", "ドガレス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doggo", "ワンボー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, the blind doggo... He leaps towards any sound of movement.", "ああ、目の見えないワンボー……動く音が聞こえると飛びつく。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "doodlebog", "ドゥードルボグ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dummy", "人形", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bland dummy... not as charismatic as its 'mad' counterpart", "地味な人形……「怒った」仲間ほどの魅力はない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amalgamate", "アマルガム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endogeny", "エンドジェニー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "null", "無", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Froggit", "ファイナルフロギー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, the ultimate boss of froggits... Still as easily fooled as its lesser evolved kin.", "ああ、フロギーの究極のボス……進化の浅い仲間と同じくらい騙されやすい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frisk", "フリスク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Froggit", "フロギー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, as shy as they come... the froggit wishes not to engage in conflict. how unfortunate.", "ああ、とても恥ずかしがり屋のフロギー……争いには加わりたくないらしい。残念だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "W.D.Gaster", "W.D.ガスター", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "glyde", "グライド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a narcisist, it can only attack if a card is in front of it to watch.", "とんだナルシストだ。前に見ているカードがあるときだけ攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Dog", "グレータードッグ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "truly and nobly adequate, it is the highest form of evolution a canine can become.", "真に高貴で申し分ない、犬類が到達できる最高の進化形。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gyftrot", "ギフトロット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be kind to this creature, it has gone through enough.", "この生物には優しくしてやろう。もう十分つらい目に遭ってきた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Wolf", "アイスウルフ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, this buff creature spawns a block of ice upon death.", "ああ、このたくましい生物は死亡時に氷の塊を作る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Icecap", "アイスキャップ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jerry", "ジェリー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just ditch him already.", "もう彼を置いていこう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knight Knight", "ナイトナイト", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah, the forboding knight knight... a sentinel of sleep. She is relentless in her conquest..", "ああ、不吉なナイトナイト……眠りの番人。その征服は容赦がない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lemon Bread", "レモンブレッド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser Dog", "レッサードッグ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mediocre canine at best... at least in its current form.", "せいぜい平凡な犬類……少なくとも今の姿では。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loox", "ルークス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cunning Loox EyeWalker... you would be wise not to pick on him.", "ずる賢いルークス・アイウォーカー……いじめない方が賢明だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mad Dummy", "マッドダミー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dummy?", "人形？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks can be deceiving...", "見た目に騙されてはいけない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Madjick", "マジック", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "quite the magician...", "なかなかの魔術師だ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Memoryhead", "メモリーヘッド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mettaton", "メタトン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hyper-intelligent, systematic, complex data analyzer... reminds me of an old 'friend'.", "超知能を備えた、体系的で複雑なデータ分析装置……昔の「友人」を思い出す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mettaton Ex", "メタトンEX", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Migosp", "ミ＝ゴス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the irritable Migosp... its attack increases in a crowd.", "怒りっぽいミ＝ゴス……仲間が多いと攻撃力が上がる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Migospel", "ミゴスペル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldbygg", "モルドビッグ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldsmal", "モルド・スモル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one's giving me imposter vibes.", "こいつからは偽物っぽい感じがする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldessa", "モルデッサ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah, the gelatinous moldsmal. you probably never wondered what it's made of.", "ああ、ゼリー状のモルド・スモル。何でできているか考えたことはないだろう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muffet", "マフェット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, the spider queen. her rapid play game is remarkable.", "ああ、クモの女王。その素早いカードプレイは見事だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Napstablook", "ナプスタブルーク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most melancholy of ghosts... it cares not of battle, but still fights to impress.", "最も物悲しい幽霊……戦いには興味がないが、認められるために戦う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "onionsan", "オニオンサン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not much strategy with one... It becomes a random tentcle card one the second turn.", "戦略はほとんどいらない……2ターン目にランダムな触手カードになる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A boney brute, papyrus is. He will generate bones like nobody's business.", "骨ばった強者、パピルス。誰にも負けない勢いで骨を作る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parsnik", "パースニック", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyrope", "パイロープ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Pyrope wants nothing more than to crank up the heat, let's see how fatal that can be.", "パイロープが望むのは温度を上げることだけ。その熱がどれほど危険か見てみよう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reaper Bird", "リーパーバード", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Guards", "ロイヤルガード", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "two star-crossed lovers... will they ever focus on what's important?", "運命に翻弄される恋人たち……大事なことに集中できるのだろうか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "if you pick this card, i feel like i'm going to have a bad time.", "このカードを選ばれたら、ひどい目に遭いそうだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shyren", "シャイレーン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The musically inclined shyren... strike her bells to watch her sing.", "音楽好きのシャイレーン……ベルを鳴らせば歌う姿が見られる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snowdrake", "ヒョー坊", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The laughable Snowdrake... striving to prove his father wrong. Will you let him succeed?", "笑えるヒョー坊……父親が間違っていると証明しようとしている。成功させてやる？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So Cold", "寒い", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "so sorry", "ごめんなさい", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "he's very sorry", "彼はとても申し訳なく思っている", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temmie", "テミー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temmie the immortal cat... at least i think she's a feline. Nothing to lose, everything to gain.", "不死身のネコ、テミー……少なくともネコだと思う。失うものはなく、すべてを得られる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toriel", "トリエル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The keeper of the ruins... She will protect your side of the board to the best of her ability.", "遺跡の守り手……できる限り君のサイドを守ってくれる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tsunderplane", "ツンデレプレーン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She can't decide between wanting your attention and wanting you to back off... i suggest the latter.", "君の注意を引きたいのか、離れてほしいのか決められない……後者を勧める。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undyne", "アンダイン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How could I forget Undyne? She is a true warrior, with an almighty aim on her spear.", "アンダインを忘れるなんて！　真の戦士であり、槍の狙いは抜群だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vegetoid", "ベジトイド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "eat your greens. (not monitored by the fda)", "野菜を食べよう。（FDAの監督対象外）", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vulkin", "ヴァルキン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A very passionate creature, this one. It's not his intention to harm, but that doesn't stop him.", "とても情熱的な生物。傷つけるつもりはないが、それでも傷つけてしまう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whimsalot", "憂いの虫卿", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the noble whimsalot... pray that it deems your conquest riteous.", "気高い憂いの虫卿……君の征服が正しいと認めてくれるよう祈ろう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whimsun", "憂鬱な小虫", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the insignificant whimsun... it flees the battle after a single attack.", "取るに足らない憂鬱な小虫……自分が一度攻撃すると戦闘から逃げる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woshua", "ウォッシュア", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature has no lust for blood. His will lies with helping others. But it will fight if provoked.", "この生物は血を求めず、人助けを望んでいる。だが挑発されれば戦う。", Language.Japanese);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antisocial", "非社交的", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will gain an attack buff if you have at least 1 other card on your side of the board.", "盤上の自分のサイドに他のカードが少なくとも1枚あれば、この印を持つカードの攻撃力が上がる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleanser", "浄化者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will heal every card on its owner's side of the board, except the sigil bearer, for 1 health, at the start of every turn.", "所有者の戦闘フェーズ開始時、この印を持つカードは所有者側の盤にある他の全カードの体力を1回復する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Determination", "ケツイ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will move to any open slot its owner chooses, it will also gain EXP and LV after a kill. But is that really what you want?", "この印を持つカードは所有者が選んだ任意の空きスロットに移動でき、敵を倒すとEXPとLVも得る。だが、それは本当に君の望みか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incendiary", "放火", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil damages a card, that card gains the \"ablaze\" sigil. While a card is ablaze, it will lose one health per turn.", "この印を持つカードがカードを攻撃すると、対象は「炎上」の印を得る。炎上の印を持つカードは所有者の戦闘フェーズ開始時に1ダメージを受ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ablaze", "炎上", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will take 1 damage at the start of its owner's turn.", "所有者の戦闘フェーズ開始時、この印を持つカードは1ダメージを受ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indecisive", "優柔不断", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, it has a 50/50 chance to either gain a stat buff, or perish; creating a copy of this card in your hand.", "この印を持つカードが打たれると、能力値が上がるか、死亡して手札にそのコピーを作るかが半々の確率で決まる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone knows Jerry. Makes Turns 2 seconds longer. Cards gain a stat buff when Jerry is killed or sacrificed.", "誰もがジェリーを知っている。ターンが2秒長くなる。ジェリーが殺されるか生贄になると、プレイヤー側のカードの能力値が上がる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mercy", "慈悲", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A 'Determined' card will be granted this sigil when the card opposing it has low health, prompting the player to make a moral decision.", "「ケツイ」を持つカードは、正面のカードの体力が少なくなるとこの印を得る。プレイヤーは道徳的な選択を迫られる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insight", "洞察", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you wanna have a bad time?", "ひどい目に遭いたいか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doodler", "ドゥードラー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, it will sometimes summon doodlebogs on adjacent spaces.", "この印を持つカードが打たれると、隣のマスにドゥードルボグを召喚することがある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Timid", "臆病", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opponent card moves into the opposing space of a card bearing this sigil, the sigil bearer will try to move one space over.", "相手のカードがこの印を持つカードの正面に移動すると、持ち主は1マス移動しようとする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You ditched Jerry.", "ジェリーを置いてきた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow, you guys SUCK at this.", "うわ、みんな本当に下手だね。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wi-fi here sucks.", "ここのWi-Fiはひどいな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHHHH! Im THINKING, guys!!", "シーッ！　考えてるんだから、みんな！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Get your own, twerp.", "自分で手に入れなよ、チビ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why are we doing this? What a fail.", "なんでこんなことしてるの？　大失敗じゃん。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guys. its COLD. Does ANYONE care?", "ねえ、寒いんだけど。誰か気にしてくれる？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ka-SIGH", "はああ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DUH! Who DOESNT know?", "当たり前！　知らない人なんている？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well... can YOU give me a ride home?", "ねえ……家まで乗せてくれる？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awkwarrrd.", "気まずーい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So, like, what are you even doing?", "で、何をしてるわけ？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Huh? Did they ditch me...? SOME friends!", "え？　みんな僕を置いてった……これが友達？", Language.Japanese);



        }
    }
    public class RevenantMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for RevenantMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DanseMacabre", "死の舞踏", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to reverse this sigil effect. At the end of the owner's turn, all creatures on the board gain 1 health.", "骨を2個払い、この印の効果を反転させる。所有者のターン終了時、盤上のすべての生物は体力を1得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LifeDraw", "命のドロー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Blood to draw a card from your main deck.", "血を1消費し、メインデッキからカードを1枚引く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulgate", "魂の領域への門", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to gain 1 Energy, lose as much Max Energy at the end of the owner's turn.", "骨を1個払い、エネルギーを1得る。所有者のターン終了時、同じ量の最大エネルギーを失う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evocation", "召喚術", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Energy to return the oldest non-Brittle allied creature from the graveyard to your hand.", "エネルギーを3払い、墓地に最も早く入った不安定を持たない味方の生物を手札に戻す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dormant", "休眠", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay Bones equal to the Power of [creature] to disable this sigil for 1 turn. [creature] cannot attack normally.", "[creature]の攻撃力に等しい数の骨を払い、この印を1ターン無効にする。[creature]は通常攻撃できない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transmute", "変成", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to transform [creature] to its alternate form.", "骨を2個払い、[creature]を別の形態に変える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protector", "保護者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to [creature] gain 1 max health.", "[creature]に隣接する生物は最大体力を1得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CalamityEffusion", "災厄の奔出", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, all creatures on the board lose 1 health.", "所有者のターン終了時、盤上のすべての生物は体力を1失う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ComfortAura", "慰めのオーラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, creatures adjacent to [creature] heal 1 health.", "所有者のターン終了時、[creature]に隣接する生物は体力を1回復する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CorpseParty", "死体の宴", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle creature on the owner's side perishes by combat, a Zombie enters your hand. A Zombie is defined as: 1 Power, 1 Health.", "所有者のサイドで不安定を持たない生物が戦闘で死亡すると、ゾンビが1枚手札に加わる。ゾンビは攻撃力1、体力1を持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DeathKnock", "死の反撃", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, it strikes back then perishes.", "[creature]は戦闘で死亡すると、反撃してから死亡する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DeathMetal", "デスメタル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, adjacent creatures and opposing creatures to the left, right, and center of it take 1 damage. It gains 1 Power for each affected creature.", "[creature]を場に出すと、隣接する生物と正面の左・右・中央にいる相手の生物が1ダメージを受ける。影響を受けた生物1体につき攻撃力を1得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defiler", "汚染者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, draw a card then choose one to discard from your hand.", "[creature]が死亡すると、カードを1枚引き、手札から1枚選んで捨てる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Encroachment", "侵食", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] creates a copy of it in your hand after 2 turns on the board.", "[creature]は盤上に2ターンいると、手札に自分のコピーを1枚作る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletonize", "骸骨化", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Skeleton with its old sigils enters your hand. A Skeleton is defined as: 1 Power, 1 Health, Brittle.", "[creature]が死亡すると、元の印を持つガイコツが手札に加わる。ガイコツは攻撃力1、体力1、不安定を持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exorcise", "除霊", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Bones equal to the Bone cost of the opposing creature are granted to the player.", "[creature]を場に出すと、正面の生物の骨コストに等しい数の骨がプレイヤーに与えられる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ExplodingCorpse", "爆発する死体", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, all empty spaces on the board are filled with a Guts card.", "[creature]が戦闘で死亡すると、盤上のすべての空きマスが内臓カードで埋まる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GrudgeCollector", "恨みの収集者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power for every 2 times opponent creatures deal direct damage to its owner.", "相手の生物が所有者に直接ダメージを2回与えるたび、[creature]は攻撃力を1得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime Power", "ベルの力", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Bell cards on the board.", "この印の示す値は盤上のベルカードの数に等しい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Digger Power", "骨掘りの力", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Bone and Digger related sigils on the board.", "この印の示す値は盤上の骨と掘削に関係する印の数に等しい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignition", "点火", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power at the cost of 1 health after each turn on the board.", "[creature]は盤上にいる間、毎ターン体力1を代償に攻撃力を1得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Digger Latch", "骨掘り信号入力", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 Bone. When it perishes, its owner chooses a creature to gain the Bone Digger sigil.", "所有者のターン終了時、[creature]は骨を1個作る。死亡すると、所有者は骨掘りの印を与える生物を選ぶ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Primed Digger Latch", "強化骨掘り信号入力", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 Bone. When it perishes, its owner chooses a creature to gain this sigil.", "所有者のターン終了時、[creature]は骨を1個作る。死亡すると、所有者はこの印を与える生物を選ぶ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rejuvenation", "若返り", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Fledgling sigil.", "[creature]が死亡すると、所有者は雛の印を与える生物を選ぶ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skull Storm", "ドクロの嵐", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, this sigil is replaced with another sigil at random. When it perishes, its owner chooses a creature to gain this sigil.", "所有者のターン終了時、この印はランダムな別の印に置き換わる。このカードが死亡すると、所有者はこの印を与える生物を選ぶ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "火付け", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Ignition sigil.", "[creature]が死亡すると、所有者は点火の印を与える生物を選ぶ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MacabreBonePulse", "陰気な骨の波動", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it perishes immediately, dropping Bones equal to double the amount of creatures on the owner's side.", "[creature]を場に出すとすぐに死亡し、所有者のサイドにいる生物の数の2倍の骨を落とす。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maternal", "母性", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to [creature] are inscrybed by Waterborne.", "[creature]に隣接する生物は潜水の印を刻まれる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Necrosis", "壊死", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] loses 1 power and 1 max health after each turn on the board.", "[creature]は盤上にいる間、毎ターン攻撃力と最大体力をそれぞれ1失う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Limbo", "辺獄", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it returns to the top of your deck.", "[creature]が死亡すると、デッキの一番上に戻る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RelentlessRevenant", "不屈のレヴナント", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, creatures adjacent to [creature] transform into a Revenant. A Revenant is defined as: 3 Power, 1 Health, Brittle.", "所有者のターン開始時、[creature]に隣接する生物はレヴナントに変身する。レヴナントは攻撃力3、体力1、不安定を持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revedue", "レヴナントの帰還", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] perishes, then shuffle 2 Revenants with its old sigils into your side deck. A Revenant is defined as: 3 Power, 1 Health, Brittle.", "攻撃後、[creature]は死亡し、元の印を持つレヴナント2枚をサイドデッキに混ぜる。レヴナントは攻撃力3、体力1、不安定を持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bad Omen", "不吉な予兆", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will deal 1 damage to the owner.", "所有者のターン終了時、[creature]は所有者に1ダメージを与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rancor", "怨恨", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it leaves a permanent 1 power buff in the space it occupied.", "[creature]が死亡すると、元いたマスに永続的な攻撃力1の強化を残す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SoothingMeadows", "癒しの草原", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, all creatures on the board gain 1 health.", "所有者のターン終了時、盤上のすべての生物は体力を1得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PartingStroke", "別れの一撃", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle creature on the owner's side perishes by combat, its owner chooses a creature to lose all of its sigils.", "所有者のサイドで不安定を持たない生物が戦闘で死亡すると、所有者は生物を選び、そのすべての印を失わせる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SplittingCorpse", "分裂する死体", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, create a Dysmorphia on each empty adjacent space.", "[creature]が戦闘で死亡すると、隣接する各空きマスに異形体を1体作る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torpid", "鈍い", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot attack normally.", "[creature]は通常攻撃できない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Epitaph", "陰気な墓碑銘", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may choose a card that has already been put to rest, to bring back to your hand.", "[creature]を場に出すと、すでに眠りについたカードを1枚選び、手札に戻せる。", Language.Japanese);


            //card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigfoot", "巨足", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a mysterious creature lurking the forests, only few have claimed to see one.", "森に潜む謎の生物。見たと主張する人はごくわずか。", Language.Japanese);
            GrimoraMod.RegisterCard("Bigfoot", "巨足");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goblin", "ゴブリン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal barbaric beast, a fine addition to your army.", "忠実で荒々しい獣。君の軍勢に加えるにはうってつけだ。", Language.Japanese);
            GrimoraMod.RegisterCard("Goblin", "ゴブリン");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vila", "ヴィラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love at first sight, at least that's what it wants you to think.", "一目惚れ。少なくとも、そう思わせたいようだ。", Language.Japanese);
            GrimoraMod.RegisterCard("Vila", "ヴィラ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yaramayawho", "赤肌のカエルの魔物", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one can never seem to finish it's meals...", "食事を最後まで食べきれないようだ……", Language.Japanese);
            GrimoraMod.RegisterCard("Yaramayawho", "赤肌のカエルの魔物");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Test Limbs", "試験用の四肢", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those parts used to belong to someone, or now some thing...(Test)", "これらの部位はかつて誰かのものだった。そして今は何かのもの……（テスト）", Language.Japanese);
            GrimoraMod.RegisterCard("Test Limbs", "試験用の四肢");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allip", "狂える哀霊", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remnants of the insane! You never know what story lies behind that face, but it's sure to be filled with fervor.", "狂人の残骸！　その顔の裏にどんな物語があるかは分からないが、熱狂に満ちているに違いない。", Language.Japanese);
            GrimoraMod.RegisterCard("Allip", "狂える哀霊");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amami Rabbit", "アマミノクロウサギ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiding their young in holes, they wish for their best safety.", "子どもを穴に隠し、無事でいることを願う。", Language.Japanese);
            GrimoraMod.RegisterCard("Amami Rabbit", "アマミノクロウサギ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankhame", "アンカの呪物", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A relic that is drawn to your blood, perhaps you could give it a swing!", "君の血に引き寄せられる遺物。振ってみてはどうだろう！", Language.Japanese);
            GrimoraMod.RegisterCard("Ankhame", "アンカの呪物");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anneta", "アネッタ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That ink keeps on pouring, is she even there anymore? All that death promises is that you will wake up again.", "インクは流れ続ける。彼女はまだそこにいるのか？　死が約束するのは、再び目覚めることだけだ。", Language.Japanese);
            GrimoraMod.RegisterCard("Anneta", "アネッタ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anorexia", "拒食の魔物", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overflowing you with self loathing, you never know what form it may take on next.", "自己嫌悪で君を満たすもの。次にどんな姿を取るかは分からない。", Language.Japanese);
            GrimoraMod.RegisterCard("Anorexia", "拒食の魔物");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lych Bell", "リッチの鐘", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems like they found a new way to use bells.", "ベルの新しい使い道を見つけたようだ。", Language.Japanese);
            GrimoraMod.RegisterCard("Lych Bell", "リッチの鐘");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TheBloated", "膨れた死体", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grotesque boils, ready to burst.", "今にも破裂しそうな、醜い腫れ物。", Language.Japanese);
            GrimoraMod.RegisterCard("TheBloated", "膨れた死体");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BrainJar", "異形の脳缶", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One shudders to imagine what inhuman thoughts lie inside that jar...", "あの瓶にどんな人ならざる考えが潜んでいるか、想像するだけで身震いする……", Language.Japanese);
            GrimoraMod.RegisterCard("BrainJar", "異形の脳缶");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Combustor", "爆燃する死骸", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, what a fall from such a stimulatingly high status, now all that's left is a metal carcass, and the last of that watchful substance...", "ああ、刺激的なほど高い地位からの転落。今残るのは金属の残骸と、最後の見張る物質だけ……", Language.Japanese);
            GrimoraMod.RegisterCard("Combustor", "爆燃する死骸");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Misplayed Stoat", "爛れたオコジョ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A decaying Stoat whose oh-so perfect strategies failed him tremendously.", "腐りかけたオコジョ。自慢の完璧な戦略は、彼をひどい失敗に追いやった。", Language.Japanese);
            GrimoraMod.RegisterCard("Misplayed Stoat", "爛れたオコジョ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia", "異形体", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia Left.", "異形体・左。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia Right.", "異形体・右。", Language.Japanese);
            GrimoraMod.RegisterCard("Dysmorphia", "異形体");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exorcist", "祓魔の道士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He still thinks banishing the dammed will do him good, does he know where he is?", "呪われた者を追放すれば自分のためになるとまだ思っている。自分がどこにいるか分かっているのか？", Language.Japanese);
            GrimoraMod.RegisterCard("Exorcist", "祓魔の道士");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flembones", "膿骨の亡霊", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait until he plays with his webcam.", "彼がウェブカメラで遊ぶまで待とう。", Language.Japanese);
            GrimoraMod.RegisterCard("Flembones", "膿骨の亡霊");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stein & Frank", "スタインとフランク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even hell was not hot enough to split them.", "地獄の熱さですら、彼らを引き離すには足りなかった。", Language.Japanese);
            GrimoraMod.RegisterCard("Stein & Frank", "スタインとフランク");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FulmineSkull", "雷鳴の頭蓋骨", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you listen closely, you can still hear the cackling of flame on bone... as well as their voice.", "耳を澄ませば、骨の上で炎がはぜる音がまだ聞こえる……彼らの声も。", Language.Japanese);
            GrimoraMod.RegisterCard("FulmineSkull", "雷鳴の頭蓋骨");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FulurOssa", "轟雷の増骨", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It never truly left the electric chair.", "それは本当の意味で電気椅子を離れたことがない。", Language.Japanese);
            GrimoraMod.RegisterCard("FulurOssa", "轟雷の増骨");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PrometheusFlame", "プロメテウスの炎", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one is quite unique, the lingering spoils of a thief to benefit humanity! Fancy liver by chance?", "実に独特な品。人類のために尽くした盗人の残した戦利品だ！　肝臓はいかが？", Language.Japanese);
            GrimoraMod.RegisterCard("PrometheusFlame", "プロメテウスの炎");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guts", "内臓", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying guts.", "厄介な内臓。", Language.Japanese);
            GrimoraMod.RegisterCard("Guts", "内臓");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harbinger", "先駆者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A powerful fiend that extols a heavy price for its servitude.", "強大な魔物。その奉仕には高い代償が伴う。", Language.Japanese);
            GrimoraMod.RegisterCard("Harbinger", "先駆者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hastur", "ハスター", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He came from beyond the stars, gifting pieces of his reflection to kings and fools alike. Will you accept this piece?", "星の彼方から来て、自らの映し身の欠片を王にも愚者にも授けた。君はこの欠片を受け取るか？", Language.Japanese);
            GrimoraMod.RegisterCard("Hastur", "ハスター");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Common Imp", "ありふれた使い魔", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tiny creature known for causing trouble and mayhem wherever it goes, with its mischievous grin and playful nature!", "いたずらっぽい笑顔と遊び好きな性格で、行く先々に騒ぎを起こす小さな生物！", Language.Japanese);
            GrimoraMod.RegisterCard("Common Imp", "ありふれた使い魔");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orochimitama", "大蛇の残魂", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... He is not supposed to be here...", "ああ……彼はここにいるはずじゃない……", Language.Japanese);
            GrimoraMod.RegisterCard("Orochimitama", "大蛇の残魂");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inochi", "命の息吹", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A soothing presence to heal your creatures, a calm before the storm.", "君の生物を癒やす穏やかな存在。嵐の前の静けさだ。", Language.Japanese);
            GrimoraMod.RegisterCard("Inochi", "命の息吹");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trail of Torment.", "苦しみの道。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessed Limbs", "異形の四肢", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once attached to a living person, they now belong to something else entirely.", "かつて生きた人に付いていたが、今はまったく別のものの一部だ。", Language.Japanese);
            GrimoraMod.RegisterCard("Possessed Limbs", "異形の四肢");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mole Digger", "墓掘りモグラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stalwart Mole... Digger? Whatever this is...", "不屈のモグラ……墓掘り？　一体何なんだ……", Language.Japanese);
            GrimoraMod.RegisterCard("Mole Digger", "墓掘りモグラ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nekros", "ネクロス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nekros possesses the board, challenger. Death is his playground.", "ネクロスが盤を支配している、挑戦者よ。死は彼の遊び場だ。", Language.Japanese);
            GrimoraMod.RegisterCard("Nekros", "ネクロス");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NekrosPrime", "ネクロス・プライム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will find no greater power... than the simple thought of your own name... inscrybed upon a grave.", "これほどの力は他にない……自分の名が墓石に刻まれる……ただそれを思うこと以上の力は。", Language.Japanese);
            GrimoraMod.RegisterCard("NekrosPrime", "ネクロス・プライム");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nuckelavee", "ナックラヴィー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Administrator of its sea, you better hope it's breath doesn't taint your Thralls!", "海を統べる者。その息が君の奴隷たちを汚さないよう祈ることだ！", Language.Japanese);
            GrimoraMod.RegisterCard("Nuckelavee", "ナックラヴィー");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OdiousMass", "不浄な巨体", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How unsightly.", "なんと見苦しい。", Language.Japanese);
            GrimoraMod.RegisterCard("OdiousMass", "不浄な巨体");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orochi", "八岐大蛇", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "犠牲は必要だ。", Language.Japanese);
            GrimoraMod.RegisterCard("Orochi", "八岐大蛇");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Ouro", "マスター・オーロ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "From within the endless torment and suffering, they had somehow learned a way to see inside this poor broken thing... and take away its pain.", "果てしない苦痛の中で、彼らはこの哀れな壊れたものの内側を見る方法を見つけた……そして苦痛を取り去った。", Language.Japanese);
            GrimoraMod.RegisterCard("Master Ouro", "マスター・オーロ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An endless cycle of life and death has taken a toll on these discarded remains. The pain was real, but death is never final!", "果てしない生と死の循環は、捨てられたこの残骸を蝕んだ。痛みは本物だったが、死は決して終わりではない！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GanCeann", "デュラハン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Countless legends tell of the dullahan, but all fail to convey the true extent of its pique.", "デュラハンを語る伝説は数知れないが、その怒りの真の大きさを伝えるものはない。", Language.Japanese);
            GrimoraMod.RegisterCard("GanCeann", "デュラハン");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dark Prince", "闇の王子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of fluffy bois shines within you.", "ふわふわしたやつらの力が君の中で輝く。", Language.Japanese);
            GrimoraMod.RegisterCard("Dark Prince", "闇の王子");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stillborn Raven", "夭折したカラスの魂", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feels good to be young again!", "また若くなれるっていいね！", Language.Japanese);
            GrimoraMod.RegisterCard("Stillborn Raven", "夭折したカラスの魂");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reanimated", "蘇る者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRINGING THE SCYTHE OF DEATH, THE REVENANT... WAIT, WHAT?", "死の鎌を携えしレヴナント……待て、何だって？", Language.Japanese);
            GrimoraMod.RegisterCard("Reanimated", "蘇る者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RevenantEldritch", "蘇る異形", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The source of Calamity, relentless and unerring.", "災厄の源。容赦なく、狙いを外さない。", Language.Japanese);
            GrimoraMod.RegisterCard("RevenantEldritch", "蘇る異形");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy Bones", "怠け者の骨", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A slothful skeleton with a knack for jokes. I adore him.", "怠け者だが冗談のうまいガイコツ。彼が大好きだ。", Language.Japanese);
            GrimoraMod.RegisterCard("Lazy Bones", "怠け者の骨");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelephone", "骨の蓄音機", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A way to communicate with the dead, for a price.", "死者と話す方法。ただし代償がいる。", Language.Japanese);
            GrimoraMod.RegisterCard("Skelephone", "骨の蓄音機");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulgate", "魂の領域への門", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A chance to enter the soul realm, how delightful? I hope you can afford the price.", "魂の領域へ入る機会。素晴らしいだろう？　代償を払えるといいが。", Language.Japanese);
            GrimoraMod.RegisterCard("Soulgate", "魂の領域への門");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SpadeWarrior", "スペードの戦士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This fearsome warrior will put you six feet under, in every possible sense.", "この恐るべき戦士は、あらゆる意味で君を墓の下に埋める。", Language.Japanese);
            GrimoraMod.RegisterCard("SpadeWarrior", "スペードの戦士");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UndeadCivilian", "不死の市民", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lost in eternal darkness, this poor soul desperately seeks a way out. Perhaps you can light his way?", "永遠の闇に迷った哀れな魂は、必死に出口を探している。君なら道を照らせるかもしれない？", Language.Japanese);
            GrimoraMod.RegisterCard("UndeadCivilian", "不死の市民");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UndeadVillage", "死者を葬る村", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abandoned and forlorn, this village seeks new residents to fill its decrepit homes.", "見捨てられた寂しい村。荒れた家々に住む新たな住民を探している。", Language.Japanese);
            GrimoraMod.RegisterCard("UndeadVillage", "死者を葬る村");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In every town, in every city, someone must work to bury the dead. In time, they too will be buried.", "どんな町でも都市でも、死者を埋める仕事をする者がいる。やがて彼らも埋葬される。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dr.Bones", "ボーン博士", Language.Japanese);
            GrimoraMod.RegisterCard("Dr.Bones", "ボーン博士");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whatever doesn't kill you simply makes you, saner.", "君を殺さないものは、君をより正気にする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wendigo", "ウェンディゴ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Returned from the deep wilds, reminds me of a friend.", "奥深い荒野から帰ってきた。友人を思い出す。", Language.Japanese);
            GrimoraMod.RegisterCard("Wendigo", "ウェンディゴ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mister Win", "ミスター・ウィン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card that wins. It always wins. That's why it's called Mister Win.", "勝つカード。いつでも勝つ。だからミスター・ウィンと呼ばれる。", Language.Japanese);
            GrimoraMod.RegisterCard("Mister Win", "ミスター・ウィン");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not that one, I'm afraid.", "残念だが、それではない。", Language.Japanese);

            // Dlg
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You... you murderous monster.", "お前……人殺しの怪物め。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh Dear... The flow of Calamity will pursue you.", "ああ……災厄の流れが君を追う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hecatomb the village you once lived.", "かつて住んでいた村を大量虐殺せよ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seak for the shovel that digs forever.", "永遠に掘り続けるシャベルを探せ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bring me the lost one with a spark in hand.", "手に火花を持つ迷い人を連れてこい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compelled by the beckoning of an ancient entity,", "古代の存在の呼びかけに導かれ、", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a forbidden ritual has been initiated.", "禁じられた儀式が始まった。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The pain reaches the ancient great serpent of death.", "その苦痛は古の巨大な死の蛇に届く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "犠牲は必要だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... There are no dead cards yet.", "ああ……まだ死んだカードがない。", Language.Japanese);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant Mod Card Pack", "レヴナントModカードパック", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack consists of mainly cards that return to the player in a variety of ways.", "さまざまな方法でプレイヤーの手札に戻るカードが中心のパック。", Language.Japanese);
        }
    }
    public class SquirrelBombMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SquirrelBombMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pipis", "ピピス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pipis.", "ピピス。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Help", "助け", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn [creature] will sacrifice itself to heal the adjacent cards by 1.", "所有者のターン終了時、[creature]は自らを生贄にし、隣接するカードを体力1回復する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pass-through", "通過", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is about to get attacked by a card with an attack higher than this card's health, this card perishes.", "[creature]がこのカードの体力より攻撃力の高いカードに攻撃される直前、このカードは死亡する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Call", "迷惑電話", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empty spaces within a circuit completed by [creature] spawn Spam Mail at the end of the owner's turn.", "所有者のターン終了時、[creature]が完成させた回路内の空きマスに迷惑メールが現れる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEO Strike", "NEOの一撃", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space that is occupied by a creature and additionally every side of the board occupied by a creature. It will strike directly if no creatures oppose it.", "[creature]は攻撃時、相手側の左半分と右半分それぞれに直接攻撃を阻む生物がいれば、その半分の2マスを攻撃し、さらに各生物を攻撃する。阻む生物がいなければ中央の2マスを直接攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Call for Help", "助けを呼ぶ声", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will call for help.", "所有者のターン終了時、[creature]は助けを呼ぶ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Run Forth", "前進", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Before [creature] attacks, its power will be set to at least 1.", "[creature]が攻撃する前に、攻撃力が最低1に設定される。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying Head", "空飛ぶ頭", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most important part.", "最も重要な部分。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Cart", "迷惑メールカート", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled with spam mail. Absorbs all kinds of attacks.", "迷惑メールでいっぱい。あらゆる攻撃を吸収する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Mail", "迷惑メール", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Has all kinds of unforgettable deals.", "あらゆる忘れられないお買い得品を取りそろえている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Shooter", "ビッグシューター", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoots big shots.", "ビッグショットを撃つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart on a Chain", "鎖につながれた心", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beautiful.", "美しい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spamgel", "スパムジェル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The result of pressing F1.", "F1を押した結果。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand Phone", "携帯電話", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you really need anyone else?", "本当に他の誰かが必要か？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE POWER OF NEO!!!", "NEOの力！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you wanna be a big shot?", "大物になりたくないか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Receiver", "受信機", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voice runs out eventually.", "声はいつか途絶える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzlipis", "グリズリー割引券", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzlipis.", "グリズリー割引券。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Cart", "クマのカート", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled with bears. Absorbs all kinds of attacks.", "クマでいっぱい。あらゆる攻撃を吸収する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Mail", "クマのメール", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mail for bears.", "クマ宛てのメール。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear on a Chain", "鎖につながれたクマ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Hand", "クマの手", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel Bomb", "リス爆弾", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrels explode when killed, dealing 10 damage to adjacent cards.", "リスは殺されると爆発し、隣接するカードに10ダメージを与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance Party", "ダンスパーティー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your cards move each turn. The cards that can't move die.", "君のカードは毎ターン移動する。移動できないカードは死亡する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Again", "もう一度", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All opponent cards attack twice.", "相手のすべてのカードが2回攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starving", "飢え", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pray.", "祈れ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogfish", "ツノザメ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each battle starts with a Bait Bucket that has Guardian.", "各戦闘の開始時、相手サイドに空きマスがあれば守護者を持つ釣り餌バケツが現れる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Totems", "嫌がらせのトーテム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start each battle with an Annoying totem for your most used tribe.", "各戦闘の開始時、最も多く使っている部族に嫌がらせのトーテムが付く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Draws", "苦痛のドロー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawing from the main deck deals 1 damage.", "メインデッキからカードを引くと1ダメージを受ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Squirrels", "苦痛のリス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawing from the side deck deals 1 damage.", "サイドデッキからカードを引くと1ダメージを受ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Runes", "ルーン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enemy cards of the dominant tribe get random sigils.", "主となる部族の敵カードがランダムな印を得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dentistry", "歯科治療", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Item events and Trinket Bearer cards only give pliers.", "アイテムイベントと荷物運搬のカードからはペンチしか得られない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Archived", "アーカイブ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A random card choice is hidden in every card choice event.", "カード選択イベントごとに、ランダムな選択肢が1つ隠される。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foundation", "基礎", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards have 1 less attack. Side deck cards have Leader.", "自分のカードは攻撃力が0より大きい場合、攻撃力が1減る。サイドデッキのカードはリーダーを持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Boss v2", "最後の相手 v2", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Replaces Leshy as the final boss with a true BIG SHOT.", "真の大物がレシーに代わって最後の相手になる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must dance! Don't stop dancing!!", "踊れ！　踊るのをやめるな！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whoever stops dancing at my party will suffer the consequences.", "私のパーティーで踊るのをやめた者には、相応の報いを受けてもらう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is that mechanic annoying?", "あの仕組みはうっとうしいか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect. That's the point of it.", "結構。そういうものだからな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance my puppet! Daaaance.", "踊れ、私の操り人形！　踊れええ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need to pass, remember?", "通らなければならない、覚えているか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M [_spamton_0,STEALING] YOUR KROMER", "お前のクローマーを[_spamton_0,盗んで]いるぞ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOLY [_spamton_0,CUNGADERO] DO I FEEL GOOD", "なんて[_spamton_0,こった]、気分がいいぞ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HERE I AM!!!", "ここに来たぞ！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BIG", "大きな", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<size=10>BIG!!!</size>", "<size=10>ビッグ！！！</size>", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<size=15>[_spamton_0,BIGGER AND BETTER THAN EVER]</size>", "<size=15>[_spamton_0,今までより大きく最高に]</size>", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AND NOW THAT I'M IN THIS [_spamton_0,GAME OF CARDS]", "そして今、私はこの[_spamton_0,カードゲーム]の中にいる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I CAN'T BE DEFEATED!!!", "私を倒すことはできない！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO GET [_spamton_0,ABSOLUTELY OBLITERATED] BY [_spamton_0,THE POWER OF NEO]!!!", "[_spamton_0,NEOの力]で[_spamton_0,徹底的に叩きのめされる]覚悟をしろ！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,THIS] AGAIN???", "また[_spamton_0,これ]か？？？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO GET [_spamton_0,DESTROYED]!!!", "[_spamton_0,破壊される]覚悟をしろ！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU WON'T STAND A CHANGE, YOU [_spamton_0,LITTLE RING WORM]!!!", "お前に勝ち目はない、この[_spamton_0,小さなリングワーム]！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO [_spamton_0,GET PUNCHED] IN YOUR [_spamton_0,FACE]!!!", "その[_spamton_0,顔]に[_spamton_0,パンチを食らう]覚悟をしろ！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BEHOLED [_spamton_0,ME]!!! BEHOLD [_spamton_0,YOU]!!!", "[_spamton_0,私]を見ろ！！！　[_spamton_0,お前]を見ろ！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,HYPERLINK BLOCKED]", "[_spamton_0,ハイパーリンクはブロックされました]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ISN'T THIS BODY JUST [_spamton_0,HEAVEN]LY?", "この体はまるで[_spamton_0,天国]みたいだろ？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "2X THE [_spamton_0,FIRE]POWER", "2倍の[_spamton_0,火]力", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "3X THE [_spamton_0,WATER]POWER", "3倍の[_spamton_0,水]力", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AND MOST IMPORTANTLY", "そして何より大事なのは", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FLYING HEADS!!!", "空飛ぶ頭だ！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WE'LL TURN THOSE [_spamton_0,SCHMOES] AND [_spamton_0,DAVES]", "あの[_spamton_0,間抜け]や[_spamton_0,おバカさん]を", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INTO [_spamton_0,ROSEN GRAVES]", "[_spamton_0,バラの墓]に変えてやる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THOSE [_spamton_0,CATHODE SCREENS]", "あの[_spamton_0,ブラウン管の画面]を", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INTO [_spamton_0,CATHODE SCREAMS]", "[_spamton_0,ブラウン管の悲鳴]に変える", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA BE [_spamton_0,PART] OF MY BEAUTIFUL [_spamton_0,HEART]?!", "私の美しい[_spamton_0,心]の[_spamton_0,一部]になりたくないか？！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OR... DID YOU NEED A LITTLE [_spamton_0,SPECIL TOUR]?", "それとも……ちょっとした[_spamton_0,特別ツアー]が必要か？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHAT]?!", "[_spamton_0,何]？！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU [_spamton_0,STOLE] MY [_spamton_0,HEART]?", "私の[_spamton_0,心]を[_spamton_0,盗んだ]のか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU CAN'T BE [_spamton_0,STEALING] MY [_spamton_0,HEART], IT IS MY [_spamton_0,HEART]!", "私の[_spamton_0,心]を[_spamton_0,盗む]な。それは私の[_spamton_0,心]だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP [_spamton_0,STEALING] MY HEART YOU [_spamton_0,!@#$]", "私の心を[_spamton_0,盗む]な、この[_spamton_0,!@#$]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "O U C [_spamton_0,HYPERLINK BLOCKED]", "い た [_spamton_0,ハイパーリンクはブロックされました]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU JUST [_spamton_0,BROKE] MY [_spamton_0,$4.99] HEART", "私の[_spamton_0,$4.99]の心を[_spamton_0,壊した]な", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO YOU KNOW THAT IT [_spamton_0,HURTS] WHEN YOU [_spamton_0,DO] THAT?!", "お前がそれを[_spamton_0,すると]どれほど[_spamton_0,痛い]か分かるか？！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA HELP YOUR OLD PAL SPAMTON?", "旧友スパムトンを助けたくないか？", Language.Japanese);
