            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ROYAL [_spamton_0,WHAT]? ROYAL [_spamton_0,WHO]?", "ロイヤル[_spamton_0,何]？　ロイヤル[_spamton_0,誰]？", Language.Japanese);
