            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled With Whimsy And Joy! But When They Grow Up...", "気まぐれと喜びでいっぱい！　でも成長すると……", Language.Japanese);
