            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Need something destroyed?", "何か壊してほしいものは？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Captain Ansel", "アンセル大尉", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heroic Valkyrie.", "英雄級のヴァルキリー。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vulture", "ハゲワシ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Somethin' on yo' mind?", "何か考え事か？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jim Raynor -V", "ジム・レイナー -V", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heroic Vulture.", "英雄級のハゲワシ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wraith", "陰の霊", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know who the best star fighter in the fleet is?", "艦隊一の宇宙戦闘機乗りが誰だか知ってるか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tom Kazansky", "トム・カザンスキー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heroic Wraith.", "英雄級の陰の霊。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zealot", "狂信者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My life for Aiur!", "アイアーのために命を！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fenix -Z", "フェニックス -Z", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heroic Zealot.", "英雄級の狂信者。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zergling", "ザーグリング", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chattering.", "おしゃべりするような音。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Devouring One", "貪る者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heroic Zergling.", "英雄級のザーグリング。", Language.Japanese);

        }
    }
    public class LegendsFromTheDarknessMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for LegendsFromTheDarkness Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legends From The Darkness", "闇からの伝説", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards consisting of a random assortment of animals, myths and urban legends.", "動物、神話、都市伝説をランダムに集めた約[count]枚のカードセット。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mako Shark", "アオザメ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The swift Mako, an agile sea predator.", "素早いアオザメ。海を泳ぐ俊敏な捕食者。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The robust Puma, a fierce creature.", "頑丈なピューマ。獰猛な生物だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hideous offspring of a voracious creature.", "大食らいの生物から生まれた恐ろしい子。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahuizotl", "アウィツォトル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar creature. I wonder if that tail is special.", "変わった生物。あの尾には何か特別なものがあるのだろうか。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahuizotl Tail", "アウィツォトルの尾", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiding in dismal waters, the ferocious alligator approaches those who dare get close.", "薄暗い水辺に潜む獰猛なアリゲーター。近づく者に迫る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angler Fish", "アンコウ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let that glamorous shine decieve you.", "その魅惑的な光に騙されるな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antlion", "アリジゴク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Automaton", "オートマトン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The rusted machine's exposed wires shock any would-be aggressor", "錆びた機械のむき出しの電線は、襲おうとする者に電撃を浴びせる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the regenerative sea predator, what would happen if the eternal juvenile were to reach maturity?", "再生する海の捕食者。この永遠の幼体が成体になったらどうなるのだろう？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beetle", "甲虫", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unsurpassable strength of the beetle knocks creatures away.", "甲虫の比類なき力が生物を吹き飛ばす。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloater", "膨れた者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An unfortunate demise to this particular being.", "この特別な存在にとって、不運な最期。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boa", "ボア", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The constricting Boa ensnares its prey and won't let go.", "獲物を締めつけるボアは一度捕らえたら離さない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bombardier", "投弾虫", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armed with a noxious spray, this odd beetle retaliates against its aggressors.", "有害な噴霧で武装した奇妙な甲虫。襲う者に反撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Braxie", "ブラクシー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wandering Braxie's horrid stench weakens any threat it encounters.", "さまようブラクシーの恐ろしい悪臭は、出会う脅威を弱らせる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cape Buffalo", "アフリカスイギュウ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Vengeful Buffalo, attacking it is a woeful decision.", "復讐心に燃えるスイギュウ。攻撃すれば後悔する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bush Dog", "ヤブイヌ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thought to be extinct, the Illusive Bush Dog is normally found in packs.", "絶滅したと思われていた謎めいたヤブイヌ。普段は群れで行動する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cadejo", "カデホ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bound to chance, your guardian will be either benign or maleficent.", "運次第で、守護者は善にも悪にもなる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camazotz", "カマソッソ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A servant to the lords of the underworld, associated with darkness, death... and 'sacrifice'.", "冥界の領主たちに仕え、闇、死……そして「生贄」と結びついた存在。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The \"spit\" of the camel is enough to blind most aggressors.", "ラクダの「唾」は、たいていの襲撃者の目を見えなくする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carpenter Moth", "ボクトウガ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The resourceful carpenter, able to draw blood from stone.", "機転の利く大工。石から血を搾り出すことさえできる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "few are able to catch the nimble cheetah.", "俊敏なチーターを捕まえられる者は少ない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The humble chicken, its meat is nourishing for most creatures.", "地味なニワトリ。その肉はほとんどの生物の栄養になる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chupacabra", "チュパカブラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the horrid chupacabra. It hungers for your livestock.", "恐ろしいチュパカブラ。君の家畜を食べたがっている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ever-bothersome cicada, using its loud buzzing to summon its kin.", "いつもうるさいセミ。大きな羽音で仲間を呼ぶ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cloth", "布", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the mystifying Clouded Leopard. The missing link between the cat family.", "神秘的なウンピョウ。ネコ科をつなぐ失われた環。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cookiecutter", "ダルマザメ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crab", "カニ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "an armored crustacean. The crab's carapace covers it from fatal blows.", "鎧をまとった甲殻類。カニの甲羅は致命的な一撃から守ってくれる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dart Frog", "ヤドクガエル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is Ill-advised to attack this creature.", "この生物を攻撃するのは賢明ではない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dirt Pile", "土の山", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dobhar-chu", "ドバル・クー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the king of the otters. The Dobhar-chu requires sustenance to grow.", "カワウソの王。ドバル・クーは成長するために食べ物を必要とする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The onerous eagle, a keen guard of the sky. ", "手強いワシ。鋭い目で空を守る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How did such a creature learn to use electricity as a weapon?", "こんな生物がどうやって電気を武器にすることを覚えたのだろう？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerging Zombie", "現れるゾンビ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sprightly falcon, eager to attack in a breakneck pace", "元気なハヤブサ。目にも止まらぬ速さで攻撃したがっている", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The arboreal Fisher Cat", "木の上で暮らすフィッシャー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fisher Cat", "フィッシャー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The red fox, born with a deceitful nature.", "生まれつきずる賢いアカギツネ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gargoyle", "ガーゴイル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A horrid man-made beast, does humanity know no limit?", "恐ろしい人工の獣。人間に限界はないのか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The towering culmination of spirits of fallen soldiers, risen from pure hatred in their souls.", "倒れた兵士たちの魂が集まった巨大な存在。魂の純粋な憎しみによって立ち上がった。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Genet", "ジェネット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The slender Genet can sneak past airborne creatures.", "細身のジェネットは飛行生物をこっそり通り抜けられる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Lobster", "巨大ロブスター", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An eternal lifespan can lead to dire changes in a creature.", "永遠の寿命は生物に恐ろしい変化をもたらすことがある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goblin", "ゴブリン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ever-hungry imp of greed. He shall give you an item... But not without a cost.", "常に飢えた強欲な小悪魔。アイテムをくれるが……代償なしではない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goose", "ガチョウ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The phoney goose. Rarely will a creature call its bluff.", "見せかけだけのガチョウ。そのはったりを見抜く生物はめったにいない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haggard", "魔骸", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the abominable Haggard, a wretched hulking beast.", "忌まわしい魔骸。卑しく巨大な獣。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hammerhead", "シュモクザメ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The perceptive Hammerhead, able to retaliate against those that tread into its waters", "鋭い感覚を持つシュモクザメ。自分の水域に入る者に反撃する", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hawk Wasp", "オオベッコウバチ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The threatening Hawk Wasp. An intelligent hunter.", "脅威となるオオベッコウバチ。賢い狩人だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hellhound", "地獄の猟犬", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It spreads misery to those its near, making them suffer its pain", "近くの者に不幸を広め、自分の痛みを味わわせる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heron", "アオサギ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The keen-eyed heron is able to perforate through aquatic creatures.", "鋭い目を持つアオサギは、水生の生物を突き刺せる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Highland Cow", "ハイランド牛", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The tranquil highland cow, able to shrug off assaults by grazing the land", "穏やかなハイランド牛。草を食べることで攻撃をものともしない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Horde", "死者の大群", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Hunter", "狩人", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "\"It's all about the sport\" he claims, though his true intentions still remain a mystery.", "「すべて狩りを楽しむためだ」と彼は言うが、真の目的は謎のままだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Hunter's Bible", "狩人の聖書", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iguana", "イグアナ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The battered iguana, its power weakens without its tail.", "傷だらけのイグアナ。尾を失うと力が弱まる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Isopod", "ダイオウグソクムシ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stricken with gigantism, the giant isopod can resist most forms of harm.", "巨大化したダイオウグソクムシは、ほとんどの害に耐えられる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jaguar", "ジャガー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beware the efficacy of a Jaguar's hunt.", "ジャガーの狩りの効率に気をつけよう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jellyfish", "クラゲ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A simple invertebrate, with barbed tentacles capable of paralyzing the biggest of creatures.", "単純な無脊椎動物。棘のある触手は最大級の生物も麻痺させる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jerboa", "トビネズミ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A meager rodent, the jumpy Jerboa will carelessly leap throughout the board.", "小さな齧歯類。跳ね回るトビネズミは盤上を無造作に飛び回る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jiangshi", "キョンシー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This ghastly cadaver steals life energy from unfortunate souls.", "恐ろしい死体。不運な魂から生命エネルギーを奪う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kappa", "カッパ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A direful spirit of the sea, it will take those who dare tread its waters.", "恐ろしい海の霊体。水域に踏み込む者を連れ去る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "King Cobra", "キングコブラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The prestigious King Cobra, its venom slowly cripples any aggressor.", "威厳あるキングコブラ。その毒は襲う者を徐々に蝕む。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Komodo Dragon", "コモドドラゴン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The baneful Komodo, with a bite so caustic, it's victim is guaranteed a painful death.", "危険なコモドドラゴン。その腐食性の強い噛みつきは、犠牲者に苦痛の死を約束する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Krampus", "クランプス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "emerging from the winter forests, the hateful krampus marches through, carrying unfortunate souls in his sack.", "憎しみに満ちたクランプスが冬の森から現れ、不運な魂を袋に入れて歩く", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kuchisake-onna", "口裂け女", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is she hiding behind that mask?", "そのマスクの下に何を隠している？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antlion Larva", "アリジゴクの幼虫", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the antlion larva is a proficient hunter, though with such dwindling youth.", "アリジゴクの幼虫は熟練の狩人。ただし幼い時期は残り少ない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ferocious leopard. Born with an insatiable hunger.", "獰猛なヒョウ。生まれながらに満たされない飢えを抱える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lethargic Dragon", "眠気に沈む竜", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The proud lion, a courageous soul able to empower its kin.", "誇り高いライオン。勇敢な魂で仲間を鼓舞する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lobster Claw", "ロブスターのハサミ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The solitary Lynx attacks with its sharp claws and teeth.", "孤独なオオヤマネコは鋭い爪と牙で攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mako Pup", "アオザメの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The juvenile Mako pup, its no less crafty in it's childlike state.", "幼いアオザメの子。子どもの姿でも狡猾さは変わらない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mandrill", "マンドリル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mandrill, an aggressive and hefty old-world monkey.", "攻撃的で大柄な旧世界ザル、マンドリル。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nessie", "ネッシー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remorseless creature, born from a long-forgotten era.", "遠い昔に忘れられた時代から生まれた、無慈悲な生物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightcrawlers", "ナイトクローラー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such weird creatures they are, acting as one.", "奇妙な生物たち。まるで一つのように動く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not Jerma", "ジェルマではない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I... Don't really know what to say about this one.", "これについては……本当に何と言えばいいか分からない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Golem", "古いゴーレム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a long deactivated protector, born with sentience but no heartbeat.", "長い間停止していた保護者。知覚を持って生まれたが、鼓動はない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Osprey", "ミサゴ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Piscivorous Osprey, with claws tailored to catch its prey in the water.", "魚を食べるミサゴ。水中の獲物を捕らえるのに適した爪を持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owl", "フクロウ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The predatory Owl grows vicious against other birds, cutting their wings.", "捕食者のフクロウは他の鳥に容赦なく、その翼を切り落とす。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasite", "寄生虫", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Penguin", "ペンギン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the flightless penguin. An agile swimmer.", "飛べないペンギン。泳ぎは俊敏だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom", "幻影", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "\"The dead shall never rest\" is a statement that rings true for the phantom.", "「死者は決して眠らない」。この言葉は幻影に当てはまる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raging Dragon", "怒れる竜", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He has risen.", "彼はよみがえった。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raging King Dragon", "怒れる竜王", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scavenger", "あさり屋", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the resourceful scavenger, what little consciousness is left is spent on bone collecting.", "機転の利くあさり屋。残されたわずかな意識を骨集めに費やす。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scorpion", "サソリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The rancorous Scorpion. With a potent venom capable of slaying most prey.", "恨み深いサソリ。強力な毒はほとんどの獲物を殺す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shark Fin", "サメのヒレ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrike", "モズ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The gruesome Shrike uses spiked branches to its advantage.", "むごたらしいモズはトゲ付きの枝を巧みに使う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Siguanaba", "シグアナバ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sorrowful spirit that wanders near lakes, luring unwary souls to their demise.", "湖の近くをさまよう悲しげな霊体。油断した魂を死へと誘う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El Silbon", "エル・シルボン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A greedy miscreant. I wonder which bones are from his ascendant?", "強欲な悪党。どの骨が彼の祖先のものなのだろう？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skinwalker", "スキンウォーカー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the malevolent shapeshifter, able to take form of any animal it kills.", "悪意ある変身者。殺した動物なら何にでも姿を変えられる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sleeping Dragon", "眠る竜", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "May the gods have mercy on any sorrowful soul who wakes it.", "これを目覚めさせた哀れな魂に、神々の慈悲があらんことを。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disturbed Dragon", "眠りを妨げられた竜", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sloth Bear", "ナマケグマ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The docile sloth bear, it swipes wildly when it feels threatened.", "温厚なナマケグマ。脅かされるとやたらに爪を振り回す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiked Branches", "トゲ付きの枝", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stalker", "忍び寄る者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a husk of a human, doomed to an infernal punishment.", "人間の抜け殻。地獄の責め苦を受ける運命にある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strigoi", "ストリゴイ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Blood-hungry beast of hell, the Strigoi is evil incarnate.", "血に飢えた地獄の獣、ストリゴイは邪悪そのものだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "superstar", "スーパースター", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "he gets a lot of money, and drives fancy cars.", "大金を稼ぎ、派手な車を乗り回す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thorny Dragon", "トゲのドラゴン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Thorny Dragon uses its spikes to deterr predators.", "トゲのドラゴンは棘で捕食者を遠ざける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thresher Shark", "オナガザメ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The crafty Thresher, it uses its tail to attack prey.", "狡猾なオナガザメは尾を使って獲物を攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thunderbird", "サンダーバード", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "born from the mad skies, This Terrorbird dwarves the largest of known creatures.", "狂った空から生まれたこの恐鳥は、知られる限り最大の生物すら小さく見せる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiger", "トラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Frightful apex predator, the tiger attacks the weak first.", "恐ろしい頂点捕食者のトラは、弱い者から先に攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tuna", "マグロ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fish that is a lot larger than you may believe.", "想像するよりずっと大きな魚。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the solitary vampire works best when alone.", "孤独な吸血伯爵は一人でいるときに最も力を発揮する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warthog", "イボイノシシ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the savage warthog, it's attack style is unpredictable.", "荒々しいイボイノシシ。その攻撃は予測できない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wendigoon", "ウェンディグーン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this... is not one of my deathcards...", "これは……私のデスカードじゃない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey there. ", "やあ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "how's it going?", "調子はどう？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hey.", "よお。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "how's it hanging?", "元気か？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'Sup.", "よっ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think", "多分", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you know what", "何をしているか", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you're doing.", "分かってるよな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "here we go.", "行こう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "let's get to it.", "さっさとやろう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "alright.", "よし。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "guess I'm here now.", "どうやらここに来たみたいだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:3] Ow...", "[e:3] 痛っ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2] God. it's one of", "[e:2] うわ、またこういう", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2] these games...", "[e:2] ゲームか……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "stop it.", "やめろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "goddamnit.", "くそっ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2] [c:R]can you f#@k off? [c:]", "[e:2] [c:R]とっとと失せてくれないか？ [c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2] ow.", "[e:2] 痛っ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2] [c:R] son of a bitch.", "[e:2] [c:R] くそったれ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well shit...", "くそっ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:3] hey!", "[e:3] おい！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:3] wait wait wai-", "[e:3] 待て待て待――", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "come on now.", "おいおい、勘弁してくれ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2] again?", "[e:2] また？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2] really?", "[e:2] マジで？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2] come on...", "[e:2] 勘弁してくれ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2] You're kidding..", "[e:2] 冗談だろ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:4] Huh,", "[e:4] おや、", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:dB] this is new. [c:]", "[c:dB] これは初めてだ。 [c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:dB] cool.", "[c:dB] いいね。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:dB] 'aight.", "[c:dB] いいだろう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:dB] guess I'll have it.", "[c:dB] もらっておくか。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2] should've seen this one coming.", "[e:2] こうなると分かってたはずなのに。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "goddamnit....", "くそっ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2] [c:R] what the hell is wrong with you?", "[e:2] [c:R] お前、一体どうかしてるのか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2] [c:R] go to hell...", "[e:2] [c:R] 地獄に落ちろ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey there...", "やあ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[w:2] ...", "[w:2] ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:3] I gotta be honest...[w:1]", "[e:3] 正直に言うと……[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:3] I have no idea", "[e:3] どうして", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:3] how I got here.", "[e:3] ここに来たのか分からない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:4] this feels....", "[e:4] この感じ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R] familiar...", "[c:R] 見覚えがある……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hey there.", "やあ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2] This guy is really weird...", "[e:2] こいつ、本当に変だ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:3]does he just", "[e:3]こいつ、いつも", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:3]do this regularly?", "[e:3]こんなことをしてるのか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "word of advice,", "忠告しておく。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "unless you got", "不死みたいなのが", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "something like unkillable..", "ない限り……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2]try not to waste", "[e:2]できるだけ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "your good cards in phase 1.", "第1段階でいいカードを無駄にするな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:3]This guy again...", "[e:3]またこいつか……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you probably know", "もう何をすればいいか", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the drill by now.", "分かってるだろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2]God...", "[e:2]なんてことだ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2]it reeks like death.", "[e:2]死の臭いがする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:3]don't tell me those", "[e:3]まさかあれは", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:3]are real dead fish.", "[e:3]本物の死んだ魚じゃないだろうな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This boss again...", "またこのボスか……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2]great....", "[e:2]やったね……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you know the drill,", "いつもの通り、", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "throw a squirrel", "リスか何かを", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "or something when", "投げてやればいい、", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "he takes out the hook.", "フックを出したときに。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2]yadda yadda..,", "[e:2]はいはい……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you should be fine.", "君なら大丈夫だろう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm honestly sick of this one.", "こいつには本当にうんざりだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:4] Trapper, huh? [w:2]", "[e:4] 罠猟師か？ [w:2]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:3]I got a bad feeling about this.", "[e:3]嫌な予感がする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "let's get this over with.", "さっさと終わらせよう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "trapper again,", "また罠猟師か。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2]great...", "[e:2]やったね……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:4]huh...", "[e:4]ふむ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "these pelts might seem helpful.", "この毛皮は役に立つかもしれない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2]let's end this.", "[e:2]終わらせよう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "we're finally here..", "ようやく着いた……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You got this, man.", "君ならやれるよ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:1] I believe in you.", "[e:1] 君を信じている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2] god I'm sick", "[e:2] ああ、もううんざりだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2]of this guy.", "[e:2]こいつには。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "please win.", "頼むから勝ってくれ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm feeling", "今回は", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "optimistic this time.", "うまくいきそうだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:1] I think you got this.", "[e:1] 君ならやれると思う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wisp", "鬼火", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a spirit of pure fire, one of which requires fuel to grow.", "純粋な炎の霊体。成長には燃料が必要だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Xolotl", "ショロトル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sinister god of twilight, banished into the bodies of meager amphibians, has risen from his ancient shackles.", "薄暮の邪悪な神。弱い両生類の体に追放され、古代の枷から立ち上がった。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zebra", "シマウマ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vitriolic zebra will stop at nothing to kill whatever is there to harm it.", "辛辣なシマウマ。自分を傷つけようとするものを殺すためなら手段を選ばない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The grim zombie, a punished soul forced to wander for eternity.", "陰気なゾンビ。罰を受けた魂は永遠にさまよい続ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emporer Penguin", "コウテイペンギン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clouded Leopard", "ウンピョウ", Language.Japanese);

            //sigils
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apex Predator", "頂点捕食者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifice 2 cards to boost [creature]'s attack by 1.", "カードを2枚生贄に捧げ、[creature]の攻撃力を1上げる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonepile Strafe", "骨の山を残す移動", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] will move, leaving a pile of bones in it's place.", "所有者のターン終了時、[creature]は印の方向に移動し、元の場所に骨の山を残す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, the sigil bearer will move, leaving a pile of bones in it's place.", "所有者のターン終了時、印の持ち主は印の方向に移動し、元の場所に骨の山を残す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon placing the sigil bearer, draw an acorn. An acorn is defined as: 1 health, fledgling.", "印の持ち主を置くと、ドングリを1枚引く。ドングリは体力1、雛を持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "at the end of the enemy's turn, the card owner's board is fully replaced with a 'the horde'.", "カードの所有者のターン開始時、所有者のサイドのすべてのマスが死者の大群に置き換わる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summons a cicada swarm on the owner's board, placing cicada cards on their side wherever it can.", "所有者の盤にセミの群れを召喚し、そのサイドの置ける場所にセミのカードを配置する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wendigo's Ambush", "ウェンディゴの待ち伏せ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wendigo will move to your board at the end of my turn.", "私のターン終了時、ウェンディゴは君の盤に移動する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A heavy burden to carry all those bones.", "あれほどの骨を運ぶのは重荷だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A poor soul has awakened the beast.", "哀れな魂が獣を目覚めさせた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bird of Prey", "猛禽", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying cards struck by [creature] will take 1 damage each time it declares an attack, and renders their wings useless.", "[creature]に攻撃を受けた飛行カードは、ただちに飛行能力を失い、以後はそのカード自身が攻撃を宣言するたびに1ダメージを受ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying cards struck by the sigil bearer will take 1 damage each time it declares an attack, and renders their wings useless.", "印の持ち主に攻撃を受けた飛行カードは、ただちに飛行能力を失い、以後はそのカード自身が攻撃を宣言するたびに1ダメージを受ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sentry of the skies, keeping things grounded.", "空の哨兵。すべてを地上にとどめる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dog Summon", "犬の召喚", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sigil bearer will move to an empty adjacent slot and leave a bloodhound.", "印の持ち主は隣接する空きスロットに移動し、ブラッドハウンドを残す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "doesn't she look beautiful?", "彼女は美しく見えないか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So impatient....", "なんてせっかちなんだ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infested", "感染", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, draw a parasite into your hand.", "[creature]が打たれると、寄生虫を1枚引いて手札に加える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "is the host alive or merely being puppeted? Best not to know.", "宿主は生きているのか、それとも操り人形なのか？　知らないほうがいい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrieker's call", "叫ぶ者の呼び声", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the opponent's turn ends, [creature]'s board is replaced with a zombie horde.", "所有者のターン開始時、[creature]のサイドのすべてのマスがゾンビの大群に置き換わる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A painful screech is echoed throughout.", "痛ましい叫び声が響き渡る。", Language.Japanese);

            //encounters
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caribou", "カリブー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alebrije", "アレブリヘ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anteater", "アリクイ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caiman", "カイマン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caribou Fawn", "カリブーの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Condor", "コンドル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lobsterzilla", "ロブスターゴジラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giraffe", "キリン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gold Pile", "金の山", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaker", "漏らす者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minotaur", "ミノタウロス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reaper", "死神", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhino", "サイ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrieker", "叫ぶ者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it's best to take it down before it launches its cry.", "叫びを上げる前に倒すのが一番だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stone Wall", "石の壁", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brambles", "イバラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legends From The Darkness: Encounters", "闇からの伝説：エンカウント", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "an Ever-expanding content pack for LFTD, meant to add battle encounters to the game.", "闇からの伝説のための、拡大を続けるコンテンツパック。ゲームに戦闘エンカウントを追加する。", Language.Japanese);

        }
    }
    public class GarethMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for GarethMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gareth's Mod", "GarethのMod", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A part 1 booster pack created by Gareth48 and illustrated by Plutraser. Adds [count] cards and 7 sigils designed to fit right into vanilla Inscryption.", "Gareth48が制作し、Plutraserが描いた第1部のブースターパック。[count]枚のカードと7つの印が追加され、本編のInscryptionに自然に溶け込む。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gareth48", "Gareth48", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sorry, can't do that", "ごめん、それはできない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whats... he doing here?", "なぜ……彼がここに？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skinwalker", "スキンウォーカー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The enigmatic skinwalker. It mimics the identity of the first creature it slays.", "謎めいたスキンウォーカー。最初に殺した生物の姿をまねる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wounded Animal", "傷ついた動物", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An easy target for hungry predators.", "飢えた捕食者には格好の獲物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lemming", "レミング", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The paranoid lemming. Fragile and a favorite treat among many animals.", "用心深いレミング。弱く、多くの動物に好まれる獲物だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Treant", "トレント", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How did this creature get here?", "この生物はどうやってここに来た？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snag", "障害物", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapling", "苗木", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With time, even the smallest sapling becomes a massive, imposing obstacle.", "時がたてば、小さな苗木でさえ巨大で威圧的な障害物になる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oxpecker", "ウシツツキ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The adored Oxpecker. A bird capable of befriending even the fiercest of foes.", "愛されるウシツツキ。最も獰猛な敵とさえ仲良くなれる鳥。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sturdy elephant. Friendly but not weak.", "頑丈なゾウ。友好的だが弱くはない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cackling hyena. It always has an ally lurking in the shadows.", "笑うハイエナ。いつも仲間が影に潜んでいる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The aggressive panther. Never one to back down from a fight.", "攻撃的なクロヒョウ。戦いから決して引かない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Panther Cub", "クロヒョウの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The young panther. Even now its caution is unwavering", "若いクロヒョウ。今も警戒を怠らない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tasmanian Devil", "タスマニアデビル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vicious Tasmanian devil. A fierce carnivore with a voracious appetite.", "凶暴なタスマニアデビル。食欲旺盛な肉食動物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Archerfish", "テッポウウオ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The archerfish, an excellent marksman, known to shoot bugs out of the air with a blast of water.", "テッポウウオは見事な射手。水を噴き、空中の虫を撃ち落とすことで知られる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hercules Beetle", "ヘラクレスオオカブト", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The forceful Hercules beetle. It can move creatures many times its size.", "力強いヘラクレスオオカブト。何倍もの大きさの生物を動かせる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Golem", "ゴーレム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ancient golem. The magic that binds it is old but powerful. It will reform after death.", "古代のゴーレム。縛る魔法は古いが強力だ。死後に再形成される。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The awe-inspiring lion. Sure to lead your creatures to victory.", "威厳あるライオン。君の生物をきっと勝利へ導く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juvenile Lion", "ライオンの幼体", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lion Cub", "ライオンの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The princely lion cub. Given time it will become the king of its pride.", "王子のようなライオンの子。時がたてば群れの王になる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Piranha", "ピラニア", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ferocious piranha. Schools can devour any living thing in seconds.", "獰猛なピラニア。群れならどんな生き物も数秒で食べ尽くす。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stealthy leopard. Invisible to its prey until it's too late.", "忍び寄るヒョウ。獲物は手遅れになるまでその姿に気づかない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Killer Bee Swarm", "キラービーの群れ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vicious killer bee. The more one fights the more will swarm.", "獰猛なキラービー。戦えば戦うほど群れが増える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ravenous pig. Its hunger is insatiable, it will eat and eat until nothing remains.", "食いしん坊のブタ。その飢えは尽きず、何も残らなくなるまで食べ続ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Badger", "アナグマ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bothersome badger. Quick to strike and retreat back into the shadows.", "厄介なアナグマ。素早く攻撃し、再び影の中へ退く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bobcat", "ボブキャット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wily bobcat. Unafraid to defend its territory but smart enough to know when to retreat.", "ずる賢いボブキャット。縄張りを恐れず守り、退き時も心得ている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hasty dragonfly. Few can hit an insect this fast.", "せっかちなトンボ。これほど速い昆虫を捕らえる者は少ない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allies", "味方", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature bearing this sigil dies, a random ally will temporarily join your hand to avenge it.", "この印を持つ生物が死亡すると、ランダムな味方が仇を討つため一時的に手札に加わる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems a creature has come to avenge the passing of its ally.", "仲間の死の仇を討つため、生物がやって来たようだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Essence Steal", "精髄の窃取", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature bearing this sigil kills another, it transforms into an exact copy of it.", "この印を持つ生物が別の生物を倒すと、倒した生物の完全なコピーに変身する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your creature has slain mine, and will now become an imitation of it.", "君の生物が私の生物を倒した。今度はその姿をまねることになる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After a creature bearing this sigil attacks the user chooses a space. The creature will move to that space.", "この印を持つ生物の攻撃後、プレイヤー側の空きマスを選び、その生物をそこへ移動する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It retreated after it struck, perhaps it's regathering its strength for another strike.", "攻撃後に退いた。また攻撃するため力を蓄えているのかもしれない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hungry", "空腹", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature bearing this sigil is played, choose another friendly creature to eat. The eaten creature will have its health and power added to the creature bearing this sigil.", "この印を持つ生物を出すと、食べる別の味方生物を選ぶ。食べられた生物の体力と攻撃力は、この印を持つ生物に加わる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems eating another creature has caused yours to grow stronger.", "別の生物を食べたことで、君の生物は強くなったようだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shove", "押しのけ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature bearing this sigil is played, it will move up to the space opposing it. Creatures that are in the way will be pushed in the same direction.", "プレイヤーがこの印を持つ生物を出すと、正面にカードがあれば相手の待機列に押し戻す。その後、この生物は相手のカードとなり正面のマスへ移動する。正面のカードが切断不可の特性を持つ場合は押せず、移動もしない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have such fickle allies.", "君の味方は気まぐれだな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Standoffish", "よそよそしい", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as a creature bearing this sigil is opposed by another, it has +2 attack.", "この印を持つ生物は、正面に別の生物がいる間、攻撃力が+2される。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tasty", "おいしい", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature bearing this sigil dies, a random creature shows up to devour it.", "この印を持つ生物が死亡すると、ランダムな生物が現れてそれを食べる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your creature will fight with all it has until none oppose it.", "君の生物は、敵対するものがいなくなるまで全力で戦う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems that another animal has come to feed. The cycle of life continues.", "また動物が食べに来たようだ。命の循環は続く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curious, I don't seem to remember this creature...", "妙だな、この生物には見覚えがない……", Language.Japanese);

        }
    }
    public class LifeCostAPIMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Life_Cost_API Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leck", "レック", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Lost Beast, in the shape of a tooth, showing up only in error.", "歯の形をした迷い獣。エラーによってのみ現れる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meck", "メック", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Teck", "テック", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have enough [c:bG]Life[c:] or [c:gray]Foils[c:] to play that. Damage your opponent to gain more [c:bG]Life[c:].", "これを出すには[c:bG]生命[c:]または[c:gray]プレミアム[c:]が足りない。対戦相手にダメージを与えて[c:bG]生命[c:]を増やそう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have enough [c:bG]Life[c:] on your scales to play that. Damage your opponent to gain more [c:bG]Life[c:].", "天秤の[c:bG]生命[c:]が足りず、これを出せない。対戦相手にダメージを与えて[c:bG]生命[c:]を増やそう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have enough [c:gray]Foils[c:] to play that. You gain [c:gray]Foils[c:] by dealing overkill damage.", "これを出すには[c:gray]プレミアム[c:]が足りない。過剰ダメージを与えると[c:gray]プレミアム[c:]を得られる。", Language.Japanese);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Max Energy Gamble", "最大エネルギーの賭け", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 6 energy to put 0 to 3 damage on someone's side of the scale", "エネルギーを6払い、天秤のどちらかの側に0～3のダメージを置く", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Die Roll", "サイコロを振る", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Money for Blood", "お金を血に", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 5 Life/Foils to gain between 0 and 6 increase in stats, distributed randomly", "生命／プレミアムを5払い、0～6の能力値増加をランダムに振り分ける", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sing it once, Sing it twice, take a chance and roll the dice!", "一度歌って、二度歌って、運試しにサイコロを振ろう！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cash Converter", "現金変換器", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 foils to put 1 damage on your opponent's side of the scale", "プレミアムを4払い、天秤の相手側に1ダメージを置く", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life Converter", "生命変換器", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 life to gain 1 foils", "生命を2払い、プレミアムを1得る", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vamperic Strength", "吸血の力", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 life to increase the power and health of this card by 1", "生命を3払い、このカードの攻撃力と体力をそれぞれ1上げる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood for money", "血をお金に", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hurting oneself can lead to an increase in strength.", "自分を傷つければ力が増すこともある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greedy Strength", "強欲の力", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 5 currency to increase the power and health of this card by 1", "通貨を5払い、このカードの攻撃力と体力をそれぞれ1上げる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A puddle that errods all that touches it.", "触れたものすべてを腐食させる水たまり。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One can be hired to do many tasks", "さまざまな仕事に雇える", Language.Japanese);

        }
    }
    public class EriCardExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Eri_Card_Expansion Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Young Bear", "若いクマ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A young grizzly, old enough to defend itself.", "幼いグリズリー。自分の身を守れる年頃だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crow", "カラス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ominous crow, an omen of death", "不吉なカラス。死の前兆", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Electric Eel, it will shock the creatures next to its target", "デンキウナギは標的の隣にいる生物に電撃を与える", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elk Skeleton", "エルクの骸骨", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A short one? Strange", "背が低い？　妙だな", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malaysian Ant", "マレーシアアリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Malaysian Ant, it will explode to protect the nest", "マレーシアアリは巣を守るため自爆する", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'Heavy' Bird", "「重い」鳥", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm not sure how that one can still fly", "どうしてまだ飛べるのか分からない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In cooking, always use much garlic. But one should be sufficient for our purposes.", "料理にはいつもたっぷりのニンニクを使う。だが、我々の目的なら一つで十分だろう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rotting Garlic", "腐ったニンニク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Leech", "巨大なヒル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A nasty vermin, it will drain the lifeforce of it's foes", "厄介な害虫。敵の生命力を吸い取る", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gorilla", "ゴリラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The powerful gorilla, it will lead your team", "力強いゴリラが君のチームを率いる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diving Hawk", "急降下するタカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic hawk, hunting its prey", "威厳あるタカが獲物を狩る", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soaring Hawk", "舞い上がるタカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic hawk, soaring in the sky", "威厳あるタカが空を舞う", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hedgehog", "ハリネズミ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, the wise hedgehog. Swift to escape danger.", "ああ、賢いハリネズミ。危険から素早く逃げる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ferocious Honey Badger, it will grows stronger when attacked", "獰猛なラーテル。攻撃されると強くなる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't underestimate the might of this scavenger", "このあさり屋の力を侮るな", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Egg", "カマキリの卵", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With time this egg will become a powerful mantis", "時がたてば、この卵は強力なカマキリになる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fitting name, for one who learns its song from others.", "他の者から歌を学ぶ相手には、ぴったりの名前だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Myconid", "マイコニド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The easily annoyed myconid, not quite sure what they're about", "怒りっぽいマイコニド。何を考えているのかよく分からない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oak Tree", "オークの木", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Octopus", "タコ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Goat", "年老いたヤギ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The apotheosized Goat. This one is long due for a sacrifice.", "神格化されたヤギ。とうに生贄になるべきだった。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owlbear", "アウルベア", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The savage Owlbear, it will rampage through its opponents.", "獰猛なアウルベアが敵陣を暴れ回る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owlcat", "フクロウネコ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Half cat, half owl... an aberation really.", "半分ネコで半分フクロウ……まさに異形だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owlslime", "フクロウスライム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh no... what happenned to that owl?", "なんてことだ……あのフクロウに何があった？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Platypus", "カモノハシ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He's a platypus. They don't do much.", "カモノハシだ。あまり何もしない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A regrettable fate. But perhaps he may be of some use, yet.", "残念な運命だ。だが、まだ役に立つかもしれない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valley Raccoon", "谷のアライグマ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The conniving raccoon, it will use the strenghts of his opponent against them", "狡猾なアライグマ。相手の長所を逆手に取る", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Horn", "オオツノヒツジ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The powerful ram will clear most things standing in your way", "力強いオスヒツジは行く手を阻むものの大半を片づける", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rat Skeleton", "ネズミの骸骨", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remnant of a rat... Can't be picky when you're starving for ressources", "ネズミの残骸……資源に飢えているときは選り好みできない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Red Fox", "アカギツネ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The red fox, a source of terror to the meek rabbit", "アカギツネ。おとなしいウサギにとって恐怖の源だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The massive Rhinoceros, nothing will stop its charge", "巨大なサイ。その突進を止められるものはない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ring-Tailed Lemur", "ワオキツネザル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He likes to move it.", "彼は体を動かすのが好き。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Jelly", "ローヤルゼリー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This sweet jar attract both ants and bees", "この甘い瓶はアリもハチも引き寄せる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sea Otter", "ラッコ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cunning sea otter, it will dive to kill submerged creature", "狡猾なラッコは潜って水中の生物を狩る", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Secretary Bird", "ヘビクイワシ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This secretary bird, it will only fly away when outmatched", "このヘビクイワシは相手に勝てないときだけ飛び去る", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sheep", "ヒツジ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What do you intend to do with a flock of sheep", "ヒツジの群れをどうするつもりだ？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snail", "カタツムリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A snail, safe in its shell", "殻の中で安全に過ごすカタツムリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sniper Ant", "狙撃アリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small sharpshooter, more dangerous than it appears", "小さな狙撃手。見た目より危険だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The resistant thorny devil, creature fighting it should be wary", "頑丈なモロクトカゲ。戦う生物は気をつけるべきだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Truffle Hog", "トリュフブタ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tasty beast obsessed with hidden treasures.", "隠された宝に夢中なおいしい獣。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Griffon Vulture", "シロエリハゲワシ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Griffon Vulture will feed on your dead but will not stick around", "シロエリハゲワシは君の死者を食べるが、長居はしない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Walrus", "セイウチ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The massive walrus, a very territorial beast", "巨大なセイウチ。縄張り意識の強い獣", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warthog", "イボイノシシ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "White Wolf", "白いオオカミ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The arctic white wolf, the smell of blood will strengthen the pack", "北極の白いオオカミ。血の臭いが群れを強くする", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wolf Skeleton", "オオカミの骸骨", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wolf is as dangerous in this form as it used to be", "この姿になっても、オオカミの危険さは変わらない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ant Husk", "アリの抜け殻", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The husk of an ant, their dedication truly know no bounds", "アリの抜け殻。彼らの献身には本当に限りがない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nest Worker", "巣作りの働きアリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unrelenting ant worker, taking care of its nest", "たゆまぬ働きアリが巣の世話をする", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a cute little critter", "なんてかわいい小動物だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Cub", "子グマ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With time, this young one may grow into a powerful beast.", "時がたてば、この子は強い獣に育つかもしれない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Skeleton", "クマの骸骨", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A terrible creature that shouldn't allow to be.", "存在を許されるべきではない恐ろしい生物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bell Warrior", "ベルの戦士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tricky little fighter.", "一筋縄ではいかない小さな戦士。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bird Skeleton", "鳥の骸骨", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remnant of a bird, no longer will it fly", "鳥の残骸。もう飛ぶことはない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Totem", "骨のトーテム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An idol dedicated to death and rebirth", "死と再生に捧げられた偶像", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buffalo", "スイギュウ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The massive buffalo, it will tackle its opponent out of the way when played", "巨大なスイギュウ。出すと相手に突進して押しのける", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Capuchin", "オマキザル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The agile capucin, it will avoid incomming attack", "俊敏なオマキザルは迫り来る攻撃を避ける", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carrion Ant", "腐肉アリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They'll strip a dead body clean. Or a live one.", "死体をきれいに食べ尽くす。生きた体でも同じだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carrion Swarm", "腐肉アリの群れ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The resilient crab. It’s hard shell will lessen any damage it takes.", "しぶといカニ。硬い甲羅が受けるダメージをすべて軽減する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gator", "アリゲーター", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most dangerous beast lurking the wetlands", "湿地に潜む最も危険な獣", Language.Japanese);

        }
    }
    public class TheBeastBossBattleMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for The_Beast_Boss_Battle Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come forth and be saved by his light!", "前に出て、彼の光による救いを受けよ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You forgo his teachings? Disgusting!", "その教えを捨てるのか？　忌まわしい！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suddenly, the sky above cracked open, and a white beam of light reached down into the Earth, smiting the Mother of Harlots asunder and setting the blood lake to a boil.", "突然、天が裂け、白い光が大地へ降り注いだ。淫婦たちの母を打ち砕き、血の湖を沸騰させた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, poor, ignorant heretic...you have doomed us all! I can hear their arrival at this moment...!", "ああ、哀れで無知な異端者……お前は我々全員を破滅させた！　もう彼らが来る音が聞こえる……！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No. I won't allow you just take God's power like that. Face it or die.", "いいや。そんなふうに神の力を奪うことは許さない。それに立ち向かうか、死ぬかだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You fought well... But you will need more strenght... and faith... if you want to overcome the challenge. Goodbye for now.", "よく戦った……だがこの試練を乗り越えたいなら、さらなる力と……信仰が必要だ……今はさらば。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you ready to confess your sins?", "罪を告白する準備はできたか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Behold! The apocalypse is imminent!", "見よ！　終末は間近だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So you really want this story to end this way, don't you. Right then.", "本当にこの物語をこんな形で終わらせたいのだな。ならばいい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And the belly of the earth quivered, and so came forth Famine, bringer of strife and ruin.", "大地の腹が震え、争いと破滅をもたらす飢饉が現れた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And henceforth came Pestilence, bringer of the plagues, desecrator of the ill.", "続いて疫病が現れた。病をもたらし、病める者を冒涜する者。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "War, atop his steed, strode with wild abandon. He knew not the inevitable self-destruction his manic nature brought, just as those who meaninglessly conflict themselves.", "戦争は馬に乗り、無謀に進んだ。その狂気が避けられぬ自滅を招くことも知らず、無意味に争う者たちと同じように。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finally, upon his pale horse, arrived Death. The ending of endings, the bringer of salvation and damnation - the reaper of the deceased.", "最後に、青ざめた馬に乗って死が現れた。終わりの終わり、救済と破滅をもたらす者――死者の刈り手。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And so arrives the Mother of Harlots, as forewarned, and as preceded by the untimely deaths of her harbingers.", "こうして淫婦たちの母が予告どおり現れた。その先触れたちは早すぎる死を迎えていた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Repentance", "懺悔", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leshy is replaced as the final boss of the run. Blasphemy!", "レシーに代わる者がランの最後の相手となる。なんたる冒涜！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hell Strike", "地獄の一撃", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack only cards in the two middle slots. If a targeted slot is empty, the damage will be redirected to the opponent.", "[creature]は中央2スロットのカードだけを攻撃する。対象スロットが空ならダメージは対戦相手に向かう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stalactites", "鍾乳石", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of every second turn, a random card on the opponent's side will take 5 damage. If this effect kills that card, a Stalactite is created in its place.", "2ターンごとの開始時、相手サイドのランダムなカード1枚が5ダメージを受ける。そのカードが死亡すると、その場所に鍾乳石が作られる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomber", "爆撃機", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card becomes active, it will deal 4 damage to a random card on the opponent's side. if there are no cards to target, it will deal damage directly", "このカードが起動すると、相手サイドのランダムなカード1枚に4ダメージを与える。対象がなければ直接ダメージを与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Christian Broadcast", "キリスト教放送", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Domga", "教義", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "fat", "脂肪", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "enter the gungeon hardmode", "ガンジョンに入れ・ハードモード", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "starvation from inscryption", "Inscryptionの飢え", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sabs Undersale", "サブスのアンダーテール", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mother of Harlots", "淫婦たちの母", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "wait how did you even get this to evolve", "待て、一体どうやってこれを進化させた？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "wait what the fuck??? wasnt beast supposed to gain +1 attack?? what????", "待て、何だって？？？　獣の攻撃力が+1されるはずじゃなかったのか？？？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this isnt going as planned", "計画どおりにいっていない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You fool. You think I will allow you to skip this battle earlier? Face your sins, you coward!", "愚か者め。戦いを早々に飛ばせると思ったか？　罪と向き合え、臆病者！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stalactite", "鍾乳石", Language.Japanese);

        }
    }
    public class FiveNightsAtInscryptionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for FiveNightsAtInscryption Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have enough [c:bB]Remnant [c:]to play that creature.", "その生物を出すには[c:bB]残響 [c:]が足りない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You think you can skip this fight?", "この戦いを飛ばせると思うか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You think you can skip this fight? Face Me, you coward!", "この戦いを飛ばせると思うか？　私と戦え、臆病者！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your Deck won't starve just yet...", "君のデッキはまだ尽きない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Welcome...", "ようこそ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't worry about someone interrupting us...", "誰かが邪魔する心配はない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fnai Achievements", "FNAIの実績", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Restart", "再起動", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Restart the game and get rid of the Virus inside of the Game.", "ゲームを再起動し、ゲーム内のウイルスを取り除く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trapfinder's Trick", "罠探しの策略", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Try to skip Parts of the fight against the Virus.", "ウイルスとの戦いの一部を飛ばそうとする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quirky at night", "夜の奇行", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Witness Animatronics getting quirky at night.", "夜にアニマトロニクスがおかしな動きをするのを目撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antivirus", "アンチウイルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat The Virus plagueing the Game.", "ゲームを悩ませるウイルスを倒す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Connection Terminated", "接続終了", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Set your entire side ablaze.", "自分のサイドをすべて炎上させる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exotic Butters", "エキゾチックバター", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reach the maximum amount of stolen batteries and make Hand unit attack.", "盗んだ電池を最大数まで集め、携帯端末を攻撃させる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Horror", "恐怖", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Survive the Fight against Springtrap in Fazbears Fright.", "ファズベアーズ・フライトで、スプリングトラップとの戦いを生き延びる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Found Soul", "見つかった魂", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Return the Soul stolen by Glitchtrap to you.", "グリッチトラップに奪われた魂を取り戻す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powerleech", "エネルギー吸い", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain your first Stolen Battery.", "初めて盗まれた電池を手に入れる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Classical", "クラシック", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Classic Animatronics.", "クラシックのアニマトロニクスをすべて手に入れる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Refurbished", "修復済み", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Toy Animatronics.", "トイのアニマトロニクスをすべて手に入れる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Withered Animatronics.", "ウィザードのアニマトロニクスをすべて手に入れる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Phantom Animatronics.", "ファントムのアニマトロニクスをすべて手に入れる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nighmarish", "悪夢のような", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Nightmare Animatronics.", "ナイトメアのアニマトロニクスをすべて手に入れる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Killer Robots", "殺人ロボット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Funtime Animatronics.", "ファンタイムのアニマトロニクスをすべて手に入れる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Last Remnants", "最後の残響", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Scrap Animatronics.", "スクラップのアニマトロニクスをすべて手に入れる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Murderers Legacy", "殺人者の遺産", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all of Aftons forms.", "アフトンのすべての形態を手に入れる。", Language.Japanese);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incarnation", "化身", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon Death, [creature] will transform into another Card and will be added to your Hand.", "[creature]は死亡すると別のカードに変身し、手札に加わる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anger Issues", "怒りっぽい", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Death: [creature] will deal 1 damage to every opposing card.", "死亡時、[creature]は相手のすべてのカードに1ダメージを与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baby", "ベイビー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...A failure to the end.", "……最後まで失敗作だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ballora", "バローラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A familiar creation. She will move differently each time.", "見覚えのある創造物。毎回違う動きをする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Balloon Boy", "バルーンボーイ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An annoyance to the core, it takes that which it doesn't deserve.", "根っからの厄介者。自分にふさわしくないものを奪う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bon Bon", "ボンボン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonnet", "ボネット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonnie Jump", "ボニージャンプ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Energy to move [creature] to any free Slot on your side.", "エネルギーを1払い、[creature]を自分のサイドの任意の空きスロットに移動する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonnie the Bunny", "ウサギのボニー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The guitarist of the Fazbear Band, constantly mistaken to be purple.", "ファズベアー・バンドのギタリスト。紫だとよく間違われる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kill this abomination, please.", "頼むから、この化け物を殺してくれ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lost Soul", "失われた魂", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bucket Bob", "バケツのボブ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You set him down and nothing happens. Then, something stirs beneath your feet. You feel the energy seep into your hands.", "彼を置いても何も起きない。すると足元で何かが動き、エネルギーが手に染み込むのを感じる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Turn End: [creature] will take 1 damage.", "ターン終了時、[creature]は1ダメージを受ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chica the Chicken", "ニワトリのチカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The backup singer of the Fazbear Band, however she is not a duck.", "ファズベアー・バンドのバックシンガー。ただしアヒルではない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Closeted", "閉じこもり", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will get +2/0 after 2 turns of being unopposed.", "[creature]は正面に敵がいない状態が2ターン続くと、+2/0を得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghastly Body", "幽霊の体", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start Of Turn: [creature] will loose 1 Health.", "持ち主のターン終了時、[creature]は1ダメージを受ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Damaged", "損傷", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When struck, [creature] will damage the striker with equal damage.", "[creature]がダメージを受けた時、ダメージの発生源が生存していれば、その現在の攻撃力に等しいダメージを発生源に与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endo 01", "エンド 01", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A suitless skeleton. A useless, easily broken husk.", "着ぐるみを持たない骨格。役に立たず、壊れやすい抜け殻。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endo 02", "エンド 02", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A suitless skeleton. A more reliable husk.", "着ぐるみを持たない骨格。少しは頼りになる抜け殻。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endo Army", "エンド軍団", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Play: [creature] will create multiples of itself in every free slot on [creature]'s side.", "[creature]を出すと、[creature]のサイドの空きスロットすべてにそのコピーを作る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No Remnant", "残響なし", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Death: [creature] will not give any Remnant.", "死亡時、[creature]は残響を一切与えない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Converter", "残響変換器", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will convert 2 Energy into 1 Remnant.", "[creature]はエネルギー2を残響1に変える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ennard", "エナード", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stitched together to make one being...that sounds familiar.", "一つの存在になるよう縫い合わされた……聞き覚えがあるな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Union", "結合", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On other Cards Death: [creature] will gain 1 Health.", "他のカードが死亡すると、[creature]は体力を1得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malhare", "マルヘア", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I always come back!", "私は必ず戻ってくる！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foxys Hook", "フォクシーのフック", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will move until it reaches something, attacking every opposing slot on its way.", "[creature]は何かにぶつかるまで移動し、途中の正面スロットをすべて攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foxy the Pirate", "海賊のフォクシー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A side attraction, with a fast sprint and a rather deadly hook.", "素早く走り、かなり危険なフックを持つ脇役のアトラクション。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freddle", "フレドル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creation of fear. Tiny sharp-toothed faces grin up at you from the dark.", "恐怖から生まれたもの。小さな鋭い歯の顔が、暗闇からにやりと笑う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freddles", "ミニフレディ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Play: [creature] will spawn 3 Freddles and shuffles them into your side deck.", "[creature]を出すと、ミニフレディを3体生み出し、サイドデッキに混ぜる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freddy Fazbear", "フレディ・ファズベアー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The namesake and leader of the Fazbear Band. The one, the only, Freddy Fazbear!", "ファズベアー・バンドの名を冠するリーダー。唯一無二のフレディ・ファズベアー！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freddy Mask", "フレディのマスク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reduces all Cards Attack by 1, cannot be used on some Animatronics.", "すべてのカードの攻撃力を1下げる。一部のアニマトロニクスには使えない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm... The Mask, it prevents some Animatronics from attacking...", "うーん……マスクは一部のアニマトロニクスの攻撃を防ぐ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funtime Foxy", "ファンタイム・フォクシー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A familiar creation. Nothing can stand in their way.", "見覚えのある創造物。その行く手を遮るものはない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funtime Freddy", "ファンタイム・フレディ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A familiar creation. His Companion, Bon Bon, also attacks with him.", "見覚えのある創造物。相棒のボンボンも一緒に攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Collector", "残響の収集家", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Play: Gain 1 Remnant.", "場に出すと、残響を1得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Golden Freddy", "ゴールデンフレディ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...I don't like the look of this one.", "……こいつの見た目は好きじゃない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand Unit", "携帯端末", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see what you were trying to choose and I will auto correct it for you. Thank you for choosing Hand Unit.", "選ぼうとしたものが分かりました。自動的に修正します。携帯端末をお選びいただきありがとうございます。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Last Will", "遺言", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Death: [creature] will give you 2 Remnant.", "死亡時、[creature]は君に残響を2与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lefty", "レフティ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A container for something far more troublesome.", "もっと厄介なものを入れる容器。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lolbit", "ロルビット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TECHNICAL DIFFICULTIES. PLEASE STAND BY.", "技術的な問題が発生しました。しばらくお待ちください。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mangle Strafe", "マングル移動", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the Owners turn a [creature] will move in the Sigil Direction and leave behind a pile of Wire(0/1,Sharp Quills).", "所有者のターン終了時、[creature]は印の方向に移動し、ワイヤーの山（0/1、針毛）を残す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mimic", "模倣者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minireena", "ミニリーナ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Molten Freddy", "モルテンフレディ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mass of wires lashing out at everything in reach.", "手の届くすべてを打ちすえるワイヤーの塊。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mr Can Do", "ミスター・キャンドゥ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rusted can with a vacant smile. It doesn't do much, but if you feed it enough power, it coughs up something useful. The process seems... unnatural.", "虚ろな笑みを浮かべた錆びた缶。普段は何もしないが、十分なエネルギーを与えると役立つものを吐き出す。その過程は……不自然だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mr Hugs", "ミスター・ハグ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A... Vaccuum? It shuffles along, leaving a strange, lingering presence in its wake", "掃除機……？　ゆっくり動き回り、後には奇妙な気配が残り続ける", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare", "悪夢", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A shadow of terror. It draws power from the fears you hold close to yourself.", "恐怖の影。君が心に抱える恐れから力を得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare Bonnie", "ナイトメア・ボニー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creation of fear. He waits in silence, unmoving. You know he's there, even when you close your Eyes.", "恐怖から生まれたもの。静かに動かず待っている。目を閉じても、そこにいると分かる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare Chica", "ナイトメア・チカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creation of fear. Her gaping, hollow maw shouldn't be able to open that wide. The Noise she makes is neither human nor mechanical -it's something else entirely.", "恐怖から生まれたもの。その虚ろな口は、あれほど大きく開くはずがない。彼女の声は人間でも機械でもない――まったく別の何かだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare Foxy", "ナイトメア・フォクシー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creation of fear. He lurks just out of sight. The longer you ignore him, the closer he gets. When he strikes, there won't be time to react.", "恐怖から生まれたもの。視界の外に潜み、無視するほど近づいてくる。襲われたら反応する暇はない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare Fredbear", "ナイトメア・フレッドベア", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creation of terror. It is incredibly sensitive to the sounds of ringing.", "恐怖から生まれたもの。ベルの音に非常に敏感だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare Freddy", "ナイトメア・フレディ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creation of fear. He is never alone. His little ones are already waiting for you.", "恐怖から生まれたもの。一人ではいない。小さな仲間たちがもう君を待っている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No1 Crate", "ナンバーワン箱", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The crate shudders when placed. Whatever's inside shifts, lending its strength to whatever stands beside it. For a price, it does even more.", "置くと箱が震える。中の何かが動き、隣のものに力を貸す。代償を払えばさらに力を発揮する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pan Stan", "パン・スタン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sound of clanging metal echoes long after he falls apart. Yet, teh pieces still radiate something.", "彼がばらばらになってからも、金属のぶつかる音が長く響く。それでも破片は何かを放っている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Party Favors", "パーティーの贈り物", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Turn End: [creature] heals cards adjacent to it equal to its Attack.", "各ターン終了時、[creature]は左のマスのカードを1回復する。左のマスがない場合は、代わりに右のマスのカードを回復する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Chica", "ファントム・チカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remnant of the past. It can interact with this world for mere moments at a time.", "過去の残影。一度にほんの短い間だけこの世界に干渉できる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Foxy", "ファントム・フォクシー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remnant of the past, its hook is still deadly. But it can only stay for a short time.", "過去の残影。そのフックは今も致命的だが、短い間しか留まれない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Freddy", "ファントム・フレディ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remnant of the past, loves to read fanfiction.", "過去の残影。二次創作小説を読むのが好き。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Mangle", "ファントム・マングル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remnant of the past. You can feel the seeping Energy it leaves behind.", "過去の残影。後に残したエネルギーが染み出すのを感じる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Puppet", "ファントム・パペット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a remnant of the past, it now no longer revives dead souls.", "過去の残影。今はもう死んだ魂を蘇らせない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pop-Pop", "ポップポップ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deals 1 Damage to all Cards.", "すべてのカードに1ダメージを与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm... a Creature from some Game... It looks like it will blow up soon!", "うーん……何かのゲームの生物……もうすぐ爆発しそうだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Surge", "残響の奔流", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will get +1 Attack for 2 Remnant.", "現在のエネルギーをすべて消費し、2消費するごとに[creature]の攻撃力が+1される。効果はターン終了まで。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Puppet", "パペット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You hear the distant melody of a music box. A sprrpwful presence lingers, its strings pulling at the lost and forgotten... offering them one more chance.", "遠くでオルゴールの旋律が聞こえる。悲しげな気配が漂い、糸が迷い忘れられた者を引く……もう一度チャンスを与えるために。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppeter", "操り人形師", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Play: [creature] will draw either Bon Bon or Bonnet.", "場に出すと、[creature]はボンボンかボネットを引く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppeteers Puppet", "人形師の人形", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Turn End: [creature] will combine with Funtime Freddy On Play.", "プレイヤーのターン終了時、[creature]は盤上の自分のファンタイム・フレディと合体する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Other Card Death: [creature] will ressurect friendly creatures in a weaker state when they perish.", "他のカードが死亡すると、[creature]は死亡した味方生物を弱い状態で蘇らせる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rainbow", "虹", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Escape key", "エスケープキー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will draw a random card.", "[creature]はランダムなカードを1枚引く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Drawn: [creature] Chooses a random Strafe Ability as part of the Choreography.", "ドロー時、[creature]は振り付けの一部としてランダムな移動能力を選ぶ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Drawer", "残響のドロー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Play: [creature] will draw a card from your Deck (Draw an additional Card for 2 Remnant).", "場に出すと、[creature]はメインデッキからカードを1枚引く。残響が2を超えていれば、自動で残響2を消費してもう1枚引く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Sharer", "残響の分かち手", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will allow you to gain Remnant from your own Cards.", "[creature]によって自分のカードから残響を得られる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Side Drawer", "残響サイドドロー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Death: [creature] will draw a card from your Side Deck (Draw an additional Card for 2 Remnant).", "死亡時、[creature]はサイドデッキからカードを1枚引く。残響が2を超えていれば、自動で残響2を消費してもう1枚引く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Spawner", "残響の生成者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Death: [creature] will draw itself in exchange for 2 Remnant.", "死亡時、[creature]は残響2と引き換えに自分自身を引く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bad Pc", "低性能PC", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disables the changes made to the Cabin", "小屋に加えられた変更を無効にする", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scooper", "スクーパー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Turn End: [creature] has a 1/10 chance to instantly kill the opposing Card.", "ターン終了時、[creature]は1/10の確率で正面のカードを即死させる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrap Baby", "スクラップ・ベビー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " ...A freakshow. Mind her grasping claw.", "……見世物だ。つかみかかる爪に気をつけろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Bonnie", "シャドウボニー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Freddy", "シャドウフレディ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Showtime", "ショータイム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Drawn: [creature] will have its energy cost randomized from 1 - 6.", "ドロー時、[creature]のエネルギーコストは1～6にランダム化される。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul", "魂", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once a human being, now only a tool of Remnant and Agony.", "かつては人間だったが、今や残響と苦痛の道具にすぎない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrybe of Beasts", "獣のスクライブ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrybe of Death", "死のスクライブ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrybe of Magik", "魔法のスクライブ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrybe of Technology", "技術のスクライブ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Springtrap", "スプリングトラップ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A murderer trapped in his own creation.", "自らの創造物に閉じ込められた殺人犯。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Static", "ノイズ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] Irritates the Opponent, making it unable to attack.", "プレイヤー側の[creature]が巨大でない敵カードと向かい合っている間、自身の受動的な攻撃力補正は無視される。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stuffed", "詰め込まれた", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dave", "デイブ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... How did this guy get here?", "……こいつはどうやってここに来た？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Debris", "燃える残骸", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Debris of Fazbears Fright", "ファズベアーズ・フライトの燃える残骸", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bite", "噛みつき", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Take Damage: [creature] will give 1 Remnant.", "[creature]が自分自身にダメージを与えた時、残響を1得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mangle", "マングル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He constantly falls apart, but she keeps putting herself back together.", "彼はいつもばらばらになるが、彼女は何度も自分を組み直す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toy Bonnie", "トイボニー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The 'New and Improved' Bonnie. You'll need to charge it to get any use.", "「新しく改良された」ボニー。役立てるには充電する必要がある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ToyChica", "トイチカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The 'New and Improved' Chica. It has an excess amount of energy.", "「新しく改良された」チカ。エネルギーが余っている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toy Freddy", "トイフレディ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The 'New And Improved' Freddy. A true xXGamerXx with anger issues.", "「新しく改良された」フレディ。短気な本物のxXGamerXx。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Turn End: [creature] will capture the opposing Card in itself.", "ターン終了時、[creature]は正面のカードを自分の中に捕らえる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wire Pile", "ワイヤーの山", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Withered Bonnie", "ウィザードボニー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A broken down version of Bonnie. Erratic, violent, and has a mean punch.", "壊れたボニー。気まぐれで暴力的、強烈なパンチを放つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Withered Chica", "ウィザードチカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A broken down version of Chica. Its touch is deadly, due to its exposed wirings. Just as erratic as the others.", "壊れたチカ。むき出しの配線に触れると致命的で、他と同じく気まぐれだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Withered Foxy", "ウィザードフォクシー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A broken down version of Foxy. Easily angered, but also spends a good amount of its time roaming. Mind its hook, it's still just as sharp.", "壊れたフォクシー。怒りやすく、長い時間を歩き回る。フックには気をつけろ、今も鋭い。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Withered Freddy", "ウィザードフレディ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " A broken down version of Freddy. It's erratic, and will attack anything that touches it.", "壊れたフレディ。気まぐれで、触れるものは何でも攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are Number One", "君がナンバーワン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Turn End: [creature] will give the Card to its left +1/0 (Additionally: If you have 1 Remnant also give the Card to its right +1/0).", "各ターン終了時、残響が1以上あれば自動的に1消費し、[creature]の左右に隣接するカードの攻撃力をそれぞれ1増やす。なければ左のカードだけ攻撃力を1増やす。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Five Nights at Inscryption", "Inscryptionでの5夜", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack contains a bunch of FNAF themed Cards, from Freddy Fazbear to Springtrap.", "このカードパックにはフレディ・ファズベアーからスプリングトラップまで、FNAFをテーマにしたカードが多数含まれる。", Language.Japanese);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let us enjoy this Fight.", "この戦いを楽しもう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]As it will be your last.", "[c:bR]君にとって最後の戦いとなるのだから。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see...", "そうか……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seems like all your cards are turning against you!", "君のカードがすべて寝返ったようだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is taking too long.", "時間がかかりすぎだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finally, another Victim...", "ついに次の犠牲者が……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you seriously think id let you win that easily?", "本当にそんな簡単に勝たせてもらえると思った？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "₮Ⱨł₴ ₩łⱠⱠ ₦Ø₮ ฿Ɇ ⱧØ₩ ł Đł-", "こ、こんな死に方は――", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have fun being stuck here.", "ここに閉じ込められたまま楽しむがいい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "₩-Ⱨ₳₮ Ⱨ₳-VɆ ɎØɄ ĐØ₦-Ɇ?", "な、何をし――た？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you really think i'd let a moron like you reach the end of the game?", "君みたいなバカをゲームの最後まで進ませると思った？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ha ha! Surprised?", "ハハ！　驚いた？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yeah, did you really think I'd let a moron like you reach the end of the game?", "そう、君みたいなバカをゲームの最後まで進ませると思った？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pshaw!", "ふん！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You stupid idiotic moron.", "この愚かな大バカ者。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now, if you'll excuse me, I need a few turns to charge my rainbow cannon.", "それじゃ失礼。虹の大砲を充電するのに数ターン必要なんだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yeah.", "そう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After that, it'll be game over.", "その後はゲームオーバーだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So sit back and prepare to get rekt!", "おとなしく座って、ボコボコにされる覚悟をしてね！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You cheated!", "ズルしたな！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Besides, didn't your mommy ever tell you that you can't kill a rainbow?! ", "それに、虹は殺せないってママに教わらなかったの？！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The next time you see a rainbow in the sky that is me, comin' to your houuusssseee.... ", "次に空に虹を見たら、それは君の家に向かう僕だよぉ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just 3 minutes left, you moron!", "あと3分だ、このバカ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just 2 minutes left, then my rainbow cannon will be ready!", "あと2分で虹の大砲の準備ができる！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "1 minute left, you stupid idiot!", "あと1分だ、この大バカ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prepare for rainbow overload!!!!", "レインボーオーバーロードの覚悟をしろ！！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awww, I'm laughing at you, not with you.", "ああ、君と一緒に笑ってるんじゃない。君を笑ってるんだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Um, learn to play?", "ねえ、遊び方を覚えたら？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ha ha! You suck.", "ハハ！　下手くそ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SKRUB!", "ヘタクソ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noobie Boobie Noobie!!", "初心者ちゃん、初心者ちゃん！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Get some skills and call me in the morning.", "腕を磨いてから、明日の朝また電話して。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dumba**.", "バカ野郎。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So sad it's hilarious.", "悲しすぎて笑える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow! What a moron.", "わあ！　なんてバカなんだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awwww! It's so cute when kids try to play games!", "まあ！　子どもがゲームをやろうとする姿ってかわいい！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Excuse me, is this your first time playing a video game?", "失礼、ビデオゲームは初めて？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello Old Sport", "やあ、古い相棒", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must be the newbie", "君が新人だな", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lets strangle some kiddens.", "ガキどもを絞めに行こう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "with sausages", "ソーセージと一緒に", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How do you like it here at Freddy's?", "フレディの店は気に入ったか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "wouldn't have done that.", "俺ならそんなことはしない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep me alive.", "俺を生かしてくれ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...sure.", "……もちろん。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bullshit!", "ふざけるな！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I Will stran...", "絞めてや……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well kid,", "いいか、坊や、", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have a business proposition.", "商売の話がある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's me.", "私だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I still want", "まだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "to kill some", "殺したいんだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "kiddens", "ガキどもを", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dont sacrifice me!", "俺を生贄にするな！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ow.", "痛っ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop that.", "やめろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ouch.", "痛い。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's...", "あれは……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "him...", "奴だ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just defeat him already", "さっさとあいつを倒せ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dream big!", "大きな夢を！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " Think of better Moss.", "もっといいコケを考えろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an honor", "なんて光栄だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good luck.", "幸運を。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good luck...", "幸運を……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good luck!", "幸運を！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fingers crossed", "幸運を祈る", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Forever.", "[c:bR]永遠に。", Language.Japanese);

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have enough [c:bB]Remnant [c:]to use this ability!", "この能力を使うには[c:bB]残響 [c:]が足りない！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have enough [c:bB]Energy [c:]to use this ability!", "この能力を使うには[c:bB]エネルギー [c:]が足りない！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing beautiful can last.", "美しいものは永遠には続かない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No! I'm not ready to die yet.", "嫌だ！　まだ死ぬ覚悟はできていない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I must... still...", "まだ……やらねば……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shake your hand...", "君と握手を……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have enough Energy.", "エネルギーが足りない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may make a new Card for yourself.", "自分のために新しいカードを作れる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose one of these.", "この中から一つ選べ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Nothing?", "……何もない？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What would you like to name your Card?", "カードにどんな名前を付ける？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your card's souls have been transfereed", "カードの魂が移された", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will let you swap the souls of 2 cards...", "カード2枚の魂を交換させてあげよう……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you stand in the burning Building, a familiar Figure awaits you...", "燃える建物の中に立つ君を、見覚えのある人物が待っている……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]He [c:]will not let you go that easily.", "[c:bR]彼 [c:]はそう簡単に君を逃がさない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Building appears to fall apart even more now!", "建物がさらに崩れ始めたようだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]He [c:] appears even more angry than before!", "[c:bR]彼 [c:]はさっきより怒っているようだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Someone wants to see you...", "君に会いたがっている者がいる……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PowerSink", "パワーシンク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil is equal to the number of stolen Batteries on your side.", "この印の値は自分のサイドにある盗んだ電池の数に等しい。", Language.Japanese);


        }
    }
    public class HallownestExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for HallownestExpansion Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pack of [count] cards based around the broad variety of Hollow Knight enemies.", "ホロウナイトの多彩な敵を題材にした[count]枚のカードパック。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dreamshield", "ドリームシールド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Dreamshields are created on each adjacent empty space. [define:HE_Dreamshield]", "[creature]を場に出すと、隣接する各空きマスにドリームシールドを作る。[define:HE_Dreamshield]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukedgling", "吸虫の雛化", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will evolve into a random Fluke.", "所有者のターン終了時、[creature]はランダムな吸虫に進化する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukenest", "吸虫の巣", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] creates a Flukefey on a random empty space on the owner's side. [define:HE_Flukefey]", "所有者のターン終了時、[creature]は所有者のサイドのランダムな空きマスに吸虫の雛を作る。[define:HE_Flukefey]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glowing Womb", "光る子宮", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, an Aspid Hatchling is created in your hand. An Aspid Hatchling is defined as: Strength In Numbers, 1 Health, Brittle.", "[creature]が打たれると、手札にアスピッドの幼生を作る。アスピッドの幼生は数の力、体力1、不安定を持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiveblood", "巣の血", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] creates a Hiveling on a random empty space on the owner's side. [define:HE_Hiveling]", "所有者のターン終了時、[creature]は所有者のサイドのランダムな空きマスに小さなハチを作る。[define:HE_Hiveling]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lifeblood Core", "生命の血の核", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, a Lifeseed is created in your hand. [define:HE_Lifeseed]", "[creature]が打たれると、手札にライフシードを作る。[define:HE_Lifeseed]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Signmaker", "道しるべ職人", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, A Signpost is created in the opposing slot, if empty. [define:HE_Signpost]", "[creature]を場に出すと、正面のスロットが空なら道しるべを作る。[define:HE_Signpost]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Vengeflies", "復讐のハエの召喚", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Vengeflies are created on each adjacent empty space. [define:HE_Vengefly]", "[creature]を場に出すと、隣接する各空きマスに復讐のハエを作る。[define:HE_Vengefly]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zoteling Spitter", "ゾートの子吐き", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, a random Zoteling is created in the owner's hand.", "所有者のターン終了時、ランダムなゾートの子を所有者の手札に作る。", Language.Japanese);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Absolute Radiance", "絶対なるラディアンス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abyss Creature", "深淵の生物", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is this...?", "これは何だ……？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aluba", "アルバ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Passive glider that prefers to dwell near acid waters.", "おとなしい滑空生物。酸の水辺の近くを好む。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ambloom", "アンブルーム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simple-minded crawling fungus. Its cap is covered in a layer of hardened spikes.", "単純な這い回る菌類。かさは硬い棘に覆われている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armoured Squit", "装甲スクイット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hardened squit, bred for battle in the Colosseum of Fools. Tougher and more aggressive than its wild ancestor.", "愚者の闘技場での戦闘用に育てられた硬いスクイット。野生の祖先より頑丈で攻撃的。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspid Hatchling", "アスピッドの幼生", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspid Hunter", "アスピッドの狩人", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cunning predator that will best its prey by spitting corrosive liquid.", "腐食性の液体を吐いて獲物を仕留める狡猾な捕食者。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspid Mother", "アスピッドの母", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carries the eggs of its young inside its belly. Can hatch and birth its young as needed to deal with intruders.", "腹に子の卵を抱え、侵入者に対処するため必要に応じて孵化させ、産み出す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baldur", "バルダー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Although the shells of these youngsters are not thick enough to protect them from predators, they are still able to defend themselves if pressed.", "幼体の殻は捕食者から身を守るにはまだ薄いが、追い詰められれば自衛できる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Battle Obble", "戦闘オブル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raised in the Colosseum. Although trained for combat, its movements and attacks are still haphazard.", "闘技場で育てられた。戦闘訓練を受けても、動きや攻撃は無秩序だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Belfly", "ベルフライ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thin wings hide a highly volatile belly. Will give its own life to protect its territory.", "薄い羽の下に爆発しやすい腹を隠している。縄張りを守るためなら命を投げ出す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bluggsac", "ブルッグサック", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Placid but putrid creature. Holds rancid eggs within its gut.", "おとなしいが腐臭のする生物。腹の中に腐った卵を抱えている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blundering Oberlisk", "よろめくオベリスク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This placid herbivore doesn't seem to wish harm on any of the creatures it shares a habitat with. However, its careless nature and bulky weight sometimes leads to messy accidents.", "おとなしい草食生物。同じ場所に暮らす生物を傷つける気はないようだ。しかし不注意な性格と大きな体重が、ときに厄介な事故を起こす。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boofly", "ブーフライ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Large, docile creature that peacefully buzzes around in the caverns of Kingdom's Edge.", "王国の外れの洞窟で、穏やかに羽音を立てて飛ぶ大きく温厚な生物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Vessel", "壊れた器", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shattered corpse, reanimated by infected parasites.", "砕けた死体。感染した寄生虫によって動き出した。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brooding Mawlek", "物思いのモーレック", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ferocious but extremely social creature. Becomes aggressive if not able to mingle with its own kind.", "凶暴だが非常に社交的な生物。同種の仲間と交流できないと攻撃的になる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carver Hatcher", "土掘りの孵化者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying creature that fires out dirtcarvers from its body when potential prey comes close.", "獲物になりそうな者が近づくと、体から土掘りを発射する飛行生物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charged Lumaflies", "帯電した光バエ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A swarm of tiny, glowing insects. When threatened they cluster together, generating electricity.", "小さく光る虫の群れ。危険を感じると集まって電気を生み出す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Hornhead?", "角のある亡骸？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force. Uses its horn to attack any uninfected creature it finds.", "奇妙な力で動く虫の亡骸。見つけた未感染の生物を角で攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wandering Husk?", "さまよう亡骸？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force, wandering around aimlessly.", "奇妙な力で動く虫の亡骸。目的もなく歩き回る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly Husk", "臆病な亡骸", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Former member of Hallownest's high society. Although made aggressive by the force inside, old instincts still occasionally compel it to run from danger.", "かつてハロウネストの上流階級にいた者。内なる力で攻撃的になっても、昔の本能が危険から逃げさせることがある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crawlid", "クローリッド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Timid scavenger that crawls through the caverns looking for food.", "洞窟を這い回り、食べ物を探す臆病なあさり屋。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Cluster", "結晶の塊", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Crawler", "結晶の這う者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Discharges searing beams of light from the crystals on its back as it crawls around, seemingly unaware.", "気づいていないように這い回りながら、背中の結晶から熱い光線を放つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Guardian", "結晶の守護者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heavyset miner of the Crystal Peak overcome by crystal growth. Can discharge blazing beams of light from its crystallised limbs.", "結晶の成長に覆われた水晶山の大柄な鉱夫。結晶化した手足から燃えるような光線を放つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Hunter", "結晶の狩人", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Small, airborne insect with its abdomen overgrown with crystals. Fires shards of fast-growing crystal at intruders.", "腹が結晶に覆われた小さな飛行虫。急速に育つ結晶の破片を侵入者に放つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystallised Husk", "結晶化した亡骸", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remains of a bug who died amongst the crystals. Animated by a strange force, it attacks by firing beams of light from its crystallised arms.", "結晶の中で死んだ虫の亡骸。奇妙な力で動き、結晶化した腕から光線を放つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Loodle", "死のルードル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loodle equipped with a helmet and taught to kill.", "兜をかぶり、殺すことを教えられたルードル。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deephunter", "巣の深部の狩人", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crawls along walls and roofs, spitting burning venom at anything that passes by.", "壁や天井を這い、通りかかるものすべてに焼ける毒を吐く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deepling", "巣の深部の幼体", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infant of the Deepnest. Scuttles about in the darkness, learning the layout of its home.", "巣の深部の幼体。暗闇を素早く動き回り、住処の地形を覚える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dirtcarver", "土掘り", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swarming predator of the Deepnest. Burrows through the ground and bursts out to surprise prey.", "巣の深部に群れる捕食者。地中を掘り進み、飛び出して獲物の不意を突く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dung Defender", "糞の守護者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skilled combatant living at the heart of the Waterways. Assails intruders with balls of compacted dung.", "水路の中心に住む熟練の戦士。固めた糞の玉で侵入者を攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Duranda", "デュランダ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simple flying creature protected by a spikey shell.", "棘のある殻に守られた単純な飛行生物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Durandoo", "デュランドゥー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simple walking creature encased in a hard shell. Often found wading in shallow pools of acidic water.", "硬い殻に包まれた単純な歩行生物。浅い酸の池を歩いていることが多い。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder Baldur", "長老バルダー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bulky and covered in thick plating. Retracts into itself when attacked.", "大柄で厚い装甲に覆われている。攻撃されると体を丸める。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder Hu", "長老フー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. Travelled the world tending to those affected by the plague.", "倒れた戦士の残る夢。世界を旅し、疫病に苦しむ者を世話していた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enraged Guardian", "怒れる守護者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Entombed Husk", "埋葬された亡骸", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mummified remains, deformed and enraged by infection.", "ミイラ化した遺骸。感染によって歪み、怒りに満ちている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Failed Champion", "失敗した戦士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "False Knight", "偽の騎士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A maggot driven mad by a strange force. Inhabits a stolen armoured shell.", "奇妙な力で狂ったウジ。盗んだ鎧の殻に住みついている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukefey", "吸虫の雛", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Youngest of its species. Its body is composed of teeth, wings and stomach.", "同種の中で最も幼い。体は歯と翼と胃でできている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fluke Larva", "吸虫の幼虫", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gla gla... Grow and grow... Nice and wet...", "グラグラ……育て、育て……心地よく湿って……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukemarm", "吸虫の母", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An insatiable breeder. Has populated the Waterways with its kind. Its insides double as a nest for young Flukefeys.", "飽くことのない繁殖者。水路を仲間で満たし、体内を吸虫の雛の巣としても使う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukemon", "吸虫の怪物", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Worm-like creature that prefers damp, dark habitats.", "湿った暗い場所を好む、虫のような生物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukemon's Body", "吸虫の怪物の体", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukemon's Head", "吸虫の怪物の頭", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukemunga", "巨大吸虫", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aged fluke, grown fat on the rich refuse found in the pipes below the capital.", "都の地下の管にある豊富な廃棄物を食べ、太った年老いた吸虫。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fluke Zoteling", "吸虫のゾートの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Folly", "愚行", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once a highly intelligent bug, inflated by the misuse of soul.", "かつては非常に賢い虫だったが、魂を濫用して膨れ上がった。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fool Eater", "愚者喰らい", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carnivorous plant that snaps at any creature that comes close.", "近づく生物に噛みつく食虫植物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fungified Husk", "菌に侵された亡骸", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, consumed by a fungus. Frequently releases clouds of thick, deadly gas.", "菌類に侵された虫の亡骸。濃く致命的なガスの雲を頻繁に放つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fungling", "小さな菌の風船", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Passive fungal balloon. Internal gasses cause it to float.", "おとなしい菌類の風船。体内のガスで浮かぶ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fungoon", "菌の風船", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fully grown fungal balloon. Spits built up internal gas at aggressors.", "成長した菌類の風船。体内にたまったガスを襲撃者に吐きかける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Furious Vengefly", "怒れる復讐のハエ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vengefly whose body has been distorted by continued infection. Highly aggressive.", "感染が続き、体が歪んだ復讐のハエ。非常に攻撃的。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Galien", "ガリエン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. Trained in the wilds bordering the kingdom, hoping to become a Knight.", "倒れた戦士の残る夢。騎士になることを願い、王国の境界の荒野で鍛えた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Garpede", "ガーピード", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant burrower covered in thick shell plates. Tirelessly travels the tunnels of the Deepnest.", "厚い甲殻に覆われた巨大な穴掘り。巣の深部の坑道を休みなく進む。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gas Cloud", "ガス雲", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Geo Deposit", "ジオの鉱床", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glimback", "グリムバック", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slow, hardy creature. The crystals that grow on its back provide extra protection from foes above.", "遅いが丈夫な生物。背中の結晶が上からの敵に対する防御を強める。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gluttonous Husk", "大食いの亡骸", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Former member of Hallownest's high society. Uses its corpulent body as a weapon.", "かつてハロウネストの上流階級にいた者。肥大した体を武器にする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goam", "ゴーム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thickly armoured, it bursts from the ground to seize prey in its fangs.", "厚い鎧をまとい、地面から飛び出して牙で獲物を捕らえる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Beast", "神の獣", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Tamer", "神を馴らす者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Veteran warrior of the Colosseum of Fools. Fights by the side of creatures she has trained.", "愚者の闘技場の熟練戦士。自ら育てた生物と共に戦う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gorb", "ゴーブ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. A mysterious life-form that claimed to contain all of the world's knowledge inside of its distended brain.", "倒れた戦士の残る夢。膨らんだ脳に世界の知識すべてを収めていると主張する謎の生命体。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gorgeous Husk", "豪華な亡骸", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corpulent Husk encrusted with a shining metal. Retains the instinct to hoard Geo.", "輝く金属で飾られた肥大した亡骸。今もジオをため込む本能を持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great Hopper", "巨大なホッパー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaps around the edge of the world, trying to crush prey beneath its body.", "世界の端を跳ね回り、体の下敷きにして獲物を押し潰そうとする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great Husk Sentry", "巨大な亡骸の番兵", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animated remains of a Great Sentry, the most elite of the city's guards. Wields a greatnail and shell. Its powerful attacks cause heavy damage.", "都市の守衛の中でも最精鋭の巨大な番兵の遺骸が動き出した。大きな釘と殻を使い、強力な攻撃で大きなダメージを与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mystery Jar", "謎の瓶", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great Nailsage Sly", "偉大な釘の賢者スライ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legendary sage of the nail arts and, recently, merchant of some success.", "釘の技の伝説的な賢者。最近は商人としてもそれなりに成功している。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grey Prince Zote", "灰色の王子ゾート", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimm", "グリム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimmkin Master", "グリムの眷属マスター", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powerful and devoted member of the Grimm Troupe.", "グリム巡業団の強力で忠実な一員。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimmkin Nightmare", "グリムの眷属ナイトメア", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrifying member of the Grimm Troupe.", "グリム巡業団の恐ろしい一員。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimmkin Novice", "グリムの眷属新人", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Young and playful member of the Grimm Troupe.", "グリム巡業団の若く遊び好きな一員。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grub", "幼虫", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor little creature, separated from its family. Do you have the courage to sacrifice it?", "家族とはぐれた哀れな小さな生物。生贄にする勇気があるか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grub?", "幼虫？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gruz Mother", "グラザーの母", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mature gruzzer that carries its young in its belly. Attacks by hurling its huge body around.", "腹に子を抱えた成長したグラザー。巨大な体を振り回して攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gruzzer", "グラザー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gulka", "グルカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aggressive plant-life that retracts protectively when danger is near and spits hard spikey balls when foes are at a distance.", "攻撃的な植物。危険が近いと身を縮め、敵が遠くにいると硬い棘の球を吐く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunted Spirit", "取り憑かれた霊体", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Head of Zote", "ゾートの頭", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heavy Fool", "重装の愚者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior fighting for glory in the Colosseum of Fools. Aggressively charges down foes.", "愚者の闘技場で栄光のために戦う戦士。激しく敵に突進する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heavy Sentry", "重装の番兵", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animated remains of a large Hallownest Sentry. One of few in Hallownest strong enough to wield a greatnail.", "動き出したハロウネストの大きな番兵の遺骸。大きな釘を振るえるほど強い数少ない者の一人。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heavy Zoteling", "重装のゾートの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hive Guardian", "巣の守護者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protects the Hive by hurling its huge body at intruders.", "巨大な体を侵入者にぶつけ、巣を守る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hive Knight", "巣の騎士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loyal protector of the Hive's Queen. Flightless but ferocious in battle.", "巣の女王に忠実な保護者。飛べないが戦いは凶暴だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiveling", "小さなハチ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hive Soldier", "巣の兵士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defends the Hive against intruders with its extendable stinger.", "伸縮する針で巣を侵入者から守る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hollow Knight", "ホロウナイト", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fully grown Vessel, carrying the plague's heart within its body.", "体の中に疫病の心臓を抱えた、完全に成長した器。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hopper", "ホッパー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaps at prey and uses its sharp proboscis to drain vital fluids.", "獲物に飛びかかり、鋭い口吻で生命の液体を吸い取る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hopping Zoteling", "跳ねるゾートの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hornet", "ホーネット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skilled protector of Hallownest's ruins. Wields a needle and thread.", "ハロウネストの遺跡を守る熟練の保護者。針と糸を使う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hornet Sentinel", "ホーネットの番兵", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Bully", "亡骸のいじめっ子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force. It aggressively attacks any uninfected creature it finds.", "奇妙な力で動く虫の亡骸。見つけた未感染の生物に激しく襲いかかる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Dandy", "亡骸の伊達男", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Former member of Hallownest's high society. Limited offensive ability.", "かつてハロウネストの上流階級にいた者。攻撃能力は限られている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Guard", "亡骸の守衛", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a great Hallownest Crossguard, animated by a strange force. Instinct still drives it to guard its post against intruders.", "奇妙な力で動くハロウネストの強大な十字守衛の遺骸。本能に従い、今も侵入者から持ち場を守る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Hive", "巣の亡骸", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly husk, its body colonised by hivelings.", "小さなハチに体を占領された臆病な亡骸。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Hornhead", "角のある亡骸", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force. Uses its horn to attack any uninfected creature it finds.", "奇妙な力で動く虫の亡骸。見つけた未感染の生物を角で攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Miner", "亡骸の鉱夫", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remains of a bug drawn to the Crystal Peak for its precious crystal. Its claw-pick now doubles as a fierce weapon.", "貴重な結晶を求めて水晶山に来た虫の遺骸。その爪型のつるはしは今や恐ろしい武器だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Sentry", "亡骸の番兵", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animated remains of a Hallownest Sentry. Still retains some memory of its former task.", "動き出したハロウネストの番兵の遺骸。かつての任務をいくらか覚えている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Warrior", "亡骸の戦士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force. Wields a nail and shell.", "奇妙な力で動く虫の亡骸。釘と殻を持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hwurmp", "フワンプ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiny and placid but swells to enormous size when threatened.", "小さくおとなしいが、脅かされると巨大に膨らむ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infected Balloon", "感染した風船", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infected Pustule", "感染した膿疱", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kingsmould", "王の造り物", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guard construct of Hallownest's Palace and skilled wielder of the curved claw-blade. Its heavy white armour protects a fragile body.", "ハロウネストの宮殿を守る造り物。曲がった爪刃を巧みに扱う。重い白い鎧が弱い体を守っている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lance Sentry", "槍の番兵", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winged Sentry of Hallownest equipped with a nail-lance. Charges at threats or throws its lance from a distance.", "釘の槍を装備したハロウネストの翼ある番兵。脅威に突進するか、遠くから槍を投げる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lanky Zoteling", "ひょろ長いゾートの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaping Husk", "跳ぶ亡骸", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force. It will instinctively leap at uninfected creatures to attack them.", "奇妙な力で動く虫の亡骸。本能的に未感染の生物に飛びかかり、攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser Mawlek", "幼いモーレック", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Attacks by spitting acid and slashing with foreclaws.", "酸を吐き、前爪で切りつけて攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lifeblood Coccoon", "生命の血の繭", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Contains a living core that bleeds precious lifeblood.", "貴重な生命の血を流す生きた核を含む。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lifeseed", "ライフシード", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Small scuttling seed filled with Lifeblood, which can be extracted and consumed for its healthful properties.", "生命の血で満たされた小さく素早い種。その血を取り出して飲めば体に良い。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lightseed", "光の種", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A single-celled organism, completely infected. Scurries about simple-mindedly.", "完全に感染した単細胞生物。単純に走り回る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Little Weaver", "小さな織り手", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nimble spider that traverses its domain on thin strands of web. Often waits in ambush.", "細い糸を伝って縄張りを移動する素早いクモ。待ち伏せすることが多い。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loodle", "ルードル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inhabits the wilds beside the Queen's Gardens. Not aggressive in nature, but its wild bouncing behaviour can be dangerous.", "女王の庭園の隣の荒野に住む。攻撃的ではないが、激しく跳ねる行動は危険になりうる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lost Kin", "失われた親族", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mace Bug", "メイス虫", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What the bug doin'?", "あの虫、何してる？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Lord", "カマキリの領主", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leader of the Mantis tribe and its finest warrior. Bears a thin nail-lance and attacks with blinding speed.", "カマキリの部族のリーダーであり、最も優れた戦士。細い釘の槍を持ち、目にも止まらぬ速さで攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Lords", "カマキリの領主たち", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Petra", "カマキリ・ペトラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lurks amongst foliage and attacks by flinging wind-scythes from a distance.", "葉の間に潜み、遠くから風の鎌を飛ばして攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Traitor", "カマキリの裏切り者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once a member of the Mantis tribe, now cast out and driven mad by infection.", "かつてカマキリの部族に属していたが、追放され感染によって狂った。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Warrior", "カマキリの戦士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Member of a proud tribe, fiercely protective of its territory. Launches savage attacks with bladed forelimbs.", "誇り高い部族の一員。縄張りを必死に守り、刃のような前肢で激しく攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Youth", "若いカマキリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Member of a proud tribe, fiercely protective of its territory. Launches stinging attacks with its needle sharp abdomen.", "誇り高い部族の一員。縄張りを必死に守り、針のように鋭い腹で突き刺す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Markoth", "マルコス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. Only member of his forgotten tribe to take up a weapon.", "倒れた戦士の残る夢。忘れられた部族で唯一、武器を取った者。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Marmu", "マルム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. Protector of the Queen's Gardens.", "倒れた戦士の残る夢。女王の庭園の保護者。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maskfly", "マスクフライ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Massive Moss Charger", "巨大な苔の突撃者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Family of creatures that have learnt to bulk up with moss and live as one.", "苔で体を大きくし、一つとなって暮らすことを学んだ生物の家族。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mawlurk", "モールルーク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Large, immobile creature. Wildly spits venom when intruders pass by.", "大きく動かない生物。侵入者が通ると激しく毒を吐く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Menderbug", "修理虫", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Member of an elusive guild of bugs fixated on the maintenance of Hallownest's many signs and wayposts.", "姿を見せない虫の組合の一員。ハロウネストのさまざまな看板や道しるべの整備にこだわる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minigun Aspid", "機関銃アスピッド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mistake", "間違い", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once a highly intelligent bug, deformed by the misuse of soul.", "かつては非常に賢い虫だったが、魂を濫用して変形した。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moss Charger", "苔の突撃者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Timid creature that frightens away intruders by covering itself in huge clumps of moss.", "大きな苔の塊で体を覆い、侵入者を怖がらせる臆病な生物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mosscreep", "苔の這う者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weakling that covers itself in leaves to appear larger and hides amongst the undergrowth.", "葉で体を覆って大きく見せ、茂みに隠れる弱い生物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mossfly", "苔のハエ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winged weakling that covers itself in leaves to appear larger. Hides amongst the undergrowth, fleeing if predators draw near.", "葉で体を覆って大きく見せる翼ある弱者。茂みに隠れ、捕食者が近づくと逃げる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mosskin", "苔の生き物", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plant-like bug that charges at foes when close.", "敵が近づくと突進する植物のような虫。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moss Knight", "苔の騎士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protector of the Greenpath, trained in the ways of the Nail and the Shell.", "緑の道の保護者。釘と殻の技を身につけている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mossy Vagabond", "苔の放浪者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy, portly Mosskin. Easily swayed by others.", "怠け者で太った苔の生き物。他人に流されやすい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nailmaster Mato", "釘の達人マト", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nailmaster Oro", "釘の達人オロ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of the brothers of the nail, trained in combat by the Great Nailsage.", "釘の兄弟の一人。偉大な釘の賢者から戦いを教わった。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare King Grimm", "悪夢の王グリム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No Eyes", "目のない者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Knight?", "小さな騎士？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An enigmatic wanderer who descends into Hallownest carrying only a broken nail to fend off foes.", "敵を防ぐ折れた釘だけを携え、ハロウネストに降りてきた謎めいた放浪者。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obble", "オブル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fat, slow, flying bug. Frequently discharges the acidic liquid stored in its round body.", "太って遅い飛ぶ虫。丸い体に蓄えた酸性の液体をよく放出する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obblobble", "オブロブル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Larger cousin of the Obble. Pairs with a mate for life and will never leave its side.", "オブルの大きな親類。一生を伴侶と過ごし、決して離れない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ooma", "ウーマ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Passive outer being protecting an aggressive, explosive core.", "おとなしい外側の存在が、攻撃的で爆発しやすい核を守っている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paintmaster Sheo", "絵の達人シオ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skilled and respected master of the nail. Always eager to learn new things.", "技に長けた敬われる釘の達人。いつも新しいことを学びたがっている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pale Lurker", "青白い潜む者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forgotten champion of the Colosseum, drawn away by strange obsessions.", "奇妙な執着に引かれて去った、忘れられた闘技場の王者。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pilflip", "ピルフリップ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Odd creature that adapts to changing situations by flipping over and using the limbs on the other side of its body.", "ひっくり返り、反対側の手足を使って変化する状況に適応する奇妙な生物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Primal Aspid", "原初のアスピッド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wilder, ancestral form of the Aspid. Once thought extinct, they have reappeared at the edges of the world.", "より野生的なアスピッドの祖先。絶滅したと思われていたが、世界の端に再び現れた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pure Vessel", "純粋な器", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pustulent Scholar", "膿疱の学者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Twister overgrown by infection...", "感染によって増殖した魂をねじる者……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Radiance", "ラディアンス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The light, forgotten.", "忘れられた光。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rancid Egg", "腐った卵", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revek", "レヴェク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. The protector of the Spirits' Glade.", "倒れた戦士の残る夢。魂の空き地の保護者。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Retainers", "王家の従者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shade", "影", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Creeper", "影の這う者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Found only in deep, dark places. Has never been observed to eat or drink anything.", "深く暗い場所でのみ見つかる。何かを飲み食いする姿は観察されていない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shardmite", "欠片ダニ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feeds on crystal dust and uses crystallised spines to protect itself from danger.", "結晶の粉を食べ、結晶化した棘で危険から身を守る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharp Baldur", "鋭いバルダー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hardened baldur, bred for battle in the Colosseum of Fools. Tougher and more aggressive than its wild ancestor.", "愚者の闘技場での戦闘用に育てられた硬いバルダー。野生の祖先より頑丈で攻撃的。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shielded Fool", "盾持ちの愚者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior fighting for glory in the Colosseum of Fools. Warily approaches opponents with shell held high.", "愚者の闘技場で栄光のために戦う戦士。殻を高く掲げ、慎重に相手に近づく。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrumal Ogre", "キノコの鬼", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Huge fungal creature that attacks by spitting corrosive venom and slamming its body into foes.", "腐食性の毒を吐き、体を敵にぶつけて攻撃する巨大な菌類の生物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrumal Warrior", "キノコの戦士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fungal creature that attacks intruders to protect its young.", "子どもを守るため侵入者を攻撃する菌類の生物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrumeling", "小さなキノコ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Siblings", "兄弟姉妹", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fragments of a lingering will.", "残る意志の欠片。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Signpost", "道しるべ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sisters of Battle", "戦いの姉妹", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slobbering Husk", "よだれを垂らす亡骸", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The body of a bug, completely consumed by infection. Spits corrosive liquid.", "感染に完全に飲み込まれた虫の体。腐食性の液体を吐く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Master", "魂のマスター", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Head of the Soul Sanctum. Hoarded soul hoping to stave off Hallownest's affliction, but eventually became intoxicated by its power.", "魂の聖域の長。ハロウネストの災いを防ごうと魂をため込んだが、やがてその力に酔いしれた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Twister", "魂をねじる者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Highly intelligent bug that uses arcane knowledge to twist soul into vicious spells.", "秘術の知識で魂を凶悪な呪文に変える、非常に賢い虫。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Tyrant", "魂の暴君", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Warrior", "魂の戦士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Learned bug, wielding a refined pinblade. Enhances its combat prowess with harvested soul.", "洗練された針の刃を使う博識な虫。集めた魂で戦闘能力を高める。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiky Trap", "棘の罠", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spinning Scythe", "回転する鎌", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiny Husk", "棘だらけの亡骸", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overgrown with vegetation, it attacks by firing sharp spines from its body.", "植物に覆われ、体から鋭い棘を放って攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sporg", "スポーグ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A living fungus that detects nearby movement and fires out explosive spores that drift towards their target.", "近くの動きを察知し、標的へ漂う爆発性の胞子を放つ生きた菌類。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squit", "スクイット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flying bug that charges at prey with its needle-like proboscis.", "針のような口吻で獲物に突進する飛ぶ虫。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stalking Devout", "忍び寄る信徒", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Worshipper of Herrah the Beast. Shields itself with hard plated foreclaws, then lashes out suddenly to cut down prey.", "獣ヘラーの信奉者。硬い板に覆われた前爪で身を守り、突然飛び出して獲物を斬る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sturdy Fool", "頑丈な愚者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior fighting for glory in the Colosseum of Fools. Uses crescent-shaped blades to cut down foes.", "愚者の闘技場で栄光のために戦う戦士。三日月形の刃で敵を斬る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Collector", "収集家", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dark figure locked inside the Tower of Love. Preserves Hallownest's creatures in glass jars with particular attention given to Grubs.", "愛の塔に閉じ込められた黒い姿。ハロウネストの生物をガラス瓶に保存し、特に幼虫を大切にする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Great Collector", "偉大な収集家", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Knight", "小さな騎士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiktik", "ティクティク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A spiky, tenacious little bug that climbs all over the place using its pointed feet.", "尖った足であちこちを登る、棘だらけの粘り強い小さな虫。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Traitor Lord", "裏切り者の領主", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deposed Lord of the Mantis tribe. Embraced the infection and turned against his sisters.", "追放されたカマキリ部族の領主。感染を受け入れ、姉妹たちに敵対した。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corpse Creeper", "死体の這う者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grub Mimic", "幼虫の模倣者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nosk", "ノスク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tuk", "トゥク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The water brings everything you wish for... You just need to find it.", "水は望むものを何でも運んでくる……見つけさえすればいい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turret Zoteling", "砲台ゾートの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Uoma", "ウオマ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smallest Jelly form. Passive and unaware, but pulsing with a dangerous electric charge.", "最小のクラゲ形態。おとなしく無自覚だが、危険な電荷を脈打たせている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Uumuu", "ウームー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intelligent being that guards the inner chamber of the Teacher's Archives.", "教師の記録保管庫の奥を守る知的な存在。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vengefly", "復讐のハエ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vengefly King", "復讐のハエの王", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Patriarch of a vengefly colony. Swoops at intruders and cries out for reinforcements if threatened.", "復讐のハエの群れの長。侵入者に急降下し、脅かされると鳴いて援軍を呼ぶ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Violent Husk", "暴力的な亡骸", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maddened by massive infection. Charges at enemies with no thought for its own preservation.", "ひどい感染で狂い、自分の身も考えず敵に突進する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Void Given Focus", "集中する虚無", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Void... Power... Without unity...", "……虚無……力……一つにならず……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Void Given Form", "形を得た虚無", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Void Given Mind", "心を得た虚無", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Void Tendrils", "虚無の触手", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fragments of void taking the shape of sharp, thrashing tendrils.", "鋭く振り回される触手の形を取った虚無の欠片。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Volatile Gruzzer", "爆発するグラザー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gruzzer swollen with infection and primed to burst.", "感染で膨れ上がり、今にも破裂しそうなグラザー。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Volatile Mosskin", "爆発する苔の生き物", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plant-like bug swollen with infection. Releases deadly gas when threatened.", "感染で膨れ上がった植物のような虫。脅かされると致命的なガスを放つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Volatile Zoteling", "爆発するゾートの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Volt Twister", "電撃のねじり手", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Learned bug that adapted the teachings of the Soul Sanctum into a deadly fighting art. Attacks with bursts of electricity.", "魂の聖域の教えを致命的な戦闘術に変えた博識な虫。電気を放って攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wandering Husk", "さまよう亡骸", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force, wandering around aimlessly.", "奇妙な力で動く虫の亡骸。目的もなく歩き回る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watcher Knight", "見張りの騎士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Discarded shell of a Watcher Knight, re-animated by a swarm of infected flies.", "見張りの騎士が捨てた殻。感染したハエの群れによって動き出した。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "White Defender", "白い守護者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winged Fool", "翼ある愚者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior fighting for glory in the Colosseum of Fools. Flies just out of an opponent's reach then darts in for the kill.", "愚者の闘技場で栄光のために戦う戦士。相手の手が届かないところを飛び、素早く突っ込んで仕留める。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winged Nosk", "翼あるノスク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winged Sentry", "翼ある番兵", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying sentry of Hallownest. Patrols the heights of the vast cavern in which the city was built.", "ハロウネストの飛ぶ番兵。都市が築かれた広大な洞窟の高所を巡回する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winged Zoteling", "翼あるゾートの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wingmould", "翼の造り物", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fly-like construct formed of white shell and a dark liquid interior.", "白い殻と中の暗い液体からできた、ハエのような造り物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Xero", "ゼロ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. Executed for crimes against the King.", "倒れた戦士の残る夢。王に対する罪で処刑された。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zote's Curse", "ゾートの呪い", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zote", "ゾート", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A self-proclaimed Knight, of no renown. Wields a nail he carved from shellwood, named 'Life Ender.'", "名声なき自称騎士。殻の木から削り出した「命の終結者」という釘を振るう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. Disappeared during the plague.", "倒れた戦士の残る夢。疫病の間に姿を消した。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying predator that pursues its prey relentlessly.", "獲物を執拗に追う飛行捕食者。", Language.Japanese);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What are you", "何の用で", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "bothering me for?", "私の邪魔をする？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What do you want,", "何が欲しい、", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "cur?", "駄犬め？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another fool", "また一人の愚か者が", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "to be cut down", "切り倒される", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "by Life Ender...", "命の終結者によって……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fear not, cur...", "恐れるな、駄犬……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your death", "お前の死は", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "will be swift.", "すぐに訪れる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Umph!", "むん！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pfah!", "ふん！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're only dulling", "自分の顎を", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "your mandibles!", "鈍らせているだけだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You almost struck me!", "危うく当たるところだった！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is this kingdom", "この王国は", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "trying to mock me?", "私をからかっているのか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph.", "ふん。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Being overly devoted", "自分の義務に", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "to one's duties", "尽くしすぎるのは", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "is no virtue.", "美徳ではない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What are you doing,", "何をしている、", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you clumsy", "この不器用な", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "little oaf?!", "小さな間抜けめ？！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The air is foul", "空気はよどみ、", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and the townsfolk", "町の住民たちは", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "have beady eyes.", "小さな目をぎらつかせている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How miserable,", "なんと惨めな、", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "to be stuck here", "ここに閉じ込められ、", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "instead of continuing", "旅を続けることも", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "my quest...", "できないとは……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How ghastly...", "なんと恐ろしい……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just what do you", "一体何を", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "think you're doing?!", "しているつもりだ？！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't have time", "お前の称賛を", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "for your adulation!", "聞いている暇はない！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm a Knight.", "私は騎士だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm not interested", "お前の", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "in your", "子どもじみた遊びには", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "childish games.", "興味がない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you lost", "この暗い坑道で", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "in these dark tunnels?", "迷ったのか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yes, yes!", "そうだ、そうだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All glory to me!", "栄光はすべて私のものだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll kill", "さらに千人", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a thousand more!", "殺してやる！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tremble before me!", "私の前に震えろ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "doing, you clumsy", "している、この不器用な", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "little oaf?!", "小さな間抜けめ？！", Language.Japanese);

        }
    }
