    public class SideDeckSelectorMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Side_Deck_Selector Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a squirrel that can block fliers", "飛行生物を防げるリス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bee Drone", "雄バチ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For when you need just one point of damage", "1ダメージだけ必要なときに", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ant Drone", "雄アリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bee Drone", "雄バチ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not much, but it's an ant.", "大したことはないが、アリだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppy", "子犬", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This energetic little puppy will dig up a fresh bone every turn", "元気な子犬。毎ターン新しい骨を掘り出す", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spare Tentacle", "予備の触手", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've never seen that [c:bR]thing[c:] before, but I can tell there are no bones in it.", "あの[c:bR]もの[c:]は初めて見るが、骨がないことは分かる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One-Eyed Goat", "片目のヤギ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This goat generates additional blood...for a price", "このヤギは追加の血を生み出す……代償と引き換えに", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I didn't realize this thing came from eggs", "これが卵から生まれるとは知らなかった", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emptier Vessel", "より空っぽの器", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here you may replace the creatures in your [c:bR]side deck[c:]", "ここでは[c:bR]サイドデッキ[c:]の生物を入れ替えられる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Side Deck Second Chance", "サイドデッキの再選択", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are given the option to change your side deck on maps two and three", "2番目と3番目のマップでサイドデッキを変更する機会が与えられる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leshy is ready to give us side deck options", "レシーがサイドデッキの選択肢を用意している", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acceptable Sacrifice", "受け入れられる生贄", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrificing [creature] will count as if two creatures were sacrificed", "[creature]を生贄にすると、生物を2体生贄にしたものとして扱う", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Entrance", "苦痛の登場", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal two damage to the player when it enters play.", "[creature]が場に出ると、プレイヤーに2ダメージを与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gelatinous", "ゼラチン質", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] has no bones", "[creature]には骨がない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a Side Deck", "サイドデッキを選択", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Player selected sidedeck card", "プレイヤーが選んだサイドデッキのカード", Language.Japanese);


        }
    }
    public class TalkingPossumMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Talking_Possum Mod");


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, this one. Right. You can keep it. Not much use to me, anyway.", "ああ、これか。そうだな、持っていていい。私にはあまり役立たない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awesome Opossum", "すごいオポッサム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Playing dead? What a despicable creature.", "死んだふり？　なんて卑劣な生物だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not-So-Awesome Opossum", "そんなにすごくないオポッサム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Alright.[w:1]", "[e:anger]分かった。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]You must be... [w:0.4][c:#280085]confused[c:][w:1].", "[e:neutral]きっと…… [w:0.4][c:#280085]混乱している[c:]んだろう。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I get it.[w:0.2] I do.[w:0.2] It sucks.[w:0.4]", "分かる。[w:0.2]本当に。[w:0.2]ひどいよな。[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]So, uh.[w:0.2] Hi.[w:0.2]", "[e:surprise]それで、えっと。[w:0.2]やあ。[w:0.2]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We're...[w:0.6] [e:anger]stuck together, I suppose.[w:0.2]", "僕たちは……[w:0.6] [e:anger]一緒に閉じ込められたみたいだ。[w:0.2]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]It could be worse.[w:0.2]", "[e:neutral]もっとひどいことだってある。[w:0.2]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Look on the [c:#280085]bright side![c:][w:0.4]", "[c:#280085]明るい面[c:]を見よう！[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... There's no bright side.", "……明るい面なんてない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We're all doomed.[leshy:Quiet now.][w:2]", "僕たちはみんな終わりだ。[leshy:静かに。][w:2]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good luck.[w:1]", "幸運を。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]You know,[w:0.2] I was[w:0.4]", "[e:surprise]実はね、[w:0.2]僕は昔[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]A [c:#280085]scrybe[c:] once.[w:1]", "[e:quiet][c:#280085]スクライブ[c:]だった。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good times, good times.[w:0.6] Alas.[w:0.6]", "いい時代だった、いい時代だった。[w:0.6]ああ。[w:0.6]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Now I'm a fucking possum.[w:1]", "[e:surprise]今はクソみたいなオポッサムだ。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]... This man over there?[w:0.4]", "[e:anger]……あそこにいる男？[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That guy?[w:0.6]", "あいつ？[w:0.6]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]He wasn't so bad before this.[w:1]", "[e:quiet]前はそこまで悪い奴じゃなかった。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I still think he has...[w:0.6]", "あいつにもまだ……[w:0.6]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... Some good in him.[w:0.4]", "……いいところはあると思う。[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Some.[w:1]", "[e:anger]少しはね。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]... Anyway,[w:0.4] here's my plan-[leshy:Silence.][w:3]", "[e:quiet]……とにかく、[w:0.4]僕の計画は――[leshy:黙れ。][w:3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aight. Got the memo.[w:0.6]", "分かったよ、了解。[w:0.6]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Good luck, traveler.[w:1]", "[e:anger]幸運を、旅人。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]I'm rooting for you.[w:1]", "[e:quiet]君を応援してるよ。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[a:anger]Here we go again.[w:1]", "[a:anger]また始まった。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Isn't this FUN?[w:1] [e:surprise]Nope.[w:0.4]", "楽しいだろ？[w:1] [e:surprise]いや、全然。[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not fun.[w:1]", "楽しくない。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]You know, I think[w:0.4]", "[e:neutral]ねえ、僕は思うんだ[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]You have potential.[w:1]", "[e:quiet]君には可能性がある。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm rooting for you.[w:1]", "君を応援してる。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]Also,[w:0.2] if you[w:0.2], uh[w:0.4]", "[e:neutral]それと、[w:0.2]もし君が[w:0.2]、えっと[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you find an...[w:0.4] [c:#280085]odd-looking wolf...[c:][w:1]", "もし……[w:0.4] [c:#280085]変な見た目のオオカミ[c:]を見つけたら……[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]... Tell him I-[leshy:Enough of that now.][w:2]", "[e:quiet]……彼に僕が――[leshy:そこまでだ。][w:2]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Killjoy.[w:1]", "水を差すなよ。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]This is getting old.[w:1]", "[e:anger]もう飽き飽きだ。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]... You know...[w:0.4]", "[e:anger]……あのさ……[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That old man over there?[w:0.4]", "あそこの老人？[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]He has no idea[w:0.2]", "[e:neutral]あいつは気づいていない[w:0.2]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He's biting[w:0.2] [e:anger]way[w:0.2] more[w:0.2]", "手を出したことは[w:0.2] [e:anger]とても[w:0.2]とても[w:0.2]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Than he can possibly chew.[w:1]", "[e:surprise]あいつの手に負えるものじゃない。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]Listen to me now.[w:0.6]", "[e:neutral]今すぐ僕の話を聞いて。[w:0.6]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]You have to-[leshy:Quiet, vermin.][w:2]", "[e:anger]君は――[leshy:黙れ、害獣。][w:2]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... Vermin?[w:0.2] Excuse me?[w:0.4]", "[e:surprise]……害獣？[w:0.2]何だって？[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know my name.[w:0.4]", "僕の名前を知っているだろう。[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's-[leshy:I said quiet.][w:2]", "それは――[leshy:黙れと言った。][w:2]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger][c:#280085]Lamb to the slaughter.[c:][w:1]", "[e:anger][c:#280085]屠殺場へ向かう子羊。[c:][w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]NOT THE FACE!", "[e:surprise]顔はやめて！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]LEAVE ME ALONE.", "[e:surprise]放っておいて。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]QUIT IT, GODDAMMIT.", "[e:surprise]やめろ、クソッ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]You're lucky I'm trapped as a marsupial.", "[e:surprise]僕が有袋類に閉じ込められているからって、運がいいな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Okay, I see how it is--", "[e:surprise]なるほど、そういうことか――", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]AGAIN??", "[e:surprise]また？？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]AGAIN?? REALLY??", "[e:surprise]また？？　本当に？？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Odd feeling.", "[e:surprise]変な感じだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Maybe skip me, perhaps?", "[e:quiet]僕を飛ばしてくれない？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]I'd rather you didn't.", "[e:surprise]やめてほしいな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Have you seen a strange-looking wolf?", "[e:quiet]変な見た目のオオカミを見た？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]It'd be... acceptable.", "[e:neutral]それなら……構わない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]I mean, if you insist.", "[e:surprise]いや、君がそうしたいなら。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Would it suit me?", "[e:quiet]僕に似合うかな？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... Ah.[w:1]", "[e:surprise]……ああ。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]The board.[w:0.4] Again.[w:0.6]", "[e:anger]盤だ。[w:0.4]またか。[w:0.6]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:#1e0040]Lamb to the slaughter.[c:][w:1]", "[c:#1e0040]屠殺場へ向かう子羊。[c:][w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]I get it.[w:0.2]I do.[w:0.2]I do.[w:0.4]", "[e:surprise]分かった。[w:0.2]分かったよ。[w:0.2]本当に。[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do as you must,[w:0.2] traveler.[w:1]", "やるべきことをやってくれ、[w:0.2]旅人。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]I'm rooting for you.[w:1]", "[e:neutral]君を応援してるよ。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Ah.[w:0.2] The board, again.[w:0.2] I see.[w:1]", "[e:surprise]ああ。[w:0.2]また盤か。[w:0.2]なるほど。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger][c:#1e0040]Lamb to the slaughter.[c:][w:1]", "[e:anger][c:#1e0040]屠殺場へ向かう子羊。[c:][w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... I suppose.[w:1]", "[e:surprise]……そうかな。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Ah, this.[w:1] [e:surprise]Once again.[w:1]", "[e:quiet]ああ、これか。[w:1] [e:surprise]まただ。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]... I'm ready.[w:1]", "[e:anger]……準備はいい。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]You know what's funny?[w:0.4]", "[e:surprise]何がおかしいか分かる？[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]I really liked animals[w:0.4]", "[e:neutral]僕は動物が本当に好きだった[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Before all of this.[w:1]", "こんなことになる前はね。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Now not so much.[w:1]", "[e:surprise]今はそうでもない。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Cameras are ruined too.[w:2]", "[e:anger]カメラも台無しだ。[w:2]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Aim for their throat.[w:1]", "[e:anger]喉を狙って。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]... What?[w:0.4]", "[e:neutral]……何？[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Why are you[w:0.2]", "[e:quiet]どうして[w:0.2]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "looking at me like that?[w:0.6]", "そんな目で僕を見るの？[w:0.6]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... If you must.[w:1]", "[e:surprise]……どうしてもというなら。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise][c:#1e0040]Lamb to the slaughter.[c:][w:1]", "[e:surprise][c:#1e0040]屠殺場へ向かう子羊。[c:][w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]This sounds...[w:0.6]", "[e:anger]これは……[w:0.6]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... [c:#1e0040]acceptable.[c:][w:1]", "[e:surprise]……[c:#1e0040]悪くない。[c:][w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Is it...[w:0.4] gonna...[w:0.4]", "[e:quiet]これ……[w:0.4]その……[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is it gonna hurt?[w:1]", "痛いのかな？[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]This is...[w:0.6] [e:quiet]fine.[w:1]", "[e:surprise]これは……[w:0.6] [e:quiet]大丈夫。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... I suppose.[w:1]", "……たぶん。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]... Why me?[w:1]", "[e:anger]……どうして僕なんだ？[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]... This is weird.[w:1]", "[e:anger]……変な感じだ。[w:1]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Fate deals its cards.[w:1]", "[e:quiet]運命がカードを配る。[w:1]", Language.Japanese);



        }
    }
    public class SireMoDeersMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Sire_MoDeers Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mitosis", "有糸分裂", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the card bearing this sigil is played, it will summon two weaker copies of itself in it's adjacent slots, if possible.", "この印を持つカードを出すと、可能なら隣接するスロットに自分の弱いコピーを2枚召喚する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mo'Deers", "もっとシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card pack that makes sprinter enjoyable, with deers from fiction and reality, to the Polite Bowing Deer to the Preying Deerror! This Card Pack houses 70+ deers by a Community effort, have fun!", "スプリンターを楽しくするカードパック。お辞儀するシカから獲物を狙う迷えるシカまで、現実と創作のシカが登場！　コミュニティの力で70体以上を収録。楽しんで！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Mo'Deers", "エネルギーのもっとシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card pack that houses the Energy Deers! from the Advanced Commandeer to the Beastly Gyfrtot, this pack is for people who wants to play with electricity.", "エネルギーのシカを収録したパック！　上級の支配のシカから獣のギフトロットまで、電気を使いたい人向けだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer God", "シカの神", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conduit Deerel", "コンジットリスジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the conduit deerel, this deerel has been modified with technology.", "コンジットリスジカ。技術で改造されたリスジカだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerel", "リスジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deerel, it has adapted to it's surrounding antler-clad.", "リスジカ。角をまとって周囲の環境に適応した。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pack Moose", "荷運びの雄のヘラジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's bearings can be some of use.", "運んでいるものは何かの役に立つかもしれない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the hard working pack mule, it is carrying some creatures of use.", "働き者の荷運びラバ。役に立つ生物を何体か運んでいる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strange Deern't", "奇妙なシカではない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bidoof Deer", "ビッパジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Commandeer", "支配のシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the advanced commandeer, unlike it's antler-clad brethren, it uses a more practical weapon.", "上級の支配のシカ。角をまとった仲間と違い、より実用的な武器を使う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer Conduit", "コンジットジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this hooved creation is useful when charged.", "充電されると役に立つ有蹄類の創造物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer-ceus", "シカウス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the heavenly deer-ceus, it blesses your troupe with might.", "天上のシカウス。君の一団に力の祝福を与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Engideer", "機構ジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the intellectual engideer, is now engihere.", "知的な機構ジカ、ここに参上。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gazelle", "ガゼル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the gazelle, it can run extreme speeds in a short burst.", "ガゼルは短い間に非常に速く走れる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gun Deer", "銃ジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deformed gundeer, it contains mighty damage, ready to be activated.", "変形した銃ジカ。起動を待つ大きなダメージを秘めている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the gyftrot, a twisted monster made from holiday spirit.", "ギフトロット。祝日の気分から作られたねじれた怪物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Cube", "大きい立方体", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the perfect cube, feast your eyes of such beauty.", "完璧な立方体。その美しさを目に焼き付けよう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect Cube", "完璧な立方体", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snipeer", "狙撃ジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the snipeer, it's accuracy is unmatched.", "狙撃ジカ。その命中精度に並ぶ者はいない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time Deer", "時間ジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the time deer, it can bend time to it's will.", "時間ジカ。意のままに時間を曲げられる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Elk", "陰気なエルク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah. The Never-Dying GRIM ELK. Typically the harbinger of doom, it brings carcasses for many.", "ああ、決して死なない陰気なエルク。普段は破滅の先触れとなり、多くの者に死骸をもたらす。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stunted Deer", "成長不良のシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Where did that eye go..", "あの目はどこに行った……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Augmented Deer", "強化されたシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps it will like this form better than the last one...", "前の姿よりこっちのほうが気に入るかもしれない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaminskeer", "カミンスキージカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaminsk-eer, my very first deer-th cards.", "カミンスキージカ、私の最初のシカデスカード。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kayceer", "ケイシージカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems you found yourself as a Deer-th card Kaycee.", "君自身がシカのデスカードになったようだね、ケイシー。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loui-Stag", "ルイジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the Loui-Stag, converted from it's humanity.", "ルイジカ。人間から変えられた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reginelk", "レギネルク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reginelk, i might have repurposed some of my deathcards...", "レギネルク、デスカードを何枚か流用してしまったかもしれない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amoedeer", "アメーバジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the consequences of forced evolution.", "強制進化がもたらした結果だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspideer", "心蝕むシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this deer hasn't reached it's primal form, may you help it evolve?", "このシカはまだ原始の姿に至っていない。進化を手伝ってくれるか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Primal Aspideer", "原始の心蝕むシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blind Deer", "盲目のシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "injured after a brawl with predators, the blind deer stands no chance.", "捕食者との争いで傷ついた盲目のシカに、勝ち目はない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bowing Deer", "お辞儀するシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the polite bowing deer, it shows its gratitude to you.", "礼儀正しいお辞儀するシカが、君に感謝を示している。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bus", "バス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the devious bus, the cause of most roadkill.", "狡猾なバス。轢かれた動物の大半は、こいつの仕業だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armadeerlo", "アルマジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Deer", "死んだシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a carcass, it has value to the trader.", "死骸だ。毛皮商人には価値がある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Jackalope", "死んだジャッカロープ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a carcass, it was killed in an ambush by hunters.", "死骸だ。狩人の待ち伏せに遭ったのだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerror", "迷えるシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the apex predator.", "頂点捕食者だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer Ant", "シカアリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deer ant, providing power to it's fellow ant-lered.", "シカアリ。角を持つ仲間のアリに力を与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deeratina", "シカティナ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the demonic deeratina, it posseses whoever it lays its sight on.", "悪魔のようなシカティナ。目をつけた相手に憑依する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dear", "シカグマ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the rampaged dear, what had angered it has perished, this vile mix of deer and bear is an untouchable beast.", "荒れ狂うシカグマ。怒らせた者はもう滅びた。シカとクマが混ざったこの邪悪な獣には手出しできない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sky Deer", "天空のシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a shapeshifting deer, it is stuck in it's bird form.", "姿を変えるシカだが、鳥の姿から戻れなくなっている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sea Deer", "海のシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a shapeshifting deer, it is stuck in it's fish form.", "姿を変えるシカだが、魚の姿から戻れなくなっている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerel Ball", "リスジカボール", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the swift deerel ball, antlered squirrels connected to each other with pure sheer-will.", "敏捷なリスジカボール。角の生えたリスたちが、ただひたすらな意志の力でつながっている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerer", "シカ追い", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "doing tasks costs money.", "仕事をするには金がかかる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerman", "シカ人間", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter how much it tries to scream, It remain silent.", "どんなに叫ぼうとしても、声は出ない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deern't", "シカではない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this deer is... this isn't a deer.", "このシカは……いや、シカではない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deeroboros", "ウロボロシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it works differently than it's sibling, it does not strengthen through death, but through progress.", "仲間とは仕組みが違う。死ではなく、進行によって強くなる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer Pile", "シカの骨山", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this pile of bones screams in agony, as it begs for power.", "この骨の山は、力を求めて苦しげに叫んでいる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer Worm", "シカワーム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a dangerous parasite.", "危険な寄生虫だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Findeer", "骨探しのシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the excitable bone findeer, it happily digs through the dirt for bones.", "興奮した骨探しのシカ。楽しそうに土を掘って骨を探す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dire Elk", "ダイアエルク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The raging Dire Elk, its antlers rip apart most prey with ease", "怒り狂うダイアエルク。その角は大抵の獲物を容易く引き裂く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calamian Deer", "カラミアンジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the calamian deer, this endangered creature cannot afford to die.", "カラミアンジカ。この絶滅危惧種を死なせるわけにはいかない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deeeeer", "巨大シカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the chunky Deeeeer, it's size protects adjacent allies..", "ずんぐりした巨大シカ。その大きな体で隣接する味方を守る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerfox", "キツネジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deer-fox, loyal to it's companion.", "キツネジカ。仲間に忠実だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerfox Fawn", "キツネジカの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deerfox fawn, i found this from somewhere else.", "キツネジカの子。どこか別の場所で見つけた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frog Deer", "カエルジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the humble deerfrog, it hops around happily.", "おとなしいカエルジカ。楽しそうに跳ね回る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen Deer", "凍ったシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deer inside has been crystalized for far too long.", "中のシカは長い間、結晶に閉じ込められていた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Golden Stag", "黄金の雄鹿", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the golden stag, searching for his sister, lured away by an impostor.", "黄金の雄鹿。妹を探しているところを、偽物におびき出された。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grazing Deer", "草を食むシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this deer enjoys its meal even during battle.", "このシカは戦闘中でも食事を楽しむ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Headless Deer", "首無しシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it will not stop bleeding, make use of it's situation.", "血が止まらない。その状況を利用するんだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hunter", "狩人", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Imposdeer", "ニセモノジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this feels off...", "何かおかしい……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tired Deer?", "眠たいシカ？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the fierce jackalope, it calls a mate to help the fight.", "獰猛なジャッカロープ。仲間を呼んで一緒に戦う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Long Deer", "長いシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the long deer, it might need some push to expand.", "長いシカ。伸びるには少し後押しが必要かもしれない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerguin", "シカペンギン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the quick deerguin, it pounces swiftly.", "素早いシカペンギン。さっと飛びかかる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shed Antlers", "抜け落ちた角", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this antlers has been shed long after.", "この角はずいぶん前に抜け落ちた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maze Deer", "迷宮シカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it sheds continously as it's antlers rapidly grow.", "角が急速に伸びるため、絶えず生え替わっている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megaloceros", "メガロケロス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the extinct megaloceros, reborn to fight another day.", "絶滅したメガロケロス。また戦うためによみがえった。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moose Fawn", "ヘラジカの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the youthful moose, even in its childhood, it is powerful.", "若い雄のヘラジカ。子供の頃から強い。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Deer", "水晶のシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "made of crystal, this card can power the needy.", "水晶でできたカード。力を必要とする者を支える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer Mage", "シカの魔術師", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deer mage, it requires a certain power to live.", "シカの魔術師。生きるには特定の力が必要だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noelle", "ノエル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the frail Noelle, it has potential to be stronger.", "脆いノエル。もっと強くなる可能性を秘めている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerthulhu", "シカトゥルフ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the gigantic Deerthulhu, it slashes all opponents with it's might.", "巨大なシカトゥルフ。その力で全ての敵を切り裂く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEER?", "シカ？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Legged Deer", "一本足のシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "died a brutal death, it came back to find it's killer.", "むごい死を遂げ、自分を殺した者を探しに戻ってきた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer Knight", "シカの騎士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the loyal deer knight, it's fancy strikes can encourage others to it's calling.", "忠実なシカの騎士。華麗な攻撃で、仲間たちを呼びかけに応じさせる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Osteocoileus", "オステオコイレウス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this skeleton isnt hollow, infact, it is filled to the brim with souls.", "このガイコツは空っぽではない。魂がぎっしり詰まっている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Peryton", "ペリュトン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the peryton, the perfect mix of feathers and fur.", "ペリュトン。羽毛と毛皮が完璧に混ざり合った生き物だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noelle Pog", "驚くノエル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prickly Deer", "トゲのあるシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "its spiny quills shoots out after death.", "死ぬと鋭い針が飛び出す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prongkkall", "ツノウナギ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A slithering predator of the deep. It somehow learned how to grow antlers.", "深海を這う捕食者。なぜか角を生やす術を覚えた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pudu", "プーズー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the miniscule pudu, a small deer, for a small choice.", "小さなプーズー。小さなシカには、小さな選択を。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raged Moose", "怒れるヘラジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the raged moose, it was startled whilst sleeping.", "怒れる雄のヘラジカ。眠っているところを驚かされたのだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reindeer", "トナカイ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the reindeer, just because it's docile doesnt mean it cant lend a hand.", "トナカイ。温厚だからといって、助けにならないわけではない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reindeer Fawn", "トナカイの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the curious fawn, it's docile nature make its reluctant to fight.", "好奇心旺盛な子ジカ。温厚な性格ゆえに戦いたがらない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rudolph", "ルドルフ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this deer's glowing nose guide other's to a safer path.", "このシカの光る鼻は、皆をより安全な道へと導く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Short Elk", "短いエルク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pitiful creature. This elk has been truly... scrungled.", "哀れな生物。このエルクは見事に……ぐしゃぐしゃだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spotted Deer", "斑点のあるシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the Spotted deer, don't startle this armed deer.", "斑点のあるシカ。武装したこのシカを驚かせてはいけない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spotted Fawn", "斑点のある子ジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the Spotted fawn, it's spots are never lost when becoming stronger.", "斑点のある子ジカ。強くなっても斑点は消えない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sire", "君主", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Space Deer", "宇宙ジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the space deer, it dictates where everything should go.", "宇宙ジカ。あらゆるものの行き先を決める。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spi-Deer", "クモジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the SPI-DEER, this creature was made by a bored demigod.", "クモジカ。退屈した半神が作った生物だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "i... dont know where this came from.", "これは……どこから来たのかわからない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spore-galope", "胞子の跳躍ジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deeranged spore-galope, it was never the same since the visit from the mycologists.", "狂った胞子の跳躍ジカ。菌学者たちの訪問以来、すっかり変わってしまった。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tentakelpie", "触手の幻鹿", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the shape-shifting tentakelpie, it shows its true form during hunts.", "姿を変える触手の幻鹿。狩りの時には真の姿を現す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Throwback Deer", "先祖返りのシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the persistent throwback deer, how it survives through the years even confuses the scrybe of beasts.", "しぶとい先祖返りのシカ。長い年月を生き延びてきた理由は、獣のスクライブにもわからない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tired Deer", "眠たいシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this deer is sleeping, i suggest waking it up.", "このシカは眠っている。起こしてやるといい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Deer", "目覚めたシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "now awakened, it moves around for a perfect strike.", "目覚めたシカ。絶好の一撃を放つために動き回る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Water Deer", "キバノロ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deer that grows fangs than antlers, this is the nature of the WATER DEER.", "角の代わりに牙が伸びるシカ。それがキバノロの習性だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weakened Deer", "弱ったシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weakened Fawn", "弱った子ジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "White Stag", "白い雄ジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the white stag, they say it brings good luck.", "白い雄ジカ。幸運をもたらすと言われている。", Language.Japanese);



        }
    }
    public class ApellaDiseasedCardsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Apella_Diseased_Cards_Mod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pack_Of_The_Diseased", "疫病の群れパック", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Creatures of the Woods have Befell a Disease. They have been reborn into a New Form.", "森の生物たちは疫病に倒れ、新たな姿で生まれ変わった。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "airborne dragon", "空飛ぶドラゴン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apex predator of the sky", "空の頂点捕食者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A feast for all", "皆のごちそう", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "trapfrog", "罠のカエル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trapper is gonna be upset", "罠猟師が悲しむだろう", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hydra dragon", "九頭竜", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Three heads are better than one", "頭は一つより三つの方がいい", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "mule", "ラバ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "water dragon", "水竜", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such an amazing creature", "なんと素晴らしい生物だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The prospector will be upset", "探鉱者が悲しむだろう", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "weasel", "イイズナ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe you can find some use for this worthless creature", "この役立たずの生物も、君なら何かに使えるかもしれない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased adder", "疫病のクサリヘビ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a horrible fate", "なんと惨い運命だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased airborne dragon", "疫病の空飛ぶドラゴン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's become an unholy nightmare", "冒涜的な悪夢となってしまった", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased alpha", "疫病の親玉", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor thing is about to rot", "哀れなやつだ。もうすぐ腐ってしまう", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased bat", "疫病のコウモリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hate these things", "こいつらは嫌いだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased bait", "疫病の釣り餌", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Free bones to ye", "骨をただでやろう", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased bullfrog", "疫病のウシガエル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like it's getting ready to pop", "今にも破裂しそうだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased coyote", "疫病のコヨーテ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a feral beast", "なんと獰猛な獣だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased elk", "疫病のエルク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hmm scary lookin", "うむ、恐ろしい見た目だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "rusty trapfrog", "錆びた罠のカエル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased grizzly", "疫病のグリズリー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disease has taken it", "疫病にやられてしまった", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased hydra dragon", "疫病の九頭竜", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a shame what happened to this creature", "この生物がこんな目に遭うとは、残念だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased magpie", "疫病のカササギ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even more wild lookin", "さらに荒々しい見た目になった", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased mantis", "疫病のカマキリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh my god, it is hideous", "なんてことだ、ひどい姿だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased mole", "疫病のモグラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Was cute before the disease got to it", "疫病にかかる前はかわいかった", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased moleman", "疫病のモグラ男", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disease has made this into even more of a monster", "疫病のせいで、さらに怪物じみてしまった", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased mule", "疫病のラバ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that's what was really in there", "なるほど、本当はあれが中に入っていたのか", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased ouroboros", "疫病のウロボロス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An endless cycle, even with the disease", "疫病にかかっても、終わりなき循環は続く", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased packrat", "疫病のパックラット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still useful", "まだ役に立つ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased porcupine", "疫病のヤマアラシ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It grew a tail...", "尻尾が生えた……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased rattler", "疫病のガラガラヘビ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disease has given this thing poison", "疫病のせいでこいつは毒を持つようになった", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased raven", "疫病のカラス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It looks like it has gone mad", "気が狂ってしまったようだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased ringworm", "疫病のリングワーム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased skunk", "疫病のスカンク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This damned disease has gotten to even the smallest of critters", "この忌々しい疫病は、最も小さな生き物にまで及んだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased smoke", "疫病の煙", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That thing scares me", "あれは恐ろしい", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased urayuli", "疫病のユラユゥリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's gotten weaker", "弱くなってしまった", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased vulture", "疫病のハゲワシ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's grown a second head", "二つ目の頭が生えた", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased water dragon", "疫病の水竜", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's such a pitiful creature now", "今ではなんと哀れな生物だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased weasel", "疫病のイイズナ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not as worthless now I see", "今ではそこまで役立たずでもないようだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased wolf", "疫病のオオカミ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even more rabid than it's kin", "仲間よりもさらに凶暴だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased wolfcub", "疫病のオオカミの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh god its eye!", "なんてことだ、目が！", Language.Japanese);


        }
    }
    public class LethalCabinMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for LethalCabin Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lethal Cabin", "リーサルキャビン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Celestial Body: Inscryption.\n Population: Sparse.\n Conditions: Unknown.\n Fauna: [count] species.", "天体：Inscryption。\n個体数：少数。\n環境：不明。\n動物相：[count]種。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hygrodere", "ヒグロデレ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A eukaryotic organism that can multiply to millions with incredible speed.", "驚異的な速さで数百万体にまで増殖する真核生物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jester", "道化の怪物", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know as much as I do. I just call it the Jester.", "君も私も知っていることは同じだ。私は道化の怪物と呼んでいる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kidnapper Fox", "誘拐ギツネ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A large mammal with a horizontal jaw and unique skull shape giving it a great biting strength, and a long, frog-like tongue which can reach even twice the length of its spindly body.", "横に広い顎と独特な形の頭蓋骨によって強い咬合力を持つ大型哺乳類。カエルのような長い舌は、細い体の二倍にまで伸びる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Landmine", "地雷", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Manticoil", "マンティコイル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poses little threat and has a generally passive temperament, although it's capable of transmitting deadly diseases.", "脅威は小さく、おおむねおとなしい性格だが、致命的な病気を媒介することがある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Masked", "マスクド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mask Hornets", "マスクホーネット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mysterious creature that takes the form of an escape door in order to lure in potential prey.", "脱出口の扉に化け、獲物をおびき寄せる謎の生物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nutcracker", "くるみ割り人形", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "watches with one tireless eye, which only senses movement. It remembers the last creature it noticed, whether they are moving or not.", "疲れ知らずの一つ目で見張るが、動くものしか感知できない。最後に見つけた生物は、動いていてもいなくても覚えている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Bird", "オールドバード", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An autonomous, offensive weapon of war with a humanoid design. Equipped with a spotlight, rocket legs, an acoustic device and a missile launcher, they are truly a sight to behold.", "人型の自律攻撃兵器。探照灯、ロケット脚、音響装置、ミサイル発射機を備え、その姿は圧巻だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roaming Locusts", "さまようイナゴの群れ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unlike some species which are more prone to jump or fly, roaming locusts are almost never grounded and stay close together even when in smaller numbers.", "跳ねたり飛んだりする傾向が強い種とは違い、さまようイナゴの群れはほとんど地面に降りず、数が少なくても固まっている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sentry Turret", "セントリータレット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snare Flea", "スネアフリー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A very large arthropod that possesses the ability to tighten itself around large prey to suffocate.", "大型の獲物を締めつけ、窒息させることができる非常に大きな節足動物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spore Lizard", "胞子トカゲ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bulb on its tail secretes a chemical which attracts and accelerates the growth of a fungus, which it can then shake to release spores as a defense mechanism.", "尾の球体から分泌される化学物質は菌類を引き寄せ、その成長を促進する。球体を振って胞子を放ち、身を守ることができる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thumper", "サンパー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Highly aggressive, carnivorous species of hunters, typically at the top of their food chain.", "非常に攻撃的な肉食の狩人で、たいてい食物連鎖の頂点にいる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tulip Snake", "チューリップトカゲ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lifting heavy and large objects into the air has often been observed as a part of the tulip snake's mating display. They are capable of carrying rocks, plants and even other creatures at least twice their size in an effort to impress their potential mate.", "チューリップトカゲが求愛行動として、重く大きな物を空中に持ち上げる姿がしばしば観察される。相手の気を引くため、石や植物、さらには自分の二倍以上の大きさの生物さえ運ぶことができる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vain Shroud", "ヴェインシュラウド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baboon Hawk", "ヒヒタカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As lone scouts, baboon hawks are generally timid and won't attack unless provoked. In greater numbers they can become a great danger.", "ヒヒタカは単独で偵察するときはおおむね臆病で、刺激しなければ攻撃しない。数が増えると非常に危険になる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Barber", "理髪の怪物", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Also known as the Clay Surgeon, Barber is a pack-forming creature that follows a Master Barber's beat to move and attack unsuspecting prey", "クレイサージョンとも呼ばれる理髪の怪物は群れを作る生物で、マスター理髪の怪物の拍子に合わせて動き、無防備な獲物を襲う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bunker Spider", "バンカースパイダー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This enormous arachnid produces silk and lays it around its chosen nesting area, then waits for it to be tripped on.", "この巨大なクモ形類は、巣に選んだ場所の周囲に糸を張り、何かが引っかかるのを待つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Butler", "執事", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deformed like a deflated balloon, this humanoid smells of rotten meat and, if you listen close, you can hear a faint sound of flies buzzing inside...", "しぼんだ風船のように変形したこの人型生物は、腐った肉の臭いを放つ。耳を澄ませば、体内でハエがかすかに羽音を立てるのが聞こえる……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Circuit Bees", "回路バチ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Also known as red bees, these social insects possess the aBEElity to create a field of electrostatic charge.", "赤バチとも呼ばれるこの社会性昆虫は、静電場を作り出す能力を持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coil-Head", "コイルヘッド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Known to combust into flames when being dissected or even deactivated, and carries dangerously high levels of radioactive particles.", "解剖されたとき、あるいは停止させられただけでも発火することで知られ、危険なほど大量の放射性粒子を帯びている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Company Cruiser", "カンパニークルーザー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jeb", "ジェブ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We trust you'll be a great asset to the Company.", "君が会社の大きな戦力になると信じている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Earth Leviathan", "アースリヴァイアサン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can burrow as far as 40 meters underground, judging by the incredible excavations it can leave behind.", "残された巨大な掘削跡から判断すると、地下40メートルまで潜れるようだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eyeless Dog", "目のない犬", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A large mammal, hunting in very large packs. They are endurance hunters and attempt to make up for their lack of sight with their sense of hearing.", "大きな群れで狩りをする大型哺乳類。持久力に優れた狩人で、視力の欠如を聴覚で補っている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forest Keeper", "森の番人", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exhibits a curious behavior similar to that of a human child the age of 5 or 6. It will eat anything it find fascinating.", "5、6歳の人間の子供に似た不思議な行動をとる。興味を持ったものは何でも食べる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Girl", "幽霊の少女", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hoarding Bug", "収集虫", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Given its name due to its territorial nature, they will seek out any object they can find and will protect these objects as a part of the nest.", "縄張り意識が強いことからその名がついた。見つけられるものは何でも集め、巣の一部として守る。", Language.Japanese);




        }
    }
    public class RemoxedBossesMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Remoxed_Bosses Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Crate", "死者の箱", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil dies, it will deal 1 damage to the Scale in favor for the Player.", "この印を持つカードが死ぬと、天秤がプレイヤーに有利な方向へ1傾く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dropped Gem", "落ちたジェム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dropped Pearl", "落ちた真珠", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enchanted Frog", "魔力を付与されたカエル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Crew", "ジェムクルー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Trap", "ジェムの罠", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil dies, it will kill the opposing card.", "この印を持つカードが死ぬと、正面のカードを倒す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Nugget", "ジェムナゲット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minecart", "トロッコ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Seaman", "モックスの水兵", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem powered Trap", "ジェム駆動の罠", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Powder", "オレンジの粉", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil dies, it will grant the opossing card +1 Attack Power and the Orange Mox Sigil.", "この印を持つカードが死ぬと、正面のカードは攻撃力+1とオレンジモックスの印を得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overloaded", "過負荷", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will move in the inscribed direction and leave behind a Orange Mox.", "所有者のターン終了時、この印を持つカードは印の方向に移動し、元の位置にオレンジモックスのカードを残す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oyster", "カキ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remoxed Bosses", "モックス化ボス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Re-adds the Great White to the card pool.", "ホオジロザメをカードプールに再び追加する。", Language.Japanese);

        }
    }
    public class TerrariascryptionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Terrariascryption Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hivemind", "群れの意識", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil is equal to the number of Crimson tribes on the board.", "この印が示す値は、盤上の深紅部族の数に等しい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You dare think that you can skip this fight?", "この戦いを飛ばせると思ったのか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You dare think that you can skip this fight? Face Moonlord, you coward!", "この戦いを飛ばせると思ったのか？ ムーンロードと戦え、臆病者め！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Starvation won't interrupt this fight!", "[c:bR]飢えはこの戦いを中断しない！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Flames", "呪いの炎", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gets harmed by Acids every turn.", "[creature]は毎ターン酸によるダメージを受ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame Protected", "炎からの保護", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can not be damaged by cursed flames.", "[creature]は呪いの炎によるダメージを受けない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Flamethrower", "呪いの火炎放射器", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] discharges cursed flames to harm the opposing creature over time.", "[creature]は呪いの炎を放ち、正面の生物に継続的にダメージを与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AngryTrapper", "怒れる罠猟師", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a Man Eater consumes enough human flesh, it undergoes a cocoon-like metamorphosis into a far deadlier form.", "人食いが十分な人肉を食べると、繭を作るような変態を経て、はるかに危険な姿になる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Crawler", "ブラッドクローラー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Most spiders operate independently, but ones touched by the Crimson hive coordinate together to consume life.", "ほとんどのクモは単独で行動するが、深紅の巣に触れたものは協力して命を喰らう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Mummy", "血のミイラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The blood-dripping organic matter in these mummies display far better preservation than the rest of their ilk.", "このミイラの血を滴らせる有機組織は、同類の他のものよりはるかに保存状態が良い。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Slime", "青いスライム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A simple, gelatinous creature that swallows anything and everything whole! It takes a long time to digest anything.", "単純なゼリー状の生物で、何でも丸呑みにする！ 消化にはとても長い時間がかかる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corruptor", "コラプター", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Like a cancer, the putrid creatures born from the Corruption mutate and grow into bigger, more deadly forms which discharge acids.", "腐敗の地から生まれた腐った生物は、癌のように変異し成長する。やがてより大きく危険な姿となり、酸を放つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corrupt Slime", "腐敗したスライム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Steeped in the power of Corruption, these slimes can survive being cut apart into smaller pieces, unlike their untainted brethren.", "腐敗の力に浸されたスライムは、小さく切り刻まれても生き延びる。汚染されていない仲間にはできないことだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimera", "クリメラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most common horror to be born from the Crimson, it seeks to consume pure things with unrelenting hunger.", "深紅の地から生まれる最もありふれた恐怖。尽きることのない飢えを抱き、清らかなものを喰らおうとする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dasher", "ダッシャー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will Dash in the direction inscribed on the sigil, Attacking whoever stands infront of it.", "所有者のターン終了時、[creature]は印の方向へ突進し、前に立つ者を攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerclops", "ディアクロプス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hailing from a distant land, this cyclopic monstrosity lurks in cold places, wreaking havoc on those who disturb it.", "遠い地から来たこの一つ目の怪物は、寒い場所に潜み、邪魔する者に災いをもたらす。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Demon", "悪魔", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Demons are the infantry of the underworld. Unlike their lesser brothers, they cast shadow magic rather than hell magic.", "悪魔は地獄の歩兵だ。下位の仲間と違い、地獄の魔法ではなく影の魔法を使う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Worm-like monstrosities are the Corruption's most favored creatures, tunneling underneath unsuspecting victims.", "ワームのような怪物は腐敗の地が最も好む生物で、無防備な獲物の足元を掘り進む。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eater of Souls", "イーターオブソウル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Birthed from the Corruption as a being of pure malice, its sole instincts are to pursue, punish, and kill.", "腐敗の地から純粋な悪意として生まれ、追い、罰し、殺すことだけを本能とする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eater of Worlds", "イーターオブワールド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conceived from the bottomless malice of the Corruption, this mighty abyssal worm tunnels wildly to devour all in its path.", "腐敗の地の底知れぬ悪意から生まれた強大な深淵のワーム。荒々しく地中を進み、行く手の全てを喰らう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empress of Light", "光の女帝", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beneath the Hallow's cleansing blanket lies a vengeful fae goddess bent on scrubbing the land of any and all impurity.", "聖域を覆う清らかな幕の下には、復讐に燃える妖精の女神が潜む。彼女は大地のあらゆる穢れを洗い流そうとしている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moon lord", "ムーンロード", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eye Of Cthulu", "クトゥルフの目玉", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A piece of Cthulhu ripped from his body centuries ago in a bloody war. It wanders the night seeking its host body... and revenge!", "何世紀も前の血なまぐさい戦いで、クトゥルフの体から引き裂かれた一部。夜をさまよい、本体を探し……復讐を求めている！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eye Servant", "従者の目", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Face Monster", "フェイスモンスター", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It would be unwise to face off with one of these unfeeling, hungry mutations. Their mouths are large enough to devour all things.", "感情を持たず飢えたこの突然変異体に立ち向かうのは賢明ではない。その口は何でも丸呑みにできるほど大きい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moon Awakening", "月の覚醒", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Creature behind the Moon has awoken...", "月の背後にいる生物が目覚めた……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Tortoise", "巨大リクガメ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No one takes the giant tortoises seriously. Not until they come hurtling through the air, a spinning, spiky ball of death.", "巨大リクガメを侮る者は多い。回転する棘だらけの死の球となって空を飛んでくるまでは。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herpling", "ハープリング", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These hyper, demented, slug-like fiends serve the crimson horde with an unstoppable appetite for blood and flesh.", "興奮し狂ったナメクジのような魔物たちは深紅の大群に仕え、血肉に対する飽くなき欲望を抱いている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hooked", "鉤爪", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hook", "フック", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will summon Hooks on either side of it.", "[creature]は自分の両側にフックを召喚する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "if [creature] is not surrounded by a card bearing the Hooked Sigil it will loose all attack.", "[creature]の周囲に鉤爪の印を持つカードがなければ、攻撃力を全て失う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aggressive flying insects which swarm the jungle depths. Their venomous barbs discharge over great distances at high velocity.", "攻撃的な飛ぶ昆虫がジャングルの奥に群がっている。毒の棘を高速で遠くまで放つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Slime", "氷のスライム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimes that spent too long in arctic temperatures may begin to partially freeze, developing a shifting layer of ice on their surface.", "極寒の環境に長くいたスライムは部分的に凍り、表面に変化する氷の層ができることがある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiked Ice Slime", "棘の氷のスライム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Ice Slime has large ice shards in its mass from excessive exposure to the cold.Somehow, it is able to launch these at its prey.", "この氷のスライムは寒さにさらされすぎたため、体内に大きな氷の破片を持つ。どういうわけか、それを獲物に向けて発射できる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichor", "霊液", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gets damaged for the damage * 2.", "[creature]が受けるダメージは2倍になる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichor Protected", "霊液からの保護", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creatures]s defense can not be lowered by ichor.", "[creature]の防御力は霊液によって下げられない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichor Discharging", "霊液放出", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] discharges Ichor to lower the opposing creatures defenses.", "[creature]は霊液を放ち、正面の生物の防御力を下げる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichor Sticker", "イコルステッカー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled to the brim with powerful ichor, these squid-like abominations spew their corrosive bio-fluid at their prey.", "イカのような異形の怪物は強力な霊液で満たされ、獲物に腐食性の体液を吐きかける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "King Slime", "キングスライム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimes normally aren't intelligent, but occasionally they merge together to become a powerful force to swallow all things.", "スライムは普通知性を持たないが、ときには合体し、全てを呑み込む強大な力となる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Engulfer", "イングルファー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed on the sigil. Creatures in the way will be engulfed.", "所有者のターン終了時、[creature]は印の方向へ移動し、進路上の生物を飲み込む。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lavaborne", "溶岩生まれ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will hide underneath Lava. Any card willing to attack will be damaged by the Lava", "[creature]は溶岩の下に隠れる。攻撃しようとするカードは溶岩のダメージを受ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leap", "跳躍", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to choose an empty slot to move [creature] into and deal 1 damage to the opposing slot.", "骨を2個支払い、空のスロットを選んで[creature]を移動させ、正面のスロットに1ダメージを与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lunar Spells", "月の呪文", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will create Spells as it strafes.", "[creature]は横移動する際に呪文を作り出す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LunaticCultist", "ルナティックカルト", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lightning Orb", "稲妻の球", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Mist", "氷の霧", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lord of the Moon", "月の領主", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chest", "箱", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talking to a chest doesn't cause craziness, but if the chest answers back, it may cause death! It still contains rare treasure, regardless!", "宝箱に話しかけても気は狂わない。だが箱が返事をしたなら、命を落とすかもしれない！ それでも中には貴重な宝が入っている！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corrupted Mimic", "腐敗した模倣者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mimics which fall to Corruption grow larger and more powerful as a result. They can be birthed from ordinary chests by force.", "腐敗に堕ちた模倣者は、より大きく強くなる。普通の宝箱から強制的に生み出すこともできる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Mimic", "深紅の模倣者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "True Eye", "真の目", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phase Switcher", "フェーズ切り替え", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon Death, [creature] will reach its next Phase.", "[creature]が死ぬと、次のフェーズに移る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nebula Pillar", "ネビュラピラー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Solar Pillar", "ソーラーピラー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stardust Pillar", "スターダストピラー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vortex Pillar", "ボルテックスピラー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pixie", "ピクシー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A larger, more luminous form of fairy. Pixies provide the Hallow with more blessed light and aid in the cleansing of the land.", "より大きく明るい妖精。ピクシーは聖域に祝福された光をもたらし、大地の浄化を助ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plantera", "プランテラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dormant, yet powerful floral guardian awoken by the fallout of Cthulhu's destroyed machinations. Its reach spans the entire jungle.", "眠っていた強力な花の守護者。クトゥルフの機械が破壊された余波で目覚めた。その勢力はジャングル全体に及ぶ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Planteras Hook", "プランテラのフック", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purple Slime", "紫のスライム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will spit out a randomly chosen Rare Card upon being placed.", "[creature]は配置されると、ランダムに選ばれたレアカードを1枚吐き出す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Red Slime", "赤いスライム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who needs muscles, skin, or even eyeballs? Skeletons get by with just the bones on their back, just as deadly as more fleshy foes.", "筋肉や皮膚、眼球など必要だろうか？ ガイコツは骨だけで生きていけるし、肉のある敵に負けず劣らず危険だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Serpent", "骨の蛇", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mighty serpentine dragons once ruled hell, but long ago shed their obsidian scales.A skeletal husk is all that remains.", "かつて地獄を支配した強大な蛇のような竜は、遠い昔に黒曜石の鱗を脱ぎ捨てた。今は骨の抜け殻だけが残る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimer", "スライマー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slimer has become airborne with wings of unknown origin. The wings are easily knocked off with force, depriving it of its flight.", "スライマーは由来のわからない翼を得て飛べるようになった。翼は衝撃で簡単に外れ、飛べなくなる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Man Eater", "人食い", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sharp-toothed plant with a taste for human flesh. It has the ability to hide inside the mud and reach over great distances.", "人肉を好む鋭い歯の植物。泥の中に隠れ、遠くまで伸びることができる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dryad", "ドライアド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sands of time are flowing. And well, you are not aging very gracefully.", "時の砂は流れている。君はまあ、あまり優雅に年を重ねてはいないようだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guide", "案内人", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They say there is a person who will tell you how to survive in this land... oh wait. That's me.", "この地で生き延びる方法を教えてくれる人がいるそうだ……ああ、待って。それは僕だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tree but ded.", "木だけど、枯れてる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cool Slime", "クールなスライム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Easily the coolest slime around, no question. You can tell from the backwards hat and indecipherable slang.", "間違いなく、この辺りで一番クールなスライムだ。後ろ向きの帽子と意味不明なスラングを見ればわかる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clumsy Slime", "不器用なスライム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slime was a little confused when the other slimes started putting on hats and accessories. But it did its best.", "他のスライムたちが帽子やアクセサリーを身につけ始めたとき、このスライムは少し戸惑った。でも精一杯頑張った。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nerdy Slime", "オタクなスライム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just a smidge cleverer than other slimes, this slime discovered how to coexist with humans. The secret: accessorizing!", "他のスライムよりほんの少し賢いこのスライムは、人間と共存する方法を見つけた。秘訣はアクセサリーだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surly Slime", "不機嫌なスライム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Irascible and insufferable, this grumpy slime is probably up to no good. Probably. Its the thought that counts really.", "怒りっぽくて我慢ならない、この不機嫌なスライムはきっと何か悪事を企んでいる。たぶん。大切なのは気持ちだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder Slime", "長老スライム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Older, though not necessarily wiser, the other slimes look up to the Elder Slime. If it survived this long, it must know something!", "年は取っているが、必ずしも賢いわけではない。それでも他のスライムは長老スライムを尊敬している。これだけ長く生きたのだから、何か知っているはずだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diva Slime", "ディーバスライム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Born of the combined energies of Shimmer and the Queen Slime, this slime is full of boundless energy and enthusiasm! And so fancy!", "シマーとスライム女王のエネルギーが合わさって生まれたこのスライムは、無限の活力と情熱にあふれている！ しかも実に華やかだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mystic Slime", "神秘のスライム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slime knows that great witches wear impressive hats, but it only found a droopy one. Might explain the backfired polymorph!", "偉大な魔女が立派な帽子をかぶることは知っていたが、見つけたのはへなへなの帽子だけ。変身魔法が裏目に出たのは、そのせいかもしれない！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squire Slime", "従者スライム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hero amongst slimes, it wields the greatest arms and armor known to its kind. It doesn't actually know how to use them, but its a start.", "スライムたちの英雄。同族が知る最高の武器と防具を携える。実は使い方を知らないが、まずは第一歩だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unicorn", "ユニコーン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These majestic single-horned equines storm angrily through the hallowed land in search of lowly intrusions needing to be cleansed away.", "荘厳な一本角の馬は聖なる地を怒りに駆られて駆け、浄化すべき卑しい侵入者を探す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wall Creator", "壁の創造者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will create a Wall on [creature]s Side.", "[creature]は[creature]側に壁を作る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wall of Flesh", "肉の壁", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serving as the world's core and guardian, the towering demon lord exists to keep powerful ancient spirits sealed away.", "世界の中心であり守護者でもある、そびえ立つ悪魔の領主。その存在は強大な古代の霊を封じておくためにある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Middle Strike", "中央攻撃", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Right Strike", "右への攻撃", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Left Strike", "左への攻撃", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack only cards in the slot to its right. If a targeted slot is empty, the damage will be redirected to the opponent.", "[creature]は同じ側の右のスロットにあるカードだけを攻撃する。対象のスロットが空なら、ダメージは対戦相手に向かう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack only cards in the slot to its left. If a targeted slot is empty, the damage will be redirected to the opponent.", "[creature]は同じ側の左のスロットにあるカードだけを攻撃する。対象のスロットが空なら、ダメージは対戦相手に向かう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrascryption", "テラリプション", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack contains a bunch of awesome Terraria themed Cards!", "このカードパックには、素晴らしいテラリアをテーマにしたカードがいっぱい！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fortunate draw.", "幸運なドローだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be safe", "気をつけて", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect", "完璧", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sands of time are flowing.", "時の砂は流れている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I Hope you aren't making a Mistake!", "間違ってないといいね！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You think this works?", "これでうまくいくと思う？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh what a misplay?", "ああ、なんて悪手だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh!", "おお！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose Me.", "僕を選んで。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't Sacrifice me.", "僕を生贄にしないで。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you need to....", "必要なら……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop that.", "やめろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Angler...", "釣り人……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "how disgusting", "なんて気持ち悪い", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just defeat him already", "早く倒してよ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boss time, eh?", "ボス戦だね？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an honor.", "光栄だよ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is great!", "すごい！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an honor", "光栄だよ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fingers crossed", "幸運を祈ろう", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nice Deck.", "いいデッキだね。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iam here to help You!", "君を助けに来たよ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lucky.", "運がいい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't die", "死なないで", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "not the worst draw.", "悪くないドローだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good Choice!", "いい選択だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iam a Guide afterall.", "何しろ僕は案内人だからね。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OK...", "わかった……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its a Good Choice.", "いい選択だよ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Total misplay.", "完全な悪手だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yep.", "そうだね。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I Hope this is right!", "これで合ってるといいね！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sure I guess?", "たぶん、そうかな？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose Who you want.", "好きなものを選んで。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifice me if you need to.", "必要なら僕を生贄にして。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will still guide you!", "それでも君を導くよ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Prospector. Watch out for his Pickaxe.", "探鉱者だ。ツルハシに気をつけて。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Prospector...", "探鉱者……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kill the Mule for Cards", "ラバを倒せばカードが手に入る", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the mule's key", "ラバが鍵だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you sure about this?", "本当にそれでいいの？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Corruption is waiting for you!", "腐敗の地が君を待っている！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Crimson is waiting for you!", "深紅の地が君を待っている！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Brain of Cthulu has awoken!", "クトゥルフの脳が目覚めた！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Representing a flaming celestial event known as 'solar flares', this tower holds the seal locking away a terrifying tyrant.", "「太陽フレア」と呼ばれる燃え盛る天体現象を象徴するこの塔には、恐ろしい暴君を封じる封印がある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Representing a deep celestial void known as 'vortex', this tower holds the seal locking away a terrifying tyrant.", "「ボルテックス」と呼ばれる深い宇宙の虚空を象徴するこの塔には、恐ろしい暴君を封じる封印がある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Representing a stormy celestial body known as 'nebula', this tower holds the seal locking away a terrifying tyrant.", "「星雲」と呼ばれる嵐のような天体を象徴するこの塔には、恐ろしい暴君を封じる封印がある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Representing a glittering celestial remnant known as 'stardust', this tower holds the seal locking away a terrifying tyrant.", "「星屑」と呼ばれる輝く天体の残骸を象徴するこの塔には、恐ろしい暴君を封じる封印がある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And so arrives the Moonlord, harbringer of all Destruction.", "あらゆる破壊の先触れ、ムーンロードがやって来た。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You saved us all!", "君が皆を救ったんだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Eater of Worlds has awoken!", "イーターオブワールドが目覚めた！", Language.Japanese);

        }
    }
    public class BittysRegionsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for BittysRegions Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TIME TO FORGE METAL!", "金属を鍛えるぞ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GO MY KNIGHTS!", "行け、我が騎士たち！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah... no materials...", "ああ……材料がない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>You may claim those are your cards...</color>", "<color=#32CD32>これらは自分のカードだと言ってもいい……</color>", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>But the spiders inside them are MINE!</color>", "<color=#32CD32>だが、その中のクモは私のものだ！</color>", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>A shame... There's none of my spiders on your side...</color>", "<color=#32CD32>残念だ……君の側には私のクモがいない……</color>", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>A spider's bite always strikes when least expected...</color>", "<color=#32CD32>クモはいつも最も予想外の瞬間に噛みつく……</color>", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mad laughter of a wild dog.", "野犬の狂った笑い声。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chihuahua", "チワワ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Savage and vicious, all wrapped up in a tiny package.", "小さな体に凶暴さを詰め込んだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woodpecker", "キツツキ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The persistent Woodpecker, it strikes endlessly.", "しつこいキツツキ。絶え間なく攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ever-rolling squirrel ball, a strange and bizzare phenomenon.", "転がり続けるリス・ボール。奇妙で不思議な現象だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the mighty hawk, champion of the skies.", "力強いタカ。空の王者だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seagull", "カモメ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Known as rats of the skies... Or was that another bird?", "空のネズミと呼ばれている……それは別の鳥だったかな？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hermit Crab", "ヤドカリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The humble hermit crab. Always seeking a new home.", "つつましいヤドカリ。いつも新しい住処を探している。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rock Wall", "石壁", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sheer wall of rock.", "切り立った岩壁。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A world on fire.", "燃え上がる世界。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flaming Tree", "燃える木", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coal Pile", "石炭の山", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fuel for the flames.", "炎の燃料だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shackle", "足かせ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bindings forged in flames.", "炎の中で鍛えられた拘束具。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knight", "騎士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creations of steel and fire.", "鋼鉄と炎から生まれたもの。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turtle Rock", "カメ岩", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Covered in rocks, with strength to reflect it.", "岩に覆われ、それにふさわしい強さを持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flamemingo", "フレイミンゴ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic Phoenix. Always comes back.", "荘厳なフェニックス。必ずまた戻ってくる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flamingo in terrible pain. Not to be mistaken with the majestic Phoenix.", "ひどく苦しんでいるフラミンゴ。荘厳なフェニックスと間違えないように。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drake", "ドレイク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dwellers of volcanos and other infernal places.", "火山やその他の地獄のような場所に住む。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Salamander", "サラマンダー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A slippery little creature.", "ぬるぬるした小さな生物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flaming Salmon", "燃えるサケ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Salmon scarred by searing flames. Native to lava pools.", "灼熱の炎で傷ついたサケ。溶岩の池に生息する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A savage beast of the depths.", "深淵に棲む凶暴な獣。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire Ant", "火アリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hundreds scurry from their anthill.", "何百匹ものアリが巣から走り出す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coal Boy", "石炭の子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A freakish creation. It bites.", "奇怪な創造物。噛みつくぞ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brood Mother", "母グモ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mother of many, stored inside her own body.", "多くの子の母親。その子らは体内に収められている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Childlike wonder, monsterous body.", "子供のような好奇心に、怪物のような体。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasitic Spider", "寄生グモ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infesting everything it touches.", "触れるもの全てに寄生する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Egg Sack", "卵嚢", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sac of eggs.", "卵が入った袋。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Daddy Long Legs", "ザトウムシ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tall and spindly, father of none.", "背が高く細長いが、誰の父親でもない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pillar?", "石柱？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pillar?", "石柱か？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wolf Spider", "コモリグモ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As deadly as a normal wolf, but more skittish.", "普通のオオカミと同じくらい危険だが、もっと臆病だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Night Mare", "ナイトメア", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fragment of a darkened dream. It harms everything, including allies.", "暗い夢のかけら。味方を含む全てを傷つける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rampaging monster of many legs.", "暴れ回る多脚の怪物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doom Clock", "終末の時計", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ancient calendar foretelling the end of the world.", "世界の終わりを予言する古代の暦。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chair", "椅子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange metal chair.", "奇妙な金属の椅子。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elk Mage", "エルクの魔術師", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ambitious Elk, making its way in the world.", "野心的なエルク。世の中を渡り歩いている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mus-Elk Mage", "筋肉エルクの魔術師", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Muscle Mage's incarnation. Muscular and beautiful.", "マッスル・メイジの化身。筋肉質で美しい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glowing Buck", "光る雄ジカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fully fledged master of luminescence.", "発光を完全に極めたマスター。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fading light.", "消えゆく光。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack adds [count] new cards that are found in every region. (There are more cards that are region specific!)", "このカードパックは、全ての地域で見つかる新たなカードを[count]枚追加する。（特定の地域でのみ見つかるカードも、さらにある！）", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The damp air of the underground...", "地下の湿った空気……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And water dripping down stalagmites...", "そして石筍を伝って滴る水……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You entered... [c:bG]The Infested Caves.[c:]", "君は入った……[c:bG]虫だらけの洞窟に。[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Webs line the walls...", "壁にはクモの巣が並ぶ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The skittering of many legs echo throughout the caverns...", "無数の脚が走り回る音が洞窟中に響く……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With trepidation, you enter... [c:bG]The Infested Caves.[c:]", "不安を抱き、君は入る……[c:bG]虫だらけの洞窟に。[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cool air of the caverns greeted your face...", "洞窟のひんやりとした空気が顔に触れた……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you crept below...", "君は地下へと忍び足で進み……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Into [c:bG]The Infested Caves.[c:]", "[c:bG]虫だらけの洞窟へ。[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The smell of sulfur...", "硫黄の臭い……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And falling ash...", "そして降り注ぐ灰……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You reach... [c:bG]The Lava Flow.[c:]", "君はたどり着いた……[c:bG]溶岩流に。[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You see the land glowing in the distance...", "遠くの大地が光っている……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Molten rock, flowing in rivers...", "溶けた岩が、川となって流れている……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have reached... [c:bG]The Lava Flow.[c:]", "君はたどり着いた……[c:bG]溶岩流に。[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The landscape is dark with ash...", "灰で暗くなった風景……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trees are burning...", "木々が燃えている……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You tread through... [c:bG]The Lava Flow.[c:]", "君は歩いて行く……[c:bG]溶岩流の中を。[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This time you will choose a region specific card.", "今回は地域限定のカードを選ぶ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose wisely.", "慎重に選ぶがいい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You approach a great stone forge.", "君は巨大な石の炉に近づく。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems that you aren't alone.", "どうやら君は一人ではないようだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The clanging of metal reverberates around you.", "金属を打つ音が君の周りに響き渡る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sparks spill from the forge.", "炉から火花が散る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You run into a nearby cave to escape the smell of sulfur.", "君は硫黄の臭いから逃れるため、近くの洞窟に駆け込む。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "However, this cave is inhabited.", "だが、この洞窟には先客がいる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am the blacksmith, [c:bG]Martel.[c:]", "私は鍛冶屋の[c:bG]マーテルだ。[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The old man has given me the opportunity to face you properly...", "あの老人のおかげで、お前と正々堂々戦う機会を得た……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am the blacksmith.", "私は鍛冶屋だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's forge you into a fine creation.", "お前を立派な作品に鍛え上げてやろう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you... are the iron.", "そしてお前は……鉄だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time, challenger.", "時が来た、挑戦者よ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time for you to see the true meaning of... PERFECTION.", "見せてやろう……完璧の真の意味を。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You approach the deepest part of the cave.", "君は洞窟の最深部に近づく。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Long legs creep out of the shadows, as many smaller spiders skitter around.", "長い脚が影から這い出し、小さなクモたちが周囲を走り回る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A light hearted voice calls out to you.", "陽気な声が君に呼びかける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>Ahuhuhu~</color>", "<color=#32CD32>あふふふ～</color>", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>My, who do we have here?</color>", "<color=#32CD32>あら、誰が来たのかしら？</color>", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>It's been so long since I've seen a Challenger...</color>", "<color=#32CD32>挑戦者に会うなんて久しぶり……</color>", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>Let's have some fun...</color>", "<color=#32CD32>一緒に楽しみましょう……</color>", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>I am the queen of the spiders,</color>", "<color=#32CD32>私はクモたちの女王、</color>", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>And You're LUNCH!</color>", "<color=#32CD32>あなたは昼食よ！</color>", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is this...", "これは……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A new map?", "新しい地図か？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't know who stands at the end of this path...", "この道の先に誰が待っているのか、私にもわからない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're not meant to see this dialogue.", "この会話は本来、君には見えないはずだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something has gone wrong.", "何かが間違っている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insect Swarm", "昆虫の群れ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of insects that the owner has on their side of the table.", "この印が示す値は、盤上の所有者側にいる昆虫類の数に等しい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Create Terrain", "地形の創造", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random terrain is created on the opposing space.", "[creature]を場に出すと、向かいのスペースにランダムな地形が作られる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Egg Sacks", "卵嚢", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, Spiderlings are created on the owner's empty spaces.", "[creature]が死ぬと、所有者の空きマスに子グモが作られる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Many Legs", "多脚", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, a Leg is created in its place and a card bearing this sigil moves to the right.", "[creature]が攻撃を受けると、元の位置に脚が作られ、この印を持つカードは右へ移動する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Stock", "骨の蓄え", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a bone is generated for card on the owner's side of the board.", "[creature]を場に出すと、盤上の所有者側にあるカードごとに骨が1個生まれる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flip Attack", "攻撃反転", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, swap its Power and Health.", "[creature]が攻撃すると、攻撃力と体力を入れ替える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inflamed", "炎症", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, discard the oldest card in your hand.", "[creature]が攻撃を受けると、手札で最も古いカードを1枚捨てる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recursive", "再帰", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes or is discarded, a copy of it is created in your deck.", "[creature]が死ぬか捨てられると、デッキにそのコピーが1枚作られる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scuttler", "素早い移動", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of battle, [creature] will move in the direction inscribed in the sigil.", "戦闘開始時、[creature]は印に記された方向へ移動する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dark Growth", "暗黒の成長", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent and opposing cards gain 1 power and lose 1 health.", "[creature]が死ぬと、同じ側の左右に隣接するカードと正面のカードは攻撃力を1得て、体力を1失う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn [creature] counts down. If this sigil reaches 0, you lose.", "毎ターン終了時に[creature]のカウントが減る。この印が0に達すると、君は敗北する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muscle Milk", "筋肉ミルク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may be played on other cards. When [creature] is played on another card, it gains 1 power and loses 1 health.", "[creature]は他のカードの上に出せる。[creature]を別のカードの上に出すと、下のカードは攻撃力と体力を1ずつ得て、この生物は死ぬ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoning", "召喚", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card of the same cost tier is summoned to the right.", "[creature]を場に出すと、同じコスト段階のランダムなカードを右に召喚する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrain Dweller", "地形の住人", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may be played on terrain cards. When [creature] is played on a terrain card, the terrain gains this creature's stats and sigils.", "[creature]は地形カードの上に出せる。[creature]を地形カードの上に出すと、地形はこの生物の能力値と印を得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blazing Deck", "燃えるデッキ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, [creature] will draw 1 card from your deck with Fleeting.", "所有者のターン開始時、[creature]はデッキから束の間の印を持つカードを1枚引く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bellows", "ふいご", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, draw 1 card from your side deck with Fleeting.", "[creature]が攻撃を受けると、サイドデッキから束の間の印を持つカードを1枚引く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel Swarm", "リスの群れ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil and drop a Squirrel in its old space. Creatures that are in the way will be pushed in the same direction.", "所有者のターン終了時、[creature]は印に記された方向へ移動し、元いた場所にリスを残す。進路を塞ぐ生物は同じ方向に押される。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, deal a single damage point to the opposing card.", "[creature]を場に出すと、正面のカードに1ダメージを与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand Limit", "手札上限", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn [creature] is in your hand or on the board, discard your oldest card until you have 4 or less cards in your hand, or the oldest card has this sigil.", "毎ターン終了時、[creature]が手札か盤上にあるなら、手札が4枚以下になるか、最も古いカードがこの印を持つまで、最も古いカードを捨てる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Devour", "貪り喰う", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the opposing card is consumed. If this creature dies, the consumed creature is returned to the hand.", "[creature]を場に出すと、正面のカードを飲み込む。この生物が死ぬと、飲み込まれた生物は手札に戻る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Discard Shield", "捨て札の盾", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all cards in your hand have Fleeting removed from them. When a card is drawn, Fleeting is removed from it.", "[creature]を場に出すと、手札の全カードから束の間を取り除く。カードを引いたとき、そのカードから束の間を取り除く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anthill", "アリ塚", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card is discarded while [creature] is on the board, create a Fire Ant in your hand.", "[creature]が盤上にいる間、カードが捨てられると、手札に火アリを作る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spider's Host", "クモの宿主", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a spiderling crawls out.", "[creature]が死ぬと、子グモが這い出てくる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasitic Bite", "寄生の噛みつき", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks another creature, that creature's sigils are removed and becomes host to a spiderling.", "[creature]が他の生物を攻撃すると、その生物の印が取り除かれ、子グモの宿主になる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AH HA HA!", "アハハハ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S ME!", "僕だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LIGHT, LIGHT!", "光、光だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I BURN!", "燃えている！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I SEE YOU!", "見えてるぞ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES!", "そうだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BURN, BURN!", "燃えろ、燃えろ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DIE, DIE!", "死ね、死ね！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I BURN SO BRIGHTLY!", "僕はこんなに明るく燃えている！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "COAL BOY, AWAY!", "石炭の子、出動！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PERFECT!", "完璧だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AHAHAHAH", "アハハハ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AHAHAHAHA", "アハハハハ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BLINDING LIGHT!", "まばゆい光だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EVERYONE SHALL KNOW MY PAIN!", "皆が僕の痛みを知ることになる！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SO COLD...", "寒い……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DARKNESS...", "暗闇……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FADING...", "消えていく……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RELEASE!", "解放だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PICK ME!", "僕を選んで！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WILL SHINE!", "僕は輝く！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE LIGHT BECKONS!", "光が呼んでいる！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ME, ME!", "僕、僕だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SO BRIGHT!", "まぶしい！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reminds me of him...", "彼を思い出す……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO GOOD FROM DARK!", "闇にはいいことがない！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ASHES, LIGHT!", "灰、光だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE LIGHT BECKONS!", "光が呼んでいる！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE FLAMES!", "炎だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT HURTS!", "痛い！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DARKNESS, DARKNESS!", "闇だ、闇だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M BURNING!", "僕が燃えている！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DOOM APPROACHES...", "終末が近づいている……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "REJOICE!", "喜べ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ever closer to him...", "彼にますます近づいている……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I TRANSCEND!", "僕は超越する！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LIGHT!", "光だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STARS, HORSESHOES!", "星、蹄鉄！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TRIAL BY FIRE!", "炎の試練だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DARKNESS HIDING!", "闇が隠れている！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DID YOU GET IT?", "わかったか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I AM COAL BOY!", "僕は石炭の子だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOY OF COAL!", "石炭の子！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU!", "君だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PICKAXE MAN!", "ツルハシの人！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE MINES COAL!", "彼は石炭を掘る！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GOLD SHINES BRIGHTLY!", "金が明るく輝いている！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BURN THE DOGS!", "犬を燃やせ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOSS TIME!", "ボスの時間だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AHAHAHAHAHAHAHAHA!", "アハハハハハハハ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FISH MAN!", "魚の人！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BUCKETS OF FISH!", "バケツいっぱいの魚！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FIIIISH!", "さかなぁぁぁ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SO DARK AND COLD...", "暗くて寒い……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TWINS?", "双子？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHINY KNIVES!", "光るナイフ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HIM!", "彼だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The moon...", "月が……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EMBODIMENT OF DARKNESS...", "闇の化身……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PHANTOMS, DEMONS!", "幻影、悪魔！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DARK, DARK!", "闇だ、闇だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MOONLIGHT...", "月の光……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TRI CANDLE LIGHT!", "三本のろうそくの光！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHERE'S THE SUN?", "太陽はどこだ？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HEAVE,", "よいしょ、", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HO!", "こらしょ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GUNPOWDER!", "火薬だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOOM!", "ドカン！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't burn water...", "水は燃やせない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CREATE SPARKS!", "火花を起こせ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite!", "火をつけろ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MASTER!", "マスター！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S HIM! IT'S HIM!", "彼だ！ 彼だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have brought me into your hand.", "君は私を手札に加えた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello again.", "また会ったな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For glory!", "栄光のために！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EN GUARDE!", "構え！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reforged...", "鍛え直された……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heat and iron.", "熱と鉄。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will be good.", "これはよくなるぞ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you must.", "どうしてもと言うなら。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only a flesh wound.", "かすり傷にすぎない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ergh.", "うぐ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oof.", "うっ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will not fail.", "私は失敗しない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stronger...", "もっと強く……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I grow.", "私は成長する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A trial...", "試練か……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I shouldn't be here.", "私はここにいるべきではない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And yet I am.", "だが、私はここにいる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He mines ore for the Master.", "彼はマスターのために鉱石を掘っている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With the old man's permission of course.", "もちろん、老人の許可を得ている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Prospector.", "探鉱者。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He races against the Diver...", "彼は潜行者と競争している……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Angler.", "釣り人。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't actually know what they do.", "実のところ、彼らが何をしているのか知らない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who are they?", "彼らは誰だ？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The old man...", "あの老人……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He trades with the master sometimes.", "彼は時々マスターと取引する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Master.", "マスター。", Language.Japanese);


        }
    }
