    public class LobotomyNostalgiaMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Lobotomy_Nostalgia_Mod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lobotomy-Nostalgia-Mod", "ロボトミー・ノスタルジアMOD", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack was originally created by KingSlime, later revamped and maintained by Nostalgist, containing [count] Abnormality cards from Lobotomy Corporation.", "このカードパックはKingSlimeが制作し、後にNostalgistが改修・保守したものだ。『Lobotomy Corporation』のアブノーマリティカードを[count]枚収録する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber Dawn", "琥珀色の黎明", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber Dawn, searching for the perfect meals", "琥珀色の黎明。完璧な食事を求めている", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber Dusk", "琥珀色の夕暮れ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber Dusk, loves the taste", "琥珀色の夕暮れ。この味が大好きだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber Midnight", "琥珀色の真夜中", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'they fough amongst themselves to feed'", "「彼らは食べるために互いに戦った」", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "apocalypse, the horrid amalgamation of the defenders of the forest. a shame how it ended for them", "終末鳥。森の守護者たちが混ざり合った恐ろしい姿だ。彼らの結末は残念だった。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Aspiration, it loves seeing the battlefield", "渇望。戦場を眺めるのが好きだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The crazed notes, seems the writer lost thier mind", "狂気の手記。書いた者は正気を失ったようだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Dawn", "深紅の黎明", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The crimson Dawn, a walking circus", "深紅の黎明。歩くサーカスだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Dusk", "深紅の夕暮れ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The circus tent is finally here", "サーカスのテントがついにやって来た", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Noon", "深紅の白昼", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Crimson Noon, even more deformed then its brothers", "深紅の白昼。仲間たちよりさらに歪んでいる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Dawn", "緑の黎明", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the emerald Dawn, building towards that they came", "緑の黎明。自分たちの来た場所を目指して建設する", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Dusk", "緑の夕暮れ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "constructing a tower from whence they came, so much potential", "自分たちの来た場所へと続く塔を建設中だ。大きな可能性を秘めている", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Midnight", "緑の真夜中", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'the tower is touched by the sky, and it will leave nothing on this earth'", "「塔が空に触れ、地上には何も残らない」", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Noon", "緑の白昼", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "emerald noon, expresseing only despair and ire", "緑の白昼。絶望と怒りだけを表す", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the flesh idol, worshiped by those who are truly insane", "肉の偶像。本当に狂った者たちに崇拝されている", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Great Sap, usefull past the card", "巨大な樹液。カード以外にも使い道がある", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hod, the training meltdown", "ホド、教育のメルトダウン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malkuth, The meltdown of annoying me", "マルクト、私を苛立たせるメルトダウン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the mirror of adjustment, some say it leads to another world", "性別を変える鏡。別の世界に通じているという者もいる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "netzach, the safety meltdown", "ネツァク、安全のメルトダウン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime, heard he trying hard to make this mod good", "スライム。このMODをよくするために頑張っているらしい", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the band, popular amongst teens", "そのバンドは、若者の間で人気がある", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orchestra", "楽団", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bear, it waits to show its true self", "クマは本当の姿を見せる時を待っている", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bloody, seems the blood never ends", "血まみれのもの。血は尽きることがないようだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the box, dont stare into the keyhole for to long", "箱。鍵穴を長く覗き込まないことだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The clockwork, the humming of its motors arent the only annoyance it makes", "ぜんまい仕掛け。モーターの唸りは、こいつが引き起こす迷惑の一つにすぎない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Current, an experiment that has never seen the real world", "流れ。現実の世界を見たことのない実験体", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the cute, its looks can melt even the coldest hearts", "かわいいもの。その姿は最も冷たい心さえ溶かす", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this one is no longer cute", "もうかわいくはない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the dream, a peaceful ram that loves to sleep", "夢。眠るのが好きな穏やかな雄羊", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "guess its dream came true", "夢が叶ったようだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the exposed, taking the direct approach", "むき出しのもの。正面から立ち向かう", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The flower, living and walking on sunshine", "花。日差しを浴びて生き、歩いている", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the fragment, the poor creature experimented on into its form", "破片。哀れな生物は実験の末、この姿になった", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Happy, calm yet in a state of excietment", "幸福。落ち着いているのに興奮している", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the hatefull, innocent mind for what she hides underneath", "憎悪。彼女がその下に隠しているのは無垢な心だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the helper, it just wants to help you out", "助け手。ただ君の役に立ちたいだけだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the judge, decider of the good and the bad", "審判者。善悪を決める者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the killer, made with intent", "殺し屋。目的を持って作られた", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the lady, no one knows what she truly looks like", "貴婦人。誰も彼女の本当の姿を知らない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The little red, hunting the wolf in a game of cat and mouse", "赤ずきん。いたちごっこのようにオオカミを狩っている", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mad, its given up on playing nice", "狂ったもの。いい子を演じるのはもうやめた", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Many, Containing all the fun of 5 in 1", "多くのもの。1つに5つ分の楽しさを詰め込んでいる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the masiyah, the prophet that speaks past death", "メシア。死を越えて語る預言者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The melting, master of the servants", "溶けるもの。従者たちの主人", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Moral, It Tries but fails to keep balance", "道徳。均衡を保とうとするが、うまくいかない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yin and Yang", "陰と陽", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the nameless, abondend and always hungering", "名もなきもの。見捨てられ、常に飢えている", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Neurtal, the only one i can deal with", "中立。私が唯一対処できる相手だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Neutral Look", "今日の穏やかな表情", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the old, no one is here to keep her company", "老いた者。彼女のそばにいる者はいない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the phoenix, its ashes keep it forever alive", "フェニックス。その灰が永遠の命を与える", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Plague, its only the beginning", "疫病。まだ始まりにすぎない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the poisoned, this apple keeps everyone away", "毒。このリンゴが皆を遠ざける", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the reindeer, dragging christmas fun all over the world", "トナカイ。クリスマスの楽しさを世界中に引きずっていく", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Sad, its destined to never see the light", "悲しみ。光を見ることのない運命だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Sad Look", "今日の悲しい表情", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the sniper, one shot is all it needs", "スナイパー。一発あれば十分だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the star, the center of both attention and fashion", "スター。注目と流行の中心だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the swan, its song sound similar to those of the band", "白鳥。その歌声はあのバンドに似ている", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The train, best not walk in its way", "列車。進路には立たない方がいい", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the tree, spreading its roots to help its allies", "木。根を広げて味方を助ける", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the true hatred, seems she let out what she had inside", "真の憎悪。彼女は内に秘めたものを放ったようだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the wolf, seems cute on first glance", "オオカミ。ぱっと見はかわいらしい", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the woodsman, sweeping the forest with its axe", "木こり。斧で森をなぎ払う", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Army, they never seem to end", "軍隊。終わりがないようだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've never seen this one here", "これはここで見たことがない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The CherryTree, Contains the bodies of thousands", "桜の木。何千もの遺体が中にある", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Fruit, its ripe for the picking.", "果実。熟して摘み取れる頃だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Galaxy, a blessing, and a curse.", "銀河。祝福であり、呪いでもある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The greedfull, carefull not to touch it.", "強欲。触れないように気をつけろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Hive, The true ruler of the hive", "巣。巣の真の支配者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Innocent, Ignorant in everything besides pain", "無垢。痛み以外の全てを知らない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mountain, it smiles upon you ", "山。君に微笑みかけている", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Nest, its presence is unsettling  ", "巣。その存在は不安をかき立てる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Nothing...", "何もない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Silent, Performing the best orchestra around.", "沈黙。最高の管弦楽を奏でる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Silent", "沈黙", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Swarm, he dresses for the occasion", "群れ。彼はこの日のために着飾った", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Trap, So Cute yet so deadly", "罠。とてもかわいいが、とても危険だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiphereth, the command meltdown", "ティファレト、指令のメルトダウン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Violet Dawn", "紫色の夜明け", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "violet dawn, radiating the field", "紫色の夜明け。場を照らし出す", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "violet Midnight", "紫色の真夜中", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "we tried to accept it,we wanted to understand them", "私たちはそれを受け入れようとした。彼らを理解したかった", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Violet noon", "紫色の正午", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "violet noon, enscrybing the words of their gods", "紫色の正午。彼らの神々の言葉を刻んでいる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that explains the chills", "寒気の理由がわかった", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the white night, the true end of the world", "白夜。世界の真の終わり", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yesod, the concealing meltdown", "イェソド、隠蔽のメルトダウン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Claw", "鋭い爪", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you can survive this white midnight.", "この白い真夜中を生き延びられるといいな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You definitely won't press the button, right?", "ボタンを押したりしないよな？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If it's not voluntary, does anyone really need to be 'fixed'?", "本人の意思でないなら、本当に「治す」必要があるのだろうか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No one wants to know what truly protects them.", "誰も自分たちを本当に守っているものを知りたくはない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is currently unclear why such a painting would exist.", "なぜこのような絵が存在するのか、今のところ不明だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gloomy Seahorse", "陰鬱なタツノオトシゴ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play the fatal movement.", "致命的な楽章を奏でよ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why does the mysterious ray appear within the facility?", "なぜ謎のエイが施設内に現れるのだろうか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stingray", "エイ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What sorrow.", "なんという悲しみだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intangible creation.", "形のない創造物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A scarecrow soaked in fresh blood.", "鮮血に浸ったカカシ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you yearn for blessings?", "祝福を望むか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps, she can protect no one.", "彼女には誰も守れないのかもしれない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mechanical creations, restoring peace and health", "機械の創造物。平和と健康を取り戻す", Language.Japanese);

        }
    }
    public class NevernamedsBestiaryMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Nevernameds_Bestiary Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ace Lord", "エースロード", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aderyn Y corph", "アデリン・イ・コルフ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The corpse bird. It's appearance portends the end.", "死体の鳥。その出現は終わりを告げる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adipocere", "死蝋", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor little corpse wax, it can be molded into any shape you can think of.", "哀れな小さな死蝋。思いつくどんな形にも成形できる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It lurks below the water, until the time is ripe to rend the land for prey.", "水の下に潜み、時が来ると大地を引き裂いて獲物を捕らえる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahuizotl", "アウィツォトル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Albatross", "アホウドリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The noble albatross. It's vast wingspan creates an impressive downdraft.", "高貴なアホウドリ。その広い翼は見事な下降気流を生み出す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Albatross Chick", "アホウドリのヒナ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The young of the immense albatross, it seems almost lost inside of it's own down.", "巨大なアホウドリの子。自分の羽毛に埋もれてしまいそうだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gar Roe", "ガーの卵", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxic gar roe, will kill anything that swallows it.", "有毒なガーの卵。これを飲み込むものは何でも死ぬ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alligator Gar", "アリゲーターガー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ferocious Alligator Gar. It squirts out it's toxic eggs when frightened.", "獰猛なアリゲーターガー。驚くと有毒な卵を噴き出す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amorphous Shame", "形なき羞恥", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...such a shame...", "……なんという恥だ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anaconda", "アナコンダ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't... don't say it. I have heard it all before, and it is not funny.", "言うな……言わないでくれ。もう何度も聞いたし、面白くもない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anansi", "アナンシ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anansi, the many legged trickster. He attacks multiple times per turn, in flagrant disregard for the rules.", "多脚のトリックスター、アナンシ。ルールなどお構いなしに、毎ターン何度も攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anchimayen", "アンチマジェン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anemone", "イソギンチャク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The soft, unassuming anemone- it seems to have remarkable potential for propagation, but no means as of yet...", "柔らかく目立たないイソギンチャク。驚くほど繁殖する可能性を秘めているようだが、今のところ手段はない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angel Shark", "カスザメ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Despite the name, it is far from divine.", "その名に反して、神聖さとは程遠い。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That irritating canine...", "あの厄介な犬……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anteater", "アリクイ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The slothly anteater only attacks with vigour when presented with a meal.", "怠け者のアリクイは、食事を目の前にしたときだけ勢いよく攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antingaw", "アンティンガウ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar mollusk. It gathers sustenance from burrowing into barren rock...", "奇妙な軟体動物。何もない岩に穴を掘り、栄養を得る……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So small... so fragile...", "なんと小さく……なんと脆い……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The larvae of the antlion. It's skill for trapping knows no match... in the insect world.", "アリジゴクの幼虫。罠を仕掛ける腕前は……昆虫の世界では右に出る者がいない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ararach", "アララク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The infinilegged crawler, the Ararach never settles on a definitive strategy of attack for long...", "無数の脚を持つ這うもの、アララク。決まった攻撃戦略に長く固執することはない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The archerfish is quick to retaliate to any confrontation with a precise jet of water.", "テッポウウオは衝突が起きると、正確な水流ですぐに反撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Areion", "アレイオーン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The eternally running Areion. It loyally moves wherever it's owner demands it in the blink of an eye.", "永遠に走り続けるアレイオーン。所有者の望む場所へ忠実に、瞬く間に移動する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Artful Magister", "技巧の大導師", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspidochelone", "アスピドケロン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That ruthless spiny turtle... it shares it's spines with it's comrades..", "あの無慈悲な棘だらけのカメ……仲間にも棘を分け与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Automamox", "オートモックス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Axehandle Hound", "斧柄の猟犬", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The peculiar axehandle hound. It uses it's sharp, bladed nose to cut clean through it's foes with the cold precision of a lumberjack...", "奇妙な斧柄の猟犬。鋭い刃のような鼻で、木こりのように冷静かつ正確に敵を切り裂く……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Axe Murderer", "斧の殺人鬼", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Through night he hunts, in blackened brush, the bite of an axe heralds a blood red stream.", "夜の闇と黒い茂みの中で彼は狩る。斧が食らいつけば血の流れが生まれる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Babai", "ババイ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baboon", "ヒヒ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Far more vicious than its name and appearance would betray- it needs only a reason to strike.", "名前や見た目から想像するよりはるかに凶暴だ。攻撃する理由さえあればいい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bakunawa", "月喰いの海蛇", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lengthy Bakunawa, terror of the sea and skies.", "長い月喰いの海蛇。海と空を恐怖に陥れる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Balaur", "バラウル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The three-headed Balaur dragon. It lashes out with each of it's maws when threatened.", "三つ首の竜、バラウル。脅かされると、それぞれの口で襲いかかる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bald Eagle", "ハクトウワシ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Truly the most patriotic of birds.", "間違いなく最も愛国的な鳥だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ball Droid", "ボールドロイド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Balloondroid", "バルーンドロイド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bandito", "バンディート", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar deathcard- no matter how many times I tear it to pieces, I always find it back in my deck...", "奇妙なデスカード。何度引き裂いても、いつの間にかデッキに戻っている……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bannana", "バナナ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a small, sweet spider... It couldn't hurt a fl- ...oh", "こんなに小さくかわいいクモ……ハエ一匹傷つけられな……あっ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Barnacle", "フジツボ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unimpressive barnacle. Anything that strikes it will be torn to shreds on it's rough shell.", "ぱっとしないフジツボ。攻撃したものは、そのざらついた殻でずたずたにされる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Basilisk", "バジリスク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The grim basilisk. Life withers and dies under it's mere gaze.", "陰気なバジリスク。ただ見つめるだけで命は枯れ、死に至る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Bat", "燃えるコウモリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The first... and last time one of my... associates attempted to use living organisms to it's own advantage.", "私の……仲間の一人が生きた生物を利用しようとした、最初で最後の出来事だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Batfly", "バットフライ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The perturbing batfly. It clings to airborne creatures for a free ride.", "不気味なバットフライ。飛ぶ生物にしがみつき、ただ乗りする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bat Tery", "バッテリーコウモリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beached Whale", "打ち上げられたクジラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The poor thing, completely out of it's element... it bursts upon death.", "哀れなやつだ。完全に場違いだな……死ぬと破裂する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beast Of Exmoor", "エクスムーアの獣", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The illusory exmoor cat... hard to catch, harder to kill.", "幻のエクスムーアの猫……捕まえにくく、殺すのはさらに難しい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Belladin", "ベルパラディン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bellbird", "スズドリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Their cry is melodic, like the ringing of a great chime.", "その鳴き声は大きな鐘の音のように美しい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bellbot", "ベルボット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bhoot", "ブート", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How she floats above the holy earth... I wonder what form she will take next!", "聖なる大地の上に浮かぶ彼女を見よ……次はどんな姿になるのだろう！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bind Warden", "束縛の看守", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Biscione", "冠喰いの蛇", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vicious biscione, it is insatiable in it's lust for flesh.", "凶暴な冠喰いの蛇。肉への欲望は満たされることがない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bishop", "ビショップ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bison", "バイソン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trampling Bison. It destroys anything in it's path, and becomes more enraged as it becomes more soaked with blood...", "踏み荒らすバイソン。進路上のものを全て破壊し、血を浴びるほど怒りを増す……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Dog", "黒い犬", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The grim black dog, haunter of graveyards... omen incarnate.", "陰気な黒い犬。墓地に出没する……不吉な予兆の化身だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Egg", "黒い卵", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something pulses dimly, below the surface...", "表面の下で、何かがかすかに脈打っている……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Giant Squirrel", "黒い巨大リス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The shadowy Black Giant Squirrel. It hits hard and is easily deployed, but perishes with no brothers or sisters by it's side...", "影のような黒い巨大リス。強く攻撃し簡単に出せるが、兄弟姉妹がそばにいないと死んでしまう……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Kite", "トビ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It carries the flames of a previous inferno to drive prey from cover...", "以前の大火の炎を運び、獲物を隠れ場所から追い出す……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Widow", "クロゴケグモ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The black widow spider. It's infamous bite kills swiftly.", "クロゴケグモ。悪名高いその噛みつきは、素早く命を奪う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blank Obelisk", "無地のオベリスク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A blank obelisk. Unremarkable.", "無地のオベリスク。特筆すべきところはない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blast Termite", "爆発シロアリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disgusting blasting termite. It explodes it's foes upon death.", "不快な爆発シロアリ。死ぬと敵を爆発させる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blind Mouse", "盲目のネズミ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those blind mice... always travelling in a group. See how they run...", "あの盲目のネズミたち……いつも群れで旅をする。走る姿を見てみろ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blind Scorpion", "盲目のサソリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The poor blinded scorpion. It's venom is immaculate, but it's aim?... less so.", "哀れな盲目のサソリ。毒は申し分ないが、狙いは……そうでもない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloated Leech", "膨れたヒル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disquieting leech. It has reached full maturity.", "不安をかき立てるヒル。すっかり成長している。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blockhead", "ブロックヘッド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A comically frontheavy insect.", "前が重くておかしな姿の昆虫。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodbag", "血液袋", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Cell", "血球", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Knight", "血の騎士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Red Dog", "赤き血の猟犬", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The infamous blood red dog, nothing can stop it's lust for combat. We'll have tea in hell today...", "悪名高き赤き血の猟犬。戦いへの欲望は誰にも止められない。今日は地獄でお茶を飲もう……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodstopper", "止血者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Witch", "血の魔女", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bloodstarved beast. It will wither and die if it does not taste violence each turn.", "血に飢えた獣。毎ターン暴力を味わえなければ、衰えて死んでしまう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloody Sack", "血まみれの麻袋", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blowfly", "クロバエ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disgusting.", "気持ち悪い。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bluebottle", "クロバエ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bluebottle... what secrets lie beyond it's squishy facade?", "クロバエ……その柔らかな外見の向こうには、どんな秘密があるのか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue-Ringed", "ヒョウモンダコ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Blue-Ringed Octopus. It's venom is one of the most potent in the world...", "ヒョウモンダコ。その毒は世界でも最も強力なものの一つだ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Whale", "シロナガスクジラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The greatest mortal beast ever to roam the seas... but not the greatest immortal one.", "海を泳いだ生き物の中で最も大きな、死すべき獣……だが、不死の獣の中では最大ではない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BoardWipe", "盤面一掃", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bobbit Worm", "ボビットワーム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The terrifying bobbit worm. It leaps from it's aquatic burrow to attack with it's razor sharp jaws.", "恐ろしいボビットワーム。水中の巣穴から飛び出し、かみそりのように鋭い顎で攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bobcat", "ボブキャット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Often underestimated, the Bobcat will strike the moment it is played.", "過小評価されがちなボブキャット。場に出されるとすぐに攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Body Snatcher", "ボディスナッチャー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boil", "おでき", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A festering little blotch.", "化膿した小さな斑点。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bolotnik", "ボロトニク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bloated swampman. It drags others down to hades- returning for more.", "膨れ上がった沼の者。他者を冥府に引きずり込み、さらに獲物を求めて戻ってくる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bombardier Beetle", "ミイデラゴミムシ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The incandescant bombardier beetle. It's boiling hot secretions scald it's prey.", "白熱するミイデラゴミムシ。煮え立つ分泌物で獲物を焼く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Cell", "骨細胞", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Clutter", "骨のがらくた", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneworm", "ボーンワーム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The morbid boneworm. It excells in bringing remains to the surface of the churning soil...", "不気味なボーンワーム。かき回された土の表面に遺骸を運び出すのが得意だ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Booting Bot", "起動ボット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bot Printer", "ボットプリンター", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bowerbird", "ニワシドリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The crafty bowerbird, master of manipulating materials around itself.", "ずる賢いニワシドリ。周囲の材料を操る達人だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Box Jelly", "ハコクラゲ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Small, but possessing of a crippling set of stingers.", "小さいが、相手を麻痺させる刺を持つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Proceed", "進む", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brazen Bull", "青銅の雄牛", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The horrific brazen bull. A true metric of human depravity.", "恐ろしい青銅の雄牛。人間の堕落を測る真の尺度だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's go!", "行こう！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play me properly", "私をちゃんと使え", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAAH, YES!", "ハハハハハ、そうだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES, YES!", "そうだ、そうだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S MAKE A RING", "さあ作ろう", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OF FIRE", "炎の輪を", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAH", "ハハハハハ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BURN", "燃焼", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I want to", "私は見たい", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "see the fire", "炎を", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "for glory!", "栄光のために！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yes, very well", "そうだ、とてもいい", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's get to work", "仕事を始めよう", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHA", "ハハハハハ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAHAHAH", "ハハハハハハハ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TO GLORY", "栄光へ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAHAH", "ハハハハハハ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAH, YES!", "ハハハ、そうだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IMPROVE ME", "私を強化しろ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can be", "私はなれる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So much more!", "もっとすごい存在に！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you want.", "君が望むなら。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SACRIFICE ME!", "私を生贄にしろ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES", "そうだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WILL DIE", "私は死のう", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FOR YOU", "君のために", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's up to you", "君次第だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harder!", "もっと強く！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO IT!", "やれ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAHA!", "ハハハハハハ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES! MORE!", "そうだ！ もっとだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Very good.", "とてもいい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THANK YOU, THANK YOU!", "ありがとう、ありがとう！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VICTORY?", "勝利か？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TO GLORY!", "栄光のために！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES, YES", "そうだ、そうだ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brine Shrimp", "ブラインシュリンプ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The tiny, fleeting brine shrimp, so small it's as if it's not even there...", "小さく束の間のブラインシュリンプ。あまりに小さく、まるで存在しないかのようだ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brollachan", "ブロラハン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wicked Brollachan. It can take many powerful forms...", "邪悪なブロラハン。さまざまな強い姿を取ることができる……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brown Recluse", "ドクイトグモ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unassuming Brown Recluse. It attacks when threatened.", "目立たないドクイトグモ。脅かされると攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Budgerigar", "セキセイインコ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A friendly bird of domesticated breed, the Budgerigar will follow your command...", "人懐こい飼育された鳥のセキセイインコ。君の命令に従う……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bugbear", "クマムシ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The horrifying Bugbear. No creatures wish to remain in it's presence.", "恐ろしいクマムシ。そばにいたがる生物はいない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Busted Bot", "廃棄寸前のボット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Busted Conduit", "廃棄寸前のコンジット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buzzard", "ノスリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The shameless buzzard- an inescapable symbol of death in the sands.", "恥知らずなノスリ。砂漠で避けては通れない死の象徴だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiny Ant", "棘アリ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A friendly ant covered in sharp thorns.", "鋭い棘に覆われた、人懐こいアリ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The splifficated Cactus Cat, it roams the desert drinking the fermented juice of it's lookalike plant...", "酔っ払ったサボテンネコ。砂漠を歩き回り、自分に似た植物の発酵した汁を飲む……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caged Beasts", "檻の中の獣", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor, caged animals. Won't you set them free?", "檻の中の哀れな動物たち。自由にしてやらないか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calygreyhound", "カリグレイハウンド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The calygreyhound- a confusing chimeric clash which nonetheless stirs the loyalties of it's comrades.", "カリグレイハウンド。混乱するほど入り混じった姿だが、仲間の忠誠心を呼び起こす。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camazotz", "カマソッソ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camazotz, the bat god. He flies low amongst his enemies, slashing them with his bloodstained claws.", "コウモリの神、カマソッソ。敵の間を低く飛び、血に染まった爪で切り裂く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cam Drone", "カメラドローン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stocky camel, it is resilient against most any threat", "がっしりしたラクダ。ほぼあらゆる脅威に耐える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camel Spider", "ヒヨケムシ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Camel Spider... an unpleasant arachnid to even gaze upon.", "ヒヨケムシ……見るだけで不快になるクモ形類。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candiru", "カンディル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bloodsucking fish with a terrifying reputation.", "恐ろしい評判を持つ吸血魚。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Canopic Hawk", "カノプスのタカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A delicate ceramic bird, full of guts...", "内臓がいっぱいの繊細な陶器の鳥……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The much-beloved Capybara... it's fighting spirit is closely tied to it's wellbeing.", "皆に愛されるカピバラ……その闘志は健康状態と密接に結びついている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caracal", "カラカル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A quizzacious predator, ready to leap at any unsuspecting prey.", "好奇心の強い捕食者。無防備な獲物にはいつでも飛びかかる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carrion Fly", "腐肉バエ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disgusting carrion fly. Drawn to death.", "不快な腐肉バエ。死に引き寄せられる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catalogue Keeper", "目録管理者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catron", "カトロン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cattle Rustler", "牛泥棒", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cellar Spider", "ユウレイグモ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Cellar spider. An exemplar of all arachnida.", "ユウレイグモ。クモ形類の模範だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chameleon", "カメレオン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A chameleon always changes it's spots, as is the proverb.", "諺にもある通り、カメレオンはいつも模様を変える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enraged Fey", "怒れる妖精", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The development of the changeling is entirely dependant on it's early childhood... violence begets violence.", "取り替え子の成長は幼少期に完全に左右される……暴力は暴力を生む。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pitiful Fey", "哀れな妖精", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Changeling", "取り替え子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Card", "混沌のカード", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Engine", "混沌のエンジン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charred Lump", "焦げた塊", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charybdis", "カリュブディス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charybdis, the infernal vortex. Sucks all around it into it's collossal maw.", "地獄の渦、カリュブディス。周りの全てを巨大な口へ吸い込む。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A vindictive, nasty little bird.", "執念深く意地悪な小鳥。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chicken Bones", "ニワトリの骨", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awfully sharp... and awfully disposable.", "恐ろしく鋭い……しかも使い捨てだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chimpanzee", "チンパンジー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The true utility of the chimp lies in it's dilligent hands...", "チンパンジーの真の価値は、その働き者の手にある……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chiral Crawler", "キラルクローラー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can a creature that drags its shackles along with it ever truly be free?", "枷を引きずる生物は、本当に自由になれるのだろうか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chochin", "提灯お化け", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aha! The little lantern spook, such a mischevious little spirit it is!", "ああ！ 小さな提灯のお化け。なんといたずら好きな霊体だ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chuman", "チューマン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unholy union.", "冒涜的な結合。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This beast of the night will tear apart any small prey he finds...", "夜の獣は見つけた小さな獲物を何でも引き裂く……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clanklion", "クランクライオン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clumsy Pupil", "不器用な弟子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cobra", "コブラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The swift cobra. Usually passive, but it delivers a nasty bite when startled.", "敏捷なコブラ。普段はおとなしいが、驚かせるとひどく噛みつく。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cockle", "ザルガイ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unremarkable cockle, it feeds upon the remnants of the dead...", "目立たないザルガイ。死者の残骸を食べる……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Code Thief", "コード泥棒", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coinchenn", "コインヘン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It lurks in the shadows of history, and shows no mercy to its prey.", "歴史の陰に潜み、獲物には容赦しない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Colossal Squid", "ダイオウホウズキイカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The colossal squid. It drags it's foes down to a watery grave.", "ダイオウホウズキイカ。敵を水底の墓場へと引きずり込む。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tubular Bells", "チューブラーベル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cone Snail", "イモガイ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The venomous cone snail. Beware it's paralysing toxin.", "毒を持つイモガイ。麻痺毒に気をつけろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conjurer", "召喚術師", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Copepod", "カイアシ類", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unassuming copepod, resilient to the last.", "目立たないカイアシ類。最後までしぶとい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mysterious copycat. When it perishes, it... warps, to mimic it's murderer.", "謎めいた模倣者。死ぬと……変形し、自分を殺した者を真似る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coral", "サンゴ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A stoic coral colony, akin more to the landscape around it than to any other beast...", "忍耐強いサンゴの群体。他の獣より、周囲の風景に似ている……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Counstabot", "警官ボット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cow", "牛", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Centuries of domestication have not made it any less stubborn...", "何世紀も家畜化されてきたが、頑固さは変わらない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cowardly lion. It attempts to live up to the ferocity of it's cousins, but with little success.", "臆病なライオン。仲間の獰猛さに追いつこうとするが、なかなかうまくいかない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly Lion", "臆病なライオン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowbird", "コウウチョウ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Too cowardly to remain for long, the cowbird is always eager to cause trouble.", "コウウチョウは臆病で長居できないが、いつも騒ぎを起こしたがる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time for crab.", "カニの時間だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crab Spider", "カニグモ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hardy crab spider, it clings relentlessly to any source of food or warmth.", "頑丈なカニグモ。食べ物や熱源なら何でもしつこくしがみつく。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crayfish", "ザリガニ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unrelenting crayfish. It changes the orientation of it's claws each turn.", "容赦ないザリガニ。毎ターン、ハサミの向きを変える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cremator", "焼却者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Paladin", "深紅の聖騎士", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crooked Mouse", "曲がったネズミ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It was never the same after a run in with a crooked cat...", "曲がったネコに遭って以来、すっかり変わってしまった……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crooked Wraith", "歪んだ陰の霊", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange one, this. Even I don't know its twisted past.", "奇妙なやつだ。その歪んだ過去は私にもわからない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crucibulum", "チャダイゴケ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar little snail, forever growing it's conical shell.", "奇妙な小さなカタツムリ。円錐形の殻は永遠に成長し続ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Healer", "水晶の癒し手", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cubit", "キュービット", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curly-Legged Cat", "巻き足のネコ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its twisted legs coil and bend in ways inexplicable. It is full of potential.", "歪んだ脚は不可解な形に巻き曲がっている。大きな可能性を秘めている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curruid", "クルード", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clawed lord of the waves, the Curruid has but one blind spot.", "爪を持つ波の領主、クルード。弱点はたった一つだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Child", "呪われた子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That... should not be in my deck...", "それは……私のデッキにあるはずがない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Stunted... Wolf... I thought I threw him- ...I mean, this, away...", "あの……成長不良のオオカミ……彼を捨てたと……いや、これを捨てたと思っていた……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The... stoat. Did I leave this here?", "あの……オコジョ。ここに置いていっただろうか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The... pungent... stinkbug?..", "あの……臭い……カメムシ？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cyclops", "サイクロプス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The diminutive cyclops. It's great eye holds a perfect image of the past.", "小さなサイクロプス。その大きな目には過去の完全な像が宿っている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aim well.", "よく狙え。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoot with caution.", "慎重に撃て。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aim me well.", "私を使ってよく狙え。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acceptable draw.", "悪くないドローだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Survive.", "生き延びろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am your instrument.", "私は君の道具だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will succeed.", "私は成功する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you are", "君が", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "certain.", "確信しているなら。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I trust", "私は信じる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bigger", "大きな", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "picture.", "構図を。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Over exposed.", "露出しすぎだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This turn?", "このターンか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temporal Misplay.", "タイミングの悪手だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember this.", "これを覚えておけ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Certainly.", "もちろんだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have", "君は", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "aimed... well.", "うまく……狙った。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Within acceptable", "許容できる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "parameters.", "範囲内だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Betrayal.", "裏切り。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Judas.", "ユダ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once more?", "もう一度か？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How many times...", "何度目だ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acceptable.", "許容できる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Modification.", "改造。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is desirable.", "望ましい結果だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Picturesque.", "絵になる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regards.", "敬意を。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undesirable.", "望ましくない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cease.", "やめろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is unfriendly.", "友好的ではない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cease considerations.", "検討をやめろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Halt.", "止まれ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have been...", "私は……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...dealt a blow", "……一撃を受けた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...a blow", "……一撃を", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suffered.", "受けた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Assessing damages.", "損傷を評価中。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dealt a blow...", "一撃を受けた……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So... familiar...", "とても……見覚えがある……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is unfortunate", "残念だが、", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "that we must", "私たちは", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "trade blows...", "戦わねばならない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel... kinship.", "親近感を……感じる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am improved.", "私は強化された。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Improvement", "強化", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Edit in progress.", "編集中。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A new instrument.", "新しい道具だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Under analysis", "分析中", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "statistically viable", "統計上、実行可能", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A lineup?", "布陣か？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Darter", "ヘビウ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mind the splash.", "水しぶきに注意。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "\"When the Lamb broke the fourth seal, I heard the voice of the fourth living creature saying, \"Come.\" I looked, and behold, an ashen horse; and he who sat on it had the name Death; and Hades was following with him.\"", "「子羊が第四の封印を解いたとき、私は第四の生き物が『来なさい』と言う声を聞いた。見ると、青ざめた馬がいた。その乗り手の名は死であり、陰府が後に続いた。」", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death", "死", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deaths Door", "死の扉", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't worry, we'll pull you through.", "心配するな。私たちが助けてやる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deathstalker", "デスストーカー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The deathstalker scorpion. It's tail packs a potent venom.", "デスストーカー。その尾には強力な毒がある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "De Bug", "デバッグ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What... is that?", "あれは……何だ？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Decorator Crab", "モクズショイ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lowly decorator crab. It scrounges the bottom of the ocean for detritus to stick to it's body.", "地味なモクズショイ。海底でくずを集め、体にくっつける。", Language.Japanese);


        }
    }
    public class NeedMoreWaterMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for NeedMoreWater Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack:NMW", "カードパック：NMW", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cardumen", "魚の群れ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cuando una carta que lleve este sello mate a otra criatura en combate, se crea una copia de esa carta en tu mano.", "この印を持つカードが戦闘中に別の生物を倒すと、印を持つカード自身のコピーが手札に1枚作られる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rape", "アンコウ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Engañoso y altamente peligroso ese Rape.", "あのアンコウは狡猾で非常に危険だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "La sangre derramada las atrae...", "流れた血が彼らを引き寄せる……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Arquero", "テッポウウオ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Su disparo de agua derriba a los insectos para comérselos.", "水を飛ばして昆虫を撃ち落とし、食べる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Beta", "ベタ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El Pez Beta. Una belleza viva de las aguas.", "ベタ。水の中の生きた美しさだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Gato", "ナマズ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El Pez Gato. Nunca te faltarán cebos.", "ナマズ。釣り餌に困ることはない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cocodrilo", "ワニ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cocodrilo, gran cazador. Ningún nadador escapa de sus fauces.", "ワニは優れた狩人だ。その大口から逃れられる泳ぎ手はいない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morena", "ウツボ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acecha entre las grietas, esperando a que algo nade demasiado cerca.", "隙間に潜み、何かが近づきすぎるのを待つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez León", "ミノカサゴ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Su veneno no es letal, pero sacará a la vista tus puntos débiles.", "その毒は致命的ではないが、君の弱点をあらわにする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Piraña", "ピラニア", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pirañas, nunca hay una sola en el agua.", "ピラニアは水中に一匹だけでいることはない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Globo", "フグ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Su combinación de veneno y espinas es letal para cualquier ser vivo.", "毒と棘の組み合わせは、あらゆる生き物にとって致命的だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Remo", "リュウグウノツカイ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Una de las bestias mas raras que he fotografiado jamás.", "私が撮影した中でも最も珍しい獣の一つだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhyzostoma", "根口クラゲ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nada sobrevive a la Rhyzostoma, ni dentro ni fuera del agua.", "水の中でも外でも、根口クラゲから逃れて生き残るものはいない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Salmón", "サーモン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El salmón, pez difícil de pescar.", "サーモン。捕まえるのが難しい魚だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Esturión", "チョウザメ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El inundible esturión, acorazado marino.", "沈むことのないチョウザメ。海の装甲艦だ。", Language.Japanese);



        }
    }
    public class SauriaSigilsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SauriaSigils Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avenging", "復讐", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever an adjacent card perishes during combat, a card bearing this sigil gains 1 Power.", "隣接するカードが戦闘中に死ぬと、この印を持つカードは攻撃力を1得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avenging Strike", "復讐の一撃", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The loss of its friend will not go unpunished.", "友の死を罰せずにはおかない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever a friendly card is killed during combat by an opponent's card, a card bearing this sigil moves to that space and strikes the attacker.", "味方のカードが戦闘中に相手のカードに倒されると、この印を持つカードはその場所に移動し、攻撃者を攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To avenge the fallen...", "倒れた者の仇を討つために……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleeding", "出血", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil loses 1 Health at the end of their owner's turn.", "この印を持つカードは所有者のターン終了時に体力を1失う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How much longer can it endure?", "あとどれくらい耐えられるだろうか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blessing", "祝福", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Bones to increase Health of this and adjacent creatures by 1 if they have less than 10.", "骨を4個支払うと、この生物と隣接する生物のうち体力が10未満のものの体力を1増やす。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beasts feel better now.", "君の獣たちは元気を取り戻した。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blizzard", "吹雪", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, unoccupied spaces on its owner's side are filled with blocks of ice.", "この印を持つカードが配置されると、所有者側の空いている場所が氷の塊で埋まる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winter is coming.", "冬が来る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bone to gnaw on.", "かじるための骨。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Blast", "骨の爆発", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When initiating combat, a card bearing this sigil dies. Upon death, all other cards take damage equal to the amount of owner's bones.", "戦闘開始時、この印を持つカードは死ぬ。死亡時、他の全カードは所有者の骨の数に等しいダメージを受ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not a pretty sight", "見苦しい光景", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Gift", "骨の贈り物", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, a Bone is created in your hand. [define:Sauria_Bone]", "この印を持つカードが配置されると、手札に骨が1枚作られる。[define:Sauria_Bone]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A gift for its master.", "主人への贈り物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Offering", "骨の供物", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card on the opponent's side of board that costs Bones or Blood. Pay its price in Bones to add it to your hand. Blood is counted as 3 Bones, cannot choose cards that cost neither resource.", "相手側の盤上にある骨か血をコストとするカードを選ぶ。そのコストを骨で支払い、手札に加える。血1は骨3として数え、どちらもコストとしないカードは選べない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've managed to entice one of my beasts.", "私の獣を一頭、うまく誘い出したようだな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cannibalistic", "同族喰らい", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When another card on the owner's side of board takes damage and its Health no longer exceeds Power of the bearer of this sigil, this card attacks it.", "盤上の所有者側にある別のカードがダメージを受け、その体力がこの印の持ち主の攻撃力以下になると、このカードはそれを攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A grim opportunity to feast.", "食らうための残酷な好機。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caretaker", "世話人", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, all other cards on the owner's side of board heal 1 Health while a card bearing this sigil is alive.", "この印を持つカードが生きている間、ターン終了時に盤上の所有者側の他の全カードが体力を1回復する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It tends to their wounds.", "彼らの傷を手当てする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catapult", "カタパルト", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to select another card on your side of the board to move to another space, including opponent's side of the board.", "骨を1個支払い、自分側の盤上の別のカードを選んで別の場所へ移動させる。相手側の盤上も選べる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch out for falling beasts.", "落ちてくる獣に注意。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Change Form", "形態変化", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil transform into an alternate form.", "この印を持つカードは別の形態に変身する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch it shift its form.", "姿を変える様子を見よ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Shifter", "骨の変身者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Bones to transform this card into an alternate form.", "骨を3個支払い、このカードを別の形態に変身させる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Concerned", "心配性", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a friendly card takes damage, a card bearing this sigil attempts to move to its closest adjacent space. If that space is occupied, it attempts to move one space in that direction instead.", "味方のカードがダメージを受けると、この印を持つカードはそのカードに最も近い隣接スペースへ移動しようとする。そこが埋まっていれば、代わりにその方向へ1マス移動しようとする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It responds to its ally's distress.", "仲間の危機に応える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cruelty", "残虐", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card through any other means, it deals 1 damage to its target.", "この印を持つカードが他の手段で別のカードにダメージを与えると、対象に1ダメージを与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This beasts wishes to inflict more grievous injuries.", "この獣はさらに深い傷を負わせたがっている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deep Freeze", "深い凍結", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil perishes within 2 turns, the creature within is released.", "この印を持つカードが2ターン以内に死ぬと、中の生物が解放される。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Free at last.", "ついに自由だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Desperate Push", "必死の押し返し", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil perishes during combat while opposing space is occupied, it pushes the opposing cards back.", "この印を持つカードが戦闘中に死に、正面のスペースが埋まっていると、正面のカードを後ろへ押し戻す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps its sacrifice will pay off.", "その犠牲は報われるかもしれない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dismember", "切断", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card, gain bones equal to the damage dealt, up to 5 bones at once.", "この印を持つカードが別のカードにダメージを与えると、与えたダメージと同じ数の骨を得る。一度に得られるのは最大5個。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How gruesome.", "なんとむごい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Embolden", "鼓舞", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are adjacent cards with less Power than the bearer of this sigil, lose 1 Power and give 1 Power to them.", "所有者のターン終了時、この印の持ち主より攻撃力の低い隣接カードがあれば、持ち主は攻撃力を1失い、それらのカードに攻撃力を1ずつ与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its strength with its allies.", "仲間と力を分かち合う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enduring", "忍耐", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 2 Health at the start of its third turn on the board.", "この印を持つカードは盤上での3ターン目の開始時に体力を2得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prolonged combat is fortifying this beast.", "長引く戦闘がこの獣を強くする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic March", "気まぐれな行進", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will move in the direction inscribed on the sigil at the end of its owner's turn. If there are cards in its way or this card is at edge of the board, it will try to move to the opponent's side of board first.", "この印を持つカードは所有者のターン終了時に印の方向へ移動する。進路にカードがあるか盤の端にいる場合、まず相手側の盤へ移動しようとする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its movements are unpredictable.", "その動きは予測できない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fervor", "熱意", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 Power at the start of its third turn on the board.", "この印を持つカードは盤上での3ターン目の開始時に攻撃力を1得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prolonged combat is making this beast grow more ferocious.", "長引く戦闘がこの獣をより獰猛にする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Genetic Flaw", "先天的欠陥", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil loses 1 Health at the end of their owner's turn.", "この印を持つカードは所有者のターン終了時に体力を1失う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps it's not meant to live.", "生きるべきではないのかもしれない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Genetic Perfection", "遺伝的完璧", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If card bearing this sigil has its stats reduced below their normal values, it gains 1 Power and/or Health at the end of its owner's turn. If this card has Genetic Flaw sigil, remove it.", "この印を持つカードの能力値が通常値を下回ると、所有者のターン終了時に攻撃力と体力の一方または両方を1得る。このカードが先天的欠陥の印を持つ場合、それを取り除く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is perfection incarnate.", "完璧の化身だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Catapult", "大型カタパルト", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Bones to select another card on your side of the board to move to another space, including opponent's side of the board. If there is an obstruction with a free opposing space, it takes damage equal to this card's Attack first. If obstruction remains, selected card attempts to move to its opposing space instead.", "骨を3個支払い、自分側の盤上の別のカードを選んで別の場所へ移動させる。相手側も選べる。障害物があり、その正面が空いている場合、まずこのカードの攻撃力に等しいダメージを障害物に与える。障害物が残った場合、選んだカードは代わりにその正面へ移動しようとする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good aim.", "いい狙いだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Embolden", "大いなる鼓舞", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are any cards on owner's side of the board with less Power than the bearer of this sigil, lose 1 Power and give 1 Power to them.", "所有者のターン終了時、盤上の所有者側にこの印の持ち主より攻撃力の低いカードがあれば、持ち主は攻撃力を1失い、それらのカードに攻撃力を1ずつ与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its strength with all of its allies.", "全ての仲間と力を分かち合う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Grudge Bearer", "深い怨みを背負う者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever cards belonging to the owner of the card bearing this sigil are struck, the attacker is marked. At the start of the owner's turn, this card attacks all marked cards owned by the opponent.", "この印を持つカードの所有者のカードが攻撃されるたび、攻撃者が印をつけられる。所有者のターン開始時、このカードは相手の印をつけられた全カードを攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death is the only suitable punishment.", "死こそが唯一ふさわしい罰だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Nurture", "大いなる育み", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are any cards on owner's side of the board with less Health than the bearer of this sigil, lose 1 Health and give 1 Health to them.", "所有者のターン終了時、盤上の所有者側にこの印の持ち主より体力の低いカードがあれば、持ち主は体力を1失い、それらのカードに体力を1ずつ与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its essence with all of its allies.", "全ての仲間と自らの本質を分かち合う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grievous Display", "凄惨な見せつけ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil attacks an opposing creature and it perishes, creatures to the left and right of the target lose 1 Power.", "この印を持つカードが正面の生物を攻撃して倒すと、対象の左右にいる生物は攻撃力を1失う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not easy on the eyes.", "目に優しくない光景だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ground Pound", "地面叩き", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, cards in opposing and adjacent spaces take 1 damage. This effect is additionally activated when moving 2 spaces away from last position or the opponent's side of board.", "この印を持つカードが配置されると、同じ側の左右に隣接するカードと正面のカードは1ダメージを受ける。相手側へ移動したとき、または同じ側で2マス以上移動したときにも発動する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A less than graceful landing.", "優雅とは言えない着地だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ground Smash", "地面砕き", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, it deals damage to cards in opposing and adjacent spaces equal to its Attack or at least 1 damage. This effect is additionally activated when moving 2 spaces away from last position or the opponent's side of board.", "この印を持つカードが配置されると、同じ側の左右に隣接するカードと正面のカードに、このカードの攻撃力に等しいダメージを与える。最低1ダメージ。相手側へ移動したとき、または同じ側で2マス以上移動したときにも発動する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a nasty shockwave.", "なんと強烈な衝撃波だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grudge Bearer", "怨みを背負う者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, the attacker is marked. At the start of the owner's turn, this card attacks a random marked card owned by the opponent.", "この印を持つカードが攻撃されると、攻撃者が印をつけられる。所有者のターン開始時、このカードは相手の印をつけられたカードをランダムに1枚攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It will remember this.", "このことは忘れない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grudge-Powered", "怨みの力", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of opponent's creatures marked by Grudge Bearer sigils and the number of said creatures killed by the bearer of this sigil.", "この印が示す値は、怨みを背負う者の印で印をつけられた相手の生物の数と、この印の持ち主が倒したそれらの生物の数の合計に等しい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of opponent's creatures marked by Grudge Bearer sigils and the number of said creatures killed by [creature].", "[creature]の攻撃力は、怨みを背負う者の印で印をつけられた相手の生物の数と、[creature]が倒したそれらの生物の数の合計に等しい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grudge Target", "怨みの標的", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will be attacked by opponent's cards bearing Grudge Bearer sigils.", "この印を持つカードは、怨みを背負う者の印を持つ相手のカードに攻撃される。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A permanent stain.", "消えることのない汚れ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hasty Escape", "急ぎの逃走", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon taking damage, the bearer of this sigil returns to owner's hand if it's still alive.", "この印の持ち主がダメージを受け、生き残った場合、所有者の手札に戻る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sometimes, cowards do survive.", "臆病者も生き延びることがある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigger Block of Ice", "より大きな氷の塊", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A block of ice, nothing to see", "氷の塊だ。見るべきものはない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its meal with its newfound family.", "新しい家族と食事を分かち合う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knock Back", "押し戻し", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card, it attempts to move its target to an adjacent space, prioritizing right.", "この印を持つカードが別のカードにダメージを与えると、対象を隣のスペースへ移動させようとする。右を優先する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A nasty blow.", "強烈な一撃。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juicy Meat", "ジューシーな肉", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meat", "肉", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Makes you salivate.", "よだれが出る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Memento", "形見", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil perishes during combat, adjacent cards gain 1 Power.", "この印を持つカードが戦闘中に死ぬと、隣接するカードは攻撃力を1得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its friends will not forgive those fiends.", "仲間はあの悪党を許さない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete and total extermination is the only reasonable response.", "完全かつ徹底的な殲滅こそ、唯一の合理的な対応だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Micro", "マイクロ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Movement Command", "移動命令", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, move the bearer of this sigil to a selected empty space.", "1ターンに1回、この印の持ち主を選んだ空きマスへ移動させる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The beast follows your command.", "獣は君の命令に従う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nurture", "育み", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are adjacent cards with less Health than the bearer of this sigil, lose 1 Health and give 1 Health to them.", "所有者のターン終了時、この印の持ち主より体力の低い隣接カードがあれば、持ち主は体力を1失い、それらのカードに体力を1ずつ与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its essence with its allies.", "仲間と自らの本質を分かち合う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Outburst", "爆発", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, a card bearing this sigil performs an additional attack against opposing space if it's occupied by a card whose Attack is above 0.", "所有者のターン終了時、正面のスペースに攻撃力が0より高いカードがあれば、この印を持つカードはそこを追加で攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It won't be moving for long at this rate.", "この調子では、長くは動けまい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasitoid Propagation", "寄生繁殖", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, a copy of this card is created in your hand.", "この印を持つカードが別の生物を倒すと、このカードのコピーが手札に1枚作られる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life can be unsightly at times.", "生命は時に醜い。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parental Care", "親の世話", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, creatures with Fledgling sigil adjacent to a card bearing this sigil gain 1 Health.", "所有者のターン終了時、この印を持つカードに隣接する雛の印を持つ生物は体力を1得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good parent.", "いい親だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parting Bone", "別れの骨", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil dies or is sacrificed, a Bone is created in your hand. [define:Sauria_Bone]", "この印を持つカードが死ぬか生贄になると、手札に骨が1枚作られる。[define:Sauria_Bone]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A parting gift for its master.", "主人への別れの贈り物。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Persistent", "存続", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil would die during combat for the first time, it revives and gains 2 Power.", "この印を持つカードが戦闘中に初めて死にそうになると、復活して攻撃力を2得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That creature will not give up so easily.", "あの生物はそう簡単には諦めない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protective", "守護", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an adjacent card is struck, a card bearing this sigil strikes the attacker.", "隣接するカードが攻撃されると、この印を持つカードは攻撃者を攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It doesn't appreciate having its comrades hurt.", "仲間が傷つけられるのを嫌う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protective Parent", "子を守る親", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When owner's cards with Fledgling sigil are struck, bearer of this sigil strikes the attacker.", "所有者の雛の印を持つカードが攻撃されると、この印の持ち主は攻撃者を攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Few things inspire more awe and fear than a protective parent.", "子を守る親ほど、畏敬と恐怖を呼び起こすものは少ない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pursuer", "追跡者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever an opponent's card moves to another space, a card bearing this sigil attempts to move to its current opposing space. If successful, it deals 1 damage to its opposing space.", "相手のカードが別のスペースに移動するたび、この印を持つカードはそのカードの現在の正面へ移動しようとする。移動に成功し、そのカードが生きていれば、1ダメージを与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is no escape...", "逃げ場はない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quake", "震動", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Bones to deal 1 damage to all enemy cards. This sigil is removed afterwards.", "骨を4個支払い、全ての敵カードに1ダメージを与える。その後、この印は取り除かれる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrifying display of power.", "恐ろしい力の発露。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Served Dinner", "夕食の支度", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card on the owner's side of board. Add stats of the card bearing this sigil to the selected card. This card dies afterwards. This effect can also be activated by sacrificing or killing this page directly.", "盤上の所有者側のカードを1枚選ぶ。この印を持つカードの能力値を選んだカードに加え、その後このカードは死ぬ。このカードを直接生贄にするか倒すことでも発動する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dinner is served.", "夕食の用意ができた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoal Strike", "魚群の一撃", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, it deals 1 damage to all of opponent's submerged cards and forces them to surface.", "この印を持つカードが配置されると、潜水中の相手の全カードに1ダメージを与え、水面に浮上させる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hunt begins...", "狩りの始まりだ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skittish", "臆病", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card moves into space opposing the one bearing this sigil, deal 1 damage to it, then move to a random unoccupied space on the owner's side of board if possible.", "カードがこの印の持ち主の正面に移動してくると、それに1ダメージを与え、可能なら盤上の所有者側のランダムな空きマスへ移動する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature appears to be rather skittish.", "この生物はかなり臆病なようだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sprinter Strike", "スプリンターの一撃", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenener a card bearing this sigil moves, it deals 1 damage to its opposing space. If said space is not occupied, the opponent is deald 1 damage immediately.", "この印を持つカードが移動するたび、正面のスペースに1ダメージを与える。そこが空なら、相手に即座に1ダメージを与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A swift strike.", "素早い一撃。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sticky Tongue", "粘る舌", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owners turn, a card bearing this sigil attempts to drag creatures adjacent to opposing space or queued behind it in front of itself, prioritizing the latter. If affected card has 1 Health, this card immediately attacks it.", "所有者のターン開始時、この印を持つカードは正面のスペースに隣接する生物か、その後ろに待機中の生物を自分の前へ引き寄せようとする。後者を優先する。対象のカードの体力が1なら、すぐに攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a sticky situation.", "なんとも厄介な状況だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tactical Retreat", "戦術的撤退", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, the bearer of this sigil returns to owner's hand if it's still alive.", "所有者のターン終了時、この印の持ち主が生きていれば所有者の手札に戻る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It doesn't feel the need to stay on the board.", "盤上に留まる必要を感じていない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TearThrough", "切り裂き通過", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If opposing space is occupied, a card bearing this sigil will move in the direction inscribed on the sigil at the end of its owner's turn, dealing 1 damage to the card in that space and trying to move it as well.", "正面のスペースが埋まっている場合、この印を持つカードは所有者のターン終了時に印の方向へ移動し、そのスペースのカードに1ダメージを与えて一緒に移動させようとする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A brutal display", "残忍な見せつけ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Territorial", "縄張り争い", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When another creature moves into an adjacent or opposing space, a card bearing this sigil attacks it.", "他の生物が隣接または正面のスペースに移動してくると、この印を持つカードはそれを攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To intrude upon its territory...", "その縄張りに踏み込むとは……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tyranny", "圧政", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Blood to increase Attack and Health of this and adjacent creatures by 1, then remove this sigil.", "血を2支払い、この生物と隣接する生物の攻撃力と体力をそれぞれ1増やす。その後、この印を取り除く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sacrifice this beast is willing to make.", "この獣が喜んで払う犠牲だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vicious Growth", "凶暴な成長", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, it gains 1 Power and 1 Health.", "この印を持つカードが別の生物を倒すと、攻撃力と体力を1ずつ得る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One life to nourish another.", "一つの命が別の命を養う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wounding", "負傷", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card without Made of Stone, its target gains Bleeding effect. Bleeding cards lose 1 Health at the end of their owner's turn.", "この印を持つカードが石造りを持たない別のカードにダメージを与えると、対象は出血効果を得る。出血中のカードは所有者のターン終了時に体力を1失う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This must sting.", "これは痛むだろう。", Language.Japanese);



            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's a Grudgin'", "それは恨みを買うぞ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a card collect grudges from 10 marked cards in a single battle", "1回の戦闘で、1枚のカードが印をつけられたカード10枚から怨みを集める。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete and Total Extermination", "完全なる殲滅", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a card with Greater Grudge Bearer wipe out 4 marked cards at once.", "深い怨みを背負う者の印を持つカードで、印をつけられたカードを一度に4枚倒す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Completely Boned", "骨まみれ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wipe out the whole board via Bone Blast.", "骨の爆発で盤上の全てを一掃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plateosaurus School of Thought", "プラテオサウルス学派", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a philosopher bother 10 cards with questions in a single battle.", "1回の戦闘で、哲学者が質問でカード10枚を困らせる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrible Roommate", "ひどい同居人", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a territorial card lash out at friendly cards in a single battle", "1回の戦闘で、縄張り争いのカードが味方のカードを攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beast Cannon", "獣の大砲", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kill at least 2 enemy cards by throwing a hefty beast at them.", "重い獣を投げつけ、敵カードを少なくとも2枚倒す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Et Tu, Majungasaurus?", "お前もか、マジュンガサウルス？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a cannibalistic card devour 10 friendly cards in a single battle.", "1回の戦闘で、同族喰らいのカードが味方カードを10枚貪り喰う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'Tis But A Scratch", "かすり傷だ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have one of your cards survive 10 turns while bleeding.", "自分のカード1枚が出血しながら10ターン生き残る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empathetic", "共感", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a nurturing card sacrifice 10 Health in a single battle.", "1回の戦闘で、育みのカードが体力を10犠牲にする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rally", "結集", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have an emboldening card sacrifice 10 Power in a single battle.", "1回の戦闘で、鼓舞のカードが攻撃力を10犠牲にする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascended Arts", "昇華の技", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a certain card fully remove cost of 6 cards in a single run.", "1回のランで、あるカードが6枚のカードのコストを完全に取り除く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raptor Attack", "ラプターの攻撃", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain at least 10 Raptor cards in a single run.", "1回のランでラプターのカードを少なくとも10枚手に入れる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jurassic World", "ジュラシック・ワールド", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with 3 secret cards. Life finds a way.", "隠しカードを3枚持ってランを終える。生命は道を見つける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apex Predators", "頂点捕食者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have three biggest theropods in your deck in a single run.", "1回のランで、最大の獣脚類3種をデッキに入れる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "King of the Monsters", "百獣の王", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unleash the King of the Monsters upon the enemy.", "百獣の王を敵に放つ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ballad of Big Al", "ビッグ・アルのバラード", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Help get the big girl back on her feet. Poor thing.", "この大きな娘が再び立てるように助ける。かわいそうに。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indomitable One", "不屈の者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Create a genetic abomination with more teeth.", "さらに多くの歯を持つ遺伝子の怪物を作る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Monster Resurrected", "怪物の復活", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Make Spinosaurus feel like a monster.", "スピノサウルスに怪物のような気分を味わわせる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jurassic Painter", "ジュラ紀の画家", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Promote Stokesosaurus to a painter.", "ストケソサウルスを画家に昇格させる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All Outta Gum", "ガムはもうない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give the little guy balls of steel.", "小さなやつに鋼の度胸を与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Novel Look", "新たな姿", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take the frills off the crested critter.", "冠を持つ生き物から襟飾りを外す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bird Up", "鳥になろう", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Put too many feathers where they don't belong.", "羽毛の生えるはずがない場所に、羽毛をつけすぎる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wu's Secrets", "ウーの秘密", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have Compstegnathus, Spinoraptor and Ankylodocus in your deck in a single run.", "1回のランで、剣背のコンプソグナトゥス、スピノラプトル、アンキロドクスをデッキに入れる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Welcome to Jurassic Park", "ジュラシック・パークへようこそ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with Jurassic Park deck and at least 7 related cards.", "ジュラシック・パークのデッキと関連カードを少なくとも7枚持ってランを終える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prehistoric Collection", "先史時代のコレクション", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play a copy of every common Sauria card.", "古代のトカゲ図鑑の全てのコモンカードを1枚ずつ出す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rare Fossils", "レアな化石", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play a copy of every rare Sauria card.", "古代のトカゲ図鑑の全てのレアカードを1枚ずつ出す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paleo-Novice", "古生物初心者", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with 5 Sauria decks.", "異なる古代のトカゲ図鑑の初期デッキを少なくとも5種類使い、それぞれランをクリアする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dino-Fan", "恐竜ファン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with 20 Sauria decks.", "異なる古代のトカゲ図鑑の初期デッキを少なくとも20種類使い、それぞれランをクリアする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deck-O-Saurus", "デッキザウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with every available Sauria deck.", "利用可能な古代のトカゲ図鑑の全デッキでそれぞれランを終える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gyarouucore", "ギャルーコア", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtained every other achievement! Good job!", "他の全ての実績を獲得した！ よくやった！", Language.Japanese);

        }
    }
    public class SauriaCardsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SauriaCards Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acrocanthosaurus", "アクロカントサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acrocanthosaurus, terror of the North. It does not take much to provoke this giant into attacking.", "北の恐怖、アクロカントサウルス。少し刺激するだけで、この巨獣は攻撃を始める。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allosaurus", "アロサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This tenacious predator doesn't know when to stop its assault.", "このしぶとい捕食者は攻撃をやめる時を知らない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amargasaurus", "アマルガサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amargasaurus, a surprisingly small beast for its kind. Size is relative, however.", "アマルガサウルス。同族の中では驚くほど小さい。もっとも、大きさは相対的なものだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "American Lion", "アメリカライオン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The American Lion, a vicious feline predator with a soft heart. It does not extend its kindness towards its prey, however.", "アメリカライオン。獰猛なネコ科の捕食者だが、優しい心を持つ。ただし獲物には慈悲を見せない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "American Lion Cub", "アメリカライオンの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An American Lion Cub, an adorable kitten. It's hard to imagine something like this growing up to become a terrifying predator", "アメリカライオンの子。愛らしい子猫だ。これが育つと恐ろしい捕食者になるとは想像しがたい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankylosaurus", "アンキロサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sturdy Ankylosaurus. It may not feel claws and teeth strike its hide, but it does not appreciate being pestered during mealtime.", "難攻不落のアンキロサウルス。爪や牙が皮膚に当たっても感じないかもしれないが、食事中に邪魔されるのは嫌いだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anomalocaris", "アノマロカリス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ancient Anomalocaris, one of the first apex predators to live in this world. It does its best against modern beasts.", "古代のアノマロカリス。この世界で最初期の頂点捕食者の一つだ。現代の獣にも懸命に立ち向かう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apatosaurus", "アパトサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The formidable Apatosaurus. It doesn't need to be the biggest of its kind to crush enemies into dust.", "手強いアパトサウルス。同族で最も大きくなくても、敵を粉々に押し潰せる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Argentinosaurus", "アルゼンチノサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The titanic Argentinosaurus, truly a sight to behold. Make sure to keep your distance if you do not wish to be crushed.", "巨大なアルゼンチノサウルス。その姿はまさに圧巻だ。潰されたくなければ距離を取ることだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arthropleura", "アースロプレウラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arthropleura, an oversized centipede with a taste for decaying plants. Its movements are unpredictable.", "アースロプレウラ。腐った植物を好む巨大なムカデで、その動きは予測できない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspidorhynchus", "アスピドリンクス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is much bigger fish out there, but Aspidorhynchus is still perfectly capable of biting your fingers off.", "もっと大きな魚はいるが、アスピドリンクスにも君の指を噛み切る力は十分ある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Australovenator", "アウストラロヴェナトル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vicious Australovenator. It pierces and tears through the hide of its victims with its enlarged claws.", "獰猛なアウストラロヴェナトル。大きな爪で獲物の皮を突き刺し、引き裂く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Austroraptor", "アウストロラプトル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The keen-eyed Austroraptor, a skilled fisher of light build. It's far from harmless, however.", "目の鋭いアウストロラプトル。軽い体を持つ魚捕りの名手だ。だが無害ではない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baryonyx", "バリオニクス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baryonyx, a crocodile-faced beast with a taste for fish. Refrain from smiling if you do not wish to expand its diet.", "ワニのような顔をしたバリオニクス。魚が大好物だ。奴の食事の種類を増やしたくなければ、笑顔を見せないことだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beipiaosaurus", "ベイピアオサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Beipiaosaurus is armed with sharp claws to rend its foes apart...but it does not have the courage to stand up to anything bigger.", "このベイピアオサウルスには敵を引き裂く鋭い爪がある……だが自分より大きな相手に立ち向かう勇気はない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachiosaurus", "ブラキオサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mighty Brachiosaurus. It can use its immense size to draw aggressors away from allies.", "強大なブラキオサウルス。その巨体を使って襲撃者を仲間から引き離せる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachiosaurus Hatchling", "ブラキオサウルスの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Brachiosaurus hatchling. It will take some time for it to reach its full size.", "ブラキオサウルスの子。成体の大きさになるには時間がかかる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachytrachelopan", "ブラキトラケロパン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachytrachelopan, a bizarre creature for its kind. Though it lacks their characteristic long neck, its long tail makes up for its absence.", "ブラキトラケロパン。同族の中でも奇妙な生物だ。特徴的な長い首はないが、長い尾でそれを補っている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camarasaurus", "カマラサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ginormous Camarasaurus. Though it does not wish to bring harm directly, its great size allows it to fling beasts across the battlefield.", "巨大なカマラサウルス。直接傷つける気はないが、その巨体で獣を戦場の向こうまで投げ飛ばせる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria", "古代のトカゲ図鑑", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carnotaurus", "カルノタウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though not as swift as commonly believed, this beast can hardly be stopped once it gains momentum.", "一般に思われているほど速くはないが、一度勢いがつくと、この獣を止めるのは難しい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cartorhynchus", "カートリンクス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Cartorhynchus may be tiny, but there is bigger fish following its trail.", "このカートリンクスは小さいかもしれないが、その後を追うもっと大きな魚がいる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caturus", "カトゥルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caturus, an imposing predator to some, an enticing snack for others.", "カトゥルス。ある者には恐ろしい捕食者、別の者には魅力的なおやつだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cearadactylus", "ケアラダクティルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Too busy fretting over its meals, Cearadactylus does not make for a great fighter.", "ケアラダクティルスは食事を心配するのに忙しく、優れた戦士にはなれない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cephalaspis", "ケファラスピス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cephalaspis, an armored fish shaped like a shovel. Its thick armor lets it feed in peace.", "ケファラスピス。シャベルの形をした装甲魚だ。厚い鎧のおかげで安心して食事ができる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ceratodus", "ケラトドゥス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The peculiar Ceratodus, a fish with the ability to live on land. Makes for a fine meal.", "奇妙なケラトドゥス。陸でも生きられる魚だ。いい食事になる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ceratosaurus", "ケラトサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though often overshadowed by its bigger competitors, Ceratosaurus is a formidable threat in its own right.", "大きな競争相手の陰に隠れがちだが、ケラトサウルスも十分に手強い脅威だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chasmosaurus", "カスモサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stalwart Chasmosaurus. It uses its shield-like frill to protect allies.", "不屈のカスモサウルス。盾のような襟飾りで仲間を守る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chungkingosaurus", "チュンキンゴサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though it may not be eager to hurt other creatures, you do not want to get near the tail of Chungkingosaurus.", "チュンキンゴサウルスは他の生物を傷つけたがらないかもしれないが、その尾には近づかない方がいい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coelophysis", "コエロフィシス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coelophysis, one of the first of its kind. Many more terrible beasts have spawned from its lineage.", "コエロフィシス。同族の最初期の一つだ。その系統からさらに恐ろしい獣が生まれた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compsognathus", "コンプソグナトゥス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The diminutive Compsognathus. It can hardly pose a threat while alone.", "小さなコンプソグナトゥス。一匹ではほとんど脅威にならない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corythosaurus", "コリトサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corythosaurus, a cautious beast that does not travel alone. It finds safety in a herd.", "コリトサウルス。単独では行動しない用心深い獣だ。群れの中で安全を確保する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dacentrurus", "ダケントルルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dacentrurus, a beast with an oddly elongated neck that fiercely protects its allies.", "ダケントルルス。妙に長い首を持ち、仲間を懸命に守る獣だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Daeodon", "ダエオドン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The terrible Daeodon. It may not be a pig, but it is certainly prepared for war.", "恐ろしいダエオドン。ブタではないかもしれないが、戦いの備えは万全だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinocheirus", "デイノケイルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once thought to be a terrible beast, Deinocheirus turned out to be far more bizarre than anyone expected. Its strength is not to be underestimated, however.", "恐ろしい獣だと考えられていたデイノケイルスは、誰の予想よりも奇妙な姿だった。とはいえ、その力を侮ってはいけない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinonychus", "デイノニクス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinonychus, a vicious hunter known for the enlarged claws adorning its feet. How's that for a 'six-foot turkey'?", "デイノニクス。足の大きな爪で知られる獰猛な狩人だ。この「6フィートの七面鳥」はどうだ？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sicilian Dwarf Elephant", "シチリアのコビトゾウ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sicilian Dwarf Elephant, a severely undersized counterpart of one of the biggest animals to roam the land today. Such is life on small island.", "シチリアのコビトゾウ。現代の陸上最大級の動物の、ずっと小さな近縁種だ。小さな島での暮らしとはそういうものだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Desmatosuchus", "デスマトスクス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though not blessed with sharp teeth or claws, Desmatosuchus tries to make up for it with its thick hide", "デスマトスクスには鋭い歯や爪がないが、厚い皮でそれを補おうとする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dilophosaurus", "ディロフォサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This little critter cripples prey by spitting its uncharacteristic venom.", "この小さな生物は、珍しい毒を吐いて獲物の動きを封じる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dilophosaurus, a terror of the Early Jurassic period. Losing its ridiculous frill does not hinder its venomous nature.", "前期ジュラ紀の恐怖、ディロフォサウルス。あのばかげた襟飾りを失っても毒の性質は変わらない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimetrodon", "ディメトロドン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimetrodon, a reptilian mammal with an impressive sail. Its sharp teeth are a far bigger concern, however.", "ディメトロドン。立派な帆を持つ哺乳類型の爬虫類だ。しかし鋭い歯の方がはるかに厄介だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimorphodon", "ディモルフォドン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimorphodon, a mostly unremarkable little critter. Do not startle it, those teeth will leave a mark during its hasty retreat.", "ディモルフォドン。大して目立たない小さな生き物だ。驚かせてはいけない。慌てて逃げる際、その歯で傷を残す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dinosaur Egg", "恐竜の卵", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigger Dinosaur Egg", "より大きな恐竜の卵", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An egg left behind by some dinosaur. I wonder what will hatch from it?", "恐竜が残した卵。何が孵るのだろう？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diplodocus", "ディプロドクス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If sheer size alone is not enough to deter predators, then perhaps a mighty tail whip will make them reconsider.", "大きさだけでは捕食者を追い払えないなら、強烈な尾の一撃で考え直させられるかもしれない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dryosaurus", "ドリオサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dryosaurus, an adorable creature with a flighty attitude.", "ドリオサウルス。かわいらしいが、驚きやすい生物だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dunkleosteus", "ダンクルオステウス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ravenous Dunkleosteus, an armored fish from distant past. Its true length has little bearing on its crushing jaws.", "大食らいのダンクルオステウス。遠い昔の装甲魚だ。実際の体長は、その押し潰す顎の威力にほとんど関係しない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Edmontosaurus", "エドモントサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Edmontosaurus, a massive creature with very few natural predators. Do not expect to find it alone.", "エドモントサウルス。天敵がほとんどいない巨大な生物だ。一匹でいるところはまず見られない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elasmosaurus", "エラスモサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elasmosaurus, a prehistoric beast with an incredibly long neck. It can snatch prey far out of the reach of others.", "エラスモサウルス。驚くほど長い首を持つ先史時代の獣で、他の者の手の届かない遠くの獲物を捕らえる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eobasileus", "エオバシレウス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eobasileus, the largest of its kind. Do not stand in its path if you wish to see the sun rise again.", "エオバシレウス。同族の中で最大だ。再び日の出を見たければ、その進路に立たないことだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Euoplocephalus", "エウオプロケファルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The thick hide of this Euoplocephalus and the equally hefty club at the end of its tail protect it from most predators", "エウオプロケファルスの厚い皮と尾の先の重い棍棒は、ほとんどの捕食者から身を守る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gallimimus", "ガリミムス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gallimimus, a bird-like beast that is rather quick on its feet. It is about as friendly as it looks.", "ガリミムス。鳥のような獣で、足がかなり速い。見た目通りに人懐こい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gastornis", "ガストルニス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vigilant Gastornis. It watches over its comrades, growing furious if it loses any.", "警戒心の強いガストルニス。仲間を見守り、誰かを失うと激怒する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Ground Sloth", "オオナマケモノ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Giant Ground Sloth, a massive beast far surpassing its modern relatives. It is much less friendly than you would think.", "オオナマケモノ。現代の近縁種よりはるかに大きな獣だ。想像するほど友好的ではない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gigantoraptor", "ギガントラプトル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gigantoraptor, a disturbingly large beast. Any attempts to resist will only further provoke it.", "ギガントラプトル。不気味なほど大きい獣だ。抵抗しようとすれば、ますます怒らせるだけだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gojirasaurus", "ゴジラサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once the biggest predator to roam the land, Gojirasaurus' reign did not last. It's hard to match the titans that followed it.", "かつて陸上最大の捕食者だったゴジラサウルスの支配は長く続かなかった。後に現れた巨獣には敵わない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guanlong", "グアンロン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guanlong, a vicious predator emboldened by the thrill of combat. Many more terrible beasts have spawned from its lineage.", "グアンロン。戦いの興奮に勇気づけられる獰猛な捕食者。その系統からさらに恐ろしい獣が生まれた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hadrosaurus", "ハドロサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vengeful Hadrosaurus. It makes quick work of those who harm members of its herd.", "復讐心の強いハドロサウルス。群れの仲間を傷つける者を素早く片付ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haolong", "ハオロン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haolong, a bizarre beast covered in many sharp quills. Very few predators dare to clamp their jaws around its prickly hide.", "ハオロン。鋭い棘に覆われた奇妙な獣。その棘だらけの皮に噛みつく捕食者はほとんどいない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herrerasaurus", "ヘレラサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Herrerasaurus hails from the age before dinosaurs took over the world. Being more primitive does not make it any less successful.", "このヘレラサウルスは恐竜が世界を支配する前の時代から来た。より原始的でも、成功していないわけではない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hesperornis", "ヘスペロルニス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hesperornis, a swimming bird with a taste for fish. It has yet to lose its teeth.", "ヘスペロルニス。魚を好む泳ぐ鳥だ。まだ歯を失っていない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homalocephale", "ホマロケファレ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an adorable Homalocephale. Alas, a grim fate awaits this poor creature. Will your heart sink when you hear its cries?", "なんと愛らしいホマロケファレ。だが哀れな生物には残酷な運命が待っている。その鳴き声を聞けば、君の心も沈むだろうか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyornis", "イクチオルニス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyornis, a prehistoric bird with sharp teeth. It is no less annoying than its modern counterparts.", "イクチオルニス。鋭い歯を持つ先史時代の鳥で、現代の仲間に負けず劣らず厄介だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyosaurus", "イクチオサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The swift Ichthyosaurus. It can attack submerged foes in the blink of an eye.", "敏捷なイクチオサウルス。潜水中の敵を瞬く間に攻撃できる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iguanodon", "イグアノドン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mind your manners before this Iguanodon if you do not wish to feel its clawed thumb pierce you.", "このイグアノドンの前では行儀よくすることだ。爪のある親指で突き刺されたくなければ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inostrancevia", "イノストランケビア", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inostrancevia, a surprisingly agile apex predator of its age. The grievous injuries left by the beast's fangs are far less suprising.", "イノストランケビア。当時としては驚くほど俊敏な頂点捕食者だ。その牙が深い傷を残すことは、それほど驚くに値しない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Irish Elk", "アイリッシュエルク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic Irish Elk, the biggest of its kind. Its massive horns grant it extended reach.", "荘厳なアイリッシュエルク。同族の中で最大だ。その巨大な角でより遠くに届く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Irritator", "イリタトル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The patient Irritator. Though it primarily feeds on fish, its claws are perfectly suited for tearing into other beasts.", "辛抱強いイリタトル。主に魚を食べるが、その爪は他の獣を引き裂くのにも適している。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Isisaurus", "イシサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Isisaurus leads a herd of its own. Though they do not belong to its kind, those beasts trust this experienced titan.", "このイシサウルスは自分の群れを率いる。種族は違っても、獣たちは経験豊富な巨体を信頼している。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jeholopterus", "ジェホロプテルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jeholopterus, nothing more than a bug-eating critter. Don't expect much else out of it.", "ジェホロプテルス。虫を食べる小さな生き物にすぎない。それ以上は期待しないことだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Katifelis", "カティフェリス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Katifelis, an unremarkable feline. It does not respond well to approaching strangers.", "カティフェリス。目立たないネコ科の動物。近づく見知らぬ者にはいい反応を示さない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kentrosaurus", "ケントロサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kentrosaurus, a herbivore with a threatening appearance. Said appearance is far from deceiving, however.", "ケントロサウルス。恐ろしい見た目の草食動物だ。その見た目に偽りはない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Koolasuchus", "クーラスクス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Koolasuchus, a dreadfull creature lurking in the water. It does not pass up any opportunity to feast.", "クーラスクス。水中に潜む恐ろしい生物だ。食事の機会を逃さない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lambeosaurus", "ランベオサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The solitary Lambeosaurus. It strikes its foes multiple times when disturbed.", "孤独なランベオサウルス。邪魔されると敵を何度も攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Liopleurodon", "リオプレウロドン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While much smaller than some may believe, Liopleurodon is still a vicious predator, always ready to tear its prey apart.", "リオプレウロドン。想像するよりずっと小さいが、それでも獲物を引き裂く準備を欠かさない獰猛な捕食者だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Majungasaurus", "マジュンガサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voracious Majungasaurus. It will not hesitate to devour its own comrades to sate its hunger.", "大食らいのマジュンガサウルス。飢えを満たすためなら、仲間でもためらわずに喰らう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Masiakasaurus", "マシアカサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Masiakasaurus, a bizarre dinosaur of unimpressive size. It does not stay in battle for long.", "マシアカサウルス。大きさは平凡な奇妙な恐竜だ。長く戦場には留まらない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mawsonia", "マウソニア", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mawsonia, an enormous fish drifting in search of prey. Pray you do not bump into one while swimming.", "マウソニア。獲物を探して漂う巨大な魚だ。泳いでいるときに出くわさないよう祈ろう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalania", "メガラニア", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The monstrous Megalania. A single bite from this oversized reptile is enough to cripple most beasts.", "怪物のようなメガラニア。この巨大な爬虫類の一噛みは、ほとんどの獣を無力化する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Metriacanthosaurus", "メトリアカントサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Metriacanthosaurus mercilessly tears into its prey, unwilling to let any meal get away from its jaws.", "このメトリアカントサウルスは獲物を容赦なく引き裂き、一度くわえた食事を逃がさない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Microceratus", "ミクロケラトゥス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unlike its bigger relatives, Microceratus stands on two legs and lacks any meaningful protection against predators. The best it can do is draw attention of something bigger.", "大きな近縁種と違い、ミクロケラトゥスは二足歩行で、捕食者から身を守る術もほとんどない。できるのは、もっと大きなものの注意を引くことくらいだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minmi", "ミンミ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Minmi may seem adorable, but it is far from defenseless. In fact, defense might be all it has.", "このミンミは愛らしく見えるが、無防備ではない。むしろ防御しかできないかもしれない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muttaburrasaurus", "ムッタブラサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The persistent Muttaburrasaurus. It does not fall in battle while its herd is still in danger.", "しぶといムッタブラサウルス。群れが危険にさらされている間、戦いで倒れることはない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nanotyrannus", "ナノティラヌス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Living in the shadow of the King does not make this beast any less formidable.", "王の陰で生きているからといって、この獣が手強くないわけではない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nigersaurus", "ニジェールサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nigersaurus, a beast with countless teeth. It loses many while feeding, but they regrow just as quickly.", "ニジェールサウルス。無数の歯を持つ獣だ。食事中に多くの歯を失うが、同じ速さで生え直す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothosaurus", "ノトサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though this Nothosaurus is clumsy on land, it is an adept swimmer with a mouth full of sharp teeth.", "このノトサウルスは陸では不器用だが、泳ぎは得意で口には鋭い歯が並んでいる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Olorotitan", "オロロティタン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Olorotitan is more concerned about helping its allies than itself. Such altruism.", "このオロロティタンは自分より仲間を助けることを気にかけている。なんと利他的なのだろう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Othnielia", "オスニエリア", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Othnielia, hardly more than a snack for more ferocious beasts.", "オスニエリア。より獰猛な獣にとっては、ただのおやつにすぎない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ouranosaurus", "オウラノサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though it is not an outstanding fighter, this Ouranosaurus encourages its comrades to fight with greater strength.", "このオウラノサウルスは優れた戦士ではないが、仲間がより強く戦えるように励ます。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oviraptor", "オヴィラプトル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once thought to be a mere egg thief, this feathered fiend takes great care of its young.", "かつて卵泥棒にすぎないと思われていたこの羽毛の魔物は、子を大切に育てる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pachycephalosaurus", "パキケファロサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stubborn Pachycephalosaurus. It will attack anything that intrudes upon its territory regardless of size.", "頑固なパキケファロサウルス。大きさを問わず縄張りに入ってきたものを攻撃する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pachyrhinosaurus", "パキリノサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The nomadic Pachyrhinosaurus. It lost many brothers during its travels. It cannot bear to lose more.", "放浪するパキリノサウルス。旅の途中で多くの仲間を失い、これ以上失うことには耐えられない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasaurolophus", "パラサウロロフス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The peaceful Parasaurolophus. Its peculiar crest allows it to call upon its allies when in trouble.", "穏やかなパラサウロロフス。独特の頭冠で、困ったときに仲間を呼ぶ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasaurolophus Hatchling", "パラサウロロフスの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A meek Parasaurolophus hatchling. It has yet to develop a prominent crest to match its parents.", "おとなしいパラサウロロフスの子。親のような目立つ頭冠はまだ生えていない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Patagopelta", "パタゴペルタ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While far from the biggest armored dinosaur, Patagopelta is still perfectly capable of enduring blows.", "パタゴペルタは最大の装甲恐竜には程遠いが、打撃には十分耐えられる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plateosaurus", "プラテオサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plateosaurus, one of the first titans to roam the land. Though its descendants have far surpassed its size, it is by no means small.", "プラテオサウルス。大地を歩いた最初期の巨獣の一つだ。子孫ははるかに大きくなったが、それでも小さくはない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Platybelodon", "プラティベロドン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Platybelodon, a beast so bizarre that few would believe it existed. It can use its unsightly skull to uproot obstacles in your path.", "プラティベロドン。あまりに奇妙で、実在を信じる者は少ない。その見苦しい頭蓋骨で進路の障害を根こそぎ取り除ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raptor Plushie", "ラプターのぬいぐるみ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cute little toy, nothing more.", "かわいい小さなおもちゃ。それだけだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stuffing", "詰め物", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All that's left of a toy.", "おもちゃの残骸。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Postosuchus", "ポストスクス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Postosuchus, a bipedal crocodilian. Its bite is no less devastating than that of its modern relatives.", "ポストスクス。二足歩行のワニ形類で、その噛みつきは現代の近縁種に負けず劣らず強烈だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Proceratosaurus", "プロケラトサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The deceptive Proceratosaurus. It makes up for its lacking offense with whatever wit you may attribute to a beast.", "狡猾なプロケラトサウルス。獣にあると思える限りの知恵で、攻撃力の不足を補っている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Procompsognathus", "プロコンプソグナトゥス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Procompsognathus, a tiny terror with a surprisingly potent venom. It's particularly fond of feasting on greedy old men.", "プロコンプソグナトゥス。小さな恐怖で、驚くほど強力な毒を持つ。欲深い老人を食べるのが特に好きだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prongdeer", "枝角のシカ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prongdeer, a relatively small horned creature with an ill-fitting pair of fangs. They are not just for show, however.", "枝角のシカ。比較的小柄で、似合わない牙を持つ。だが飾りではない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protoceratops", "プロトケラトプス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Protoceratops may not seem like a threat, but the ferocity it displays when desperate is a sight to behold.", "このプロトケラトプスは脅威に見えないかもしれないが、追い詰められたときの獰猛さは見事だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protosphyraena", "プロトスフィラエナ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protosphyraena, a lightning-fast predator that cleaves its prey in half with its extended snout.", "プロトスフィラエナ。稲妻のように速い捕食者で、長い吻で獲物を真っ二つにする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Psittacosaurus", "プシッタコサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The timid Psittacosaurus. Many beasts form bonds with this adorable creature. Few wish to see it hurt.", "臆病なプシッタコサウルス。多くの獣がこの愛らしい生物と絆を結ぶ。傷つく姿を見たい者はほとんどいない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pteranodon", "プテラノドン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pteranodon, an iconic flying reptile. It may not have teeth to maul you with, but that beak spells trouble.", "プテラノドン。象徴的な飛ぶ爬虫類だ。噛み裂く歯はなくとも、その嘴は厄介だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pterodaustro", "プテロダウストロ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...No, I did not fabricate this creature. Even the most bizarre forms can serve their own purposes.", "……いや、この生物は私がでっち上げたものではない。最も奇妙な姿にも、それぞれの役目がある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Qianzhousaurus", "チエンジョウサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ambitious Qianzhousaurus. Though yet to reach the true King's might, it has potential for growth.", "野心的なチエンジョウサウルス。真の王の力にはまだ届かないが、成長の可能性を秘めている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quercylurus", "ケルキルルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quercylurus, a massive beast resembling saber-toothed cats. It gnaws on the many bones of its numerous victims.", "ケルキルルス。サーベルタイガーに似た巨獣だ。数多くの犠牲者の骨をかじる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhamphorhynchus", "ランフォリンクス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhamphorhynchus, a tiny flying reptile with a mouth full of sharp teeth. Though it prefers fish, it can and will bite your fingers.", "ランフォリンクス。鋭い歯が並ぶ口を持つ小さな飛ぶ爬虫類だ。魚を好むが、君の指も噛めるし、実際に噛む。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacabambaspis", "サカバンバスピス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The jawless Sacabambaspis, an adorable little fish with an armored hide.", "顎のないサカバンバスピス。装甲の皮膚を持つかわいい小魚だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sansanosmilus", "サンサノスミルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sansanosmilus, a cat-like predator with a particularly wounding bite. Smaller size does not make it any less dangerous.", "サンサノスミルス。特に傷を負わせる噛みつきを持つネコのような捕食者だ。小柄でも危険さは変わらない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sarcoprion", "サルコプリオン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sarcoprion, a monstrous shark with a bizarre set of jaws. It uses them to cut its prey in half.", "サルコプリオン。奇妙な顎を持つ怪物のようなサメだ。その顎で獲物を真っ二つにする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Segisaurus", "セギサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Segisaurus, hardly more than a pest. It comes in great numbers, however.", "セギサウルス。せいぜい厄介者だが、大群でやって来る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shringasaurus", "シュリンガサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shringasaurus, a horned reptile from the distant past. It shoves its attackers back in retaliation.", "シュリンガサウルス。遠い昔の角を持つ爬虫類だ。反撃として攻撃者を押し戻す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shunosaurus", "シュノサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shunosaurus, a long-necked creature with a club at the end of its tail. It can land debilitating strikes upon its enemies.", "シュノサウルス。長い首と尾の先の棍棒を持つ生物だ。敵を弱らせる一撃を放てる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simosuchus", "シモスクス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simosuchus, an adorable and completely harmless crocodilian. It protects itself with its thick scales.", "シモスクス。愛らしく完全に無害なワニ形類だ。厚い鱗で身を守る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sinosauropteryx", "シノサウロプテリクス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sneaky Sinosauropteryx, a feathered reptilian pest resembling a racoon in more than appearance.", "ずる賢いシノサウロプテリクス。羽毛を持つ厄介な爬虫類で、見た目以外にもアライグマに似ている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stegosaurus", "ステゴサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This territorial Stegosaurus is not willing to share room with anyone, friend or foe.", "縄張り意識の強いこのステゴサウルスは、敵味方を問わず誰とも場所を共有したがらない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stokesosaurus", "ストケソサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stokesosaurus, an unassuming predator. Perhaps it is more intelligent than it appears at a glance.", "ストケソサウルス。目立たない捕食者だが、見た目より賢いのかもしれない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stygimoloch", "スティギモロク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stygimoloch, a stubborn beast with an unpleasant attitude. It won't go down without a fight.", "スティギモロク。態度の悪い頑固な獣だ。戦わずには倒れない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Styracosaurus", "スティラコサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The tenacious Styracosaurus. It's not content with simply fending off its attackers.", "しぶといスティラコサウルス。攻撃者を追い払うだけでは満足しない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suchomimus", "スコミムス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suchomimus, a beats with a narrow snout that primarily hunts fish. It is no stranger to hunting prey on land, however.", "スコミムス。細長い吻を持ち、主に魚を狩る獣だ。陸での狩りにも慣れている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Supersaurus", "スーパーサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The altruistic Supersaurus. It is determined to use what's left of its essence to support its comrades.", "利他的なスーパーサウルス。残された力を仲間の支援に使うと決めている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tapejara", "タペヤラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The illustrious Tapejara. It calls upon its kin to aid it in battle.", "名高いタペヤラ。戦いを助けるために仲間を呼ぶ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiktaalik", "ティクターリク", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiktaalik, the great progenitor. You may thank it for your ability to live on land.", "偉大な祖先、ティクターリク。君が陸で生きられるのは、この生き物のおかげだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Titanis", "ティタニス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Titanis, an oversized carnivorous bird with a foul temper. Don't expect to outrun this beast.", "ティタニス。巨大な肉食の鳥で、気性が荒い。この獣より速く走れるとは思わないことだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torosaurus", "トロサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This elderly beast can hardly muster the will to retaliate. I advise against testing its patience, however.", "この老いた獣は、反撃する気力をほとんど持てない。だが忍耐を試さないことを勧める。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Triceratops", "トリケラトプス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Many have tried to best this lone Triceratops. Few could walk away.", "多くの者がこの孤独なトリケラトプスを倒そうとした。歩いて帰れた者は少ない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Triceratops Hatchling", "トリケラトプスの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A playful Triceratops hatchling. Cherish these moments before it turns into a fierce behemoth.", "遊び好きなトリケラトプスの子。獰猛な巨獣に育つ前に、この時を大切にしよう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Troodon", "トロオドン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "New life shall spring from those unfortunate to feel its venomous bite.", "不運にもその毒のある噛みつきを受けた者から、新たな命が芽生える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tyrannosaurus Hatchling", "ティラノサウルスの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The innocent Tyrannosaurus hatchling. When the time comes, the throne will belong to this little creature.", "無邪気なティラノサウルスの子。時が来れば、玉座はこの小さな生物のものだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utahraptor", "ユタラプトル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utahraptor, an unpleasantly large beast for its kind. It can disembowel you in seconds.", "ユタラプトル。同族の中でも嫌になるほど大きい獣だ。数秒で君の内臓をえぐり出せる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utatsusaurus", "ウタツサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The nimble Utatsusaurus. It has little trouble passing over obstacles.", "俊敏なウタツサウルス。障害を越えるのにほとんど苦労しない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Velociraptor", "ヴェロキラプトル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The swift Velociraptor, a tiny menace of the desert. Were you expecting something bigger?", "敏捷なヴェロキラプトル。砂漠の小さな脅威だ。もっと大きいと思ったか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Rhinoceros", "ケサイ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Rhinoceros, a particularly hairy beast with eyesight that does not help its temper. Its long horn can pierce multiple foes.", "ケサイ。毛深い獣で、視力の悪さが気性を穏やかにすることはない。長い角は複数の敵を貫ける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Xiphactinus", "シファクティヌス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Xiphactinus, a monstrous fish with endless appetite. A single bite is not enough to sate it.", "シファクティヌス。尽きることのない食欲を持つ怪物のような魚。一口では満足できない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yutyrannus", "ユウティラヌス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The fiendish Yutyrannus. It tears its prey apart while it's still alive.", "邪悪なユウティラヌス。獲物が生きているうちに引き裂く。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zhenyuanopterus", "ジェンユアンゴプテルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zhenyuanopterus, a flying pest with a mouth full of needle-like teeth. It accompanies larger beasts into battle.", "ジェンユアンゴプテルス。針のような歯が並ぶ口を持つ、厄介な飛ぶ生物だ。大きな獣に付き従って戦う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards", "古代のトカゲ図鑑", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards consisting of a random assortment of prehistoric animals, mostly reptiles.", "主に爬虫類を中心とした先史時代の動物をランダムに集めた、約[count]枚のカードコレクション。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A set of [summary] exclusively featuring a random assortment of prehistoric animals, mostly reptiles.", "[summary]のセット。主に爬虫類を中心とした先史時代の動物だけをランダムに集めている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fisher", "漁師", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, a Ceratodus is created in your hand. [define:Sauria_Ceratodus]", "この印を持つカードが配置されると、手札にケラトドゥスが1枚作られる。[define:Sauria_Ceratodus]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A successful hunt for fish.", "魚を狙う狩りは成功した。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fisher Strike", "漁師の一撃", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, a Ceratodus is created in your hand. [define:Sauria_Ceratodus]", "この印を持つカードが別の生物を倒すと、手札にケラトドゥスが1枚作られる。[define:Sauria_Ceratodus]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It appears the beast caught something.", "獣は何かを捕まえたようだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Promise of such a feast is too enticing for them to ignore.", "このごちそうの約束は、無視できないほど魅力的だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mysterious power infuses your beast.", "不思議な力が君の獣に注がれる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something is off...", "何かがおかしい……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like it left something precious.", "何か貴重なものを残したようだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Marine Shuffle", "海のシャッフル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, a free Ceratodus is shuffled into your side deck. [define:Sauria_Ceratodus]", "この印を持つカードが別の生物を倒すと、無料のケラトドゥス1枚がサイドデッキに混ぜられる。[define:Sauria_Ceratodus]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A surprise awaits you.", "驚きが君を待っている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like it lost some teeth while grazing. They are yours to keep.", "草を食べているときに歯が何本か抜けたようだ。君にあげよう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not alone anymore.", "もう一人ではない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nourishment", "栄養", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small sacrifice for small growth.", "小さな成長のための小さな犠牲。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an abhorent creature, crafted by the hands of madmen...", "なんと忌まわしい生物だ。狂人の手で作られたものだ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parting Fish", "別れの魚", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil dies or is sacrificed, a Ceratodus is created in your hand. [define:Sauria_Ceratodus]", "この印を持つカードが死ぬか生贄になると、手札にケラトドゥスが1枚作られる。[define:Sauria_Ceratodus]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So many questions to ask.", "聞きたいことがたくさんある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another beast rises from its ashes.", "また一頭の獣が灰の中から蘇る。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fatal mistake.", "致命的な間違い。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can you feel the ground beneath your feet rumble?", "足元の大地が揺れるのを感じるか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything will be dragged to the depths.", "全てが深淵へ引きずり込まれる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not satisfied with its stolen goods just yet.", "盗んだ品にはまだ満足していない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Being in the presence of that animal is making it feel like a monster.", "あの動物のそばにいると、自分が怪物のように感じる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Taking up the arts? Interesting.", "芸術を始めるのか？ 面白い。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such is the might of a titan.", "これが巨獣の力だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The king has no need for restraint. More sacrifices must be made.", "王に遠慮は必要ない。さらなる生贄が必要だ。", Language.Japanese);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ancient Iguanodon", "古代のイグアノドン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remnant of an old belief and proof of science's perpetual march, this beast has much to learn.", "古い信念の名残であり、科学が絶えず進む証。この獣にはまだ学ぶことが多い。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankylodocus", "アンキロドクス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Far less abominable than most of its artificial kin, Ankylodocus can almost be called a gentle giant.", "アンキロドクスは人工の仲間の大半よりずっとおぞましくなく、優しい巨人とさえ呼べる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anzu", "アンズー", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anzu, the vicious beast that brings thunder. Do not invite its wrath upon yourself.", "雷をもたらす獰猛な獣、アンズー。その怒りを買わないことだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Archelon", "アーケロン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wise Archelon. It fortifies its allies upon entering the battle.", "賢いアーケロン。戦闘に入ると仲間を強化する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Basilosaurus", "バシロサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Basilosaurus, the King Lizard. While not even remotely related to reptiles, it certainly earns the title of royalty.", "バシロサウルス、トカゲの王。爬虫類とは全く近縁ではないが、王の名にふさわしい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beautiful Feather", "美しい羽", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dazzling.", "まばゆい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus", "ブロントサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus, the so-called thunderbringer. Its name may not be entirely unearned.", "ブロントサウルス、いわゆる雷をもたらす者。その名は伊達ではないのかもしれない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carchadontosaurus", "カルカロドントサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bloodthirsty Carcharodontosaurus. The smell of blood drives it into a frenzy.", "血に飢えたカルカロドントサウルス。血の匂いで狂乱する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cave Bear", "ホラアナグマ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The reclusive Cave Bear. Though it may not be a vicious predator, it gives shelter to a fair share of beasts craving flesh.", "隠遁するホラアナグマ。獰猛な捕食者ではないかもしれないが、肉を求める多くの獣に住処を与える。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compstegnathus", "剣背のコンプソグナトゥス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compstegnathus, a deformed beast bred for nefarious deeds. I do not enjoy looking at it.", "剣背のコンプソグナトゥス。悪事のために育てられた歪な獣だ。私は見たくない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cryolophosaurus", "クリオロフォサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This crested beast brings the unforgiving cold of winter with it. When it enters battle, you may find some poor creatures trapped in ice as a result.", "頭冠を持つこの獣は厳しい冬の寒さを連れてくる。戦闘に入ると、哀れな生物たちが氷に閉じ込められることがある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an unsightly beast, truly an eyesore. Who could have spawned it?", "なんとも見苦しい獣だ。目障りだな。誰が生み出したのだろう？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus Hatchling", "デイノスクスの子", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A helpless Deinosuchus hatchling. It has yet to grow into a fearsome apex predator.", "無力なデイノスクスの子。恐ろしい頂点捕食者へと成長するのはまだ先だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fish Meat", "魚肉", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juicy Fish Meat", "ジューシーな魚肉", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giganotosaurus", "ギガノトサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The horrifying Giganotosaurus. Though it normally hunts alone, big enough prey may attract more of its kind.", "恐ろしいギガノトサウルス。普段は単独で狩るが、十分に大きな獲物は仲間を引き寄せることがある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Godzilla", "ゴジラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The legendary King of the Monsters. It will take more than claws and fangs to take it down.", "伝説の百獣の王。倒すには爪や牙だけでは足りない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Godzillasaurus", "ゴジラザウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once a relatively peaceful beast, Godzillasaurus would go down in history as the King of the Monsters.", "かつて比較的穏やかな獣だったゴジラザウルスは、百獣の王として歴史に名を残すことになる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gwangi", "グワンジ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voracious Gwangi, a relic of the past. Do not attribute malice to this poor creature, it merely wishes to live.", "大食らいのグワンジ。過去の遺物だ。この哀れな生物に悪意を見ないでくれ。ただ生きたいだけなのだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homotherium", "ホモテリウム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homotherium, a vicious pack hunter. It will endlessly pursue its prey to nourish its kin.", "ホモテリウム。獰猛な群れの狩人だ。仲間を養うため、獲物を果てしなく追う。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hypsilophodon", "ヒプシロフォドン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Hypsilophodon should be little more than prey for most beast... However...", "このヒプシロフォドンは、ほとんどの獣にとって獲物にすぎないはずだ……だが……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyotitan", "イクチオティタン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyotitan, an awe-inspiring aquatic titan. Its sheer size alone dictates the flow of tides.", "イクチオティタン。畏怖を誘う水中の巨獣だ。その巨大さだけで潮の流れを左右する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indominus", "インドミナス・レックス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such is the power of science...", "これが科学の力だ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaellynasaura", "レエリナサウラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mysterious Leaellynasaura. Other beasts seem to undergo drastic changes in its presence.", "謎めいたレエリナサウラ。他の獣はそのそばで劇的に変化するようだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leedsichthys", "リードシクティス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The gigantic Leedsichthys, one of the biggest fish to ever inhabit the oceans. However, it is hardly one of the most dangerous.", "巨大なリードシクティス。海に棲んだ最大級の魚の一つだが、最も危険な魚には程遠い。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maiasaura", "マイアサウラ", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maiasaura, the 'Good Mother Lizard'. It will not let harm befall the little ones as long as it breathes.", "マイアサウラ、「良い母のトカゲ」。息のある限り、子供たちを傷つけさせない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalodon", "メガロドン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The titanic Megalodon, an apex predator plagued by insatiable hunger. Make sure it always has prey to feast on.", "巨大なメガロドン。尽きない飢えに苦しむ頂点捕食者だ。常に食べる獲物を用意しておくことだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalosaurus", "メガロサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalosaurus, one of the first to be discovered. Though its own fame did not last, it paves the path for others to attain it.", "メガロサウルス。最初に発見されたものの一つだ。自身の名声は続かなかったが、他の者が名声を得る道を開いた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Microraptor", "ミクロラプトル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This particularly petty Microraptor resembles ravens in more than its appearance. Do not get on its bad side.", "ひどく意地の悪いミクロラプトル。カラスに似ているのは見た目だけではない。機嫌を損ねないことだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mosasaurus", "モササウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This aquatic behemoth is no less vicious than any land-dwelling titan of its time.", "この水中の巨獣は、同時代の陸の巨獣に負けず劣らず獰猛だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigger Mysterious Egg", "より大きな不思議な卵", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something about this egg doesn't seem right...", "この卵は何かがおかしい……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noasaurus", "ノアサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valley of the Dinosaurs is in danger... Alas, few heed its words.", "恐竜の谷が危ない……だが、その言葉を聞く者は少ない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ornithomimus", "オルニトミムス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vain Ornithomimus, a feast for the eyes. When threatened, it flees and leaves behind colorful feathers for predators to marvel at.", "虚栄心の強いオルニトミムス。目を楽しませる存在だ。脅かされると逃げ、捕食者が驚くような色鮮やかな羽を残す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paraceratherium", "パラケラテリウム", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paraceratherium, one of the largest mammals to set foot on land. Kindred beasts walk by its side.", "パラケラテリウム。陸を歩いた最大級の哺乳類の一つだ。仲間の獣がその隣を歩む。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Philosoraptor", "哲学ラプター", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The pensive Philosoraptor, always asking the questions none dare to voice aloud.", "物思いにふける哲学ラプター。誰も声に出す勇気のない疑問をいつも投げかける。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyroraptor", "ピロラプトル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Like a bird of legend, Pyroraptor rose from the ashes to greet the world. Perhaps it could use a bit more fire?", "伝説の鳥のように、ピロラプトルは灰の中から世界に現れた。もう少し炎が必要かもしれない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quetzalcoatlus", "ケツァルコアトルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The terrible Quetzalcoatlus, an alarmingly massive ruler of skies with an appetite to match.", "恐ろしいケツァルコアトルス。驚くほど巨大な空の支配者で、食欲もその大きさに見合っている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Real Parasaurolophus", "本物のパラサウロロフス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Definitely Real Parasaurolophus", "絶対に本物のパラサウロロフス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasaurolophus, a dragon with a bizarre appearance. It produces flames by igniting the fuel stored in its crest via flint-like teeth.", "パラサウロロフス。奇妙な姿の竜だ。火打石のような歯で頭冠に蓄えた燃料に火をつけ、炎を生み出す。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhedosaurus", "リドサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Rhedosaurus from a distant world. The plague it carries in its blood is much too alien for most creatures to bear.", "遠い世界から来たリドサウルス。その血に宿る疫病は、ほとんどの生物には異質すぎて耐えられない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shantungosaurus", "シャントゥンゴサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shantungosaurus, absurdly massive for something that can stand on its rear legs. Their herds are as awe-inspiring as they are terrifying.", "シャントゥンゴサウルス。後ろ足で立てる生物としては途方もなく大きい。その群れは畏敬と恐怖を同時に呼び起こす。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spicomellus", "スピコメルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spicomellus, a beast covered in numerous spikes. It does not look pleasant to touch and it is even less pleasant to strike.", "スピコメルス。無数の棘に覆われた獣だ。触るのも嫌だが、攻撃するのはもっと嫌だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spinoraptor", "スピノラプトル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An abomination born of science, Spinoraptor is an adept fisher and hunter.", "科学から生まれた異形、スピノラプトル。魚捕りも狩りも得意だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spinosaurus", "スピノサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bizarre reptile of monstrous size, few marine animals can evade its narrow jaws.", "怪物のように巨大な奇妙な爬虫類。その細い顎から逃れられる海の動物は少ない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The monstrous Spinosaurus, the only being worthy of challenging the King.", "怪物のようなスピノサウルス。王に挑む資格のある唯一の存在だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanatosdrakon", "タナトスドラコン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanatosdrakon, a beast that has breached the boundary between life and death... Hm... Perhaps this creature has been blessed by...", "タナトスドラコン。生と死の境界を越えた獣……ふむ……もしやこの生物は……の祝福を", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Al", "ビッグ・アル", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Al, a female Allosaurus that has suffered greatly during its short life. Perhaps you can help this poor creature?", "ビッグ・アル。短い生涯で多くの苦しみを味わった雌のアロサウルスだ。この哀れな生物を助けられるだろうか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Wars", "化石戦争", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They fought to protect their pride, sparing no expense. In the end, what were they left with?", "彼らは誇りを守るため、費用を惜しまず争った。最後に何が残ったのだろう？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Therizinosaurus", "テリジノサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Therizinosaurus can hardly see these days. However, you do not want to approach a half-blind giant with claws of such length.", "このテリジノサウルスは今ではほとんど見えない。だが、これほど長い爪を持つ半盲の巨獣に近づきたいとは思うまい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Titanosaurus", "ティタノサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life was not meant to reach such sizes on land. This titan bears more resemblance to a force of nature than a beast.", "陸上の生命はこれほど大きくなるようにはできていない。この巨体は獣というより自然の力に似ている。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tupandactylus", "トゥパンダクティルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic Tupandactylus. Many flying creatures find themselves drawn to its exceptional crest.", "荘厳なトゥパンダクティルス。多くの飛ぶ生物が、その見事な頭冠に引き寄せられる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tyrannosaurus", "ティラノサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The infamous Tyrant Lizard King. Do you have the courage to oppose the largest land predator the world has ever seen?", "悪名高き暴君トカゲの王。世界が見た中で最大の陸上捕食者に立ち向かう勇気はあるか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feathered Tyrannosaurus", "羽毛ティラノサウルス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This whole...feather thing is getting out of hand. Have you considered that not every dinosaur was covered in them?", "この……羽毛の話は手に負えなくなってきた。全ての恐竜が羽毛に覆われていたわけではないと考えたことは？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Velocipastor", "ヴェロキパスター", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I... uh... I'm afraid there's little I can say to explain this. It was worth the time.", "私には……ええと……これを説明する言葉がほとんどない。時間をかけた甲斐はあった。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Mammoth", "ケナガマンモス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Mammoth, an iconic beast of the Ice Age. They are never alone.", "ケナガマンモス。氷河期を代表する獣だ。決して一頭ではない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So many bones to claim...", "手に入る骨がこんなに……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus Juvenile", "デイノスクスの幼体", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A juvenile Deinosuchus. It is still growing, but it is already a fearsome predator.", "幼いデイノスクス。まだ成長中だが、すでに恐ろしい捕食者だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus", "デイノスクス", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus, a fearsome apex predator. Not even prehistoric giants could escape from its jaws.", "デイノスクス。恐ろしい頂点捕食者だ。先史時代の巨獣でさえ、その顎から逃れられない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater defense is more than sufficient.", "より高い防御があれば十分すぎる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not satisfied yet...", "まだ満足していない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astonishing recovery.", "驚異的な回復。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The beast is offering comrades to assist you in this battle.", "この獣は、この戦いで君を助ける仲間を差し出している。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is getting out of hand.", "手に負えなくなってきた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is strength in numbers.", "数は力だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something wicked lurks in these waters.", "この水域には邪悪なものが潜んでいる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are more of them now? End this before it gets any worse.", "数が増えたのか？ これ以上ひどくなる前に終わらせろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a voracious little beast.", "なんと食いしん坊な小さな獣だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It still has room for growth.", "まだ成長の余地がある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What did you do to that beast?", "あの獣に何をした？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's... It's Godzilla!!!", "ゴ……ゴジラだ！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's done being a victim.", "もう犠牲者のままではいない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A feast for its kin.", "仲間のためのごちそう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It still clings to its glory, unwilling to be surpassed.", "いまだ栄光にしがみつき、追い越されることを拒む。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards (Blood)", "古代のトカゲ図鑑（血）", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards that cost Blood. Features a random assortment of prehistoric animals, mostly reptiles.", "血をコストとする約[count]枚のカードコレクション。主に爬虫類を中心とした先史時代の動物をランダムに収録する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards (Bones)", "古代のトカゲ図鑑（骨）", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards that cost Bones. Features a random assortment of prehistoric animals, mostly reptiles.", "骨をコストとする約[count]枚のカードコレクション。主に爬虫類を中心とした先史時代の動物をランダムに収録する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards (Mixed)", "古代のトカゲ図鑑（混合）", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards that cost Blood and Bones. Features a random assortment of prehistoric animals, mostly reptiles.", "血と骨をコストとする約[count]枚のカードコレクション。主に爬虫類を中心とした先史時代の動物をランダムに収録する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ginormous Camarasaurus. Its great size allows it to fling beasts across the battlefield.", "巨大なカマラサウルス。その大きさで獣を戦場の向こうまで投げ飛ばせる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Blood to increase Health of a card bearing this sigil by 1, then remove this sigil.", "血を1支払い、この印を持つカードの体力を1増やす。その後、この印を取り除く。", Language.Japanese);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue, the most reliable among the r... This beast shouldn't be human... Hm...", "ブルー、ラ……の中で最も頼れる……この獣は人間ではないはずだ……ふむ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Hm?[w:0.5]", "[e:Curious]ん？[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]You're...[w:0.3][e:Anger] You're not Owen.[w:0.5]", "[e:Curious]君は……[w:0.3][e:Anger]オーウェンじゃない。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I could tear you to bits right now[w:0.5].[w:0.5].[w:0.5].[w:0.5]", "[e:Anger]今すぐお前をずたずたにできる[w:0.5].[w:0.5].[w:0.5].[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]But Owen doesn't like it when we do that.[w:0.5]", "[e:Anger]でもオーウェンは私たちがそうするのを嫌がる。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Maybe if he", "[e:Quiet]もし彼が", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Pleased to meet you!", "[e:Laughter]会えて嬉しい！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Take good care of me and everything will be fine.", "[e:Neutral]私を大事にしてくれれば、何も問題ない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Hey there!", "[e:Neutral]やあ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I can make quick work of 'em.", "[e:Laughter]あいつらならすぐに片付けられる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Ready to go!", "[e:Neutral]準備はいい！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If you want them dead, let me know!", "[e:Laughter]あいつらを殺したいなら言って！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Another task? I can handle it.", "[e:Neutral]また仕事？ 私に任せて。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I've never been in a place like this...[w:0.5]", "[e:Curious]こんな場所は初めて……[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]But hey, if there are no fences here[w:0.5]", "[e:Laughter]でも、ここに柵がないなら[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Then I don't need to restrain myself.", "[e:Quiet]自分を抑える必要はない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I don't get to just kill things often.", "[e:Laughter]思う存分殺せる機会はあまりないから。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Roger that!", "[e:Laughter]了解！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I'm excited to tear into prey again.", "[e:Neutral]また獲物を引き裂けるなんて楽しみ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Got it!", "[e:Neutral]わかった！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Weakness means death.", "[e:Quiet]弱さは死を意味する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Consider it done!", "[e:Neutral]任せて！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Is this the right choice?", "[e:Curious]これでいいの？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]I'll remember this.[c:]", "[e:Anger][c:R]このことは忘れない。[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Don't expect to get away with this.", "[e:Quiet]これで済むと思わないで。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]So be it.", "[e:Anger]なら、そうしよう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Wuh?", "[e:Surprise]えっ？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Oooh, what's this?", "[e:Curious]おお、これは何？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]What's going to happen next?", "[e:Curious]次は何が起きるの？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I trust your decisions.", "[e:Laughter]君の判断を信じるよ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I don't feel like participating.", "[e:Anger]参加する気はない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]No.", "[e:Anger]嫌だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Think again.", "[e:Anger]考え直して。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Can't say I didn't expect this.[w:0.4]", "[e:Anger]予想してなかったとは言えない。[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]It's okay, I've done this with the rest of my pack", "[e:Neutral]大丈夫、群れの皆とはもう", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]plenty of times, this is nothing", "[e:Neutral]何度もやったから、こんなの平気", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You're dead.", "[e:Anger]死んでもらう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I did not appreciate that.", "[e:Anger]それは気に入らない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'll return the favour.", "[e:Quiet]お返しはするよ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Just a natural part of the hunt.", "[e:Neutral]狩りの自然な一部だよ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I'll return the favour.", "[e:Neutral]お返しはするよ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Oh, a test?[w:0.5]", "[e:Surprise]あ、試験？[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I've always been good at those!", "[e:Laughter]私、こういうのは得意なんだ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Is it done?", "[e:Curious]終わった？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Did I do good?", "[e:Laughter]うまくできた？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]How did it go?", "[e:Neutral]どうだった？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Ooooh...[w:0.5]", "[e:Surprise]おお……[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Don't mind if I do!", "[e:Laughter]遠慮なくいただくよ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I've been looking forward to this.", "[e:Quiet]ずっと楽しみにしてた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You were simply not good enough.", "[e:Laughter]君はただ力不足だっただけ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Where are the others?[w:0.3].[leshy:I might have made a mistake... Very well.][w:2]", "[e:Anger]皆はどこ？[w:0.3].[leshy:私は間違えたのかもしれない……よかろう。][w:2]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, hi!", "[e:Laughter]あ、やあ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Didn't expect to see you again!", "[e:Laughter]また会えるなんて思わなかった！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How are you?", "元気？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Huh?", "[e:Surprise]えっ？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I'll remember this.", "[e:Anger]このことは忘れない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Don't get cocky.", "[e:Anger]調子に乗らないで。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Angry]I don't like the way he smells...[w:0.5]", "[e:Angry]あいつの匂いは好きじゃない……[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's kill him!", "[e:Laughter]あいつを殺そう！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy...[w:0.5]", "[e:Anger]こいつ……[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Make it hurt this time.", "[e:Neutral]今度は痛い目に遭わせよう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I hate the noise.", "[e:Anger]あの騒音は嫌い。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Kill him.", "[e:Anger]あいつを殺して。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Fish...[w:0.3]?[w:0.5]", "[e:Surprise]魚……[w:0.3]？[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I never really liked that stuff.[w:0.3]", "[e:Neutral]あれはあまり好きじゃなかった。[w:0.3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'll eat him instead.", "[e:Quiet]代わりにあいつを食べよう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I won't fall for his tricks.", "[e:Anger]あいつの罠にはかからない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Can't even enjoy eating him...", "[e:Anger]あいつを食べるのも楽しめない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]We've done this before, let's kill him again!", "[e:Neutral]前にもやったし、また殺そう！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Wuh?[w:0.5] He wasn't on our side?[w:0.5]", "[e:Curious]えっ？[w:0.5]あいつは仲間じゃなかったの？[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Then I can kill him?", "[e:Quiet]じゃあ殺していいの？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, the two-faced guy again! Let's beat him up!", "[e:Laughter]あ、またあの二枚舌！ やっつけよう！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Two birds with one stone!", "[e:Laughter]一石二鳥！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's get rid of him.", "[e:Neutral]あいつを片付けよう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Oh, this is the end?[w:0.5]", "[e:Curious]あ、これで終わり？[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Well, it's been fun.[w:0.5]", "[e:Neutral]まあ、楽しかったよ。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]We'll see each other again, right?[w:0.5]", "[e:Neutral]また会えるよね？[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I hope we get to have a good time later!", "[e:Laughter]また楽しい時間を過ごせるといいね！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]The finale![w:0.5]", "[e:Laughter]フィナーレだ！[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]This should be fun!", "[e:Neutral]楽しそう！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]It sucks having to part ways...[w:0.5]", "[e:Anger]別れなきゃいけないなんて嫌だ……[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I hope to see you again!", "[e:Laughter]また会えるといいね！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's end this with a bang!", "[e:Laughter]派手に終わらせよう！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I think...[w:0.3]", "[e:Curious]たぶん……[w:0.3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I think I've seen somebody like this before.[w:0.5]", "[e:Curious]前にこんな人を見たことがある気がする。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Owen scolded me for snarling at that guy.", "[e:Anger]あいつに唸ったらオーウェンに叱られた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I'd rather not deal with those cannons.", "[e:Anger]あの大砲は相手にしたくない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Not again...", "[e:Anger]またなの……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This isn't particularly fun.", "[e:Anger]これはあまり楽しくない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Oh, what's this?[w:0.5]", "[e:Surprise]あ、これは何？[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Well, I guess my task is still the same!", "[e:Laughter]私の仕事は変わらないみたい！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I like when they struggle more.", "[e:Neutral]もっと抵抗してくれる方が好き。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, this one looks fun!", "[e:Laughter]あ、これは楽しそう！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's just kill them.", "[e:Neutral]さっさと殺そう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, another one!", "[e:Laughter]あ、また別のが来た！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]What will it be this time?", "[e:Neutral]今度は何だろう？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]This woman?[w:0.5]", "[e:Surprise]この女の人？[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Owen always told me to be more gentle with the elderly.[w:0.4]", "[e:Neutral]オーウェンはいつも、お年寄りには優しくしろって言ってた。[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Y'know, don't startle them and all that?[w:0.5]", "[e:Neutral]ほら、驚かせないようにとか。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I didn't listen.", "[e:Quiet]聞かなかったけど。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Weakness means death.", "[e:Laughter]弱さは死を意味する。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If she's our enemy, then we should kill her!", "[e:Laughter]敵なら殺さなきゃ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]No hesitation!", "[e:Neutral]ためらわないで！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I've never liked their smell.[w:0.5]", "[e:Anger]あいつらの匂いはずっと嫌いだった。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Reminded me of him.[w:0.3]", "[e:Anger]彼を思い出す。[w:0.3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Now, let's kill them!", "[e:Laughter]さあ、あいつらを殺そう！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]More faces means more to bite!", "[e:Neutral]顔が多ければ、噛むものも増える！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]You think they'll live with one of his faces clawed off?", "[e:Curious]あいつの顔を一つ爪で剥がしても、生きてると思う？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I wonder if he'll feel spongy...", "[e:Neutral]触るとスポンジみたいなのかな……", Language.Japanese);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm... Maybe something got mixed up in there...", "ふむ……中で何かが混ざったのかもしれない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You.[w:0.5]", "お前。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't know who you are.", "お前が誰かは知らない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't particularly care either.", "特に興味もない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Either you get me out of this mess or[w:0.5].[w:0.5].[w:0.5][e:Laughter].[w:0.5]", "この面倒から私を解放するか、それとも[w:0.5].[w:0.5].[w:0.5][e:Laughter].[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]No, I [e:Quiet]don't[w:0.5][e:Laughter] need to spell it out.[w:0.5]", "[e:Laughter]いや、[e:Quiet]言う[w:0.5][e:Laughter]までもないな。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet][c:R]Know your place and you will live.[c:]", "[e:Quiet][c:R]身の程を知れば生き延びられる。[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Make it quick.", "[e:Neutral]手早く済ませろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Morsels, all for me.", "[e:Laughter]うまそうな獲物、全て私のものだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]A fine opportunity.", "[e:Neutral]いい機会だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Now is a good time to feed me.", "[e:Laughter]今こそ私に餌をやる時だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Good timing. I was feeling quite peckish.", "[e:Laughter]ちょうどいい。少し腹が減っていた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I've been looking for something", "[e:Laughter]ずっと探していた", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]to tear into since I got into this mess.", "[e:Laughter]この面倒に巻き込まれてから、引き裂くものを。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I won't make it quick.", "[e:Quiet]手早くは終わらせない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I won't leave anything behind.", "[e:Laughter]何も残さない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]A feast, just for me.", "[e:Laughter]私だけのごちそうだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Don't expect to survive.", "[e:Neutral]生き残れると思うな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Who wishes to die first?", "[e:Quiet]最初に死にたいのは誰だ？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I've been itching for a fight.", "[e:Quiet]ずっと戦いたくてうずうずしていた。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Are you sure about this choice?", "[e:Curious]本当にそれを選ぶのか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]You traitor!!![c:]", "[e:Anger][c:R]この裏切り者！！！[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'll remember this.", "[e:Quiet]このことは忘れない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]You bastard!!![c:]", "[e:Anger][c:R]この野郎！！！[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise][c:R]You...![c:]", "[e:Surprise][c:R]貴様……！[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Oh, what's this now?", "[e:Curious]おや、今度は何だ？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Who will die this time?", "[e:Curious]今度は誰が死ぬ？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]There is only one correct choice.", "[e:Laughter]正しい選択は一つだけだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Do not make any choices I would make you regret.", "[e:Quiet]私がお前に後悔させるような選択はするな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's get this done and over with.", "[e:Neutral]さっさと終わらせよう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Pick anyone else.", "[e:Neutral]他の誰かを選べ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You did this on purpose...[w:0.4]", "[e:Anger]わざとやったな……[w:0.4]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]Didn't you!?[c:][w:0.5]", "[c:R]そうだろう！？[c:][w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I'll let it slide for now.", "[e:Neutral]今回は見逃してやろう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]You dare...![c:]", "[e:Anger][c:R]よくも……！[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]I'll tear you limb from limb!!![c:]", "[e:Anger][c:R]手足を引き裂いてやる！！！[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]You've made your choice.", "[e:Quiet]選択は済んだな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Tsk!", "[e:Anger]チッ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Gh!", "[e:Anger]ぐっ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Is this some kind of a test?[w:0.5]", "[e:Surprise]これは試練か何かか？[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I don't expect to fail.", "[e:Laughter]失敗するとは思わない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Are we done?", "[e:Curious]もう終わりか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I shall aid you.", "[e:Laughter]力を貸そう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Waste of my time.", "[e:Neutral]時間の無駄だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Interesting...[w:0.5]", "[e:Curious]面白い……[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]There are enough voices screaming from within my blood.", "[e:Neutral]私の血の中では、もう十分な数の声が叫んでいる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]What's another one?", "[e:Quiet]もう一つ増えたところで何だ？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Become a part of me.", "[e:Laughter]私の一部になれ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I shall claim your power.", "[e:Quiet]お前の力は私がもらう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]It is only natural.", "[e:Laughter]当然のことだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]What did you do to me!?[c:][w:0.5].[leshy:It appears that this beast is... more human than it appeared. No matter.][w:2]", "[e:Anger][c:R]私に何をした！？[c:][w:0.5].[leshy:この獣は……見た目以上に人間らしいようだ。まあいい。][w:2]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We meet again.", "[e:Laughter]また会ったな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You shall serve me once more.", "[e:Laughter]再び私に仕えるのだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do not disappoint me this time.", "今度は失望させるな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]No, you can't...!", "[e:Surprise]いや、それは駄目だ……！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Curse you!!!", "[e:Anger]呪ってやる！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I will remember this!!!", "[e:Anger]このことは忘れん！！！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]What an eyesore...", "[e:Neutral]なんと目障りな……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Get rid of him.[w:0.5]", "あいつを片付けろ。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The noise bothers me.", "あの騒音は耳障りだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You...[w:0.5]", "[e:Anger]貴様……[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Do not make the same mistakes.", "[e:Neutral]同じ過ちを繰り返すな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This noise again...", "[e:Anger]またあの騒音か……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Get him out of my sight.", "[e:Anger]あいつを目の前から消せ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]This...[w:0.5] This smell...[w:0.5]", "[e:Surprise]この……[w:0.5]この匂いは……[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]I remember a smell like this...[w:0.5]", "[e:Surprise]この匂いを覚えている……[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]We must get out of here.", "[e:Surprise]ここから出なければ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Don't let those things near me!", "[e:Surprise]あれを私に近づけるな！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]I won't die like this again!", "[e:Surprise]二度とこんな死に方はしない！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]There's something lurking in the waters...", "[e:Surprise]水の中に何かが潜んでいる……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I have little patience for traitors.[w:0.5]", "[e:Anger]裏切り者に向ける忍耐はほとんどない。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet][c:R]Skin him alive.[c:]", "[e:Quiet][c:R]生きたまま皮を剥げ。[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]He'll make for a fine pelt.", "[e:Laughter]いい毛皮になりそうだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]The smell in the air is pleasant.", "[e:Laughter]空気の匂いが心地よい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet][c:R]Let's enrich it further with his blood.[c:]", "[e:Quiet][c:R]奴の血でさらに豊かにしよう。[c:]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You should know how this works by now.", "[e:Laughter]もうやり方はわかっているはずだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]This is it...[w:0.5]", "[e:Curious]ここか……[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]We've made it this far.[w:0.5]", "[e:Neutral]ここまで来たな。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose you weren't too bad.[w:0.5]", "お前もそれほど悪くなかったな。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't miss you[w:0.5], but I've seen worse humans.[w:0.5]", "寂しくはならないが[w:0.5]、もっとひどい人間も見てきた。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Let's put an end to his games.", "[e:Quiet]奴の遊びを終わらせよう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You can do this.[w:0.5]", "[e:Laughter]お前ならできる。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Be of service to me once again.", "[e:Laughter]もう一度私の役に立て。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We shall part soon.[w:0.5]", "[e:Laughter]もうすぐ別れの時だ。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I hope to see you again.", "[e:Laughter]また会えるといいな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]It's been fun so far.[w:0.5]", "[e:Laughter]ここまでは楽しかった。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's have some more fun in the future.", "[e:Laughter]今後ももっと楽しもう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Not...[w:0.5] Not the water again...[w:0.5]", "[e:Surprise]いや……[w:0.5]また水は嫌だ……[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]What will attack me this time?", "[e:Surprise]今度は何が私を襲う？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I don't appreciate getting shot with cannons. Kill him quickly.", "[e:Anger]大砲で撃たれるのは嫌いだ。早く奴を殺せ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This moron again...", "[e:Anger]またこの愚か者か……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]There isn't even anything to gnaw on.", "[e:Anger]かじるものすらない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]The air is different.[w:0.5]", "[e:Surprise]空気が違う。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]They are prey all the same.", "[e:Laughter]どのみち全員獲物だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]What a chore.", "[e:Neutral]面倒なことだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Perhaps something bigger to chew on?", "[e:Laughter]もっと大きな獲物でも噛めるかな？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Eyesore.", "[e:Neutral]目障りだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]This changes nothing.", "[e:Laughter]何も変わらない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]They should know their place.", "[e:Laughter]身の程を知るべきだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Hmph.[w:0.5]", "[e:Neutral]ふん。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]This foolish hag has outlived her usefulness.[w:0.5]", "[e:Neutral]あの愚かな老婆はもう用済みだ。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Her skull would be a fine decoration for a totem.", "[e:Quiet]奴の頭蓋骨はトーテムのいい飾りになる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's shave off what few years she has left.", "[e:Laughter]残り少ない寿命を削ってやろう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]One foot in the grave, another soon to come.", "[e:Laughter]片足はもう墓に入っている。もう片方もすぐだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]She'd die in a few years regardless.", "[e:Laughter]どうせ数年で死ぬだろう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Not particularly surprising.[w:0.5]", "[e:Neutral]さほど驚くことではない。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]These experimental types don't know loyalty.[w:0.5]", "[e:Neutral]実験体どもは忠誠を知らない。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'd rather get my claws on that bastard Wu", "[e:Quiet]本当はあのウーという野郎をこの爪にかけたいが", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]but this shall do for now.", "[e:Laughter]ひとまずこいつで我慢しよう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's return the favour.", "[e:Neutral]お返しをしよう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]There won't be much left to stitch together.", "[e:Laughter]縫い合わせるものはあまり残るまい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Two heads to tear off.[e:Quiet]What a treat.", "[e:Neutral]引きちぎる頭が二つ。[e:Quiet]ごちそうだ。", Language.Japanese);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owen", "オーウェン", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A human? ...No matter. I have a feeling this man will prove himself capable against claws and fangs of your opponents.", "人間？ ……まあいい。この男なら、君の敵の爪と牙にも対抗できる気がする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I don't know what this whole thing is about[w:0.3]", "[e:Curious]何がどうなってるのかわからないが[w:0.3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]but we'll make it", "[e:Laughter]きっとうまくいく", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]trust me.", "[e:Laughter]信じてくれ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Stay on guard.", "[e:Anger]警戒を怠るな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]So much for taking a break, huh.", "[e:Laughter]休憩はお預けみたいだな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You can count on me.", "[e:Laughter]俺に任せてくれ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Let's hope working at Jurassic World didn't make me rusty...", "[e:Quiet]ジュラシック・ワールドでの仕事で腕が鈍っていなければいいが……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I don't like doing this, but it's us or them here.", "[e:Anger]こんなことはしたくないが、ここでは俺たちか奴らかの二択だ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This rifle better not act up on me now...", "[e:Anger]今はこのライフルの調子が悪くならないといいが……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's do this.", "[e:Neutral]やろう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Gotta focus if we both want to keep our skins.", "[e:Quiet]二人とも生き残りたいなら、集中しないとな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Not sure about this position, but I can make it work.", "[e:Quiet]この位置はどうかと思うが、なんとかできる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Now would be a bad time to forget my training.", "[e:Quiet]訓練を忘れるには最悪のタイミングだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Wait, what are you doing!?", "[e:Surprise]待て、何をしてる！？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Huh, why me?", "[e:Surprise]え、なんで俺？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I haven't told her I-", "[e:Anger]彼女にまだ俺が——", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]What kind of-", "[e:Anger]なんてことを——", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Whatever this is, I don't like it.", "[e:Anger]何だか知らないが、気に入らない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'd rather sit this one out.", "[e:Quiet]今回は遠慮したい。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]If I have to...", "[e:Quiet]どうしてもなら……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I have a bad feeling about this one.", "[e:Anger]嫌な予感がする。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Could you pick anyone else?", "[e:Quiet]他の人を選べないか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'd rather not...", "[e:Quiet]あまり気が進まない……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Damn...[w:0.3]", "[e:Anger]くそ……[w:0.3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]The situation is worse than I thought.[w:0.3]", "[e:Anger]思ったより状況が悪い。[w:0.3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I can still handle this, don't worry.", "[e:Laughter]まだ大丈夫だ、心配するな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Shit!", "[e:Anger]くそっ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This will leave a mark.", "[e:Anger]これは傷跡が残るな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Sure, I could use another scar.", "[e:Anger]ああ、傷跡がまた一つ増えるな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Ow!", "[e:Anger]痛っ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Tsk, got careless.", "[e:Anger]チッ、油断した。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]A trial?[w:0.3]", "[e:Surprise]試練？[w:0.3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Well, did we pass it?", "[e:Curious]それで、合格したか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]How did we do?", "[e:Curious]結果はどうだった？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I have a good feeling about this one.", "[e:Laughter]今回はうまくいきそうだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I didn't just blow it, did I?", "[e:Quiet]しくじってないよな？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Me?[w:0.3]", "[e:Surprise]俺？[w:0.3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Well... Sorry, buddy", "[e:Quiet]そうか……すまない、相棒", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]but it looks like there's no other choice.", "[e:Quiet]だが他に選択肢はないようだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I hate doing this.", "[e:Quiet]こんなことはしたくない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]If we want to survive...", "[e:Quiet]生き残りたいなら……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Really wish we could avoid this, but...", "[e:Quiet]避けられたらよかったんだが……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]What is this place?[w:0.3]", "[e:Curious]ここはどこだ？[w:0.3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Well, you look like a reasonable fellow.", "[e:Laughter]話のわかる奴に見えるな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If we stick together", "[e:Laughter]一緒にいれば", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]we can escape in one piece", "[e:Laughter]無事に逃げられる", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Hello again.", "[e:Laughter]また会ったな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Did you miss me?", "[e:Laughter]俺が恋しかったか？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guess we're doing this again...", "またやることになりそうだな……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Hold on, this looks bad!", "[e:Surprise]待て、まずいぞ！", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]A prospector?[w:0.5]", "[e:Curious]探鉱者？[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This feels like some kind of an attraction[w:0.5]", "何かのアトラクションみたいだ[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]But we won't be having fun here, are we?", "[e:Anger]だが楽しめるわけじゃないよな？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy again?[w:0.3]", "[e:Anger]またこいつか？[w:0.3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Let's be a bit more careful this time.", "[e:Anger]今度はもう少し気をつけよう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I'll keep hearing this ringing for the rest of my life.", "[e:Anger]この鐘の音は一生耳に残りそうだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You know what's gonna happen soon. Get ready.", "[e:Anger]次に何が起きるかはわかるな。備えろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Woah![w:0.5]", "[e:Surprise]うわっ！[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]This guy's huge![w:0.5]", "[e:Surprise]こいつ、でかい！[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]But I've dealt with bigger fish than this.", "[e:Laughter]だが、もっと大物を相手にしたこともある。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's do this.", "[e:Laughter]やろう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]This guy again...[w:0.3]", "[e:Curious]またこいつか……[w:0.3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We've done this before, let's get him.", "[e:Laughter]前にもやった。倒そう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You know...[w:0.3]", "[e:Anger]なあ……[w:0.3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]maybe I don't need to feel so bad about the sharks we fed to that thing.", "[e:Anger]あれに食わせたサメのことを、そんなに気に病む必要はないのかもな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]The smell doesn't get any better...", "[e:Anger]匂いは相変わらずひどい……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I knew something was off[w:0.3]", "[e:Anger]何かおかしいと思ったんだ[w:0.3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Guess I've got a good grasp of people too.", "[e:Laughter]俺も人を見る目があるみたいだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Get ready.", "[e:Laughter]準備しろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Nothing to worry about", "[e:Laughter]心配はいらない", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I can disarm the traps from afar.", "[e:Laughter]罠なら遠くから解除できる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We shouldn't have any trouble at all.", "[e:Laughter]何の問題もないはずだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Here we go.", "[e:Laughter]行くぞ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If you don't want to sacrifice anybody", "[e:Laughter]誰も生贄にしたくないなら", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]let me get rid of these things myself.", "[e:Laughter]俺がこいつらを片付けよう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]So this is the guy behind everything?[w:0.3]", "[e:Curious]全ての黒幕はこいつなのか？[w:0.3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Not sure what I was expecting", "[e:Curious]何を期待していたのかはわからないが", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]But it doesn't matter.[w:0.3]", "[e:Anger]もうどうでもいい。[w:0.3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Let's end this.", "[e:Anger]終わらせよう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We've done this before", "[e:Laughter]前にもやった", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]let's do it again.", "[e:Laughter]もう一度やろう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy's no joke.", "[e:Anger]こいつは手強いぞ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Don't let your guard down.", "[e:Anger]油断するな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We've got this, don't worry.", "[e:Laughter]俺たちならやれる、心配するな。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]A...[w:0.3]pirate?", "[e:Surprise]海……[w:0.3]賊？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Hah, good one![w:0.3]", "[e:Laughter]はは、面白い！[w:0.3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Well, there's only one thing left to do.", "[e:Laughter]さて、やることは一つだけだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Watch out for the cannons.", "[e:Anger]大砲に気をつけろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This will be tough, but we can do this.", "[e:Anger]大変だが、俺たちならやれる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy isn't playing around, stay on guard.", "[e:Anger]こいつは本気だ、警戒しろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Is this some kind of...[w:0.5] Magic?[w:0.5]", "[e:Surprise]これは……[w:0.5]魔法か？[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Well, I guess this is going to get much weirder.", "[e:Quiet]もっと奇妙なことになりそうだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]They're getting empowered. Stay alert.", "[e:Anger]奴らが強化されている。警戒しろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Not this thing again...", "[e:Anger]またこれか……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]How come I don't get fancy toys like this?", "[e:Curious]なんで俺にはこんな派手な玩具がないんだ？", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Just a little handicap, nothing more.", "[e:Laughter]ちょっとしたハンデだ、それだけさ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's not give up just yet.", "[e:Laughter]まだ諦めないでおこう。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]What?[w:0.5] You of all people?[w:0.5]", "[e:Surprise]何？[w:0.5]よりによって君が？[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I wish it didn't come down to this, but...[w:0.3]", "[e:Neutral]こんなことにならなければよかったが……[w:0.3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Guess we've got no choice.", "[e:Quiet]他に選択肢はないようだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This one's tough. Get ready.", "[e:Anger]こいつは手強い。準備しろ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]One wrong move and we're done for.", "[e:Anger]一歩間違えれば俺たちは終わりだ。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I really don't like dealing with her...", "[e:Anger]彼女を相手にするのは本当に嫌だ……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I always got bad vibes from these guys.[w:0.5]", "[e:Anger]あいつらにはいつも嫌な予感がしていた。[w:0.5]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I've seen people like them.[w:0.3]", "[e:Anger]あいつらみたいな奴を見たことがある。[w:0.3]", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Whatever drives them,", "[e:Anger]何が奴らを動かしていようと、", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]we can get through just fine.", "[e:Laughter]俺たちなら切り抜けられる。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]These guys again...", "[e:Neutral]またこいつらか……", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Come on, we didn't get this far just to kick the bucket here.", "[e:Laughter]しっかりしろ。ここで死ぬために来たわけじゃない。", Language.Japanese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]This is getting dangerous. Get ready.", "[e:Neutral]危険になってきた。備えろ。", Language.Japanese);


        }
    }
}
